FR.LEXICON.B1 = [{"w":"abandonner","p":"v.","cn":"放弃；抛弃、遗弃","ex":"Malgré les difficultés, elle n'a jamais abandonné ses études.","exCn":"尽管困难重重，她从未放弃学业。","th":"常用词"},{"w":"abeille","p":"n.f.","cn":"蜜蜂","ex":"Où l'abeille vous a-t-elle piqué ?","exCn":"蜜蜂蜇到您哪儿了？","th":"常用词"},{"w":"abordable","p":"adj.","cn":"（价格）实惠的；平易近人的","ex":"Ce restaurant propose des menus à des prix abordables.","exCn":"这家餐厅的套餐价格很实惠。","th":"购物与金钱"},{"w":"aborder","p":"v.","cn":"探讨、涉及（话题等）；（上前）与…搭话","ex":"C'est un sujet sensible, je ne sais pas comment l'aborder avec mes parents.","exCn":"这个话题很敏感，我不知道怎么跟父母开口。","th":"常用词"},{"w":"abri","p":"n.m.","cn":"避难所、遮蔽处；（à l'~ de）免受…之害","ex":"La ville a ouvert un abri temporaire pour les sans-abri pendant la vague de froid.","exCn":"寒潮期间，市政府为无家可归者开设了一处临时庇护所。","th":"常用词"},{"w":"absence","p":"n.f.","cn":"缺席、不在；缺乏、没有","ex":"Une absence prolongée doit être justifiée par un certificat médical.","exCn":"长时间缺勤必须出具医生证明。","th":"常用词"},{"w":"absurde","p":"adj.","cn":"荒谬的","ex":"Cette règle est complètement absurde : personne ne la respecte.","exCn":"这条规定简直荒谬：根本没人遵守。","th":"常用词"},{"w":"abîmer","p":"v.","cn":"损坏、弄坏；（s'~）受损、坏掉","ex":"Ne mets pas ce pull en laine au sèche-linge, tu vas l'abîmer.","exCn":"别把这件羊毛衫放进烘干机，会把它弄坏的。","th":"描述与状态"},{"w":"acceptable","p":"adj.","cn":"可接受的","ex":"Insulter un collègue, même sous le coup de la colère, n'est pas acceptable.","exCn":"侮辱同事是不可接受的，哪怕是一时气愤。","th":"常用词"},{"w":"accessible","p":"adj.","cn":"可到达的、可使用的；（价格）实惠的；易懂的","ex":"Cette plage est accessible uniquement à pied ou à vélo.","exCn":"这片海滩只能步行或骑车才能到达。","th":"出行与旅行"},{"w":"accessoire","p":"n.m.","cn":"配件、配饰；次要的、附带的","ex":"Au Canada, les gants sont un accessoire indispensable en hiver.","exCn":"在加拿大，手套是冬天必不可少的配饰。","th":"常用词"},{"w":"accrocher","p":"v.","cn":"挂、挂上；钩住；（s'~ à）抓住、紧抓不放；（s'~）坚持下去、不放弃","ex":"Tu peux m'aider à accrocher ce tableau au-dessus du canapé ?","exCn":"你能帮我把这幅画挂到沙发上方吗？","th":"居住与环境"},{"w":"accuser","p":"v.","cn":"指控、控告；指责","ex":"Il est accusé de vol dans un magasin du centre-ville.","exCn":"他被控在市中心一家商店行窃。","th":"常用词"},{"w":"accès","p":"n.m.","cn":"进入、使用（权）；通道、入口；（疾病、情绪的）发作","ex":"Tous les élèves ont accès à la bibliothèque.","exCn":"所有学生都可以使用图书馆。","th":"健康与身体"},{"w":"accéder","p":"v.","cn":"（~ à）进入、到达；获取、访问（数据、权限等）","ex":"On accède au parking par la rue située derrière l'immeuble.","exCn":"从大楼后面那条街可以进入停车场。","th":"出行与旅行"},{"w":"accélérer","p":"v.","cn":"加速、加快","ex":"Le conducteur a accéléré au feu jaune au lieu de s'arrêter.","exCn":"司机遇到黄灯没有停车，反而加速了。","th":"描述与状态"},{"w":"acheteur","p":"n.","cn":"买家、购买者；采购员","ex":"Nous avons enfin trouvé un acheteur pour notre maison.","exCn":"我们的房子终于找到买家了。","th":"购物与金钱"},{"w":"acide","p":"n.m.","cn":"酸的；（化学）酸","ex":"Ces pommes vertes sont un peu trop acides à mon goût.","exCn":"这些青苹果对我来说有点太酸了。","th":"常用词"},{"w":"acte","p":"n.m.","cn":"行为、行动；（官方）证书、文书；（戏剧的）幕","ex":"Voter est un acte citoyen essentiel.","exCn":"投票是一项重要的公民行为。","th":"常用词"},{"w":"actif","p":"adj.","cn":"积极的、活跃的；（经济上）从事职业的、劳动的","ex":"Elle joue un rôle très actif dans l'association des parents d'élèves.","exCn":"她在学生家长协会里发挥着非常积极的作用。","th":"工作与学习"},{"w":"actuel","p":"adj.","cn":"当前的、现今的","ex":"Dans le contexte actuel, beaucoup d'entreprises hésitent à embaucher.","exCn":"在当前形势下，很多公司都不太敢招人。","th":"常用词"},{"w":"adaptation","p":"n.f.","cn":"适应；改编","ex":"L'adaptation des enfants à leur nouvelle école s'est faite plus vite que prévu.","exCn":"孩子们适应新学校比预想的要快。","th":"常用词"},{"w":"adapter","p":"v.","cn":"（使）适应、调整；改编（作品）","ex":"Il m'a fallu quelques mois pour m'adapter au froid de l'hiver canadien.","exCn":"我花了好几个月才适应加拿大冬天的寒冷。","th":"常用词"},{"w":"additionner","p":"v.","cn":"相加、加起来","ex":"Si on additionne tous nos abonnements, on dépense presque cent dollars par mois.","exCn":"把我们所有的订阅费加起来，每个月要花将近一百块钱。","th":"常用词"},{"w":"adieu","p":"interj.","cn":"永别了、别了；cf. faire ses adieux 告别、辞行","ex":"Il a dit adieu à ses collègues le jour de sa retraite.","exCn":"退休那天，他向同事们告别。","th":"常用词"},{"w":"admettre","p":"v.","cn":"承认；接纳、录取；容许、容忍","ex":"Je dois admettre que je n'en ai jamais entendu parler.","exCn":"我得承认，我从来没听说过这件事。","th":"常用词"},{"w":"administratif","p":"adj.","cn":"行政的","ex":"À cause d'une erreur administrative, j'ai reçu deux fois la même facture.","exCn":"由于行政上的一个失误，同一张账单我收到了两次。","th":"常用词"},{"w":"administration","p":"n.f.","cn":"行政部门、政府机关；管理","ex":"Pour obtenir ce document, il faut s'adresser à l'administration municipale.","exCn":"要办这份文件，得去找市政部门。","th":"社会与新闻"},{"w":"admiration","p":"n.f.","cn":"钦佩、赞赏","ex":"Son courage face à la maladie fait l'admiration de tous ses collègues.","exCn":"她面对疾病时的勇气令所有同事钦佩。","th":"常用词"},{"w":"admirer","p":"v.","cn":"钦佩、敬佩；欣赏、观赏","ex":"Je vous admire pour votre courage.","exCn":"我钦佩您的勇气。","th":"常用词"},{"w":"admission","p":"n.f.","cn":"录取、准入","ex":"Son admission à l'université a été confirmée hier.","exCn":"她被大学录取的消息昨天得到了确认。","th":"常用词"},{"w":"adolescence","p":"n.f.","cn":"青春期、青少年时期","ex":"Il a passé toute son adolescence à Sherbrooke avant d'aller étudier à Montréal.","exCn":"他整个青少年时期都在舍布鲁克度过，后来去蒙特利尔读书。","th":"人物与身份"},{"w":"adopter","p":"v.","cn":"采取、采用；收养；通过（法案、决议）","ex":"La ville a adopté de nouvelles mesures pour réduire la circulation au centre-ville.","exCn":"市政府采取了新措施，以减少市中心的车流。","th":"常用词"},{"w":"adversaire","p":"n.","cn":"对手、敌手","ex":"Il a battu son adversaire en trois sets.","exCn":"他三盘击败了对手。","th":"常用词"},{"w":"affection","p":"n.f.","cn":"疼爱、喜爱、感情；（医学）疾病、病症","ex":"Ma grand-mère nous a toujours entourés d'une grande affection.","exCn":"我奶奶一直用满满的爱呵护着我们。","th":"健康与身体"},{"w":"afficher","p":"v.","cn":"显示、表现出；张贴（告示等）","ex":"L'écran affiche l'heure d'arrivée de chaque autobus.","exCn":"屏幕上显示着每辆公交车的到站时间。","th":"常用词"},{"w":"affirmer","p":"v.","cn":"断言、肯定地说；（s'~）显露出来、变得自信","ex":"Le ministre a affirmé que les impôts n'augmenteraient pas l'an prochain.","exCn":"部长断言明年不会加税。","th":"常用词"},{"w":"affreux","p":"adj.","cn":"可怕的、丑陋的、糟糕透顶的","ex":"J'ai une migraine affreuse depuis ce matin.","exCn":"我从早上起就头疼得要命。","th":"描述与状态"},{"w":"afin","p":"conj.","cn":"（~ de）为了；（~ que）以便","ex":"Elle suit des cours du soir afin d'améliorer son français.","exCn":"她上夜校，为了提高自己的法语水平。","th":"常用词"},{"w":"agir","p":"v.","cn":"行动、采取行动；cf. il s'agit de 涉及、是关于；il s'agit de + 不定式 关键是、必须","ex":"Les pompiers ont agi avec beaucoup de courage.","exCn":"消防员行动得非常英勇。","th":"常用词"},{"w":"agité","p":"adj.","cn":"躁动的、坐立不安的；（睡眠）不安稳的；（海）汹涌的","ex":"Les enfants sont très agités avant les vacances.","exCn":"放假前孩子们都很躁动。","th":"居住与环境"},{"w":"agneau","p":"n.m.","cn":"小羊、羊羔；羔羊肉","ex":"Chez nous, on mange toujours de l'agneau le dimanche de Pâques.","exCn":"在我们家，复活节那个星期天总是吃羊羔肉。","th":"饮食"},{"w":"agrafeuse","p":"n.f.","cn":"订书机","ex":"Tu peux me prêter ton agrafeuse ? La mienne est vide.","exCn":"你能把订书机借我用一下吗？我的没钉了。","th":"常用词"},{"w":"agrandir","p":"v.","cn":"扩大、扩建；（照片等）放大","ex":"La ville a agrandi le parc municipal en rachetant les terrains voisins.","exCn":"市政府买下周边土地，扩建了市立公园。","th":"描述与状态"},{"w":"agresser","p":"v.","cn":"袭击、侵犯","ex":"Une femme a été agressée hier soir près de la station de métro.","exCn":"昨晚一名女子在地铁站附近遭到袭击。","th":"常用词"},{"w":"agressif","p":"adj.","cn":"有攻击性的、好斗的；咄咄逼人的","ex":"Ce chien devient agressif quand on s'approche de sa nourriture.","exCn":"有人靠近它的食物时，这条狗就会变得具有攻击性。","th":"人物与身份"},{"w":"agricole","p":"adj.","cn":"农业的","ex":"La France est un grand pays agricole.","exCn":"法国是农业大国。","th":"常用词"},{"w":"agriculture","p":"n.f.","cn":"农业","ex":"Sur les toits de la ville, l'agriculture urbaine se développe : on y cultive salades et fraises.","exCn":"城市的屋顶上，都市农业正在兴起：人们在那里种生菜和草莓。","th":"常用词"},{"w":"agréer","p":"v.","cn":"（书信套语）接受；批准、认可","ex":"Je vous prie d'agréer, Monsieur le Directeur, mes salutations respectueuses.","exCn":"主任先生，请接受我诚挚的敬意。（信末套语）","th":"常用词"},{"w":"aide-soignant","p":"n.","cn":"护工、护理员；cf. préposé aux bénéficiaires（魁北克对护工的常用说法）","ex":"Elle travaille comme aide-soignante dans un hôpital.","exCn":"她在一家医院当护工。","th":"常用词"},{"w":"aiguille","p":"n.f.","cn":"针；（钟表的）指针","ex":"Quand la petite aiguille sera sur le quatre, on ira chercher ton frère à l'école.","exCn":"等时针指到四的时候，我们就去学校接你哥哥。","th":"常用词"},{"w":"aile","p":"n.f.","cn":"翅膀；（建筑、政党等）侧翼","ex":"On a commandé des ailes de poulet épicées pour regarder le match.","exCn":"我们点了辣鸡翅，边吃边看比赛。","th":"居住与环境"},{"w":"ailleurs","p":"adv.","cn":"别处；cf. d'ailleurs 此外、况且；par ailleurs 另外、另一方面","ex":"Ce restaurant est complet, allons manger ailleurs.","exCn":"这家餐厅满了，我们去别处吃吧。","th":"功能词与连接"},{"w":"ainsi","p":"adv.","cn":"因此；这样","ex":"Les prix ont augmenté ; ainsi, nous avons changé nos habitudes.","exCn":"物价上涨了，因此我们改变了习惯。","th":"观点与论证"},{"w":"aise","p":"n.f.","cn":"舒适感；（à l'~）自在、舒适；（经济上）宽裕；（mal à l'~）不自在、尴尬","ex":"Je ne me sens pas à l'aise quand je dois parler devant un grand groupe.","exCn":"要在一大群人面前讲话时，我会觉得不自在。","th":"社会与新闻"},{"w":"ajuster","p":"v.","cn":"调整、调节","ex":"Ajustez la hauteur de votre chaise pour éviter le mal de dos.","exCn":"调好椅子的高度，以免背痛。","th":"常用词"},{"w":"alarme","p":"n.f.","cn":"警报；警报器；（手机等的）闹钟","ex":"L'alarme de la voiture s'est déclenchée en pleine nuit.","exCn":"半夜里汽车警报器突然响了。","th":"常用词"},{"w":"alentours","p":"n.m.","cn":"周围、附近一带；（aux ~ de）…左右、大约","ex":"Il n'y a aucun supermarché dans les alentours, il faut prendre la voiture.","exCn":"附近一带没有超市，得开车去。","th":"时间与数量"},{"w":"alerte","p":"n.f.","cn":"警报、警戒","ex":"J'ai reçu une alerte sur mon téléphone : un enfant a disparu dans la région.","exCn":"我手机上收到一条警报：本地区有一名儿童失踪。","th":"常用词"},{"w":"alimentaire","p":"adj.","cn":"食品的、饮食的","ex":"Les prix des produits alimentaires ont beaucoup augmenté.","exCn":"食品价格大幅上涨。","th":"常用词"},{"w":"allocation","p":"n.f.","cn":"补贴、津贴","ex":"Les familles nombreuses touchent des allocations familiales.","exCn":"多子女家庭可以领取家庭补助。","th":"常用词"},{"w":"allonger","p":"v.","cn":"延长、加长；伸出（手脚）；（s'~）躺下、变长","ex":"La ville a décidé d'allonger les heures d'ouverture des bibliothèques.","exCn":"市政府决定延长图书馆的开放时间。","th":"描述与状态"},{"w":"allongé","p":"adj.","cn":"躺着的；长形的、细长的；（咖啡）加水冲淡的","ex":"À marée basse, une dizaine de phoques restent allongés sur les rochers, sans se soucier des touristes.","exCn":"退潮时，十来只海豹躺在礁石上，对游客毫不在意。","th":"饮食"},{"w":"allumette","p":"n.f.","cn":"火柴","ex":"Il a craqué une allumette pour allumer les bougies du gâteau.","exCn":"他划了一根火柴点蛋糕上的蜡烛。","th":"常用词"},{"w":"allée","p":"n.f.","cn":"小径、林荫道；（座位、货架间的）通道","ex":"Nous nous sommes promenés dans les allées du parc.","exCn":"我们在公园的小路上散步。","th":"描述与状态"},{"w":"alpinisme","p":"n.m.","cn":"登山（运动）","ex":"Il fait de l'alpinisme depuis l'âge de quinze ans.","exCn":"他从十五岁起就开始登山。","th":"居住与环境"},{"w":"alpiniste","p":"n.","cn":"登山者","ex":"Deux alpinistes ont été secourus près du sommet.","exCn":"两名登山者在山顶附近获救。","th":"居住与环境"},{"w":"altitude","p":"n.f.","cn":"海拔、高度","ex":"Le village se trouve à plus de deux mille mètres d'altitude.","exCn":"这个村庄位于海拔两千多米处。","th":"居住与环境"},{"w":"aluminium","p":"n.m.","cn":"铝","ex":"L'aluminium est léger, résistant et se recycle à l'infini.","exCn":"铝又轻又结实，而且可以无限次回收利用。","th":"常用词"},{"w":"amande","p":"n.f.","cn":"杏仁、扁桃仁","ex":"Ce gâteau est fait avec de la poudre d'amande.","exCn":"这个蛋糕是用杏仁粉做的。","th":"常用词"},{"w":"amateur","p":"n.","cn":"爱好者；业余者；业余的","ex":"Mon père est un grand amateur de vin.","exCn":"我父亲是个葡萄酒爱好者。","th":"情绪与性格"},{"w":"ambassadeur","p":"n.","cn":"大使；（品牌、事业的）代言人、形象大使","ex":"Le nouvel ambassadeur du Canada en France a présenté ses lettres de créance.","exCn":"加拿大新任驻法大使递交了国书。","th":"人物与身份"},{"w":"ambitieux","p":"adj.","cn":"有雄心的、有抱负的","ex":"C'est un jeune homme ambitieux qui rêve de créer sa propre entreprise.","exCn":"他是个有抱负的年轻人，梦想创办自己的公司。","th":"常用词"},{"w":"ambition","p":"n.f.","cn":"雄心、抱负；野心","ex":"Son ambition démesurée l'a poussé à trahir ses collègues.","exCn":"过度的野心驱使他背叛了同事。","th":"常用词"},{"w":"amende","p":"n.f.","cn":"罚款","ex":"J'ai reçu une amende de cent euros pour excès de vitesse.","exCn":"我因为超速被罚了一百欧元。","th":"常用词"},{"w":"amer","p":"adj.","cn":"苦的；（喻）苦涩的、辛酸的","ex":"Ce café est trop amer, tu peux me passer le sucre ?","exCn":"这咖啡太苦了，能把糖递给我吗？","th":"常用词"},{"w":"amical","p":"adj.","cn":"友好的、友善的；（比赛）友谊的","ex":"Le Canada a joué un match amical contre la France samedi dernier.","exCn":"上周六，加拿大队与法国队踢了一场友谊赛。","th":"描述与状态"},{"w":"amicalement","p":"adv.","cn":"（写给朋友、熟人的信件和邮件结尾）祝好；友好地、友善地","ex":"J'ai bien reçu ton colis, merci beaucoup ! Amicalement, Julie","exCn":"你的包裹我收到了，非常感谢！祝好，朱莉","th":"人物与身份"},{"w":"ampoule","p":"n.f.","cn":"灯泡；水泡","ex":"Il faut changer l'ampoule de la cuisine.","exCn":"厨房的灯泡该换了。","th":"常用词"},{"w":"amélioration","p":"n.f.","cn":"改善、改进","ex":"La nouvelle version de l'application apporte de nombreuses améliorations.","exCn":"这款应用的新版本做了许多改进。","th":"常用词"},{"w":"améliorer","p":"v.","cn":"改善；改进","ex":"Il faut améliorer la qualité du service.","exCn":"需要改善服务质量。","th":"社会与新闻"},{"w":"aménager","p":"v.","cn":"改造、布置（空间）；调整（时间、规则）","ex":"Nous avons aménagé un petit bureau dans un coin du salon.","exCn":"我们在客厅一角布置了一个小书房。","th":"时间与数量"},{"w":"analyse","p":"n.f.","cn":"分析；（医）化验","ex":"Une analyse détaillée des résultats sera publiée le mois prochain.","exCn":"下个月将发布一份对结果的详细分析。","th":"健康与身体"},{"w":"analyser","p":"v.","cn":"分析","ex":"Le laboratoire va analyser votre échantillon de sang.","exCn":"实验室会化验您的血样。","th":"观点与论证"},{"w":"ancêtre","p":"n.","cn":"祖先；（喻）前身、鼻祖","ex":"Un de mes ancêtres est venu de Normandie pour s'installer au Québec en 1650.","exCn":"我的一位祖先1650年从诺曼底来到魁北克定居。","th":"常用词"},{"w":"anecdote","p":"n.f.","cn":"趣闻、轶事","ex":"Ce livre est plein d'anecdotes amusantes sur la vie des acteurs.","exCn":"这本书里满是演员生活中的趣闻。","th":"常用词"},{"w":"ange","p":"n.m.","cn":"天使；cf. être aux anges 高兴极了、乐不可支","ex":"Ta fille est un vrai ange : elle a dormi pendant tout le vol.","exCn":"你女儿真是个小天使，整个航程都在睡觉。","th":"情绪与性格"},{"w":"angle","p":"n.m.","cn":"角度；拐角、街角","ex":"La boulangerie se trouve à l'angle de la rue Saint-Denis et de la rue Rachel.","exCn":"面包店在圣德尼街和拉歇尔街的拐角处。","th":"出行与旅行"},{"w":"angoisse","p":"n.f.","cn":"焦虑、忧虑","ex":"Le soir, il est souvent pris d'angoisse sans raison.","exCn":"晚上他常常无缘无故地感到焦虑。","th":"情绪与性格"},{"w":"angoissé","p":"adj.","cn":"焦虑的、不安的","ex":"Il est toujours un peu angoissé quand ses enfants rentrent tard et ne répondent pas au téléphone.","exCn":"孩子们晚归又不接电话时，他总会有些焦虑不安。","th":"情绪与性格"},{"w":"animation","p":"n.f.","cn":"（组织的）文娱活动；（活动、节目的）主持；热闹、生气；动画","ex":"Une animation musicale est prévue tout l'après-midi sur la place du marché.","exCn":"整个下午市场广场上都安排了音乐活动。","th":"情绪与性格"},{"w":"animer","p":"v.","cn":"主持；使活跃、使有生气","ex":"Qui va animer la soirée de fin d'année ?","exCn":"年终晚会谁来主持？","th":"情绪与性格"},{"w":"annuel","p":"adj.","cn":"每年的、年度的","ex":"La cotisation annuelle au club est de cinquante dollars.","exCn":"俱乐部的年费是五十加元。","th":"时间与数量"},{"w":"annulation","p":"n.f.","cn":"取消、撤销","ex":"Toute annulation doit être signalée au moins 48 heures à l'avance.","exCn":"如需取消，必须至少提前48小时告知。","th":"常用词"},{"w":"anonyme","p":"adj.","cn":"匿名的；无名的、默默无闻的；cf. une société anonyme（SA）股份有限公司","ex":"La police a reçu un appel anonyme signalant un colis suspect dans la gare.","exCn":"警方接到一个匿名电话，称车站里有可疑包裹。","th":"工作与学习"},{"w":"anorak","p":"n.m.","cn":"（带风帽的）防风外套","ex":"Prends ton gros anorak, il va neiger.","exCn":"带上你那件厚防风外套，要下雪了。","th":"居住与环境"},{"w":"anormal","p":"adj.","cn":"不正常的、反常的","ex":"Il est anormal que les femmes soient encore moins payées que les hommes pour le même travail.","exCn":"女性做同样的工作，收入却仍比男性低，这很不正常。","th":"常用词"},{"w":"antenne","p":"n.f.","cn":"天线；（机构的）分支、办事处；（昆虫的）触角；cf. à l'antenne 正在播出（广播、电视）","ex":"Une nouvelle antenne de téléphonie mobile a été installée près de l'école, et certains parents s'inquiètent.","exCn":"学校附近新装了一座手机信号基站，一些家长很担心。","th":"时间与数量"},{"w":"antibiotique","p":"n.m.","cn":"抗生素","ex":"Il doit prendre des antibiotiques pendant une semaine.","exCn":"他得吃一个星期的抗生素。","th":"常用词"},{"w":"antipathique","p":"adj.","cn":"令人讨厌的、不讨喜的","ex":"Je trouve ce vendeur plutôt antipathique.","exCn":"我觉得这个店员挺讨人嫌的。","th":"情绪与性格"},{"w":"anxiété","p":"n.f.","cn":"焦虑、不安","ex":"Les examens provoquent chez lui une grande anxiété.","exCn":"考试让他非常焦虑。","th":"情绪与性格"},{"w":"apercevoir","p":"v.","cn":"看见、瞥见；（s'~）发觉、意识到","ex":"J'ai aperçu ton frère dans le métro ce matin.","exCn":"今天早上我在地铁里瞥见你哥哥了。","th":"常用词"},{"w":"apparaître","p":"v.","cn":"出现、显现；显得、看来","ex":"Les premiers symptômes sont apparus deux jours après le repas.","exCn":"吃完饭两天后，最初的症状出现了。","th":"常用词"},{"w":"apparemment","p":"adv.","cn":"看来、似乎","ex":"Apparemment, le magasin a fermé : il y a une affiche « À louer » sur la vitrine.","exCn":"那家店好像关门了，橱窗上贴着“招租”的告示。","th":"常用词"},{"w":"apparence","p":"n.f.","cn":"外表、外貌；表面、表象","ex":"Avec sa barbe, il a complètement changé d'apparence.","exCn":"留了胡子以后，他的样子全变了。","th":"常用词"},{"w":"appartenir","p":"v.","cn":"（~ à）属于","ex":"Cette maison appartient à mes grands-parents.","exCn":"这栋房子是我祖父母的。","th":"常用词"},{"w":"applaudir","p":"v.","cn":"鼓掌、喝彩；赞许、赞同","ex":"Les élèves ont applaudi très fort quand leur camarade a reçu le premier prix.","exCn":"同学获得一等奖时，学生们热烈鼓掌。","th":"饮食"},{"w":"applaudissements","p":"n.m.","cn":"掌声、喝彩","ex":"La pianiste a quitté la scène sous les applaudissements du public.","exCn":"钢琴家在观众的掌声中走下了舞台。","th":"饮食"},{"w":"appliquer","p":"v.","cn":"实施、应用、运用；涂、敷；（s'~ à）适用于","ex":"La nouvelle loi sera appliquée à partir du 1er janvier.","exCn":"新法律将于1月1日起实施。","th":"常用词"},{"w":"apprenant","p":"n.","cn":"学习者","ex":"Ce manuel de français s'adresse aux apprenants de niveau intermédiaire.","exCn":"这本法语教材面向中级水平的学习者。","th":"工作与学习"},{"w":"apprenti","p":"n.","cn":"学徒；新手、初学者","ex":"Le boulanger a engagé un apprenti pour l'aider le matin.","exCn":"面包师雇了一个学徒早上给他帮忙。","th":"描述与状态"},{"w":"apprentissage","p":"n.m.","cn":"学习；学徒培训","ex":"Pour un apprentissage efficace du français, il faut pratiquer un peu chaque jour.","exCn":"要想高效地学好法语，就得每天练一点。","th":"工作与学习"},{"w":"approprié","p":"adj.","cn":"合适的","ex":"Avec un traitement approprié, elle pourra reprendre la course à pied d'ici deux mois.","exCn":"只要治疗得当，她两个月内就能重新开始跑步。","th":"常用词"},{"w":"approuver","p":"v.","cn":"赞成、赞同；批准、通过","ex":"Je n'approuve pas sa décision d'abandonner ses études.","exCn":"我不赞成他放弃学业的决定。","th":"常用词"},{"w":"apprécier","p":"v.","cn":"欣赏、喜欢；重视、感激","ex":"Ses collègues l'apprécient pour sa patience et sa bonne humeur.","exCn":"同事们欣赏他的耐心和好脾气。","th":"情绪与性格"},{"w":"après-vente","p":"loc.","cn":"（service ~）售后（服务）","ex":"Appelez le service après-vente pour faire réparer l'appareil.","exCn":"请打电话给售后服务部门修理这台机器。","th":"常用词"},{"w":"arbitre","p":"n.","cn":"裁判；仲裁人、公断人","ex":"À seize ans, mon fils a réussi son examen d'arbitre et siffle déjà des matchs de jeunes.","exCn":"我儿子十六岁就通过了裁判考试，已经开始执法青少年比赛了。","th":"人物与身份"},{"w":"architecture","p":"n.f.","cn":"建筑、建筑学；结构、架构","ex":"Le Vieux-Québec a conservé une architecture ancienne remarquable.","exCn":"魁北克老城保留了出色的古建筑风貌。","th":"居住与环境"},{"w":"archéologue","p":"n.","cn":"考古学家","ex":"Les archéologues ont trouvé des objets romains.","exCn":"考古学家发现了一些古罗马时期的物品。","th":"常用词"},{"w":"argument","p":"n.m.","cn":"论据；理由","ex":"Son argument est clair, mais il reste incomplet.","exCn":"他的论据清楚，但不完整。","th":"观点与论证"},{"w":"arme","p":"n.f.","cn":"武器","ex":"Il est interdit d'entrer dans le stade avec une arme, même un simple couteau.","exCn":"禁止携带武器进入体育场，哪怕只是一把小刀。","th":"常用词"},{"w":"armée","p":"n.f.","cn":"军队","ex":"Son fils s'est engagé dans l'armée à dix-huit ans.","exCn":"他儿子十八岁就参军了。","th":"常用词"},{"w":"arrangement","p":"n.m.","cn":"安排、布置；协议","ex":"Le nouvel arrangement des meubles rend la pièce plus spacieuse.","exCn":"家具重新摆放后，房间显得更宽敞了。","th":"常用词"},{"w":"arranger","p":"v.","cn":"安排、布置；解决、处理（问题）；（~ qqn）对…方便、合适；（s'~）好转；（s'~ pour）设法","ex":"Mardi soir, ça t'arrange ? Sinon, on peut se voir mercredi.","exCn":"周二晚上你方便吗？不然我们周三见也行。","th":"描述与状态"},{"w":"arrogant","p":"adj.","cn":"傲慢的、自大的","ex":"Le nouveau directeur a un ton arrogant qui déplaît à ses employés.","exCn":"新主任说话语气傲慢，员工们都很反感。","th":"描述与状态"},{"w":"arrondi","p":"adj.","cn":"圆形的、圆的；（数字）凑整的","ex":"Cette table a des angles arrondis.","exCn":"这张桌子是圆角的。","th":"时间与数量"},{"w":"arroser","p":"v.","cn":"浇水、浇灌；（口语）喝酒庆祝","ex":"N'oublie pas d'arroser les plantes pendant mon absence.","exCn":"我不在的时候别忘了给植物浇水。","th":"饮食"},{"w":"artifice","p":"n.m.","cn":"（feu d'~）烟火、焰火；手法、诡计","ex":"Le feu d'artifice du 1er juillet a attiré des milliers de personnes.","exCn":"7月1日的烟火表演吸引了成千上万的人。","th":"常用词"},{"w":"artificiel","p":"adj.","cn":"人造的、人工的；做作的、不自然的；cf. l'intelligence artificielle（IA）人工智能","ex":"Ce yaourt ne contient ni colorants ni arômes artificiels.","exCn":"这种酸奶不含色素，也不含人工香料。","th":"人物与身份"},{"w":"artisan","p":"n.","cn":"手艺人、工匠","ex":"Cet artisan fabrique des meubles à la main.","exCn":"这位工匠手工制作家具。","th":"人物与身份"},{"w":"aspect","p":"n.m.","cn":"方面；外观、外表","ex":"Il faut aussi tenir compte de l'aspect financier du projet.","exCn":"还必须考虑这个项目的财务方面。","th":"常用词"},{"w":"assassin","p":"n.m.","cn":"凶手、杀人犯；刺客","ex":"La police n'a toujours pas retrouvé l'assassin du jeune commerçant.","exCn":"警方仍未找到杀害那位年轻商人的凶手。","th":"人物与身份"},{"w":"assemblée","p":"n.f.","cn":"大会、集会；议会","ex":"L'assemblée générale des copropriétaires aura lieu jeudi soir.","exCn":"共管公寓业主大会将于周四晚上举行。","th":"描述与状态"},{"w":"assistance","p":"n.f.","cn":"帮助、援助；（全体）在场者、观众","ex":"Mon assurance voyage comprend une assistance médicale gratuite en cas d'accident à l'étranger.","exCn":"我的旅行保险包含在国外发生意外时的免费医疗救助。","th":"常用词"},{"w":"association","p":"n.f.","cn":"协会、社团；联合、联想","ex":"Les parents d'élèves ont créé une association pour organiser la fête de fin d'année.","exCn":"学生家长们成立了一个协会，负责筹办学年末的联欢活动。","th":"社会与新闻"},{"w":"associer","p":"v.","cn":"把…联系起来、联想；（s'~）联合、合伙","ex":"On associe souvent le Canada au froid et à la neige.","exCn":"人们常常把加拿大和寒冷、大雪联系在一起。","th":"常用词"},{"w":"assurer","p":"v.","cn":"确保、保证；承担、负责；给…上保险；（口语）表现出色、很行；cf. s'assurer que 确认、核实","ex":"Je vous assure que le colis arrivera avant vendredi.","exCn":"我向您保证，包裹周五之前会到。","th":"常用词"},{"w":"asthme","p":"n.m.","cn":"哮喘","ex":"Elle fait une crise d'asthme quand elle court trop vite.","exCn":"她跑得太快就会哮喘发作。","th":"常用词"},{"w":"astronaute","p":"n.","cn":"宇航员","ex":"Un astronaute canadien a passé six mois à bord de la Station spatiale internationale.","exCn":"一名加拿大宇航员在国际空间站上待了六个月。","th":"常用词"},{"w":"astuce","p":"n.f.","cn":"窍门、诀窍；机灵、精明","ex":"Voici une astuce simple pour économiser de l'électricité en hiver.","exCn":"这里有一个冬天省电的简单窍门。","th":"常用词"},{"w":"athlète","p":"n.","cn":"运动员","ex":"L'ancienne athlète paralympique donne maintenant des conférences sur la persévérance dans les écoles.","exCn":"这位前残奥会女运动员如今在各所学校举办讲座，讲述坚持不懈的意义。","th":"常用词"},{"w":"atlantique","p":"adj.","cn":"大西洋的","ex":"Halifax est un grand port de la côte atlantique du Canada.","exCn":"哈利法克斯是加拿大大西洋沿岸的一个大港口。","th":"描述与状态"},{"w":"atmosphère","p":"n.f.","cn":"大气层；气氛","ex":"En rentrant dans l'atmosphère, la capsule spatiale chauffe à plus de mille cinq cents degrés.","exCn":"返回舱重返大气层时，温度会升到一千五百多度。","th":"描述与状态"},{"w":"attaché","p":"n.","cn":"（~ à）依恋…的、看重…的；专员、随员","ex":"Je suis très attaché à ma ville natale.","exCn":"我非常眷恋我的家乡。","th":"描述与状态"},{"w":"attaque","p":"n.f.","cn":"进攻、攻击；（疾病）发作","ex":"Le site Internet de la banque a subi une attaque informatique massive.","exCn":"这家银行的网站遭到了大规模网络攻击。","th":"健康与身体"},{"w":"attaquer","p":"v.","cn":"攻击、袭击；抨击、指责；（s'~ à）着手解决（难题）","ex":"Un ours a attaqué un randonneur dans le parc national.","exCn":"一头熊在国家公园里袭击了一名徒步者。","th":"常用词"},{"w":"atteindre","p":"v.","cn":"达到、抵达、触及","ex":"L'entreprise a atteint ses objectifs de vente dès le mois de septembre.","exCn":"公司早在九月就完成了销售目标。","th":"常用词"},{"w":"attentif","p":"adj.","cn":"专心的、注意的；关心的、体贴的","ex":"Tu dois être plus attentif en classe.","exCn":"你上课得更专心一点。","th":"常用词"},{"w":"attentivement","p":"adv.","cn":"仔细地、专心地","ex":"Le mécanicien a examiné attentivement le moteur avant de donner son prix.","exCn":"修车师傅仔细检查了发动机，才报了价。","th":"常用词"},{"w":"atterrir","p":"v.","cn":"（飞机）着陆、降落","ex":"Notre vol a atterri avec quarante minutes d'avance, mais nos valises ont mis une heure à arriver.","exCn":"我们的航班提前四十分钟落地，可行李却过了一个小时才出来。","th":"出行与旅行"},{"w":"atterrissage","p":"n.m.","cn":"着陆、降落","ex":"Le pilote a réussi un atterrissage d'urgence dans un champ.","exCn":"飞行员在一片田地里成功紧急迫降。","th":"常用词"},{"w":"attestation","p":"n.f.","cn":"证明、证明书","ex":"Mon employeur m'a remis une attestation de travail.","exCn":"雇主给我开了一份在职证明。","th":"观点与论证"},{"w":"attirer","p":"v.","cn":"吸引、引起（注意等）；招致、惹来（麻烦等）","ex":"Le festival de jazz attire chaque année des milliers de touristes à Montréal.","exCn":"爵士音乐节每年吸引成千上万的游客来到蒙特利尔。","th":"常用词"},{"w":"attitude","p":"n.f.","cn":"态度；姿态","ex":"Ton attitude en classe doit changer, sinon tu seras puni.","exCn":"你上课的态度得改改了，不然要受罚。","th":"常用词"},{"w":"attraction","p":"n.f.","cn":"吸引、吸引力；景点、游乐项目","ex":"Il a toujours ressenti une forte attraction pour la mer.","exCn":"他一直被大海深深吸引。","th":"工作与学习"},{"w":"auditeur","p":"n.","cn":"（广播）听众；审计员","ex":"Cette émission a beaucoup d'auditeurs fidèles.","exCn":"这个节目有很多忠实听众。","th":"常用词"},{"w":"augmentation","p":"n.f.","cn":"增加、增长；加薪","ex":"On observe une forte augmentation du nombre de cyclistes en ville.","exCn":"城里骑自行车的人数大幅增加。","th":"描述与状态"},{"w":"auparavant","p":"adv.","cn":"以前、先前","ex":"Il habitait auparavant à Toronto, mais il s'est installé à Montréal l'an dernier.","exCn":"他以前住在多伦多，去年搬到了蒙特利尔。","th":"常用词"},{"w":"auprès","p":"prép.","cn":"（~ de）在…身边；（~ de）向、对（某人）","ex":"Elle est restée auprès de son père malade.","exCn":"她守在生病的父亲身边。","th":"人物与身份"},{"w":"auquel","p":"pron.","cn":"（关系代词，= à + lequel）…的那个；（疑问）哪一个","ex":"C'est le concours auquel je me suis inscrit l'an dernier.","exCn":"这就是我去年报名参加的那个比赛。","th":"功能词与连接"},{"w":"aussitôt","p":"adv.","cn":"随即、立刻","ex":"Le médecin est arrivé et a aussitôt examiné le blessé.","exCn":"医生到了以后，随即给伤者做了检查。","th":"时间与数量"},{"w":"autant","p":"adv.","cn":"（~ que）一样多、一样（修饰动词）；（~ de + 名词）同样多的…；（~ + 不定式）还不如…；cf. d'autant plus que 更何况、尤其因为","ex":"Elle a autant de travail que son mari, mais elle gagne deux fois moins.","exCn":"她的工作量和丈夫一样多，工资却只有他的一半。","th":"功能词与连接"},{"w":"authentique","p":"adj.","cn":"真正的、正宗的；真诚的、不做作的","ex":"Ce restaurant propose une cuisine italienne authentique, préparée par un chef de Naples.","exCn":"这家餐厅供应正宗的意大利菜，由一位那不勒斯厨师掌勺。","th":"常用词"},{"w":"auto-stop","p":"n.m.","cn":"搭便车；cf.（魁北克）faire du pouce 搭便车","ex":"Ils ont traversé la France en auto-stop.","exCn":"他们搭便车穿越了法国。","th":"出行与旅行"},{"w":"automatique","p":"adj.","cn":"自动的","ex":"La porte automatique s'ouvre dès qu'on s'approche.","exCn":"人一走近，自动门就会打开。","th":"常用词"},{"w":"automatiquement","p":"adv.","cn":"自动地；必然、理所当然地","ex":"Si vous ne payez pas avant le 15, des frais de retard seront automatiquement ajoutés à votre facture.","exCn":"如果您在15号之前没有付款，滞纳金将自动计入您的账单。","th":"常用词"},{"w":"automobile","p":"n.f.","cn":"汽车；汽车工业；汽车的","ex":"Au début du XXe siècle, une automobile coûtait une fortune.","exCn":"在二十世纪初，一辆汽车的价格高得惊人。","th":"出行与旅行"},{"w":"automobiliste","p":"n.","cn":"驾车者、司机","ex":"Les automobilistes doivent ralentir près des écoles.","exCn":"驾车者在学校附近必须减速。","th":"出行与旅行"},{"w":"autoradio","p":"n.m.","cn":"车载收音机","ex":"L'autoradio de ma voiture est tombé en panne.","exCn":"我车上的收音机坏了。","th":"出行与旅行"},{"w":"autorisation","p":"n.f.","cn":"许可、批准","ex":"Les élèves ne peuvent pas quitter l'école sans autorisation.","exCn":"学生未经许可不得离开学校。","th":"常用词"},{"w":"autoriser","p":"v.","cn":"授权、允许","ex":"Mes parents ne m'autorisaient pas à sortir après dix heures du soir.","exCn":"我父母以前不允许我晚上十点以后出门。","th":"常用词"},{"w":"autoritaire","p":"adj.","cn":"专横的、霸道的；（政权）专制的、威权的","ex":"Son père était très autoritaire avec ses enfants.","exCn":"他父亲对孩子们非常专横。","th":"常用词"},{"w":"autorité","p":"n.f.","cn":"权威、权力；（复数）当局","ex":"Les autorités ont demandé aux habitants de rester chez eux pendant la tempête de verglas.","exCn":"当局要求居民在冰雨风暴期间待在家里。","th":"常用词"},{"w":"autrefois","p":"adv.","cn":"从前、过去","ex":"Autrefois, les gens voyageaient à cheval.","exCn":"从前人们骑马出行。","th":"时间与数量"},{"w":"autrement","p":"adv.","cn":"否则；以别的方式、不同地；cf. autrement dit 换句话说、也就是说","ex":"Pars maintenant, autrement tu vas rater ton train.","exCn":"现在就出发，不然你会赶不上火车。","th":"功能词与连接"},{"w":"autrement dit","p":"loc.","cn":"换言之","ex":"Autrement dit, il n'y a pas de solution simple.","exCn":"换言之，没有简单的解决办法。","th":"观点与论证"},{"w":"avaler","p":"v.","cn":"吞、咽；（口语）轻信（谎话）","ex":"Avalez ce comprimé avec un grand verre d'eau, de préférence pendant le repas.","exCn":"这片药请用一大杯水送服，最好在吃饭时服用。","th":"描述与状态"},{"w":"avancé","p":"adj.","cn":"（水平）高级的、（技术）先进的；（时间、阶段）较晚的、后期的","ex":"Les voisins ont fait la fête jusqu'à une heure avancée de la nuit.","exCn":"邻居们一直开派对到深夜。","th":"时间与数量"},{"w":"avant que","p":"conj.","cn":"（+ 虚拟式）在…之前；cf. avant de + 不定式（前后主语相同时）；书面语常加虚词 ne：avant qu'il ne parte","ex":"Rentrons avant qu'il pleuve.","exCn":"趁还没下雨，我们回家吧。","th":"常用词"},{"w":"aventurier","p":"n.","cn":"冒险家、探险者；爱冒险的","ex":"Cet aventurier a traversé l'Atlantique à la rame.","exCn":"这位探险家划船横渡了大西洋。","th":"情绪与性格"},{"w":"averse","p":"n.f.","cn":"阵雨","ex":"Surpris par une grosse averse, nous nous sommes abrités sous un porche.","exCn":"我们突然碰上一场大阵雨，赶紧躲到了门廊下。","th":"居住与环境"},{"w":"avertir","p":"v.","cn":"提醒、警告、通知","ex":"Avertissez-moi si vous ne pouvez pas venir à la réunion.","exCn":"如果您不能来开会，请通知我一声。","th":"常用词"},{"w":"avertissement","p":"n.m.","cn":"警告、提醒","ex":"Après plusieurs retards, l'employé a reçu un avertissement écrit.","exCn":"多次迟到之后，这名员工收到了书面警告。","th":"常用词"},{"w":"aveugle","p":"n.","cn":"瞎的、失明的；盲人","ex":"Mon grand-père est devenu aveugle à cause d'une maladie des yeux.","exCn":"我祖父因为一种眼疾失明了。","th":"人物与身份"},{"w":"avouer","p":"v.","cn":"承认；招供、坦白","ex":"J'avoue que je n'ai pas encore lu le rapport.","exCn":"我承认我还没看那份报告。","th":"描述与状态"},{"w":"aérer","p":"v.","cn":"使通风、给…换气；（s'~）透透气、散散心","ex":"Ouvre la fenêtre pour aérer la chambre dix minutes chaque matin.","exCn":"每天早上开窗给卧室通风十分钟。","th":"居住与环境"},{"w":"aérien","p":"adj.","cn":"航空的、空中的","ex":"Cette photo aérienne, prise par un drone, montre tout le centre-ville.","exCn":"这张由无人机拍的航拍照片拍下了整个市中心。","th":"描述与状态"},{"w":"aérobic","p":"n.m.","cn":"有氧操、健美操","ex":"Elle fait de l'aérobic deux fois par semaine.","exCn":"她每周做两次有氧操。","th":"常用词"},{"w":"aîné","p":"n.","cn":"老大（长子、长女）；（复数）老年人、长者（加拿大常用）；年长的","ex":"Au Québec, de nombreux services sont offerts aux aînés qui vivent seuls.","exCn":"在魁北克，独居长者可以享受许多服务。","th":"人物与身份"},{"w":"baccalauréat","p":"n.m.","cn":"（法国）高中毕业会考、高中文凭；（魁北克）学士学位；cf. le bac（口语简称）","ex":"En France, le baccalauréat permet d'entrer à l'université.","exCn":"在法国，拿到高中毕业文凭就可以上大学。","th":"工作与学习"},{"w":"badge","p":"n.m.","cn":"工牌、门禁卡；徽章","ex":"J'ai oublié mon badge, alors l'agent de sécurité a dû m'ouvrir la porte.","exCn":"我忘带门禁卡了，保安只好帮我开门。","th":"购物与金钱"},{"w":"bagarre","p":"n.f.","cn":"打架、斗殴","ex":"Une bagarre a éclaté à la sortie du bar vers deux heures du matin.","exCn":"凌晨两点左右，酒吧门口爆发了一场斗殴。","th":"常用词"},{"w":"bagnole","p":"n.f.","cn":"汽车、车（口语）","ex":"Sa vieille bagnole tombe en panne tous les mois.","exCn":"他那辆破车每个月都要抛锚。","th":"出行与旅行"},{"w":"bah","p":"interj.","cn":"嗨、唉（表无所谓，口语）；呃、这个嘛（表犹豫，口语）","ex":"— Tu as raté ton bus ? — Bah, j'en prendrai un autre dans dix minutes.","exCn":"——你没赶上公交车？——嗨，十分钟后再坐下一班就是了。","th":"常用词"},{"w":"bail","p":"n.m.","cn":"租约、租赁合同；cf. ça fait un bail（口语）好久没…了、好久不见","ex":"Nous avons signé un bail de trois ans.","exCn":"我们签了一份三年的租约。","th":"购物与金钱"},{"w":"baiser","p":"n.m.","cn":"吻；动词 baiser 现在是粗话（指发生性关系），「亲吻」要用 embrasser","ex":"Elle a déposé un baiser sur le front de son fils avant de partir.","exCn":"出门前，她在儿子的额头上亲了一下。","th":"时间与数量"},{"w":"baisse","p":"n.f.","cn":"下降、下跌","ex":"Vers quinze heures, je ressens toujours une grosse baisse d'énergie.","exCn":"一到下午三点左右，我总觉得精力一下子降了下来。","th":"常用词"},{"w":"bal","p":"n.m.","cn":"舞会","ex":"Le soir du 14 juillet, il y a un bal populaire sur la place de la mairie.","exCn":"7月14日晚上，市政厅广场上有一场民众舞会。","th":"常用词"},{"w":"balader","p":"v.","cn":"（se ~）散步、溜达；带…散步、遛（狗）","ex":"Nous nous sommes baladés dans le Vieux-Québec tout l'après-midi.","exCn":"我们在魁北克老城逛了一下午。","th":"出行与旅行"},{"w":"balai","p":"n.m.","cn":"扫帚","ex":"Peux-tu passer un coup de balai dans la cuisine ?","exCn":"你能把厨房扫一下吗？","th":"常用词"},{"w":"balance","p":"n.f.","cn":"秤；（贸易、收支）差额","ex":"À l'aéroport, j'ai posé ma valise sur la balance : elle pesait 25 kilos.","exCn":"在机场，我把行李箱放到秤上一称：足有25公斤。","th":"常用词"},{"w":"balayer","p":"v.","cn":"扫、打扫；清除、打消（疑虑等）","ex":"Avant de prendre la route, il faut balayer la neige sur le toit de la voiture.","exCn":"上路之前，得把车顶上的雪扫掉。","th":"日常动作"},{"w":"baleine","p":"n.f.","cn":"鲸鱼","ex":"À Tadoussac, on peut observer les baleines de juin à octobre.","exCn":"在塔杜萨克，六月到十月都可以观鲸。","th":"饮食"},{"w":"ballet","p":"n.m.","cn":"芭蕾舞","ex":"Pour Noël, nous sommes allés voir le ballet Casse-Noisette.","exCn":"圣诞节时，我们去看了芭蕾舞剧《胡桃夹子》。","th":"常用词"},{"w":"banal","p":"adj.","cn":"平常的、平淡无奇的","ex":"Pour les jeunes, payer avec son téléphone est devenu tout à fait banal.","exCn":"对年轻人来说，用手机付款已经再平常不过了。","th":"常用词"},{"w":"bandage","p":"n.m.","cn":"绷带；包扎","ex":"L'infirmière lui a fait un bandage autour du genou.","exCn":"护士给他的膝盖做了包扎。","th":"常用词"},{"w":"bande","p":"n.f.","cn":"一伙（人）、一帮；带子、条；cf. la bande dessinée（BD）漫画；la bande-annonce（电影）预告片","ex":"J'ai une super bande de copains.","exCn":"我有一群超棒的伙伴。","th":"人物与身份"},{"w":"banquier","p":"n.","cn":"银行家；（个人的）银行客户经理","ex":"Son grand-père était un riche banquier de Montréal.","exCn":"他的祖父是蒙特利尔一位富有的银行家。","th":"购物与金钱"},{"w":"barbu","p":"adj.","cn":"有胡子的、留胡须的","ex":"Son père est grand, barbu et très gentil.","exCn":"他父亲个子高高的，留着胡子，人很和善。","th":"常用词"},{"w":"barre","p":"n.f.","cn":"杆、棒；（巧克力、谷物等的）条；（数值）大关、门槛；cf. le bar = 酒吧","ex":"Dans le métro, tenez-vous bien à la barre.","exCn":"乘坐地铁时，请抓牢扶杆。","th":"饮食"},{"w":"barrière","p":"n.f.","cn":"栅栏、栏杆；障碍、壁垒","ex":"La barrière du parking se lève dès qu'on insère son ticket.","exCn":"一插入停车票，停车场的栏杆就会抬起。","th":"常用词"},{"w":"baser","p":"v.","cn":"（~ qqch sur）以…为基础；（se ~ sur）依据、凭；（être basé à）总部设在","ex":"Sur quoi est-ce que tu te bases pour dire ça ?","exCn":"你凭什么这么说？","th":"常用词"},{"w":"bataille","p":"n.f.","cn":"战役、战斗；斗争、较量","ex":"La bataille des plaines d'Abraham a eu lieu en 1759, près de Québec.","exCn":"亚伯拉罕平原战役于1759年发生在魁北克城附近。","th":"常用词"},{"w":"batterie","p":"n.f.","cn":"电池、蓄电池；（乐）架子鼓","ex":"La batterie de ma voiture est à plat à cause du froid.","exCn":"天太冷，我的汽车电瓶没电了。","th":"常用词"},{"w":"battu","p":"adj.","cn":"被打败的；被殴打的","ex":"L'équipe battue a quitté le terrain en silence.","exCn":"被打败的球队默默离开了球场。","th":"常用词"},{"w":"beau-fils","p":"n.m.","cn":"继子；女婿","ex":"Il s'entend bien avec son beau-fils de dix ans.","exCn":"他和十岁的继子相处得很好。","th":"人物与身份"},{"w":"beaux-arts","p":"n.m.","cn":"美术；（les Beaux-Arts）美术学院","ex":"Nous avons visité le musée des Beaux-Arts de Lyon.","exCn":"我们参观了里昂美术馆。","th":"常用词"},{"w":"belle-famille","p":"n.f.","cn":"配偶的家人（婆家、岳家）","ex":"La première rencontre avec sa future belle-famille l'a beaucoup stressé.","exCn":"第一次见未来的岳家人，让他压力很大。","th":"人物与身份"},{"w":"belle-fille","p":"n.f.","cn":"儿媳；继女","ex":"Ma belle-fille attend son deuxième enfant.","exCn":"我儿媳正怀着第二个孩子。","th":"人物与身份"},{"w":"berger","p":"n.","cn":"牧羊人；（~ allemand）德国牧羊犬","ex":"Chaque été, le berger monte avec ses moutons dans les alpages.","exCn":"每年夏天，牧羊人都会赶着羊群上高山牧场。","th":"人物与身份"},{"w":"bermuda","p":"n.m.","cn":"及膝短裤、百慕大短裤","ex":"En été, il porte toujours un bermuda.","exCn":"夏天他总穿一条及膝短裤。","th":"时间与数量"},{"w":"biberon","p":"n.m.","cn":"奶瓶","ex":"C'est le père qui donne le biberon au bébé.","exCn":"是爸爸用奶瓶给宝宝喂奶。","th":"常用词"},{"w":"bien que","p":"conj.","cn":"尽管（+虚拟式）","ex":"Bien qu'il soit cher, cet appartement est agréable.","exCn":"虽然贵，这套公寓住着舒服。","th":"观点与论证"},{"w":"bien à vous","p":"loc.","cn":"（信件、邮件结尾）此致、谨上（比 Cordialement 略显亲切）","ex":"Je vous confirme ma présence à la réunion de jeudi. Bien à vous, Claire Martin","exCn":"我确认会参加周四的会议。此致，克莱尔 · 马丁","th":"日常动作"},{"w":"bienvenu","p":"adj.","cn":"受欢迎的；来得正好的；cf. Bienvenue ! 欢迎！（魁北克也用来回答 merci，表示「不客气」）；souhaiter la bienvenue à qqn 向某人表示…","ex":"Vous êtes toujours bienvenus chez nous, passez quand vous voulez.","exCn":"随时欢迎你们来我们家，想来就来。","th":"人物与身份"},{"w":"bilan","p":"n.m.","cn":"总结、盘点；（灾难的）伤亡人数；（~ de santé）全面体检","ex":"À la fin de l'année, l'entreprise fait le bilan de ses activités.","exCn":"年底公司会对全年业务进行总结。","th":"健康与身体"},{"w":"billard","p":"n.m.","cn":"台球；台球桌；cf. passer sur le billard 上手术台（口语）","ex":"Mon oncle joue au billard comme un professionnel.","exCn":"我叔叔打台球打得跟职业选手一样。","th":"健康与身体"},{"w":"bille","p":"n.f.","cn":"弹珠、玻璃球；滚珠","ex":"Quand j'étais petit, j'échangeais mes billes avec les copains de l'école.","exCn":"小时候，我常和学校的小伙伴交换弹珠。","th":"常用词"},{"w":"biographie","p":"n.f.","cn":"传记","ex":"Cette journaliste a consacré trois ans à écrire une biographie de René Lévesque.","exCn":"这位记者花了三年时间撰写勒内 · 莱维斯克的传记。","th":"常用词"},{"w":"biologie","p":"n.f.","cn":"生物学","ex":"Elle étudie la biologie marine à l'université et rêve de travailler sur les baleines.","exCn":"她在大学学习海洋生物学，梦想将来研究鲸鱼。","th":"常用词"},{"w":"biologique","p":"adj.","cn":"生物（学）的；有机的","ex":"De plus en plus d'agriculteurs se tournent vers l'agriculture biologique.","exCn":"越来越多的农民转向有机农业。","th":"常用词"},{"w":"bizarrement","p":"adv.","cn":"奇怪地","ex":"Bizarrement, ce restaurant est toujours vide alors que la cuisine est excellente.","exCn":"奇怪的是，这家餐厅菜做得很好，却总是没什么客人。","th":"常用词"},{"w":"blessure","p":"n.f.","cn":"伤、伤口；（心灵）创伤","ex":"Le joueur souffre d'une blessure au genou et manquera trois matchs.","exCn":"这名球员膝盖受伤，将缺席三场比赛。","th":"健康与身体"},{"w":"blessé","p":"n.","cn":"受伤的；（感情上）受伤害的；伤者、伤员","ex":"Elle s'est sentie blessée par la remarque de son collègue sur son travail.","exCn":"同事对她工作的那番评论让她很受伤。","th":"健康与身体"},{"w":"bloquer","p":"v.","cn":"堵住、阻挡；（使）卡住、动不了；冻结（账户、价格）；（社交网络上）拉黑","ex":"Des manifestants ont bloqué le pont pendant deux heures.","exCn":"示威者把桥堵了两个小时。","th":"购物与金钱"},{"w":"blouse","p":"n.f.","cn":"工作服、白大褂；女式衬衫","ex":"Au laboratoire, il faut porter une blouse blanche et des lunettes de protection.","exCn":"在实验室里必须穿白大褂、戴护目镜。","th":"工作与学习"},{"w":"blé","p":"n.m.","cn":"小麦；钱（俚语）；（~ d'Inde）玉米（魁北克）","ex":"Le Canada est l'un des plus grands producteurs de blé au monde.","exCn":"加拿大是世界上最大的小麦生产国之一。","th":"购物与金钱"},{"w":"bombe","p":"n.f.","cn":"炸弹；（喷漆、发胶等）喷雾罐；大美女、尤物（口语）","ex":"L'annonce de leur divorce a fait l'effet d'une bombe dans la famille.","exCn":"他们要离婚的消息在家里犹如投下了一颗炸弹。","th":"人物与身份"},{"w":"bonhomme","p":"n.m.","cn":"（图画、信号灯上的）小人；家伙、老头儿（口语）；cf. bonhomme de neige 雪人","ex":"C'est un drôle de bonhomme, notre voisin : il tond sa pelouse à six heures du matin.","exCn":"我们的邻居真是个怪家伙：早上六点就修剪草坪。","th":"人物与身份"},{"w":"bonté","p":"n.f.","cn":"善良、仁慈","ex":"Je n'oublierai jamais la bonté de cette famille qui m'a accueilli à mon arrivée au Canada.","exCn":"我刚到加拿大时，那户人家收留了我，他们的善良我永远不会忘记。","th":"常用词"},{"w":"bordeaux","p":"n.m.","cn":"波尔多葡萄酒；酒红色的","ex":"Ce bordeaux est encore un peu jeune ; il vaut mieux le garder quelques années en cave.","exCn":"这瓶波尔多还有点年轻，最好在酒窖里再存几年。","th":"饮食"},{"w":"bosser","p":"v.","cn":"干活、工作（口语）；用功、苦读（口语）","ex":"Je bosse dans un resto le week-end pour payer mon loyer.","exCn":"我周末在一家餐馆打工交房租。","th":"工作与学习"},{"w":"bouchon","p":"n.m.","cn":"瓶塞、盖子；交通堵塞","ex":"Je n'arrive pas à enlever le bouchon de la bouteille.","exCn":"我拔不出瓶塞。","th":"出行与旅行"},{"w":"bouché","p":"adj.","cn":"堵塞的、不通的；（前途）渺茫的；笨、脑子不开窍（口语）","ex":"Tous les soirs, l'autoroute est bouchée à la sortie de la ville.","exCn":"每天晚上，出城方向的高速公路都堵得水泄不通。","th":"常用词"},{"w":"boucle","p":"n.f.","cn":"环、圈；（en ~）循环；（头发的）卷儿；（~ d'oreille）耳环","ex":"Cette chanson passe en boucle à la radio depuis une semaine.","exCn":"这首歌一周来一直在电台循环播放。","th":"常用词"},{"w":"boue","p":"n.f.","cn":"泥、泥浆","ex":"Le sentier était plein de boue après l'orage, et nous avons glissé plusieurs fois.","exCn":"雷雨过后，小路上全是泥，我们滑倒了好几次。","th":"常用词"},{"w":"bouilloire","p":"n.f.","cn":"烧水壶、电水壶","ex":"Je fais chauffer de l'eau dans la bouilloire pour le thé.","exCn":"我用水壶烧水泡茶。","th":"常用词"},{"w":"bourse","p":"n.f.","cn":"奖学金；（la Bourse）证券交易所、股市","ex":"Elle a obtenu une bourse pour étudier au Canada.","exCn":"她获得了去加拿大留学的奖学金。","th":"常用词"},{"w":"boxeur","p":"n.","cn":"拳击手","ex":"Le boxeur a mis son adversaire K.-O. au troisième round.","exCn":"这名拳击手在第三回合把对手击倒了。","th":"常用词"},{"w":"branche","p":"n.f.","cn":"树枝；分支、部门；行业、领域","ex":"La tempête a cassé plusieurs branches de l'érable devant chez nous.","exCn":"暴风雨折断了我们家门前那棵枫树的好几根树枝。","th":"居住与环境"},{"w":"brancher","p":"v.","cn":"接通、插上（电源）；使感兴趣（口语）；（se ~）拿定主意（魁北克口语）","ex":"On va voir un film d'horreur ce soir, ça te branche ?","exCn":"今晚我们去看恐怖片，你有兴趣吗？","th":"常用词"},{"w":"brave","p":"adj.","cn":"勇敢的；（置于名词前）善良的、老实的","ex":"C'est une femme brave qui n'a jamais eu peur de dénoncer l'injustice.","exCn":"她是一位勇敢的女性，从不畏惧揭露不公。","th":"情绪与性格"},{"w":"bref","p":"adj.","cn":"简短的、短暂的；总之、简言之","ex":"Après une brève pause, la réunion a repris.","exCn":"短暂休息后，会议继续进行。","th":"描述与状态"},{"w":"brevet","p":"n.m.","cn":"专利；证书、执照；（法国）初中毕业文凭","ex":"L'entreprise a déposé un brevet pour sa nouvelle batterie.","exCn":"公司为其新型电池申请了专利。","th":"工作与学习"},{"w":"bricolage","p":"n.m.","cn":"自己动手修理制作；（儿童）手工；凑合之作","ex":"Ce magasin de bricolage vend tout ce qu'il faut pour rénover une maison.","exCn":"这家五金建材店卖翻修房子需要的所有东西。","th":"常用词"},{"w":"bricoler","p":"v.","cn":"自己动手修修弄弄；凑合着修","ex":"Le dimanche, il aime bricoler dans son garage.","exCn":"周日他喜欢在车库里修修弄弄。","th":"常用词"},{"w":"brillant","p":"adj.","cn":"闪亮的；出色的、才华出众的","ex":"Après le nettoyage, le parquet était brillant comme un miroir.","exCn":"打扫过后，木地板亮得像镜子一样。","th":"描述与状态"},{"w":"briller","p":"v.","cn":"发光、闪耀；出众、表现出色","ex":"Le soleil brillait sur la neige fraîche.","exCn":"阳光照在新雪上，闪闪发光。","th":"常用词"},{"w":"brique","p":"n.f.","cn":"砖、砖块；（饮料）纸盒","ex":"À Montréal, beaucoup de vieux immeubles sont construits en brique rouge.","exCn":"在蒙特利尔，很多老楼都是红砖砌的。","th":"常用词"},{"w":"briquet","p":"n.m.","cn":"打火机","ex":"Tu as un briquet ? Je n'arrive pas à allumer le barbecue.","exCn":"你有打火机吗？我点不着烧烤炉。","th":"常用词"},{"w":"briser","p":"v.","cn":"打碎、打破","ex":"Pendant la tempête, le vent a brisé la vitre de la cuisine.","exCn":"暴风雨中，大风打碎了厨房的窗玻璃。","th":"常用词"},{"w":"bronchite","p":"n.f.","cn":"支气管炎","ex":"Le médecin dit que j'ai une bronchite.","exCn":"医生说我得了支气管炎。","th":"常用词"},{"w":"bronze","p":"n.m.","cn":"青铜；铜牌","ex":"Une statue en bronze se dresse au milieu de la place.","exCn":"广场中央矗立着一座青铜雕像。","th":"常用词"},{"w":"bronzé","p":"adj.","cn":"晒黑的、古铜色的","ex":"Tu es tout bronzé ! Tu reviens de vacances ?","exCn":"你晒得好黑！刚度假回来吗？","th":"描述与状态"},{"w":"brouillon","p":"n.m.","cn":"草稿、底稿","ex":"Fais d'abord un brouillon avant d'écrire ta lettre.","exCn":"写信前先打个草稿。","th":"常用词"},{"w":"brut","p":"adj.","cn":"（金额）税前的、毛的；未加工的、天然的","ex":"Mon salaire brut est de 3 000 euros par mois.","exCn":"我的税前月薪是3000欧元。","th":"时间与数量"},{"w":"brutal","p":"adj.","cn":"粗暴的、野蛮的；突然的、急剧的","ex":"Le témoin a décrit une agression brutale en pleine rue.","exCn":"目击者描述了一起当街发生的野蛮袭击。","th":"常用词"},{"w":"brûlant","p":"adj.","cn":"滚烫的、灼热的；（话题）敏感的、热点的","ex":"Attention, la soupe est brûlante !","exCn":"小心，汤很烫！","th":"居住与环境"},{"w":"budget","p":"n.m.","cn":"预算","ex":"Nous cherchons un appartement de deux chambres, mais notre budget est limité.","exCn":"我们在找一套两居室，但预算有限。","th":"购物与金钱"},{"w":"bulle","p":"n.f.","cn":"气泡、泡泡；（经济）泡沫","ex":"Les enfants s'amusent à faire des bulles de savon dans le jardin.","exCn":"孩子们在花园里吹肥皂泡玩。","th":"社会与新闻"},{"w":"bulletin","p":"n.m.","cn":"（新闻、天气等）简报、公报；（~ scolaire）成绩单；（~ de vote）选票","ex":"J'écoute le bulletin météo tous les matins.","exCn":"我每天早上都听天气预报。","th":"出行与旅行"},{"w":"but","p":"n.m.","cn":"目的、目标；（足球等）球门、进球；cf. dans le but de 为了、以便","ex":"Quel est le but de votre voyage ?","exCn":"您此行的目的是什么？","th":"抽象与概念"},{"w":"bâiller","p":"v.","cn":"打哈欠","ex":"Il n'arrêtait pas de bâiller pendant la réunion, car il n'avait dormi que quatre heures.","exCn":"他开会时哈欠连天，因为他只睡了四个小时。","th":"常用词"},{"w":"bâton","p":"n.m.","cn":"棍、棒、手杖；（滑雪）雪杖；（魁北克）冰球杆；cf. mettre des bâtons dans les roues 从中作梗","ex":"Les enfants ont ramassé des bâtons pour faire griller des guimauves sur le feu.","exCn":"孩子们捡了些小棍子，用来在火上烤棉花糖。","th":"居住与环境"},{"w":"bénéficier","p":"v.","cn":"（~ de）享有、享受；（~ à）有利于","ex":"Les étudiants bénéficient d'une réduction de 20 %.","exCn":"学生享受八折优惠。","th":"常用词"},{"w":"bénévolat","p":"n.m.","cn":"志愿工作","ex":"Elle fait du bénévolat le week-end.","exCn":"她周末做志愿者。","th":"社会与新闻"},{"w":"bénévole","p":"n.","cn":"志愿者、义工；志愿的、无偿的","ex":"Une bénévole de la Croix-Rouge a accueilli les familles sinistrées.","exCn":"一位红十字会的女志愿者接待了受灾家庭。","th":"常用词"},{"w":"bêtise","p":"n.f.","cn":"傻事、傻话；愚蠢","ex":"Arrête de faire des bêtises !","exCn":"别再干傻事了！","th":"常用词"},{"w":"cabane","p":"n.f.","cn":"小木屋、棚屋；（~ à sucre）枫糖屋（魁北克）","ex":"Mon père nous a construit une cabane dans le grand érable du jardin.","exCn":"我爸爸在花园里那棵大枫树上给我们搭了一间小木屋。","th":"饮食"},{"w":"cabinet","p":"n.m.","cn":"事务所、诊所；内阁、办公厅","ex":"Elle travaille dans un cabinet d'avocats au centre-ville.","exCn":"她在市中心的一家律师事务所工作。","th":"工作与学习"},{"w":"cachette","p":"n.f.","cn":"藏身处、藏东西的地方；cf. en cachette 偷偷地、背地里","ex":"Les enfants ont trouvé une cachette parfaite derrière la cabane du jardin.","exCn":"孩子们在花园小屋后面找到了一个绝佳的藏身之处。","th":"常用词"},{"w":"cactus","p":"n.m.","cn":"仙人掌","ex":"Le cactus est une plante qui a besoin de très peu d'eau.","exCn":"仙人掌是一种几乎不需要浇水的植物。","th":"人物与身份"},{"w":"caddie","p":"n.m.","cn":"（超市）购物车；cf. 也说 chariot；（魁北克）常说 panier","ex":"N'oublie pas de ranger le caddie après les courses.","exCn":"买完东西别忘了把购物车放回去。","th":"出行与旅行"},{"w":"cadre","p":"n.m.","cn":"框、框架；环境、背景；管理人员、干部；cf. dans le cadre de 在…范围内、在…框架下","ex":"J'ai mis notre photo de mariage dans un cadre en bois.","exCn":"我把我们的结婚照放进了一个木相框里。","th":"人物与身份"},{"w":"caféine","p":"n.f.","cn":"咖啡因","ex":"Évitez la caféine après 16 heures si vous dormez mal.","exCn":"如果你睡眠不好，下午四点以后就别摄入咖啡因了。","th":"饮食"},{"w":"cage","p":"n.f.","cn":"笼子；cf. cage d'escalier 楼梯间","ex":"Le perroquet de mes voisins vit dans une grande cage sur le balcon.","exCn":"我邻居家的鹦鹉住在阳台上的一个大笼子里。","th":"居住与环境"},{"w":"caillou","p":"n.m.","cn":"石子、小石头","ex":"Le chemin qui mène au chalet est plein de cailloux, roule doucement.","exCn":"通往木屋的路上全是石子，开慢点。","th":"描述与状态"},{"w":"calcul","p":"n.m.","cn":"计算；盘算、算计","ex":"J'ai fait un rapide calcul : le loyer représente la moitié de mon salaire.","exCn":"我粗略算了一下：房租占了我工资的一半。","th":"常用词"},{"w":"calculette","p":"n.f.","cn":"（袖珍）计算器","ex":"Sors ta calculette, on va faire le budget du mois.","exCn":"把计算器拿出来，我们来算算这个月的预算。","th":"常用词"},{"w":"caleçon","p":"n.m.","cn":"（男式）平角内裤；（女式）紧身裤、打底裤","ex":"Il porte toujours des caleçons en coton.","exCn":"他总是穿棉质平角内裤。","th":"人物与身份"},{"w":"calmement","p":"adv.","cn":"平静地、冷静地","ex":"Le pilote a expliqué calmement aux passagers la raison du retard.","exCn":"机长平静地向乘客解释了延误的原因。","th":"居住与环境"},{"w":"cambriolage","p":"n.m.","cn":"入室盗窃","ex":"Les cambriolages sont plus fréquents pendant les vacances d'été.","exCn":"暑假期间入室盗窃案更多发。","th":"居住与环境"},{"w":"cambrioler","p":"v.","cn":"入室盗窃","ex":"Notre appartement a été cambriolé pendant les vacances.","exCn":"我们家在度假期间被盗了。","th":"居住与环境"},{"w":"camionnette","p":"n.f.","cn":"小货车","ex":"Nous avons loué une camionnette pour notre déménagement.","exCn":"我们租了一辆小货车来搬家。","th":"出行与旅行"},{"w":"camp","p":"n.m.","cn":"营地、营；阵营；（~ de jour / de vacances）日间夏令营、夏令营；（ficher le ~）走开、溜走（口语）","ex":"Cet été, ma fille va au camp de jour de la municipalité.","exCn":"今年夏天，我女儿去参加市里办的日间夏令营。","th":"时间与数量"},{"w":"campus","p":"n.m.","cn":"校园","ex":"Notre campus se trouve en dehors de la ville, entouré d'arbres.","exCn":"我们的校园在城外，四周绿树环绕。","th":"常用词"},{"w":"canal","p":"n.m.","cn":"运河；渠道、途径；（魁北克）电视频道","ex":"Le canal de Suez relie la mer Méditerranée à la mer Rouge.","exCn":"苏伊士运河连接地中海和红海。","th":"常用词"},{"w":"cancer","p":"n.m.","cn":"癌症","ex":"Son père se bat contre un cancer depuis deux ans.","exCn":"他父亲与癌症抗争已经两年了。","th":"常用词"},{"w":"candidature","p":"n.f.","cn":"（求职、入学等）申请；参选、候选资格","ex":"Sa candidature a été retenue parmi une centaine de candidats.","exCn":"他的申请从一百来名候选人中脱颖而出。","th":"交际与礼貌"},{"w":"canicule","p":"n.f.","cn":"热浪、酷暑","ex":"Pendant la canicule, buvez beaucoup d'eau.","exCn":"酷暑期间要多喝水。","th":"居住与环境"},{"w":"capacité","p":"n.f.","cn":"能力；容量","ex":"Elle a une grande capacité d'adaptation, ce qui l'a aidée à s'installer au Canada.","exCn":"她适应能力很强，这帮助她在加拿大安顿了下来。","th":"抽象与概念"},{"w":"capitaine","p":"n.","cn":"船长、机长；队长；（军衔）上尉","ex":"Le capitaine du navire a demandé aux passagers de rester calmes.","exCn":"船长让乘客们保持冷静。","th":"出行与旅行"},{"w":"capuche","p":"n.f.","cn":"（衣服上的）兜帽、风帽；cf. le capuchon 兜帽（魁北克常用）","ex":"Mets ta capuche, il commence à pleuvoir.","exCn":"戴上兜帽吧，开始下雨了。","th":"居住与环境"},{"w":"caractéristique","p":"n.f.","cn":"特征、特点；（复数）性能、参数；典型的；（~ de）…特有的","ex":"Avant d'acheter un ordinateur, comparez bien les caractéristiques techniques.","exCn":"买电脑之前，要好好比较一下技术参数。","th":"抽象与概念"},{"w":"carafe","p":"n.f.","cn":"（玻璃）水瓶、长颈瓶","ex":"Vous pourriez nous apporter une carafe d'eau, s'il vous plaît ?","exCn":"能给我们来一壶水吗？","th":"描述与状态"},{"w":"caravane","p":"n.f.","cn":"（汽车拖挂的）房车；商队、驼队；cf. la roulotte 房车（魁北克常用）","ex":"Ils ont loué une caravane pour passer l'été au bord de la mer.","exCn":"他们租了一辆房车，在海边过夏天。","th":"出行与旅行"},{"w":"carbone","p":"n.m.","cn":"碳","ex":"Prendre le train plutôt que l'avion réduit fortement votre empreinte carbone.","exCn":"坐火车而不坐飞机，能大大减少你的碳足迹。","th":"常用词"},{"w":"carburant","p":"n.m.","cn":"燃料","ex":"L'avion a dû atterrir en urgence parce qu'il manquait de carburant.","exCn":"飞机因燃料不足，不得不紧急降落。","th":"常用词"},{"w":"cardiaque","p":"adj.","cn":"心脏的；患心脏病的","ex":"Il a fait une crise cardiaque l'an dernier.","exCn":"他去年心脏病发作过一次。","th":"健康与身体"},{"w":"carie","p":"n.f.","cn":"龋齿、蛀牙","ex":"Le dentiste m'a soigné une carie.","exCn":"牙医给我补了一颗蛀牙。","th":"常用词"},{"w":"carrière","p":"n.f.","cn":"职业生涯、事业","ex":"Elle a fait toute sa carrière chez le même employeur.","exCn":"她整个职业生涯都在同一家单位度过。","th":"工作与学习"},{"w":"carton","p":"n.m.","cn":"纸板；纸箱、纸盒；（~ jaune / rouge）黄牌、红牌","ex":"Pour le déménagement, j'ai mis toute la vaisselle dans un grand carton.","exCn":"搬家时，我把所有餐具都装进了一个大纸箱。","th":"描述与状态"},{"w":"cascade","p":"n.f.","cn":"瀑布；（喻）一连串、连锁","ex":"Nous avons pique-niqué au pied d'une magnifique cascade.","exCn":"我们在一座壮观的瀑布脚下野餐。","th":"常用词"},{"w":"casino","p":"n.m.","cn":"赌场","ex":"Le Casino de Montréal se trouve sur l'île Notre-Dame.","exCn":"蒙特利尔赌场位于圣母岛上。","th":"常用词"},{"w":"casserole","p":"n.f.","cn":"（带柄）煮锅、炖锅；cf.（魁北克）常说 chaudron","ex":"Il ne reste plus une seule casserole propre, il faut faire la vaisselle.","exCn":"一个干净的锅都没了，得洗碗了。","th":"日常动作"},{"w":"cassette","p":"n.f.","cn":"磁带","ex":"Mon père garde encore ses vieilles cassettes de musique des années 80.","exCn":"我父亲还留着他八十年代的旧音乐磁带。","th":"常用词"},{"w":"catastrophe","p":"n.f.","cn":"灾难","ex":"Les inondations ont été une véritable catastrophe pour les agriculteurs.","exCn":"洪水对农民来说是一场真正的灾难。","th":"常用词"},{"w":"catholique","p":"n.","cn":"天主教徒；天主教的；（pas très ~）不太正当的、可疑的（口语）","ex":"Ma grand-mère, une catholique pratiquante, va à la messe chaque dimanche.","exCn":"我祖母是虔诚的天主教徒，每个星期天都去做弥撒。","th":"时间与数量"},{"w":"catégorie","p":"n.f.","cn":"类别、种类；等级、级别","ex":"Sur ce site, vous pouvez trier les produits par catégorie et par prix.","exCn":"在这个网站上，可以按类别和价格筛选商品。","th":"常用词"},{"w":"cauchemar","p":"n.m.","cn":"噩梦","ex":"J'ai fait un cauchemar terrible la nuit dernière.","exCn":"我昨晚做了一个可怕的噩梦。","th":"常用词"},{"w":"causer","p":"v.","cn":"造成、引起；聊天、交谈","ex":"Le verglas a causé de nombreux accidents ce matin.","exCn":"今天早上路面结冰，引发了多起事故。","th":"时间与数量"},{"w":"caution","p":"n.f.","cn":"押金、担保","ex":"Pour louer des skis, j'ai dû laisser une caution de cent euros, qu'on m'a rendue au retour.","exCn":"租滑雪板时，我得交一百欧元押金，还板时退给了我。","th":"常用词"},{"w":"cellulaire","p":"n.m.","cn":"细胞的；（魁北克）手机","ex":"La division cellulaire est un processus essentiel à la croissance.","exCn":"细胞分裂是生长的一个基本过程。","th":"常用词"},{"w":"cendrier","p":"n.m.","cn":"烟灰缸","ex":"Il n'y a aucun cendrier sur la terrasse.","exCn":"露台上一个烟灰缸都没有。","th":"常用词"},{"w":"censé","p":"adj.","cn":"（être ~ + 不定式）应该、理应；被认为；cf. sensé 明智的、合情理的（同音）","ex":"Le train était censé arriver à 18 h, mais il a une heure de retard.","exCn":"火车本该18点到，可现在晚点了一个小时。","th":"观点与论证"},{"w":"central","p":"adj.","cn":"中央的、中心的；核心的、主要的","ex":"Face au pouvoir central, les provinces défendent jalousement leurs compétences en matière d'éducation.","exCn":"面对中央政府，各省竭力维护自己在教育领域的权限。","th":"常用词"},{"w":"cependant","p":"conj.","cn":"然而","ex":"Il est jeune ; cependant, il a beaucoup d'expérience.","exCn":"他很年轻，然而经验丰富。","th":"观点与论证"},{"w":"cercle","p":"n.m.","cn":"圆、圆圈；圈子、团体","ex":"Les enfants se sont assis en cercle autour de l'enseignante.","exCn":"孩子们围着老师坐成一圈。","th":"常用词"},{"w":"certificat","p":"n.m.","cn":"证书、证明","ex":"Pour inscrire votre enfant, apportez son certificat de naissance.","exCn":"给孩子报名时，请带上他的出生证明。","th":"观点与论证"},{"w":"cerveau","p":"n.m.","cn":"大脑；（喻）主谋、策划者","ex":"Le sommeil est essentiel au bon fonctionnement du cerveau.","exCn":"睡眠对大脑的正常运转至关重要。","th":"描述与状态"},{"w":"cesser","p":"v.","cn":"停止、中止","ex":"Il a cessé de fumer il y a cinq ans.","exCn":"他五年前戒了烟。","th":"日常动作"},{"w":"chalet","p":"n.m.","cn":"（山间）木屋；（魁北克）乡间度假屋、湖畔小屋","ex":"Chaque année, nous fêtons le jour de l'An au chalet de mon oncle.","exCn":"每年我们都在叔叔家的度假木屋里过元旦。","th":"居住与环境"},{"w":"chaleureux","p":"adj.","cn":"热情的、热烈的；（氛围、色调）温馨的","ex":"Nous avons reçu un accueil chaleureux.","exCn":"我们受到了热情的接待。","th":"居住与环境"},{"w":"champ","p":"n.m.","cn":"田地；领域、范围；cf. sur-le-champ 立刻、当场","ex":"Ce champ de maïs appartient à mon oncle.","exCn":"这片玉米地是我叔叔的。","th":"时间与数量"},{"w":"championnat","p":"n.m.","cn":"锦标赛","ex":"Notre équipe a remporté le championnat régional de natation.","exCn":"我们队赢得了地区游泳锦标赛。","th":"常用词"},{"w":"chanceux","p":"adj.","cn":"幸运的、走运的","ex":"Tu as été chanceux : le dernier bus était encore là.","exCn":"你运气真好，末班车还没走。","th":"常用词"},{"w":"change","p":"n.m.","cn":"（货币）兑换、外汇；（gagner au ~）换得划算","ex":"Le bureau de change de l'aéroport est fermé.","exCn":"机场的货币兑换处关门了。","th":"常用词"},{"w":"changeant","p":"adj.","cn":"多变的、变化无常的","ex":"Le temps est très changeant en ce moment.","exCn":"最近天气变化无常。","th":"抽象与概念"},{"w":"chantier","p":"n.m.","cn":"工地、施工现场；（喻）重大工程；乱七八糟的地方（口语）","ex":"Il passe ses samedis sur le chantier de sa future maison pour surveiller les travaux.","exCn":"他每个星期六都待在自己新房的工地上，盯着施工进度。","th":"描述与状态"},{"w":"chapitre","p":"n.m.","cn":"章、章节","ex":"Pour demain, lisez le chapitre trois du manuel.","exCn":"明天之前，请读完教材的第三章。","th":"常用词"},{"w":"charbon","p":"n.m.","cn":"煤、煤炭","ex":"Le charbon reste la principale source d'électricité dans plusieurs pays d'Asie.","exCn":"在亚洲一些国家，煤炭仍是最主要的电力来源。","th":"常用词"},{"w":"charge","p":"n.f.","cn":"负担、负荷；职责、责任；（复数）（房租外的）杂费；（法律）指控；（电池）充电；cf. prendre en charge 负责、承担（费用）；à la charge de 由…负担","ex":"Avant de signer le bail, demandez combien coûtent les charges chaque mois.","exCn":"签租约之前，先问清楚每个月的杂费是多少。","th":"购物与金钱"},{"w":"charger","p":"v.","cn":"装载；充电；（电脑）加载；（~ qqn de）委托…负责；（se ~ de）负责、承担；（魁北克口语）收费、要价","ex":"Nous avons chargé tous les cartons dans le camion de déménagement.","exCn":"我们把所有箱子都装上了搬家卡车。","th":"购物与金钱"},{"w":"chariot","p":"n.m.","cn":"手推车、购物车","ex":"Au supermarché, il faut parfois une pièce de monnaie pour prendre un chariot.","exCn":"在超市，有时得投一枚硬币才能推走购物车。","th":"出行与旅行"},{"w":"charme","p":"n.m.","cn":"魅力","ex":"Ce vieux quartier a beaucoup de charme avec ses petites rues pavées.","exCn":"这个老街区小巷铺着石板，很有魅力。","th":"常用词"},{"w":"chasse","p":"n.f.","cn":"打猎、狩猎；追捕、搜寻；cf. tirer la chasse d'eau 冲马桶","ex":"La chasse est interdite toute l'année dans ce parc national.","exCn":"这个国家公园全年禁止狩猎。","th":"常用词"},{"w":"chasser","p":"v.","cn":"打猎、狩猎；赶走、驱逐","ex":"Mon oncle chasse le cerf chaque automne dans le nord du Québec.","exCn":"我叔叔每年秋天都去魁北克北部猎鹿。","th":"常用词"},{"w":"chasseur","p":"n.","cn":"猎人","ex":"En automne, les chasseurs doivent porter un vêtement orange pour être bien visibles.","exCn":"秋天，猎人必须穿橙色衣服，好让别人看清楚。","th":"人物与身份"},{"w":"chauve","p":"adj.","cn":"秃头的、秃顶的","ex":"Mon oncle est devenu chauve avant quarante ans.","exCn":"我叔叔不到四十岁就秃顶了。","th":"常用词"},{"w":"chemin de fer","p":"n.m.","cn":"铁路","ex":"Le chemin de fer a transformé la France au XIXe siècle.","exCn":"铁路在19世纪改变了法国。","th":"出行与旅行"},{"w":"cheminée","p":"n.f.","cn":"壁炉；烟囱","ex":"De la fumée sortait de la cheminée.","exCn":"烟囱里冒出了烟。","th":"常用词"},{"w":"chemisier","p":"n.m.","cn":"女式衬衫","ex":"Au bureau, elle porte souvent un chemisier avec un pantalon noir.","exCn":"上班时，她常穿一件女式衬衫配黑裤子。","th":"人物与身份"},{"w":"chercheur","p":"n.","cn":"研究人员、研究员；寻找者","ex":"Un chercheur de l'Université Laval a mis au point un test de dépistage plus rapide.","exCn":"拉瓦尔大学的一位研究员研发出了一种更快的筛查检测。","th":"工作与学习"},{"w":"chevalier","p":"n.m.","cn":"骑士","ex":"Au Moyen Âge, un chevalier devait servir fidèlement son seigneur.","exCn":"在中世纪，骑士必须忠心侍奉自己的领主。","th":"常用词"},{"w":"cheville","p":"n.f.","cn":"脚踝","ex":"Elle porte un petit tatouage en forme d'étoile à la cheville.","exCn":"她脚踝上有一个星星形状的小文身。","th":"常用词"},{"w":"chiffon","p":"n.m.","cn":"抹布、破布","ex":"Essuyez l'écran avec un chiffon doux et sec.","exCn":"用柔软的干布擦拭屏幕。","th":"常用词"},{"w":"chimique","p":"adj.","cn":"化学的","ex":"Pour le ménage, j'utilise du vinaigre blanc plutôt que des produits chimiques.","exCn":"打扫卫生时，我用白醋，而不用化学清洁剂。","th":"常用词"},{"w":"chirurgie","p":"n.f.","cn":"外科；外科手术","ex":"Elle a subi une chirurgie du genou le mois dernier.","exCn":"她上个月做了膝盖手术。","th":"健康与身体"},{"w":"chirurgien","p":"n.","cn":"外科医生","ex":"Le chirurgien m'a dit que l'opération s'était bien passée.","exCn":"外科医生告诉我手术很顺利。","th":"健康与身体"},{"w":"choc","p":"n.m.","cn":"震惊、打击；撞击、碰撞","ex":"Je suis encore sous le choc.","exCn":"我到现在还没缓过神来。","th":"常用词"},{"w":"choquant","p":"adj.","cn":"令人反感的、令人震惊的","ex":"Les images de l'accident étaient si choquantes que la chaîne les a floutées.","exCn":"事故画面太令人震惊，电视台给打上了马赛克。","th":"人物与身份"},{"w":"choquer","p":"v.","cn":"使震惊；冒犯、使反感；（se ~）生气、发火（魁北克口语）","ex":"La violence de l'agression a choqué tout le quartier.","exCn":"这起袭击之残暴，震惊了整个街区。","th":"情绪与性格"},{"w":"choqué","p":"adj.","cn":"震惊的、受惊吓的；（受到冒犯而）反感的；生气的、恼火的（魁北克口语）","ex":"Les témoins de l'accident sont encore très choqués.","exCn":"事故的目击者仍然惊魂未定。","th":"情绪与性格"},{"w":"chorale","p":"n.f.","cn":"合唱团","ex":"Elle chante dans la chorale de son quartier.","exCn":"她在社区合唱团唱歌。","th":"常用词"},{"w":"chute","p":"n.f.","cn":"跌倒、落下；下降、下跌；倒塌、垮台；（常用复数）瀑布","ex":"Les ventes de voitures neuves ont connu une chute de 15 % cette année.","exCn":"今年新车销量下降了15%。","th":"常用词"},{"w":"chéquier","p":"n.m.","cn":"支票簿","ex":"Ma mère paie encore ses courses par chèque : elle a toujours son chéquier dans son sac.","exCn":"我妈妈买东西还用支票，包里总揣着支票簿。","th":"出行与旅行"},{"w":"chêne","p":"n.m.","cn":"橡树、栎树；橡木","ex":"Ce chêne du parc a plus de trois cents ans.","exCn":"公园里的这棵橡树已经有三百多年了。","th":"居住与环境"},{"w":"chômeur","p":"n.","cn":"失业者","ex":"Cette formation gratuite est réservée aux chômeurs de longue durée.","exCn":"这项免费培训只面向长期失业者。","th":"社会与新闻"},{"w":"cible","p":"n.f.","cn":"目标、对象；靶子","ex":"Les personnes âgées sont souvent la cible d'arnaques téléphoniques.","exCn":"老年人经常成为电话诈骗的对象。","th":"常用词"},{"w":"cimetière","p":"n.m.","cn":"墓地","ex":"Il y a un petit cimetière derrière l'église du village.","exCn":"村里教堂后面有一个小墓地。","th":"常用词"},{"w":"cinquantaine","p":"n.f.","cn":"五十来个、五十左右；五十岁上下","ex":"Il y a une cinquantaine d'années, ce quartier était encore un village.","exCn":"大约五十年前，这个街区还是个村子。","th":"常用词"},{"w":"cintre","p":"n.m.","cn":"衣架；cf.（魁北克口语）也说 un support","ex":"Mets ta veste sur un cintre.","exCn":"把你的外套挂到衣架上。","th":"常用词"},{"w":"cinéaste","p":"n.","cn":"电影导演、电影人","ex":"Ce jeune cinéaste a reçu un prix à Cannes.","exCn":"这位年轻导演在戛纳获了奖。","th":"人物与身份"},{"w":"cinématographique","p":"adj.","cn":"电影的","ex":"Montréal est devenue une ville cinématographique : on y tourne beaucoup de films américains.","exCn":"蒙特利尔成了一座电影城：很多美国电影都在这里拍摄。","th":"常用词"},{"w":"circuit","p":"n.m.","cn":"环线、路线、旅游线路；电路","ex":"L'agence propose un circuit de dix jours à travers la Gaspésie.","exCn":"这家旅行社推出了一条游遍加斯佩半岛的十日游线路。","th":"出行与旅行"},{"w":"circulation","p":"n.f.","cn":"交通、车流；（血液）循环；流通","ex":"Après l'accident, la circulation a été déviée par le centre-ville.","exCn":"事故发生后，车流被改道经过市中心。","th":"健康与身体"},{"w":"circuler","p":"v.","cn":"（车辆、行人）通行；（消息等）流传、传播","ex":"En ville, on circule souvent mieux à vélo qu'en voiture.","exCn":"在城里，骑自行车往往比开车走得更顺。","th":"出行与旅行"},{"w":"citer","p":"v.","cn":"引用、引述；提到、列举","ex":"Il cite souvent Victor Hugo dans ses discours.","exCn":"他在演讲中经常引用维克多 · 雨果的话。","th":"常用词"},{"w":"citoyen","p":"n.","cn":"公民；公民的；民众参与的","ex":"Après quatre ans au Canada, mon père est enfin devenu citoyen canadien.","exCn":"在加拿大住了四年后，我爸爸终于入了加拿大籍。","th":"人物与身份"},{"w":"cité","p":"n.f.","cn":"（城郊）廉租住宅区；城市、古城；（~ universitaire）大学生宿舍区","ex":"Il a grandi dans une cité de la banlieue parisienne.","exCn":"他在巴黎郊区的一个住宅区长大。","th":"购物与金钱"},{"w":"civil","p":"n.m.","cn":"民事的、公民的；民用的、平民的；平民；（en ~）穿便服","ex":"Ils ont choisi un mariage civil plutôt qu'une cérémonie religieuse.","exCn":"他们选择了民事婚礼，而不是宗教仪式。","th":"人物与身份"},{"w":"civilisation","p":"n.f.","cn":"文明","ex":"Les Mayas ont développé une civilisation très avancée.","exCn":"玛雅人创造了一个高度发达的文明。","th":"常用词"},{"w":"clairement","p":"adv.","cn":"清楚地、明确地；显然、明显","ex":"Il a clairement dit qu'il n'était pas d'accord.","exCn":"他明确表示自己不同意。","th":"常用词"},{"w":"classement","p":"n.m.","cn":"排名、名次；分类、归档","ex":"Cette université est en tête du classement.","exCn":"这所大学在排名中位居榜首。","th":"常用词"},{"w":"classer","p":"v.","cn":"分类、归类；排名、列为","ex":"Classez ces factures par date avant de les ranger.","exCn":"把这些发票按日期归类后再收起来。","th":"常用词"},{"w":"clientèle","p":"n.f.","cn":"（全体）顾客、客户","ex":"Ce café attire surtout une clientèle jeune et étudiante.","exCn":"这家咖啡馆的顾客主要是年轻学生。","th":"常用词"},{"w":"clignotant","p":"n.m.","cn":"（汽车）转向灯；闪烁的","ex":"Il a tourné à gauche sans mettre son clignotant.","exCn":"他没打转向灯就左转了。","th":"出行与旅行"},{"w":"climat","p":"n.m.","cn":"气候；气氛、氛围","ex":"Le climat de Vancouver est beaucoup plus doux que celui de Montréal.","exCn":"温哥华的气候比蒙特利尔温和得多。","th":"居住与环境"},{"w":"climatique","p":"adj.","cn":"气候的","ex":"Les catastrophes climatiques coûtent de plus en plus cher aux assureurs.","exCn":"气候灾害让保险公司的赔付越来越多。","th":"居住与环境"},{"w":"clin d'œil","p":"n.m.","cn":"眨眼、使眼色；（向…）致意、暗指；cf. en un clin d'œil 一眨眼工夫、转眼间","ex":"Pendant la réunion, ma collègue m'a fait un clin d'œil complice.","exCn":"开会时，同事冲我心照不宣地眨了眨眼。","th":"描述与状态"},{"w":"clinique","p":"n.f.","cn":"私立医院、诊所；临床的","ex":"J'ai dû attendre trois heures à la clinique sans rendez-vous.","exCn":"我在免预约诊所等了三个小时。","th":"健康与身体"},{"w":"cloche","p":"n.f.","cn":"钟","ex":"La cloche de l'église sonne tous les dimanches à dix heures.","exCn":"教堂的钟每个星期天十点敲响。","th":"常用词"},{"w":"clou","p":"n.m.","cn":"钉子；（演出等的）高潮、亮点","ex":"Il a planté un clou pour accrocher le tableau.","exCn":"他钉了一颗钉子来挂画。","th":"描述与状态"},{"w":"coach","p":"n.","cn":"教练","ex":"Mon coach de course m'a préparé un programme d'entraînement sur trois mois.","exCn":"我的跑步教练给我定了一个为期三个月的训练计划。","th":"常用词"},{"w":"cocktail","p":"n.m.","cn":"鸡尾酒；鸡尾酒会","ex":"Le barman prépare un cocktail à base de rhum et de citron vert.","exCn":"调酒师正在调一杯以朗姆酒和青柠为基底的鸡尾酒。","th":"饮食"},{"w":"coffre","p":"n.m.","cn":"（汽车）后备箱；箱子、保险箱；cf.（魁北克口语）后备箱也说 la valise","ex":"Mets les valises dans le coffre, il reste encore de la place.","exCn":"把行李箱放进后备箱吧，还有地方。","th":"出行与旅行"},{"w":"coiffé","p":"adj.","cn":"梳好头发的；戴着（帽子等）的","ex":"Elle est toujours très bien coiffée.","exCn":"她的头发总是梳得整整齐齐。","th":"描述与状态"},{"w":"coincer","p":"v.","cn":"卡住、夹住；（être ~）被困住、脱不开身（口语）；逮住、难住（口语）","ex":"Désolé, je suis coincé au bureau jusqu'à huit heures.","exCn":"抱歉，我被困在办公室，要到八点才走得了。","th":"购物与金钱"},{"w":"col","p":"n.m.","cn":"衣领；山口","ex":"Il fait froid : remonte le col de ton manteau.","exCn":"天冷了，把大衣领子竖起来吧。","th":"居住与环境"},{"w":"collaborateur","p":"n.","cn":"同事、合作者；（企业）员工","ex":"Le directeur a remercié tous ses collaborateurs pour leur travail pendant l'année.","exCn":"经理感谢全体员工一年来的辛勤工作。","th":"工作与学习"},{"w":"collaboration","p":"n.f.","cn":"合作、协作","ex":"Ce projet a été réalisé en collaboration avec l'Université Laval.","exCn":"这个项目是与拉瓦尔大学合作完成的。","th":"常用词"},{"w":"collaborer","p":"v.","cn":"合作、协作","ex":"Notre équipe collabore avec une entreprise de Toronto depuis deux ans.","exCn":"我们团队与多伦多的一家公司合作已有两年。","th":"常用词"},{"w":"collant","p":"n.m.","cn":"连裤袜、裤袜；黏的、粘手的；缠人的（口语）","ex":"Il fait froid, mets un collant sous ta jupe.","exCn":"天冷，裙子里面穿条连裤袜吧。","th":"人物与身份"},{"w":"collectif","p":"n.m.","cn":"集体的、共同的；（社团）联合组织、团体","ex":"Au sein de l'équipe, les décisions importantes sont prises de manière collective.","exCn":"团队里的重要决定都是集体作出的。","th":"社会与新闻"},{"w":"collectionneur","p":"n.","cn":"收藏家、收集者","ex":"Ce collectionneur de vinyles passe tous ses week-ends dans les marchés aux puces.","exCn":"这位黑胶唱片收藏者每个周末都泡在跳蚤市场里。","th":"常用词"},{"w":"collégien","p":"n.","cn":"（法国）初中生；（魁北克）cégep 学生、大专生","ex":"Ce collégien de quatorze ans a créé une application pour aider ses camarades à réviser.","exCn":"这名十四岁的初中生开发了一款帮同学复习的应用。","th":"工作与学习"},{"w":"colocation","p":"n.f.","cn":"合租；cf. le / la colocataire（口语 coloc）合租室友","ex":"Pour économiser sur le loyer, beaucoup d'étudiants vivent en colocation.","exCn":"为了省房租，很多学生都和人合租。","th":"购物与金钱"},{"w":"colonie","p":"n.f.","cn":"殖民地；（~ de vacances）夏令营","ex":"L'Algérie a été une colonie française jusqu'en 1962.","exCn":"1962年以前，阿尔及利亚一直是法国的殖民地。","th":"时间与数量"},{"w":"colonne","p":"n.f.","cn":"柱子、圆柱；（表格等的）栏、列；（~ vertébrale）脊柱","ex":"La façade de la mairie est ornée de quatre grandes colonnes blanches.","exCn":"市政厅的正面装饰着四根白色的大圆柱。","th":"常用词"},{"w":"combat","p":"n.m.","cn":"战斗；斗争","ex":"Des soldats ont été blessés lors d'un violent combat près de la frontière.","exCn":"在边境附近的一场激战中，有士兵受伤。","th":"常用词"},{"w":"combattre","p":"v.","cn":"战斗、打仗；与…作斗争","ex":"Son arrière-grand-père a combattu en Normandie en 1944.","exCn":"他的曾祖父1944年在诺曼底打过仗。","th":"常用词"},{"w":"comique","p":"adj.","cn":"滑稽的、好笑的；喜剧的","ex":"La situation était tellement comique que tout le monde a éclaté de rire.","exCn":"当时的场面太滑稽了，大家都忍不住笑了出来。","th":"描述与状态"},{"w":"commenter","p":"v.","cn":"评论；（比赛等）解说","ex":"Le ministre n'a pas voulu commenter cette décision.","exCn":"部长不愿对这一决定发表评论。","th":"常用词"},{"w":"commercial","p":"n.","cn":"商业的、贸易的；销售人员、业务员","ex":"Cette rue commerciale est très animée le samedi.","exCn":"这条商业街周六非常热闹。","th":"人物与身份"},{"w":"commettre","p":"v.","cn":"犯（错误、罪行等）","ex":"Il a commis une grave erreur en signant ce contrat sans le lire.","exCn":"他没看就签了这份合同，犯了一个严重的错误。","th":"常用词"},{"w":"commissaire","p":"n.","cn":"警长、警察分局局长；专员、委员","ex":"Le commissaire chargé de l'enquête a donné une conférence de presse ce matin.","exCn":"负责此案的警长今天上午召开了记者会。","th":"社会与新闻"},{"w":"commun","p":"adj.","cn":"共同的、公共的；常见的、普通的；cf. en commun 共同、一起；les transports en commun 公共交通","ex":"Les locataires partagent une cuisine commune au rez-de-chaussée.","exCn":"租户们共用一楼的公共厨房。","th":"出行与旅行"},{"w":"communauté","p":"n.f.","cn":"群体、社区；共同体","ex":"La communauté chinoise de Vancouver organise un grand défilé pour le Nouvel An lunaire.","exCn":"温哥华的华人社区为农历新年组织了一场盛大的游行。","th":"居住与环境"},{"w":"compagnon","p":"n.","cn":"伴侣；同伴、伙伴","ex":"Elle vit avec son compagnon depuis cinq ans, mais ils ne sont pas mariés.","exCn":"她和伴侣同居五年了，但两人没有结婚。","th":"常用词"},{"w":"comparaison","p":"n.f.","cn":"比较、对比","ex":"En comparaison avec Toronto, les loyers à Montréal restent abordables.","exCn":"和多伦多相比，蒙特利尔的房租还算负担得起。","th":"常用词"},{"w":"complexe","p":"n.m.","cn":"复杂的；自卑感、（心理）情结；（体育、商业等）综合设施、建筑群","ex":"Il a longtemps eu des complexes à cause de son accent.","exCn":"他因为自己的口音自卑了很久。","th":"居住与环境"},{"w":"compliment","p":"n.m.","cn":"称赞、恭维","ex":"Je prends cela comme un compliment.","exCn":"我就把这当作夸奖了。","th":"常用词"},{"w":"compliquer","p":"v.","cn":"使复杂化","ex":"Le fait qu'il ne parle pas anglais a compliqué ses recherches d'emploi à Toronto.","exCn":"他不会说英语，这让他在多伦多找工作难上加难。","th":"描述与状态"},{"w":"comportement","p":"n.m.","cn":"行为","ex":"Le comportement de cet élève s'est beaucoup amélioré depuis septembre.","exCn":"从九月起，这名学生的行为有了很大改善。","th":"常用词"},{"w":"comporter","p":"v.","cn":"包含、包括；（se ~）表现、举止","ex":"L'examen comporte quatre épreuves obligatoires.","exCn":"这场考试包括四项必考科目。","th":"常用词"},{"w":"compositeur","p":"n.","cn":"作曲家","ex":"Ce compositeur québécois a écrit la musique de plusieurs films célèbres.","exCn":"这位魁北克作曲家为好几部著名电影写过配乐。","th":"常用词"},{"w":"comprimé","p":"n.m.","cn":"药片","ex":"Mon fils refuse d'avaler ses comprimés, alors je les écrase dans un peu de compote.","exCn":"我儿子不肯吞药片，所以我把药片碾碎拌进一点果泥里。","th":"健康与身体"},{"w":"compréhensible","p":"adj.","cn":"可以理解的、情有可原的；易懂的","ex":"Sa réaction est tout à fait compréhensible après une telle nouvelle.","exCn":"听到这样的消息，他有这种反应完全可以理解。","th":"常用词"},{"w":"compréhension","p":"n.f.","cn":"理解、领会；体谅、谅解","ex":"Écouter des podcasts en français tous les jours m'a beaucoup aidé en compréhension orale.","exCn":"每天听法语播客对我的听力理解帮助很大。","th":"常用词"},{"w":"comptabilité","p":"n.f.","cn":"会计、会计学；账目；会计部门","ex":"Pour une petite entreprise, tenir sa comptabilité soi-même prend beaucoup de temps.","exCn":"对小企业来说，自己记账要花很多时间。","th":"常用词"},{"w":"comptable","p":"n.","cn":"会计、会计师；会计的","ex":"Ma sœur travaille comme comptable dans un cabinet à Montréal.","exCn":"我姐姐在蒙特利尔一家事务所当会计。","th":"常用词"},{"w":"compteur","p":"n.m.","cn":"（水电气）表、计量器；（车）速度表、里程表","ex":"Un technicien viendra relever le compteur d'électricité jeudi matin.","exCn":"周四上午会有技术员来抄电表。","th":"出行与旅行"},{"w":"comptoir","p":"n.m.","cn":"柜台；吧台；（魁北克）厨房台面","ex":"Payez au comptoir avant de vous installer à une table.","exCn":"请先到柜台付款，再找桌子坐。","th":"饮食"},{"w":"compétence","p":"n.f.","cn":"能力；技能","ex":"La communication est une compétence clé.","exCn":"沟通是一项关键能力。","th":"工作与学习"},{"w":"compétition","p":"n.f.","cn":"竞争；比赛","ex":"Dans cette classe préparatoire, la compétition entre élèves est très rude.","exCn":"在这个预科班里，学生之间的竞争非常激烈。","th":"常用词"},{"w":"concentration","p":"n.f.","cn":"专注、专心；集中、聚集","ex":"Ce travail de précision demande une grande concentration.","exCn":"这项精细的工作需要高度集中注意力。","th":"常用词"},{"w":"concentrer","p":"v.","cn":"（se ~）专心、集中注意力；集中","ex":"J'ai du mal à me concentrer sur mes études avec ce bruit.","exCn":"这么吵，我很难专心学习。","th":"常用词"},{"w":"concentré","p":"n.m.","cn":"专心的、全神贯注的；浓缩的；浓缩物","ex":"Chut, elle est concentrée sur ses devoirs.","exCn":"嘘，她正在专心做作业。","th":"常用词"},{"w":"concept","p":"n.m.","cn":"概念","ex":"Le concept de développement durable est au cœur de ce projet.","exCn":"可持续发展这一概念是这个项目的核心。","th":"抽象与概念"},{"w":"concernant","p":"prép.","cn":"关于、涉及","ex":"J'ai quelques questions concernant le projet.","exCn":"我有几个关于这个项目的问题。","th":"常用词"},{"w":"concerner","p":"v.","cn":"涉及；关系到","ex":"Cette loi concerne tous les salariés.","exCn":"这项法律涉及所有雇员。","th":"观点与论证"},{"w":"concierge","p":"n.","cn":"门房、看门人；（加拿大）楼宇、学校的管理员、清洁工；（酒店）礼宾员","ex":"La concierge distribue le courrier dans l'immeuble.","exCn":"门房在楼里分发信件。","th":"饮食"},{"w":"conclure","p":"v.","cn":"得出结论、推断；达成、缔结（协议、交易）；结束（讲话、文章）","ex":"Après des mois de négociations, les deux entreprises ont enfin conclu un accord.","exCn":"经过几个月的谈判，两家公司终于达成了协议。","th":"观点与论证"},{"w":"conclusion","p":"n.f.","cn":"结论；结尾、结束","ex":"Les chercheurs sont arrivés à la conclusion que le sommeil influence la mémoire.","exCn":"研究人员得出结论：睡眠会影响记忆。","th":"观点与论证"},{"w":"concours","p":"n.m.","cn":"竞赛、（选拔性）考试；协助、帮助","ex":"Elle a réussi le concours de la fonction publique.","exCn":"她通过了公务员考试。","th":"工作与学习"},{"w":"concret","p":"adj.","cn":"具体的、实际的","ex":"Pouvez-vous me donner un exemple concret ?","exCn":"您能给我举个具体的例子吗？","th":"常用词"},{"w":"concurrence","p":"n.f.","cn":"竞争；竞争对手（统称）","ex":"Il y a beaucoup de concurrence entre les restaurants de cette rue.","exCn":"这条街上的餐馆竞争很激烈。","th":"常用词"},{"w":"concurrent","p":"n.","cn":"竞争对手；参赛者","ex":"Notre principal concurrent vient de baisser ses prix de 20 %.","exCn":"我们的主要竞争对手刚把价格降了20%。","th":"常用词"},{"w":"condition","p":"n.f.","cn":"条件；状况、处境","ex":"Je veux bien t'aider, à condition que tu sois à l'heure.","exCn":"我愿意帮你，条件是你要准时。","th":"抽象与概念"},{"w":"conduite","p":"n.f.","cn":"驾驶；行为、品行；（水、气）管道","ex":"La conduite sur une route enneigée demande beaucoup de prudence.","exCn":"在积雪的路面上驾驶需要格外小心。","th":"常用词"},{"w":"confier","p":"v.","cn":"托付、委托；吐露（秘密）；（se ~ à）向…倾诉","ex":"Je te confie mes clés pendant mon absence.","exCn":"我不在的时候，钥匙就交给你保管了。","th":"常用词"},{"w":"confirmation","p":"n.f.","cn":"确认、证实","ex":"Vous recevrez une confirmation écrite de votre inscription par la poste.","exCn":"您会通过邮寄收到书面的注册确认。","th":"常用词"},{"w":"conflit","p":"n.m.","cn":"冲突、争端","ex":"Pour éviter tout conflit d'intérêts, la juge s'est retirée de l'affaire.","exCn":"为避免任何利益冲突，这位法官回避了此案。","th":"常用词"},{"w":"confondre","p":"v.","cn":"混淆、弄混；（se ~）混为一体、重合","ex":"On me confond souvent avec ma sœur jumelle.","exCn":"别人常把我和我的双胞胎姐妹弄混。","th":"描述与状态"},{"w":"confort","p":"n.m.","cn":"舒适、安逸","ex":"Après trois semaines de camping, quel bonheur de retrouver le confort d'un vrai lit !","exCn":"露营了三个星期之后，能重新享受一张真正的床的舒适，真是太幸福了！","th":"常用词"},{"w":"confusion","p":"n.f.","cn":"混淆、弄错；混乱","ex":"Il y a eu une confusion dans les réservations : notre chambre avait été donnée à quelqu'un d'autre.","exCn":"预订出了差错：我们的房间被给了别人。","th":"常用词"},{"w":"conférence","p":"n.f.","cn":"讲座、会议","ex":"Un écrivain célèbre donnera une conférence à la bibliothèque jeudi soir.","exCn":"一位著名作家周四晚上将在图书馆做讲座。","th":"工作与学习"},{"w":"conscience","p":"n.f.","cn":"意识、知觉；良心","ex":"Beaucoup de gens ont pris conscience de l'importance du recyclage.","exCn":"很多人已经意识到了回收的重要性。","th":"常用词"},{"w":"conscient","p":"adj.","cn":"意识到的、清醒的","ex":"Les jeunes sont de plus en plus conscients des enjeux environnementaux.","exCn":"年轻人越来越意识到环境问题的重要性。","th":"常用词"},{"w":"conserver","p":"v.","cn":"保存、储存；保留、保持","ex":"Ce médicament se conserve au réfrigérateur après ouverture.","exCn":"这种药开封后需冷藏保存。","th":"常用词"},{"w":"considérer","p":"v.","cn":"认为、视为；考虑","ex":"Je te considère comme mon meilleur ami.","exCn":"我把你当作我最好的朋友。","th":"观点与论证"},{"w":"consigne","p":"n.f.","cn":"指示、规定；（行李）寄存处；（瓶罐的）押金","ex":"Avant le décollage, les agents de bord rappellent les consignes de sécurité.","exCn":"起飞前，空乘人员会提醒大家注意安全须知。","th":"出行与旅行"},{"w":"consister","p":"v.","cn":"（~ à + 不定式）在于、就是；（~ en）由…组成、包括","ex":"Mon travail consiste à accueillir les nouveaux arrivants et à les aider dans leurs démarches.","exCn":"我的工作就是接待新移民，帮他们办理各种手续。","th":"常用词"},{"w":"consommateur","p":"n.","cn":"消费者","ex":"Pour un achat en ligne, le consommateur dispose de quatorze jours pour changer d'avis.","exCn":"网购时，消费者有十四天的反悔期。","th":"购物与金钱"},{"w":"consommation","p":"n.f.","cn":"消费；（能源等）消耗、耗量；（咖啡馆、酒吧里点的）饮料","ex":"Le gouvernement veut encourager une consommation plus responsable.","exCn":"政府希望鼓励更负责任的消费。","th":"饮食"},{"w":"constamment","p":"adv.","cn":"不断地、一直","ex":"Les règles changent constamment, c'est difficile de suivre.","exCn":"规则老是在变，很难跟得上。","th":"常用词"},{"w":"constater","p":"v.","cn":"注意到、发现；（官方）确认、证实","ex":"En rentrant de vacances, nous avons constaté que la porte avait été forcée.","exCn":"度假回来，我们发现门被撬过了。","th":"常用词"},{"w":"consultant","p":"n.","cn":"顾问、咨询师","ex":"L'entreprise a engagé un consultant pour réorganiser son service des ventes.","exCn":"公司聘请了一位顾问来重组销售部门。","th":"常用词"},{"w":"consultation","p":"n.f.","cn":"（医生）看诊、诊察；征求意见、咨询","ex":"Sans assurance, une consultation chez le dentiste coûte environ 80 dollars.","exCn":"没有保险的话，看一次牙医大约要80加元。","th":"健康与身体"},{"w":"consulter","p":"v.","cn":"查阅、查看；咨询、请教；看（医生）、就诊","ex":"Vous pouvez consulter les horaires des bus sur le site de la ville.","exCn":"您可以在市政府网站上查看公交时刻表。","th":"健康与身体"},{"w":"conséquence","p":"n.f.","cn":"后果、结果","ex":"La hausse des loyers est une conséquence directe de la pénurie de logements.","exCn":"房租上涨是住房短缺的直接后果。","th":"抽象与概念"},{"w":"conséquent","p":"adj.","cn":"（par ~）因此、所以；（言行）一致的、合乎逻辑的；相当大的、可观的（口语）","ex":"Le train a été annulé ; par conséquent, la réunion est reportée à demain.","exCn":"火车取消了，因此会议推迟到明天。","th":"观点与论证"},{"w":"contagieux","p":"adj.","cn":"传染性的、会传染的；（笑、情绪）有感染力的","ex":"Tant que tu as de la fièvre, tu es contagieux : reste à la maison.","exCn":"只要你还在发烧就会传染别人，待在家里吧。","th":"健康与身体"},{"w":"contemporain","p":"adj.","cn":"当代的；同时代的","ex":"J'adore visiter les musées d'art contemporain.","exCn":"我很喜欢参观当代艺术博物馆。","th":"常用词"},{"w":"contenir","p":"v.","cn":"包含、含有；抑制、控制（情绪等）","ex":"Ce produit contient des traces d'arachides.","exCn":"本产品含有微量花生。","th":"常用词"},{"w":"contenu","p":"n.m.","cn":"内容；（容器里的）东西","ex":"Le contenu du cours sera mis en ligne la semaine prochaine.","exCn":"课程内容下周会放到网上。","th":"常用词"},{"w":"contexte","p":"n.m.","cn":"背景、环境；上下文、语境","ex":"Dans le contexte économique actuel, beaucoup de familles réduisent leurs dépenses.","exCn":"在当前的经济背景下，很多家庭都在削减开支。","th":"居住与环境"},{"w":"continu","p":"adj.","cn":"连续的、不间断的；（formation continue）继续教育、在职进修","ex":"Le magasin est ouvert en journée continue.","exCn":"这家商店全天营业，中午不休息。","th":"社会与新闻"},{"w":"contraire","p":"n.m.","cn":"相反的；反面、相反的事物；cf. au contraire 相反、恰恰相反","ex":"Elle fait toujours le contraire de ce qu'on lui demande.","exCn":"别人让她做什么，她偏偏反着来。","th":"功能词与连接"},{"w":"contrairement","p":"adv.","cn":"（~ à）与…相反","ex":"Contrairement à son frère, il adore le sport.","exCn":"和他哥哥不同，他非常喜欢运动。","th":"功能词与连接"},{"w":"contrat","p":"n.m.","cn":"合同、契约","ex":"Mon contrat d'assurance se renouvelle automatiquement chaque année.","exCn":"我的保险合同每年自动续约。","th":"常用词"},{"w":"contribuer","p":"v.","cn":"有助于、促成；出资、分摊（费用）","ex":"Le beau temps a contribué au succès du festival.","exCn":"好天气为音乐节的成功出了不少力。","th":"常用词"},{"w":"contrôler","p":"v.","cn":"检查、核查；控制、掌控","ex":"Avant d'envoyer le devis au client, contrôle bien tous les montants.","exCn":"把报价单发给客户之前，把所有金额都仔细核对一遍。","th":"常用词"},{"w":"contrôleur","p":"n.","cn":"检查员、查票员；（空中交通）管制员","ex":"Le contrôleur m'a donné une amende parce que je n'avais pas validé mon billet.","exCn":"因为我没有打票，查票员罚了我的款。","th":"出行与旅行"},{"w":"convaincant","p":"adj.","cn":"有说服力的、令人信服的","ex":"L'avocat a présenté des arguments convaincants devant le juge.","exCn":"律师在法官面前提出了令人信服的论据。","th":"人物与身份"},{"w":"convaincre","p":"v.","cn":"说服、使信服","ex":"Elle a convaincu son patron de la laisser travailler à domicile deux jours par semaine.","exCn":"她说服了老板，让她每周在家办公两天。","th":"常用词"},{"w":"convenir","p":"v.","cn":"（~ à）适合、对…方便；（~ de）商定、约定；（il convient de）应该、宜","ex":"Est-ce que mardi à dix heures vous convient pour le rendez-vous ?","exCn":"约在周二10点，您方便吗？","th":"常用词"},{"w":"coopérer","p":"v.","cn":"合作、协作","ex":"Les témoins ont accepté de coopérer avec la police.","exCn":"证人们同意配合警方调查。","th":"常用词"},{"w":"copie","p":"n.f.","cn":"副本、复制品；试卷、答卷","ex":"Fais une copie de ce rapport.","exCn":"把这份报告复印一份。","th":"常用词"},{"w":"copieux","p":"adj.","cn":"丰盛的、量多的","ex":"Le petit-déjeuner de l'hôtel était très copieux.","exCn":"酒店的早餐非常丰盛。","th":"常用词"},{"w":"coquillage","p":"n.m.","cn":"贝壳；贝类","ex":"Ma fille a trouvé un énorme coquillage sur la plage.","exCn":"我女儿在海滩上捡到一个很大的贝壳。","th":"常用词"},{"w":"corbeille","p":"n.f.","cn":"篮子、筐；（~ à papier）废纸篓；（电脑）回收站","ex":"Il y a une corbeille de fruits sur la table.","exCn":"桌上有一篮水果。","th":"日常动作"},{"w":"corde","p":"n.f.","cn":"绳子、绳索；（乐器的）弦","ex":"Ils ont attaché le bateau au quai avec une grosse corde.","exCn":"他们用一根粗绳把船拴在了码头上。","th":"常用词"},{"w":"cordialement","p":"adv.","cn":"（邮件、信件结尾，也说 Bien ~）此致、诚挚问候；热情地、诚挚地","ex":"Un e-mail professionnel se termine généralement par « Cordialement ».","exCn":"工作邮件结尾一般写 Cordialement（此致）。","th":"居住与环境"},{"w":"correction","p":"n.f.","cn":"改正、修正；批改、校对","ex":"La correction des examens prendra environ deux semaines.","exCn":"阅卷大约需要两周时间。","th":"常用词"},{"w":"correspondance","p":"n.f.","cn":"换乘；转车","ex":"Vous avez une correspondance à Lille.","exCn":"您在里尔需要换乘。","th":"出行与旅行"},{"w":"correspondant","p":"n.","cn":"通讯员、驻外记者；笔友、交换伙伴；（电话的）对方；相应的","ex":"Selon notre correspondant à Paris, la grève des transports devrait se poursuivre toute la semaine.","exCn":"据本台驻巴黎记者报道，交通罢工可能会持续一整周。","th":"常用词"},{"w":"correspondre","p":"v.","cn":"（~ à）符合、对应；通信","ex":"Ce poste correspond tout à fait à mon profil et à mes compétences.","exCn":"这个职位完全符合我的背景和能力。","th":"常用词"},{"w":"costume","p":"n.m.","cn":"西装；戏服、服装；（~ de bain）泳衣（魁北克）；cf. la coutume = 习俗","ex":"Ce costume te va bien.","exCn":"这套西装很适合你。","th":"常用词"},{"w":"coudre","p":"v.","cn":"缝、缝制","ex":"Je ne sais même pas coudre un bouton, alors j'ai apporté ma veste chez la couturière.","exCn":"我连扣子都不会缝，所以就把外套拿到裁缝那儿去了。","th":"常用词"},{"w":"couette","p":"n.f.","cn":"被子、羽绒被；（头两侧的）小辫子","ex":"En hiver, je dors sous une grosse couette.","exCn":"冬天我盖着一床厚被子睡觉。","th":"描述与状态"},{"w":"couler","p":"v.","cn":"流、流动；沉没；（考试）不及格、挂科（魁北克口语）","ex":"Le Saint-Laurent coule du lac Ontario vers l'océan Atlantique.","exCn":"圣劳伦斯河从安大略湖流向大西洋。","th":"工作与学习"},{"w":"coupable","p":"n.","cn":"有罪的；（感到）内疚的；罪犯、肇事者；罪魁祸首","ex":"La police pense avoir trouvé le coupable.","exCn":"警方认为已经找到了罪犯。","th":"常用词"},{"w":"couper-coller","p":"n.m.","cn":"剪切粘贴","ex":"Fais un couper-coller de ce paragraphe à la fin.","exCn":"把这一段剪切粘贴到末尾。","th":"日常动作"},{"w":"coupure","p":"n.f.","cn":"（水电等）中断；割伤、伤口；（预算、开支的）削减（魁北克）","ex":"Une coupure de courant a touché tout le quartier pendant trois heures.","exCn":"一次停电波及整个街区，持续了三个小时。","th":"健康与身体"},{"w":"courant","p":"n.m.","cn":"水流、气流；电流；潮流、思潮；常见的、日常的；cf. être au courant 知道、了解情况","ex":"Ne nage pas ici, le courant est trop fort.","exCn":"别在这儿游泳，水流太急了。","th":"抽象与概念"},{"w":"coureur","p":"n.","cn":"跑步者、赛跑选手；（自行车等）赛车手","ex":"Tôt le matin, le parc est déjà rempli de coureurs et de gens qui promènent leur chien.","exCn":"一大早，公园里就已经满是跑步的人和遛狗的人。","th":"出行与旅行"},{"w":"couronne","p":"n.f.","cn":"王冠；花环、花圈；（牙科）牙冠；（加拿大）检方、公诉方","ex":"La reine portait une couronne en or.","exCn":"女王戴着一顶金王冠。","th":"人物与身份"},{"w":"coussin","p":"n.m.","cn":"靠垫、坐垫；（~ gonflable）（汽车）安全气囊","ex":"Elle a glissé un coussin derrière son dos pour être plus à l'aise.","exCn":"她在背后塞了个靠垫，好坐得舒服些。","th":"出行与旅行"},{"w":"coutume","p":"n.f.","cn":"习俗、风俗；习惯","ex":"Selon une vieille coutume française, on mange la galette des rois en janvier.","exCn":"按照法国的古老习俗，人们在一月份吃国王饼。","th":"居住与环境"},{"w":"couture","p":"n.f.","cn":"缝纫；（高级）时装业","ex":"Ma grand-mère m'a appris la couture.","exCn":"我奶奶教会了我缝纫。","th":"描述与状态"},{"w":"couvercle","p":"n.m.","cn":"盖子","ex":"Pouvez-vous retirer le couvercle de cette boîte ?","exCn":"您能把这个盒子的盖子拿掉吗？","th":"常用词"},{"w":"couverture","p":"n.f.","cn":"毯子；（书刊的）封面；（保险、网络、媒体等的）覆盖、保障","ex":"Il fait froid cette nuit, prends une couverture de plus.","exCn":"今晚很冷，再拿一条毯子吧。","th":"社会与新闻"},{"w":"couvrir","p":"v.","cn":"覆盖、盖住；（保险等）承担、支付（费用）；（新闻）报道；（se ~）穿暖、多穿点","ex":"Le lierre couvre entièrement le mur de la vieille maison.","exCn":"常春藤爬满了老房子的整面墙。","th":"购物与金钱"},{"w":"covoiturage","p":"n.m.","cn":"拼车、合乘","ex":"Pour aller au travail, je fais du covoiturage avec un collègue.","exCn":"我和一个同事拼车去上班。","th":"出行与旅行"},{"w":"coïncidence","p":"n.f.","cn":"巧合","ex":"Quelle coïncidence ! Je pensais justement à toi quand tu as appelé.","exCn":"真巧！你打电话来的时候，我正好在想你。","th":"常用词"},{"w":"coût","p":"n.m.","cn":"成本、费用","ex":"Les entreprises cherchent toutes à réduire leurs coûts.","exCn":"企业都在想方设法降低成本。","th":"常用词"},{"w":"crabe","p":"n.m.","cn":"螃蟹","ex":"Nous avons mangé du crabe des neiges en Gaspésie.","exCn":"我们在加斯佩半岛吃了雪蟹。","th":"常用词"},{"w":"cracher","p":"v.","cn":"吐（口水、痰）","ex":"Il est interdit de cracher par terre dans le métro.","exCn":"地铁里禁止随地吐痰。","th":"常用词"},{"w":"craindre","p":"v.","cn":"害怕、担心；（ça craint）糟糕、差劲（口语）","ex":"Je crains de ne pas pouvoir venir à la réunion de demain.","exCn":"恐怕我明天没法参加会议了。","th":"情绪与性格"},{"w":"craquer","p":"v.","cn":"嘎吱作响、噼啪作响；破裂、裂开；崩溃、撑不住（口语）；（~ pour）忍不住（买、要）、动心（口语）","ex":"Le vieux plancher craque à chaque pas.","exCn":"旧地板每走一步都嘎吱作响。","th":"购物与金钱"},{"w":"creuser","p":"v.","cn":"挖、掘；深入研究（问题、想法）","ex":"C'est une bonne idée, mais il faudrait la creuser un peu avant de la présenter au patron.","exCn":"这个想法不错，不过在向老板提出之前，最好再深入研究一下。","th":"工作与学习"},{"w":"crever","p":"v.","cn":"（轮胎等）破裂、扎破；死（口语）；（~ de）…得要命（口语）；cf. être crevé 累坏了（口语）","ex":"Les éclats de verre sur la route risquent de crever les pneus.","exCn":"路上的玻璃碎片可能会扎破轮胎。","th":"描述与状态"},{"w":"cri","p":"n.m.","cn":"叫喊、喊声；cf. le dernier cri 最新款、最新潮的东西","ex":"Le bébé a poussé un petit cri de joie en voyant sa mère.","exCn":"看到妈妈，宝宝开心地叫了一声。","th":"描述与状态"},{"w":"crime","p":"n.m.","cn":"罪行、犯罪；谋杀、凶杀","ex":"Il a commis un crime grave et passera dix ans en prison.","exCn":"他犯下重罪，将在狱中度过十年。","th":"社会与新闻"},{"w":"criminel","p":"n.","cn":"罪犯；犯罪的、刑事的","ex":"Ce film raconte l'histoire d'un criminel qui veut changer de vie.","exCn":"这部电影讲的是一个想改过自新的罪犯的故事。","th":"社会与新闻"},{"w":"crise","p":"n.f.","cn":"危机；（病的）发作；cf. piquer une crise 大发脾气（口语）","ex":"La crise du logement frappe durement les familles à Toronto et à Vancouver.","exCn":"住房危机让多伦多和温哥华的家庭苦不堪言。","th":"健康与身体"},{"w":"critique","p":"n.f.","cn":"批评、评论；危急的、关键的；批判性的（esprit ~）；cf. le critique = 评论家","ex":"Il accepte mal la critique, même quand elle est constructive.","exCn":"他很难接受批评，哪怕是建设性的批评。","th":"观点与论证"},{"w":"critiquer","p":"v.","cn":"批评、指责","ex":"Le nouveau logo de la ville a été vivement critiqué sur les réseaux sociaux.","exCn":"城市的新标志在社交媒体上遭到了强烈批评。","th":"观点与论证"},{"w":"critère","p":"n.m.","cn":"标准、准则、条件","ex":"Le prix reste le principal critère de choix pour la plupart des acheteurs.","exCn":"对大多数买家来说，价格仍是最主要的选择标准。","th":"抽象与概念"},{"w":"croisement","p":"n.m.","cn":"交叉口、十字路口；（生物）杂交","ex":"L'accident s'est produit au croisement de deux routes de campagne.","exCn":"事故发生在两条乡间道路的交叉口。","th":"出行与旅行"},{"w":"croiser","p":"v.","cn":"（偶然）遇见、碰到；交叉、交叠；cf. croiser les doigts 祈求好运","ex":"J'ai croisé mon ancienne professeure au supermarché hier.","exCn":"我昨天在超市碰到了我以前的老师。","th":"描述与状态"},{"w":"croisière","p":"n.f.","cn":"邮轮旅行、航游；（vitesse de ~）巡航速度","ex":"Pour fêter leur retraite, ils ont fait une croisière en Méditerranée.","exCn":"为了庆祝退休，他们去地中海坐了一趟邮轮。","th":"出行与旅行"},{"w":"croix","p":"n.f.","cn":"十字、十字架；（表格里打的）叉号","ex":"Mettez une croix dans la case qui correspond à votre réponse.","exCn":"在与您的答案对应的方框里打个叉。","th":"常用词"},{"w":"croquer","p":"v.","cn":"咬、嚼（脆的东西）","ex":"Ne croque pas les glaçons, tu vas t'abîmer les dents !","exCn":"别嚼冰块，会把牙齿弄坏的！","th":"常用词"},{"w":"cru","p":"adj.","cn":"生的、未煮过的；（言辞）露骨的、直白的；（魁北克）（天气）湿冷的","ex":"Je n'aime pas le poisson cru.","exCn":"我不喜欢吃生鱼。","th":"时间与数量"},{"w":"crudités","p":"n.f.","cn":"生蔬菜冷盘","ex":"En entrée, nous avons des crudités.","exCn":"前菜是生蔬菜冷盘。","th":"饮食"},{"w":"cruel","p":"adj.","cn":"残忍的、残酷的","ex":"À la récréation, les enfants peuvent être très cruels entre eux.","exCn":"课间休息时，孩子们之间有时会非常残忍。","th":"常用词"},{"w":"créateur","p":"n.","cn":"创造者、创始人；（时装等）设计师","ex":"Le créateur de cette application n'avait que dix-neuf ans.","exCn":"这款应用的创始人当时只有十九岁。","th":"人物与身份"},{"w":"créatif","p":"adj.","cn":"有创造力的、创意的","ex":"Les enfants sont souvent plus créatifs que les adultes quand on leur donne une simple boîte en carton.","exCn":"只要给孩子们一个简单的纸箱，他们往往会比大人更有创造力。","th":"常用词"},{"w":"création","p":"n.f.","cn":"创造、创建；（艺术）创作","ex":"Depuis la création de l'association en 2015, plus de trois cents familles ont été aidées.","exCn":"自2015年协会成立以来，已有三百多个家庭得到了帮助。","th":"常用词"},{"w":"créativité","p":"n.f.","cn":"创造力、创意","ex":"Ce concours encourage la créativité des jeunes artistes.","exCn":"这项比赛鼓励年轻艺术家发挥创造力。","th":"常用词"},{"w":"crédit","p":"n.m.","cn":"贷款、信贷；信誉、信任；（大学课程的）学分；（~ d'impôt）税收抵免","ex":"Ils ont pris un crédit sur vingt-cinq ans pour acheter leur maison.","exCn":"为了买房，他们贷了一笔二十五年期的款。","th":"购物与金钱"},{"w":"créole","p":"n.m.","cn":"克里奥尔的；克里奥尔语","ex":"Dans le quartier Saint-Michel, à Montréal, on entend souvent parler le créole haïtien.","exCn":"在蒙特利尔的圣米歇尔区，经常能听到人们讲海地克里奥尔语。","th":"常用词"},{"w":"cube","p":"n.m.","cn":"立方体、方块；（~ de glace）冰块（魁北克用语）；（数学）立方","ex":"Coupez les pommes de terre en petits cubes avant de les faire cuire.","exCn":"先把土豆切成小方块再煮。","th":"常用词"},{"w":"cueillir","p":"v.","cn":"采摘、摘","ex":"Nous avons cueilli des fraises dans le jardin.","exCn":"我们在园子里摘了草莓。","th":"常用词"},{"w":"cuisse","p":"n.f.","cn":"大腿；（禽类的）腿","ex":"Le joueur s'est blessé à la cuisse droite pendant l'entraînement.","exCn":"那名球员在训练中右大腿受了伤。","th":"描述与状态"},{"w":"cuisson","p":"n.f.","cn":"烹煮、烧煮；（肉的）熟度","ex":"Le temps de cuisson est de vingt minutes.","exCn":"烹煮时间为二十分钟。","th":"饮食"},{"w":"culinaire","p":"adj.","cn":"烹饪的、饮食的","ex":"Lyon est célèbre pour ses traditions culinaires.","exCn":"里昂以烹饪传统闻名。","th":"常用词"},{"w":"cultiver","p":"v.","cn":"种植、耕种；培养、陶冶","ex":"Mes grands-parents cultivaient des tomates et des courgettes dans leur jardin.","exCn":"我爷爷奶奶以前在院子里种西红柿和西葫芦。","th":"常用词"},{"w":"cultivé","p":"adj.","cn":"有学识的、有教养的；（土地）耕种的、栽培的","ex":"C'est une femme très cultivée qui lit beaucoup.","exCn":"她是位很有学识的女士，读了很多书。","th":"常用词"},{"w":"curieusement","p":"adv.","cn":"奇怪的是、说来奇怪；奇怪地、古怪地","ex":"Curieusement, personne n'a remarqué que la porte était restée ouverte toute la nuit.","exCn":"奇怪的是，门开了一整夜，竟然没人发现。","th":"常用词"},{"w":"curiosité","p":"n.f.","cn":"好奇心；奇物、名胜","ex":"Par curiosité, j'ai assisté à un cours de cuisine haïtienne.","exCn":"出于好奇，我去上了一堂海地菜烹饪课。","th":"描述与状态"},{"w":"cycle","p":"n.m.","cn":"周期、循环；（学业）阶段","ex":"Le cycle de l'eau est l'un des premiers thèmes étudiés en sciences à l'école primaire.","exCn":"水循环是小学科学课最早学习的主题之一。","th":"时间与数量"},{"w":"câble","p":"n.m.","cn":"电缆、线缆；缆绳、钢索；（le ~）有线电视","ex":"Tu aurais un câble HDMI ? J'aimerais brancher mon ordinateur sur la télé.","exCn":"你有HDMI线吗？我想把电脑连到电视上。","th":"常用词"},{"w":"célébration","p":"n.f.","cn":"庆祝、庆典；（仪式的）举行","ex":"Une grande célébration est prévue pour les cent ans de la ville.","exCn":"为庆祝建城一百周年，市里将举办一场盛大的庆典。","th":"常用词"},{"w":"célébrer","p":"v.","cn":"庆祝；举行（仪式）","ex":"Pour célébrer sa promotion, elle a offert le champagne à toute l'équipe.","exCn":"为了庆祝升职，她请全组同事喝香槟。","th":"常用词"},{"w":"célébrité","p":"n.f.","cn":"名气、声望；名人","ex":"Ce jeune acteur a connu la célébrité grâce à une série télévisée.","exCn":"这位年轻演员凭借一部电视剧一举成名。","th":"人物与身份"},{"w":"d'ailleurs","p":"loc.","cn":"再说；此外","ex":"Le musée est fermé ; d'ailleurs, on n'a plus le temps.","exCn":"博物馆关门了，再说我们也没时间了。","th":"观点与论证"},{"w":"dater","p":"v.","cn":"（~ de）始于、追溯到；注明日期","ex":"Notre dernière rencontre date de l'année dernière.","exCn":"我们上次见面还是去年的事。","th":"常用词"},{"w":"davantage","p":"adv.","cn":"更多、更加","ex":"Si vous souhaitez en savoir davantage, consultez notre site Internet.","exCn":"如果您想了解更多，请访问我们的网站。","th":"常用词"},{"w":"demi-cercle","p":"n.m.","cn":"半圆；（en ~）呈半圆形","ex":"Les chaises forment un demi-cercle autour de la scène.","exCn":"椅子围着舞台摆成一个半圆。","th":"时间与数量"},{"w":"demi-finale","p":"n.f.","cn":"半决赛","ex":"Elle a perdu une demi-finale très serrée contre la tenante du titre.","exCn":"她在一场比分胶着的半决赛中输给了卫冕冠军。","th":"时间与数量"},{"w":"demi-livre","p":"n.f.","cn":"半斤（法国指250克）；（加拿大）半磅（约227克）","ex":"Une demi-livre de beurre, s'il vous plaît.","exCn":"请给我半斤黄油。","th":"时间与数量"},{"w":"demi-pension","p":"n.f.","cn":"（旅馆）含两餐的住宿；（学校）在校吃午饭","ex":"Nous avons réservé l'hôtel en demi-pension.","exCn":"我们订的酒店住宿含两餐。","th":"饮食"},{"w":"demi-tour","p":"n.m.","cn":"（faire ~）掉头、折返；向后转","ex":"La route était coupée par la neige, alors nous avons dû faire demi-tour.","exCn":"路被大雪封了，我们只好掉头。","th":"常用词"},{"w":"demoiselle","p":"n.f.","cn":"小姐、少女；（~ d'honneur）伴娘","ex":"Une jeune demoiselle nous a accueillis à l'entrée du musée.","exCn":"一位年轻小姐在博物馆门口接待了我们。","th":"人物与身份"},{"w":"dernièrement","p":"adv.","cn":"最近、近来","ex":"Il a beaucoup maigri dernièrement : il est malade ?","exCn":"他最近瘦了很多，是生病了吗？","th":"常用词"},{"w":"descente","p":"n.f.","cn":"下坡（路）；下来、下降；（警察的）突击搜查","ex":"Les cyclistes doivent ralentir dans cette descente dangereuse.","exCn":"骑车的人在这段危险的下坡路上必须减速。","th":"出行与旅行"},{"w":"design","p":"n.m.","cn":"设计、设计风格；有设计感的、新潮的","ex":"Elle étudie le design graphique à l'Université du Québec.","exCn":"她在魁北克大学学平面设计。","th":"居住与环境"},{"w":"dessinateur","p":"n.","cn":"（漫画、插图）画家；绘图员","ex":"C'est un célèbre dessinateur de bandes dessinées.","exCn":"他是一位著名的漫画家。","th":"常用词"},{"w":"dessiné","p":"adj.","cn":"画出的、绘制的；（轮廓）分明的；cf. la bande dessinée 漫画、连环画","ex":"Ces personnages ont été dessinés à la main.","exCn":"这些人物是手绘的。","th":"常用词"},{"w":"destin","p":"n.m.","cn":"命运","ex":"Le destin a voulu qu'ils se retrouvent à Montréal vingt ans plus tard.","exCn":"命运使然，二十年后他们在蒙特利尔重逢了。","th":"常用词"},{"w":"destinataire","p":"n.","cn":"收件人、收信人","ex":"Écrivez l'adresse du destinataire au milieu de l'enveloppe.","exCn":"把收件人地址写在信封中间。","th":"人物与身份"},{"w":"dette","p":"n.f.","cn":"债务","ex":"Il a mis cinq ans à rembourser toutes ses dettes.","exCn":"他花了五年才还清所有债务。","th":"常用词"},{"w":"diable","p":"n.m.","cn":"魔鬼；（喻）调皮鬼、淘气鬼","ex":"Dans ce conte, le diable propose un marché à un pauvre paysan.","exCn":"在这个故事里，魔鬼向一个穷苦的农民提出了一笔交易。","th":"常用词"},{"w":"diabète","p":"n.m.","cn":"糖尿病","ex":"Mon père souffre de diabète et doit surveiller son alimentation.","exCn":"我父亲患有糖尿病，得注意饮食。","th":"饮食"},{"w":"diagnostic","p":"n.m.","cn":"诊断","ex":"Le médecin a posé un diagnostic après plusieurs examens.","exCn":"做了几项检查之后，医生给出了诊断。","th":"常用词"},{"w":"diamant","p":"n.m.","cn":"钻石、金刚石","ex":"Dans la vitrine de la bijouterie, un énorme diamant brillait sous les projecteurs.","exCn":"珠宝店的橱窗里，一颗硕大的钻石在灯光下闪闪发亮。","th":"常用词"},{"w":"difficilement","p":"adv.","cn":"吃力地、艰难地；难以、很难","ex":"Le vieil homme montait difficilement l'escalier.","exCn":"老人吃力地爬着楼梯。","th":"饮食"},{"w":"différemment","p":"adv.","cn":"不同地","ex":"Que ferais-tu différemment ?","exCn":"你会有什么不同的做法？","th":"常用词"},{"w":"digestion","p":"n.f.","cn":"消化","ex":"Une petite promenade aide à la digestion.","exCn":"散散步有助于消化。","th":"常用词"},{"w":"digérer","p":"v.","cn":"消化；（喻）接受、忍受","ex":"Les produits laitiers sont difficiles à digérer pour certaines personnes.","exCn":"对有些人来说，乳制品不好消化。","th":"常用词"},{"w":"dimension","p":"n.f.","cn":"方面、层面；尺寸、规模","ex":"Ce projet a aussi une dimension sociale importante.","exCn":"这个项目还有很重要的社会层面。","th":"常用词"},{"w":"diminuer","p":"v.","cn":"减少、降低","ex":"Le prix de l'essence a légèrement diminué ce mois-ci.","exCn":"这个月汽油价格略有下降。","th":"描述与状态"},{"w":"dingue","p":"adj.","cn":"疯的、离谱的、难以置信的（口语）；（~ de）迷恋…的（口语）","ex":"C'est dingue, on s'est croisés trois fois aujourd'hui !","exCn":"太巧了，我们今天都碰见三回了！","th":"常用词"},{"w":"dinosaure","p":"n.m.","cn":"恐龙","ex":"Les dinosaures ont disparu il y a environ soixante-six millions d'années.","exCn":"恐龙大约在六千六百万年前灭绝。","th":"常用词"},{"w":"diplômé","p":"n.","cn":"（~ de）毕业于…的、有文凭的；毕业生","ex":"Elle est diplômée de l'Université de Montréal.","exCn":"她毕业于蒙特利尔大学。","th":"工作与学习"},{"w":"diriger","p":"v.","cn":"领导、管理；指挥；（se ~ vers）走向、朝…去","ex":"Elle dirige une petite entreprise de vingt employés.","exCn":"她管理着一家有二十名员工的小公司。","th":"常用词"},{"w":"discipline","p":"n.f.","cn":"纪律；学科；（体育）项目","ex":"Dans cette école, la discipline est très stricte.","exCn":"这所学校的纪律非常严格。","th":"工作与学习"},{"w":"discours","p":"n.m.","cn":"演讲、言论","ex":"Le jour de la remise des diplômes, c'est elle qui a prononcé le discours des finissants.","exCn":"毕业典礼那天，由她代表毕业生致辞。","th":"常用词"},{"w":"discret","p":"adj.","cn":"（人）嘴严的、谨慎的；低调的、不显眼的","ex":"Tu peux me faire confiance, je suis quelqu'un de très discret.","exCn":"你可以相信我，我嘴很严。","th":"人物与身份"},{"w":"disparaître","p":"v.","cn":"消失、不见；失踪","ex":"Sans protection, plusieurs espèces d'oiseaux risquent de disparaître.","exCn":"如果不加以保护，好几种鸟类可能会消失。","th":"常用词"},{"w":"disparition","p":"n.f.","cn":"消失、失踪；（委婉）去世","ex":"Certaines espèces d'oiseaux sont menacées de disparition.","exCn":"一些鸟类面临灭绝的威胁。","th":"常用词"},{"w":"disposition","p":"n.f.","cn":"布局、安排；（à la ~ de）供…支配、使用；（复数）措施、准备；（法律）条款","ex":"Je reste à votre disposition pour tout renseignement complémentaire.","exCn":"如需更多信息，请随时与我联系。","th":"社会与新闻"},{"w":"dispute","p":"n.f.","cn":"争吵、口角、吵架","ex":"Une dispute a éclaté entre deux voisins à propos d'une place de stationnement.","exCn":"两个邻居为了一个停车位吵了起来。","th":"描述与状态"},{"w":"distinguer","p":"v.","cn":"区分、辨别；（se ~）出众、突出","ex":"Les jeunes enfants ont du mal à distinguer la réalité de la fiction.","exCn":"小孩子很难分清现实和虚构。","th":"居住与环境"},{"w":"distraire","p":"v.","cn":"使分心、打扰；（se ~）消遣、散心","ex":"Ne distrais pas ton frère, il fait ses devoirs.","exCn":"别让你弟弟分心，他在写作业。","th":"交际与礼貌"},{"w":"distribuer","p":"v.","cn":"分发、分配；配送、经销","ex":"Des bénévoles distribuent des repas aux sans-abri chaque soir.","exCn":"志愿者每晚给无家可归的人分发饭菜。","th":"常用词"},{"w":"distribution","p":"n.f.","cn":"分发、分配；（商品）销售、流通；（影视）演员阵容","ex":"La distribution des colis alimentaires aura lieu samedi matin au centre communautaire.","exCn":"食品包将于周六上午在社区中心发放。","th":"购物与金钱"},{"w":"divan","p":"n.m.","cn":"长沙发、无靠背沙发；（魁北克）沙发（日常用语）","ex":"Il s'est endormi sur le divan du salon.","exCn":"他在客厅的长沙发上睡着了。","th":"描述与状态"},{"w":"divers","p":"adj.","cn":"各种的、多样的；cf. les faits divers 社会新闻","ex":"Il a exercé divers métiers avant de devenir enseignant.","exCn":"当老师之前，他干过各种行当。","th":"社会与新闻"},{"w":"diversité","p":"n.f.","cn":"多样性、多元","ex":"Montréal est connue pour sa diversité culturelle.","exCn":"蒙特利尔以文化多元著称。","th":"常用词"},{"w":"divertir","p":"v.","cn":"使娱乐、逗乐；（se ~）消遣、娱乐","ex":"Ce spectacle de magie a beaucoup diverti les enfants.","exCn":"这场魔术表演让孩子们看得非常开心。","th":"常用词"},{"w":"divertissement","p":"n.m.","cn":"娱乐、消遣","ex":"La lecture reste mon divertissement préféré.","exCn":"阅读仍然是我最喜欢的消遣。","th":"常用词"},{"w":"diviser","p":"v.","cn":"划分、分开；（数学）除；使分裂、使对立","ex":"Le professeur a divisé la classe en quatre groupes.","exCn":"老师把全班分成了四个小组。","th":"常用词"},{"w":"doctorat","p":"n.m.","cn":"博士学位","ex":"Elle est la première de sa famille à obtenir un doctorat.","exCn":"她是家里第一个拿到博士学位的人。","th":"常用词"},{"w":"domaine","p":"n.m.","cn":"领域；地产、庄园","ex":"Elle cherche un emploi dans le domaine de la santé.","exCn":"她在找医疗卫生领域的工作。","th":"常用词"},{"w":"domestique","p":"adj.","cn":"家庭的、家务的；（动物）家养的","ex":"Nous partageons les tâches domestiques à égalité.","exCn":"我们平均分担家务。","th":"居住与环境"},{"w":"domicile","p":"n.m.","cn":"住所、住址；（à ~）上门、在家","ex":"Le supermarché du quartier livre les courses à domicile.","exCn":"街区的超市提供送货上门服务。","th":"居住与环境"},{"w":"don","p":"n.m.","cn":"捐赠、捐献；天赋、才能","ex":"Elle a fait un don de cent dollars à la Croix-Rouge.","exCn":"她向红十字会捐了一百加元。","th":"时间与数量"},{"w":"donnée","p":"n.f.","cn":"数据、资料；（问题的）已知条件","ex":"Les données de l'enquête ont été analysées par des chercheurs.","exCn":"调查数据由研究人员进行了分析。","th":"时间与数量"},{"w":"dont","p":"pron.","cn":"…的（关系代词、代替 de + 名词）；其中（包括）","ex":"Voici le formulaire dont vous aurez besoin pour votre demande.","exCn":"这是您申请时需要用到的表格。","th":"功能词与连接"},{"w":"dortoir","p":"n.m.","cn":"集体宿舍","ex":"Dans cette auberge de jeunesse, un lit en dortoir coûte vingt-cinq dollars la nuit.","exCn":"这家青年旅舍的多人间床位每晚二十五加元。","th":"常用词"},{"w":"doré","p":"adj.","cn":"镀金的；金色的；（烹饪）煎得或烤得金黄的；cf.（魁北克）le doré 大眼梭鲈（常见淡水鱼）","ex":"Faites cuire les crêpes jusqu'à ce qu'elles soient bien dorées.","exCn":"把可丽饼煎到两面金黄。","th":"饮食"},{"w":"dose","p":"n.f.","cn":"剂量、用量","ex":"Ne dépassez pas la dose indiquée sur la notice.","exCn":"不要超过说明书上标明的剂量。","th":"常用词"},{"w":"dossier","p":"n.m.","cn":"（一套）材料、档案、文件夹；议题、案件；（椅子的）靠背","ex":"J'ai un gros dossier à terminer avant les vacances.","exCn":"放假前我手上有个大项目要做完。","th":"常用词"},{"w":"doubler","p":"v.","cn":"（使）加倍、翻番；超车；（影视）配音","ex":"Ce dessin animé japonais a été doublé en français par des acteurs très connus.","exCn":"这部日本动画片由一批知名演员配成了法语。","th":"出行与旅行"},{"w":"douceur","p":"n.f.","cn":"温柔、温和；柔软、柔和；（复数）甜食；cf. en douceur 平稳地、温和地","ex":"Elle a parlé à l'enfant avec une grande douceur.","exCn":"她非常温柔地跟孩子说话。","th":"饮食"},{"w":"douloureux","p":"adj.","cn":"疼痛的；痛苦的、令人悲痛的","ex":"J'ai le genou douloureux depuis ma chute.","exCn":"摔倒之后我的膝盖一直疼。","th":"健康与身体"},{"w":"douter","p":"v.","cn":"怀疑；（se ~）料到、猜到","ex":"Je doute qu'il puisse finir ce travail avant vendredi.","exCn":"我怀疑他能不能在周五前完成这项工作。","th":"常用词"},{"w":"doué","p":"adj.","cn":"有天赋的、有才能的；（~ de）具有…的","ex":"Ma fille est très douée pour la musique.","exCn":"我女儿很有音乐天赋。","th":"时间与数量"},{"w":"dragon","p":"n.m.","cn":"龙","ex":"Dans la culture chinoise, le dragon est un symbole de puissance et de chance.","exCn":"在中国文化中，龙是力量和好运的象征。","th":"常用词"},{"w":"dramatique","p":"adj.","cn":"严重的、悲惨的；戏剧性的；戏剧的（art ~ 戏剧艺术）","ex":"La situation dans les zones inondées est dramatique.","exCn":"洪灾地区的情况非常严峻。","th":"描述与状态"},{"w":"drame","p":"n.m.","cn":"惨剧、悲剧事件；（戏剧、影视）正剧、剧情片；cf. en faire tout un drame（口语）小题大做","ex":"Ce drame a profondément choqué toute la ville.","exCn":"这场惨剧让全城深感震惊。","th":"描述与状态"},{"w":"drap","p":"n.m.","cn":"床单；cf. être dans de beaux draps 处境不妙、陷入困境","ex":"J'ai mis un drap propre sur le lit de la chambre d'amis.","exCn":"我在客房的床上铺了一条干净的床单。","th":"常用词"},{"w":"drogue","p":"n.f.","cn":"毒品","ex":"La drogue détruit la vie de nombreux jeunes.","exCn":"毒品毁掉了许多年轻人的生活。","th":"常用词"},{"w":"duo","p":"n.m.","cn":"二人组、搭档；二重唱、二重奏","ex":"Ces deux humoristes forment un duo très populaire au Québec.","exCn":"这两位喜剧演员是魁北克很受欢迎的搭档组合。","th":"人物与身份"},{"w":"durable","p":"adj.","cn":"可持续的；持久的","ex":"Ils cherchent une solution durable.","exCn":"他们在寻找可持续的方案。","th":"社会与新闻"},{"w":"durant","p":"prép.","cn":"在…期间","ex":"Durant les vacances d'été, la bibliothèque ferme plus tôt.","exCn":"暑假期间，图书馆关门比较早。","th":"常用词"},{"w":"dès","p":"prép.","cn":"从…起、自…起；cf. dès que 一…就","ex":"Le magasin est ouvert dès sept heures du matin.","exCn":"这家商店早上七点就开门。","th":"常用词"},{"w":"débardeur","p":"n.m.","cn":"无袖背心；cf. la camisole 无袖背心（魁北克说法）","ex":"En été, il porte souvent un débardeur.","exCn":"夏天他常穿无袖背心。","th":"常用词"},{"w":"débarrasser","p":"v.","cn":"收拾（桌子）、清理、腾空；（se ~ de）摆脱、处理掉","ex":"Peux-tu m'aider à débarrasser la table ?","exCn":"你能帮我收拾一下桌子吗？","th":"描述与状态"},{"w":"débat","p":"n.m.","cn":"辩论、讨论","ex":"Le débat a duré plus de deux heures sans qu'on arrive à se mettre d'accord.","exCn":"讨论持续了两个多小时，大家还是没能达成一致。","th":"观点与论证"},{"w":"débrancher","p":"v.","cn":"拔掉插头、断开","ex":"Débranchez l'appareil avant de le nettoyer.","exCn":"清洁前请先拔掉电器的插头。","th":"常用词"},{"w":"débuter","p":"v.","cn":"开始；初入行、首次登台","ex":"Le spectacle débutera à 20 heures précises.","exCn":"演出将于晚上8点整开始。","th":"常用词"},{"w":"déception","p":"n.f.","cn":"失望","ex":"Quelle déception ! Le film était beaucoup moins bon que le livre.","exCn":"太让人失望了！电影比原著差远了。","th":"情绪与性格"},{"w":"décevoir","p":"v.","cn":"使失望","ex":"Ce restaurant m'a beaucoup déçu : le service était très lent.","exCn":"这家餐厅让我很失望：上菜太慢了。","th":"情绪与性格"},{"w":"déchet","p":"n.m.","cn":"（多用复数）垃圾、废物","ex":"Il faut bien trier ses déchets ménagers.","exCn":"要做好生活垃圾分类。","th":"常用词"},{"w":"déchirer","p":"v.","cn":"撕破、撕碎；（喻）撕裂、使痛苦","ex":"Il a déchiré la lettre sans même l'ouvrir.","exCn":"他连信都没拆就把它撕了。","th":"健康与身体"},{"w":"déclaration","p":"n.f.","cn":"声明；申报、登记；（~ d'amour）表白","ex":"N'oubliez pas de faire votre déclaration de revenus avant le 30 avril.","exCn":"别忘了在4月30日之前申报个人所得税。","th":"描述与状态"},{"w":"déclarer","p":"v.","cn":"宣布、声明；申报；（se ~）（火灾、疾病等）发生、爆发","ex":"Le joueur a déclaré aux journalistes qu'il prendrait sa retraite à la fin de la saison.","exCn":"这名球员向记者表示，他将在赛季结束后退役。","th":"健康与身体"},{"w":"décollage","p":"n.m.","cn":"（飞机）起飞；（经济）腾飞","ex":"Le décollage de notre vol a été retardé à cause du brouillard.","exCn":"由于大雾，我们的航班推迟起飞了。","th":"出行与旅行"},{"w":"déconseiller","p":"v.","cn":"劝阻、建议不要","ex":"Je vous déconseille de prendre la voiture ce soir : les routes sont glacées.","exCn":"我建议您今晚别开车，路面都结冰了。","th":"常用词"},{"w":"décontracté","p":"adj.","cn":"放松的、轻松的；（衣着）休闲的、随意的","ex":"Il est arrivé à l'entretien très décontracté, comme si de rien n'était.","exCn":"他去面试时一副轻松自在、若无其事的样子。","th":"描述与状态"},{"w":"décor","p":"n.m.","cn":"装饰、装潢；（舞台）布景、背景","ex":"Le décor de ce restaurant est simple mais chaleureux.","exCn":"这家餐厅的装潢简单却温馨。","th":"常用词"},{"w":"découper","p":"v.","cn":"切开、切块；剪下、裁下","ex":"Découpez le poulet en morceaux avant de le faire revenir dans la poêle.","exCn":"先把鸡切成块，再放进平底锅里煸炒。","th":"日常动作"},{"w":"décourager","p":"v.","cn":"使气馁、使灰心；（~ qqn de）使打消念头、劝阻；（se ~）灰心、泄气","ex":"Ne te décourage pas, tu auras ton permis la prochaine fois.","exCn":"别灰心，下次你一定能考到驾照。","th":"常用词"},{"w":"découragé","p":"adj.","cn":"灰心的、气馁的","ex":"Les bénévoles sont découragés par le manque de moyens.","exCn":"资源不足让志愿者们很泄气。","th":"常用词"},{"w":"décrocher","p":"v.","cn":"（从挂处）取下、摘下；接（电话）；获得、拿到（合同、奖牌等）；辍学；走神、跟不上（口语）","ex":"J'ai appelé trois fois, mais personne n'a décroché.","exCn":"我打了三次电话，但都没人接。","th":"常用词"},{"w":"décès","p":"n.m.","cn":"死亡、去世","ex":"Il a appris le décès de son oncle par téléphone.","exCn":"他通过电话得知了叔叔去世的消息。","th":"常用词"},{"w":"défaire","p":"v.","cn":"解开、拆开；（se ~ de）摆脱、舍弃","ex":"Dès mon arrivée à l'hôtel, j'ai défait ma valise.","exCn":"一到酒店，我就把行李箱里的东西拿了出来。","th":"日常动作"},{"w":"défaite","p":"n.f.","cn":"失败、战败","ex":"Après trois défaites d'affilée, l'entraîneur a été remplacé.","exCn":"连输三场之后，教练被撤换了。","th":"常用词"},{"w":"défaut","p":"n.m.","cn":"缺点、缺陷；（par ~）默认；（à ~ de）没有…的话、缺少…时","ex":"Son plus grand défaut, c'est qu'il n'écoute jamais les autres.","exCn":"他最大的缺点就是从来不听别人的意见。","th":"常用词"},{"w":"défendre","p":"v.","cn":"保卫、捍卫；禁止","ex":"Cette association défend les droits des locataires.","exCn":"这个协会捍卫租户的权益。","th":"常用词"},{"w":"défense","p":"n.f.","cn":"防御、保卫；辩护；（~ de + 动词原形）禁止…","ex":"Le gouvernement a augmenté le budget de la défense nationale.","exCn":"政府增加了国防预算。","th":"常用词"},{"w":"défi","p":"n.m.","cn":"挑战","ex":"Apprendre le français en un an est un véritable défi.","exCn":"一年内学会法语是个不小的挑战。","th":"常用词"},{"w":"défilé","p":"n.m.","cn":"游行、阅兵；时装秀；（人、车）络绎不绝","ex":"Les enfants ont adoré le défilé du père Noël.","exCn":"孩子们特别喜欢圣诞老人游行。","th":"出行与旅行"},{"w":"définir","p":"v.","cn":"定义；确定、明确","ex":"Il est difficile de définir le bonheur en quelques mots.","exCn":"很难用三言两语来定义幸福。","th":"常用词"},{"w":"définitif","p":"adj.","cn":"最终的、确定的；永久的","ex":"Le résultat définitif du vote sera connu demain soir.","exCn":"投票的最终结果明晚揭晓。","th":"常用词"},{"w":"définition","p":"n.f.","cn":"定义；（图像）清晰度","ex":"Je ne connais pas ce mot, je vais chercher sa définition dans le dictionnaire.","exCn":"我不认识这个词，我去词典里查一下它的定义。","th":"常用词"},{"w":"définitivement","p":"adv.","cn":"永久地、彻底地；口语中也常当「肯定、绝对」讲（魁北克尤其常见），正式写作避免","ex":"Après dix ans à Paris, ils se sont installés définitivement à Montréal.","exCn":"在巴黎住了十年之后，他们在蒙特利尔定居了下来。","th":"常用词"},{"w":"déforestation","p":"n.f.","cn":"森林砍伐、毁林","ex":"La déforestation menace de nombreuses espèces.","exCn":"森林砍伐威胁着许多物种。","th":"居住与环境"},{"w":"dégoûter","p":"v.","cn":"使恶心、使厌恶；（~ qqn de）使对…失去兴趣；（être dégoûté）郁闷、失望（口语）","ex":"L'odeur du poisson pas frais me dégoûte.","exCn":"不新鲜的鱼的味道让我恶心。","th":"情绪与性格"},{"w":"déguisement","p":"n.m.","cn":"化装服、装扮服；乔装、伪装","ex":"Pour Halloween, mon fils a choisi un déguisement de pirate.","exCn":"万圣节我儿子挑了一套海盗装。","th":"常用词"},{"w":"dégât","p":"n.m.","cn":"（多用复数）损坏、损失","ex":"La tempête a causé d'importants dégâts.","exCn":"暴风雨造成了严重的损失。","th":"描述与状态"},{"w":"délai","p":"n.m.","cn":"期限、时限；延期、宽限","ex":"Le délai d'inscription à l'université est déjà dépassé : il faudra attendre l'année prochaine.","exCn":"大学报名期限已经过了，只能等明年了。","th":"描述与状态"},{"w":"délicat","p":"adj.","cn":"精致的、细腻的；娇嫩的、脆弱的；棘手的、微妙的；体贴的","ex":"Ce thé blanc a un parfum délicat qui disparaît si l'eau est trop chaude.","exCn":"这款白茶香气细腻，水太烫的话香味就没了。","th":"描述与状态"},{"w":"délice","p":"n.m.","cn":"美味（佳肴）；乐事、享受","ex":"Cette tarte au sirop d'érable est un vrai délice !","exCn":"这个枫糖派真是人间美味！","th":"常用词"},{"w":"délégué","p":"n.","cn":"代表、代表人","ex":"En septembre, les élèves ont élu deux délégués de classe.","exCn":"九月份，学生们选出了两名班级代表。","th":"人物与身份"},{"w":"démarche","p":"n.f.","cn":"（办事）手续、步骤；步态、走路姿势","ex":"J'ai commencé les démarches pour obtenir mon visa.","exCn":"我已经开始办理签证手续了。","th":"出行与旅行"},{"w":"démission","p":"n.f.","cn":"辞职；（对责任的）放弃、失职","ex":"Après dix ans dans l'entreprise, elle a donné sa démission.","exCn":"在公司工作十年后，她递交了辞呈。","th":"常用词"},{"w":"démissionner","p":"v.","cn":"辞职","ex":"Il a démissionné de son poste de directeur pour des raisons de santé.","exCn":"他因为健康原因辞去了经理职务。","th":"常用词"},{"w":"démocratie","p":"n.f.","cn":"民主","ex":"La liberté de la presse est essentielle dans une démocratie.","exCn":"在民主国家，新闻自由至关重要。","th":"常用词"},{"w":"démonstration","p":"n.f.","cn":"演示、示范；（数学、逻辑）证明、论证","ex":"Le vendeur nous a fait une démonstration du nouvel aspirateur.","exCn":"售货员给我们演示了新款吸尘器。","th":"观点与论证"},{"w":"déménageur","p":"n.m.","cn":"搬家工人","ex":"Le déménageur arrive demain à huit heures avec son camion.","exCn":"搬家工人明天八点开着卡车过来。","th":"人物与身份"},{"w":"dépasser","p":"v.","cn":"超过、超出；超（车）、赶过；（ça me dépasse）让人无法理解（口语）","ex":"Le coût des travaux a dépassé le budget prévu.","exCn":"工程费用超出了原定预算。","th":"出行与旅行"},{"w":"dépendre de","p":"v.","cn":"取决于","ex":"Le prix dépend de la saison.","exCn":"价格取决于季节。","th":"观点与论证"},{"w":"dépense","p":"n.f.","cn":"开支、支出；消耗（能量）","ex":"Le loyer est ma plus grosse dépense chaque mois.","exCn":"房租是我每个月最大的一笔开支。","th":"购物与金钱"},{"w":"dépensier","p":"adj.","cn":"爱花钱的、大手大脚的","ex":"Il est tellement dépensier qu'il est à découvert à la fin de chaque mois.","exCn":"他花钱大手大脚，每到月底账户都透支。","th":"购物与金钱"},{"w":"déplacement","p":"n.m.","cn":"出行、出差；移动、迁移","ex":"Le directeur est en déplacement à Toronto jusqu'à jeudi.","exCn":"经理去多伦多出差了，周四才回来。","th":"常用词"},{"w":"déplacer","p":"v.","cn":"挪动、移动；改期、调整（时间）；（se ~）出行、走动","ex":"Pouvez-vous m'aider à déplacer ce meuble près de la fenêtre ?","exCn":"您能帮我把这件家具挪到窗边吗？","th":"时间与数量"},{"w":"déplaire","p":"v.","cn":"（~ à）使不高兴、不讨…喜欢；（ne pas ~）还挺喜欢","ex":"Sa remarque sur les horaires a beaucoup déplu à son chef.","exCn":"他对工作时间的那番话让上司很不高兴。","th":"情绪与性格"},{"w":"dépliant","p":"n.m.","cn":"宣传折页、宣传册","ex":"Prenez un dépliant à l'office de tourisme.","exCn":"去旅游局拿一份宣传折页吧。","th":"常用词"},{"w":"déposer","p":"v.","cn":"放下、存放、存入（钱款）；（开车）把（某人）送到；提交（申请、投诉）","ex":"Je peux te déposer à la gare en allant au travail.","exCn":"我上班顺路可以把你送到火车站。","th":"出行与旅行"},{"w":"déprimé","p":"adj.","cn":"情绪低落的、抑郁的","ex":"Depuis son licenciement, il est très déprimé.","exCn":"自从被解雇后，他一直很消沉。","th":"描述与状态"},{"w":"dépôt","p":"n.m.","cn":"存款、存入；仓库；（申请、文件的）提交、递交","ex":"J'ai fait un dépôt de cinq cents dollars sur mon compte ce matin.","exCn":"今天早上我往账户里存了五百元。","th":"交际与礼貌"},{"w":"dérangement","p":"n.m.","cn":"打扰、麻烦","ex":"Excusez-moi du dérangement, j'aurais une petite question.","exCn":"不好意思打扰一下，我想问个小问题。","th":"交际与礼貌"},{"w":"désaccord","p":"n.m.","cn":"分歧、意见不合","ex":"Il y a un désaccord profond entre les deux partis sur la réforme fiscale.","exCn":"两党在税制改革问题上存在严重分歧。","th":"观点与论证"},{"w":"désastre","p":"n.m.","cn":"灾难、灾祸","ex":"Le concert en plein air a été un désastre à cause de la pluie.","exCn":"因为下雨，这场露天音乐会简直是一场灾难。","th":"常用词"},{"w":"désespéré","p":"adj.","cn":"绝望的；（情况）无望的、危急的","ex":"Après des mois de recherche d'emploi sans succès, il commence à être désespéré.","exCn":"找了几个月工作都没结果，他开始绝望了。","th":"抽象与概念"},{"w":"déshabiller","p":"v.","cn":"给…脱衣服；（se ~）脱衣服","ex":"La mère a déshabillé le bébé avant de lui donner son bain.","exCn":"妈妈先给宝宝脱了衣服，再给他洗澡。","th":"日常动作"},{"w":"désir","p":"n.m.","cn":"愿望、欲望","ex":"Il a exprimé le désir de travailler à l'étranger.","exCn":"他表达了想去国外工作的愿望。","th":"常用词"},{"w":"désordonné","p":"adj.","cn":"（人）不爱整理的、邋遢的；杂乱的、无序的","ex":"Mon colocataire est très désordonné : sa chambre est un vrai champ de bataille.","exCn":"我室友特别邋遢，他的房间简直像个战场。","th":"情绪与性格"},{"w":"désordre","p":"n.m.","cn":"混乱、凌乱、无序","ex":"Excuse le désordre, je n'ai pas eu le temps de ranger.","exCn":"不好意思，家里很乱，我还没来得及收拾。","th":"常用词"},{"w":"détacher","p":"v.","cn":"解开、松开；（se ~）脱离、脱落","ex":"Ne détachez pas votre ceinture avant l'arrêt complet de l'avion.","exCn":"飞机完全停稳之前，请不要解开安全带。","th":"日常动作"},{"w":"détective","p":"n.","cn":"侦探","ex":"Il a engagé un détective privé pour retrouver son frère disparu.","exCn":"他雇了一名私家侦探寻找失踪的哥哥。","th":"常用词"},{"w":"détente","p":"n.f.","cn":"放松、休息；（局势、关系）缓和","ex":"Cette séance de yoga m'a apporté une vraie détente après une semaine stressante.","exCn":"紧张了一周之后，这节瑜伽课让我真正放松了下来。","th":"抽象与概念"},{"w":"déterminer","p":"v.","cn":"确定、查明；决定","ex":"Il faut d'abord déterminer qui est responsable de l'accident.","exCn":"首先得确定谁该为这起事故负责。","th":"常用词"},{"w":"déterminé","p":"adj.","cn":"坚决的、下定决心的；确定的、特定的","ex":"Malgré sa blessure, il est plus déterminé que jamais à courir le marathon de Paris.","exCn":"尽管受了伤，他还是比以往任何时候都更坚定地要跑巴黎马拉松。","th":"常用词"},{"w":"détour","p":"n.m.","cn":"绕道、绕路；（sans ~）直截了当、不拐弯抹角；（valoir le ~）值得专程一去","ex":"La route était fermée, nous avons dû faire un détour de vingt kilomètres.","exCn":"路被封了，我们只好绕道多走了二十公里。","th":"出行与旅行"},{"w":"détruire","p":"v.","cn":"摧毁、破坏","ex":"L'incendie a complètement détruit l'entrepôt pendant la nuit.","exCn":"大火在夜里把仓库烧得精光。","th":"描述与状态"},{"w":"détruit","p":"adj.","cn":"被毁的、被摧毁的；（精神上）垮掉的","ex":"Le pont détruit par la tempête sera reconstruit.","exCn":"被暴风雨摧毁的桥将会重建。","th":"常用词"},{"w":"développement","p":"n.m.","cn":"发展、开发","ex":"Le sommeil joue un rôle essentiel dans le développement de l'enfant.","exCn":"睡眠对儿童的成长发展起着至关重要的作用。","th":"常用词"},{"w":"développer","p":"v.","cn":"发展、开发；详述、展开","ex":"Cette entreprise développe des logiciels pour les hôpitaux.","exCn":"这家公司为医院开发软件。","th":"常用词"},{"w":"effectuer","p":"v.","cn":"进行、执行","ex":"Le contrôle technique doit être effectué tous les deux ans.","exCn":"车检必须每两年做一次。","th":"常用词"},{"w":"efficace","p":"adj.","cn":"有效的；（人）能干的、办事高效的","ex":"Pour retenir le vocabulaire, la méthode la plus efficace, c'est de le revoir régulièrement.","exCn":"要记住词汇，最有效的方法就是定期复习。","th":"人物与身份"},{"w":"efficacité","p":"n.f.","cn":"效力、效果；效率","ex":"L'efficacité de ce vaccin a été confirmée par plusieurs études.","exCn":"多项研究证实了这种疫苗的效果。","th":"常用词"},{"w":"effrayant","p":"adj.","cn":"可怕的、吓人的","ex":"J'ai vu hier soir un film d'horreur vraiment effrayant.","exCn":"我昨晚看了一部非常吓人的恐怖片。","th":"人物与身份"},{"w":"emballage","p":"n.m.","cn":"包装、包装材料","ex":"Ce supermarché encourage les clients à apporter leurs propres contenants pour réduire les emballages.","exCn":"这家超市鼓励顾客自带容器，以减少包装。","th":"常用词"},{"w":"emballer","p":"v.","cn":"包装、打包；使着迷、使兴奋（口语）；（s'~）激动起来；（s'~）（价格等）飙升、失控","ex":"Pourriez-vous emballer ce livre ? C'est pour offrir.","exCn":"能帮我把这本书包起来吗？是送人的。","th":"购物与金钱"},{"w":"embarquer","p":"v.","cn":"上船、登机；（魁北克）上车；带走、（警察）抓走（口语）；（s'~ dans）着手、卷入","ex":"Nous avons embarqué sur le ferry à six heures du matin pour rejoindre l'île.","exCn":"我们早上六点登上渡轮前往岛上。","th":"出行与旅行"},{"w":"embarrassé","p":"adj.","cn":"尴尬的、难为情的；为难的、困惑的","ex":"Il avait l'air embarrassé quand je lui ai demandé où il était hier soir.","exCn":"我问他昨晚去哪儿了，他显得很尴尬。","th":"常用词"},{"w":"embaucher","p":"v.","cn":"雇用","ex":"La société va embaucher dix personnes.","exCn":"公司要招十个人。","th":"工作与学习"},{"w":"embêter","p":"v.","cn":"烦、打扰、使厌烦（口语）；（s'~）感到无聊、发闷（口语）","ex":"Ça m'embête de devoir travailler samedi.","exCn":"周六还得上班，真烦人。","th":"情绪与性格"},{"w":"emménager","p":"v.","cn":"搬入、迁入（新居）；cf. déménager 搬家","ex":"Mes nouveaux voisins viennent d'emménager et ne connaissent encore personne dans l'immeuble.","exCn":"我的新邻居刚搬进来，在楼里还谁都不认识。","th":"描述与状态"},{"w":"empereur","p":"n.m.","cn":"皇帝","ex":"Napoléon est devenu empereur en 1804.","exCn":"拿破仑于1804年称帝。","th":"常用词"},{"w":"emplacement","p":"n.m.","cn":"位置、地点","ex":"N'oubliez pas de noter l'emplacement de votre voiture dans le stationnement.","exCn":"别忘了记下你的车停在停车场的哪个位置。","th":"常用词"},{"w":"employer","p":"v.","cn":"雇用、聘用；使用、运用","ex":"Cette usine emploie près de trois cents personnes.","exCn":"这家工厂雇用了近三百名员工。","th":"常用词"},{"w":"employeur","p":"n.m.","cn":"雇主","ex":"Mon employeur m'a accordé une semaine de congé.","exCn":"雇主给了我一周假。","th":"常用词"},{"w":"emporter","p":"v.","cn":"带走（物）；（水流、风）冲走、卷走；（l'~ sur）战胜、占上风；（s'~）发火、发脾气；cf. emmener 带走（人）；apporter 带来（物）","ex":"Sur place ou pour emporter ?","exCn":"堂食还是外带？","th":"人物与身份"},{"w":"emprunter","p":"v.","cn":"借（入）、借用；走（某路线）、取道","ex":"J'ai emprunté trois livres à la bibliothèque.","exCn":"我从图书馆借了三本书。","th":"出行与旅行"},{"w":"empêcher","p":"v.","cn":"阻止、妨碍；（s'~ de）忍住、克制；n'empêche (que)…：不过、尽管如此（口语）","ex":"La pluie ne nous a pas empêchés de visiter la vieille ville.","exCn":"下雨也没妨碍我们游览老城。","th":"居住与环境"},{"w":"en avant","p":"loc.","cn":"向前、往前；（mettre ~）突出、强调","ex":"Il a fait un pas en avant.","exCn":"他向前迈了一步。","th":"描述与状态"},{"w":"en effet","p":"loc.","cn":"确实；因为（证实）","ex":"En effet, la situation est compliquée.","exCn":"确实，情况很复杂。","th":"观点与论证"},{"w":"en revanche","p":"loc.","cn":"相反地；另一方面","ex":"Le loyer est cher ; en revanche, le quartier est calme.","exCn":"房租贵，不过这个街区很安静。","th":"观点与论证"},{"w":"enceinte","p":"n.f.","cn":"怀孕的；音箱；围墙、（场所的）范围","ex":"Elle est enceinte de cinq mois et attend son premier enfant.","exCn":"她怀孕五个月了，这是她的第一个孩子。","th":"抽象与概念"},{"w":"encourager","p":"v.","cn":"鼓励、激励；促进、助长；（为选手、球队）加油、助威","ex":"Les parents doivent encourager leurs enfants à lire tous les jours.","exCn":"父母应该鼓励孩子每天阅读。","th":"描述与状态"},{"w":"encre","p":"n.f.","cn":"墨水","ex":"Mon stylo fuit, j'ai de l'encre plein les doigts.","exCn":"我的笔漏墨了，弄得满手都是墨水。","th":"常用词"},{"w":"enfer","p":"n.m.","cn":"地狱；cf. d'enfer（口语）超棒的、极好的","ex":"Selon la tradition chrétienne, les méchants vont en enfer après leur mort.","exCn":"按照基督教的说法，恶人死后会下地狱。","th":"描述与状态"},{"w":"enfermer","p":"v.","cn":"关进去、锁起来；（s'~）把自己关在…里","ex":"Il a enfermé ses documents importants à clé dans un tiroir.","exCn":"他把重要文件锁进了抽屉里。","th":"常用词"},{"w":"engagement","p":"n.m.","cn":"承诺、保证；（社会、政治上的）投入、参与","ex":"L'entrepreneur n'a pas tenu ses engagements : les travaux devaient être terminés en mars.","exCn":"承包商没有兑现承诺：工程本该在三月完工。","th":"社会与新闻"},{"w":"engager","p":"v.","cn":"雇用；发起、开始；投入、使承担；（s'~ à）承诺、保证；（s'~ dans）投身、参与","ex":"Ils ont engagé une nounou pour s'occuper des jumeaux trois jours par semaine.","exCn":"他们请了一位保姆，每周三天照看双胞胎。","th":"常用词"},{"w":"ennemi","p":"n.","cn":"敌人","ex":"Le stress est le pire ennemi du sommeil.","exCn":"压力是睡眠的头号大敌。","th":"人物与身份"},{"w":"ennui","p":"n.m.","cn":"无聊、厌烦；麻烦、问题","ex":"Pendant ce long trajet en train, je lisais pour tromper l'ennui.","exCn":"在漫长的火车旅途中，我靠看书打发无聊。","th":"情绪与性格"},{"w":"enquête","p":"n.f.","cn":"调查","ex":"Selon une enquête, les jeunes lisent moins qu'avant.","exCn":"据一项调查，年轻人比过去读书少了。","th":"工作与学习"},{"w":"enregistrement","p":"n.m.","cn":"录音、录制；登记、注册；（机场）值机","ex":"L'enregistrement en ligne est ouvert vingt-quatre heures avant le vol.","exCn":"网上值机在航班起飞前二十四小时开放。","th":"出行与旅行"},{"w":"enregistrer","p":"v.","cn":"记录、登记；录制、录音；保存（文件）；托运（行李）","ex":"À l'aéroport, nous avons enregistré deux valises et gardé un sac en cabine.","exCn":"在机场，我们托运了两个行李箱，随身带了一个包上飞机。","th":"出行与旅行"},{"w":"enseignement","p":"n.m.","cn":"教育、教学；教训、启示","ex":"Elle travaille dans l'enseignement depuis vingt ans.","exCn":"她从事教育工作已经二十年了。","th":"社会与新闻"},{"w":"enterrer","p":"v.","cn":"埋、掩埋；埋葬、安葬","ex":"La ville va enterrer les lignes électriques du quartier pour limiter les pannes.","exCn":"市里打算把这个街区的电线埋到地下，以减少停电。","th":"常用词"},{"w":"enthousiasme","p":"n.m.","cn":"热情、热忱","ex":"Les étudiants ont accueilli la nouvelle avec un grand enthousiasme.","exCn":"学生们听到这个消息后反应非常热烈。","th":"居住与环境"},{"w":"entièrement","p":"adv.","cn":"完全地、全部地","ex":"Ce gâteau est entièrement fait maison.","exCn":"这个蛋糕完全是自己在家做的。","th":"常用词"},{"w":"entorse","p":"n.f.","cn":"扭伤；（~ à）违反（规则）","ex":"Je me suis fait une entorse à la cheville.","exCn":"我扭伤了脚踝。","th":"健康与身体"},{"w":"entourage","p":"n.m.","cn":"身边的人、亲友圈；随从、身边人士","ex":"Elle n'a parlé de sa maladie qu'à son entourage proche.","exCn":"她只把自己的病告诉了身边最亲近的人。","th":"人物与身份"},{"w":"entourer","p":"v.","cn":"围绕、环绕；圈出（答案）；关心、陪伴（某人）","ex":"Lisez le texte, puis entourez la bonne réponse.","exCn":"阅读短文，然后圈出正确答案。","th":"人物与身份"},{"w":"entraînement","p":"n.m.","cn":"训练、练习","ex":"L'équipe suit un entraînement intensif trois fois par semaine.","exCn":"球队每周进行三次高强度训练。","th":"常用词"},{"w":"entraîner","p":"v.","cn":"训练；导致、引起；带走、卷走；（s'~）练习、锻炼","ex":"Il entraîne une équipe de hockey pour enfants le samedi matin.","exCn":"他每周六上午给一支少儿冰球队当教练。","th":"健康与身体"},{"w":"entraîneur","p":"n.","cn":"教练","ex":"Le nouvel entraîneur de l'équipe nationale a été présenté hier.","exCn":"国家队的新任主教练昨天正式亮相。","th":"常用词"},{"w":"entrepreneur","p":"n.","cn":"企业家、创业者；承包商","ex":"L'incubateur de l'université aide les entrepreneurs à trouver leurs premiers investisseurs.","exCn":"大学的创业孵化器帮助创业者寻找第一批投资人。","th":"社会与新闻"},{"w":"entretien","p":"n.m.","cn":"面试；维护；谈话","ex":"J'ai un entretien d'embauche mardi.","exCn":"我周二有一个求职面试。","th":"工作与学习"},{"w":"envier","p":"v.","cn":"羡慕、嫉妒；（n'avoir rien à ~ à）毫不逊色于","ex":"J'envie mes collègues qui peuvent travailler de chez eux toute la semaine.","exCn":"我很羡慕那些整周都能在家办公的同事。","th":"情绪与性格"},{"w":"environnemental","p":"adj.","cn":"环境的","ex":"Ce projet de mine aurait un impact environnemental énorme.","exCn":"这个矿山项目会对环境造成巨大影响。","th":"居住与环境"},{"w":"environs","p":"n.m.","cn":"周边地区、郊外；cf. aux environs de 在…附近；（时间、数量）大约、…前后","ex":"Nous cherchons un appartement à Montréal ou dans ses environs immédiats.","exCn":"我们在蒙特利尔市内或紧邻的周边地区找公寓。","th":"时间与数量"},{"w":"envisager","p":"v.","cn":"考虑、打算；设想、预想","ex":"Nous envisageons de déménager à Québec l'année prochaine.","exCn":"我们打算明年搬到魁北克城。","th":"常用词"},{"w":"envoi","p":"n.m.","cn":"寄送、发送；邮件、包裹","ex":"Les frais d'envoi sont offerts dès 50 dollars d'achat.","exCn":"购物满50加元即免邮费。","th":"常用词"},{"w":"escalade","p":"n.f.","cn":"攀岩、攀登；（冲突等）升级、加剧","ex":"Elle pratique l'escalade en salle deux fois par semaine.","exCn":"她每周去室内攀岩馆练两次攀岩。","th":"常用词"},{"w":"escale","p":"n.f.","cn":"中途停留、经停","ex":"Notre vol pour Tokyo fait escale à Dubaï.","exCn":"我们飞往东京的航班在迪拜经停。","th":"常用词"},{"w":"esclave","p":"n.","cn":"奴隶","ex":"Ce roman raconte l'histoire d'une esclave qui fuit les États-Unis pour se réfugier au Canada.","exCn":"这部小说讲述了一个女奴逃离美国、到加拿大避难的故事。","th":"常用词"},{"w":"espoir","p":"n.m.","cn":"希望","ex":"Ce nouveau médicament représente un grand espoir pour les malades.","exCn":"这种新药给病人带来了很大的希望。","th":"常用词"},{"w":"esprit","p":"n.m.","cn":"头脑、思想；精神；机智、才智","ex":"Cette idée ne m'était jamais venue à l'esprit.","exCn":"我从来没有想到过这个主意。","th":"常用词"},{"w":"espèce","p":"n.f.","cn":"种类；（生物）物种；（复数）现金；cf. une espèce de 一种…、类似…的东西（不说 un espèce de）；espèce d'idiot ! 你这个笨蛋！（口语）","ex":"Le béluga du Saint-Laurent est une espèce menacée.","exCn":"圣劳伦斯河的白鲸是濒危物种。","th":"购物与金钱"},{"w":"essai","p":"n.m.","cn":"尝试、试验；（文学）随笔、论著；cf. la période d'essai 试用期；à l'essai 试用","ex":"Ce n'est qu'un essai : si ça ne marche pas, on essaiera autre chose.","exCn":"这只是试一试，不行我们就换个办法。","th":"常用词"},{"w":"essayage","p":"n.m.","cn":"试穿、试衣","ex":"Les cabines d'essayage sont au fond du magasin.","exCn":"试衣间在商店最里面。","th":"日常动作"},{"w":"essentiel","p":"n.m.","cn":"必不可少的、至关重要的；要点、最重要的事","ex":"Votre signature est essentielle : sans elle, le dossier ne peut pas être traité.","exCn":"您的签名必不可少：没有签名，材料就无法受理。","th":"抽象与概念"},{"w":"essuyer","p":"v.","cn":"擦、擦干；遭受（失败、拒绝等）","ex":"Essuie-toi les mains avant de toucher l'ordinateur.","exCn":"碰电脑之前先把手擦干。","th":"常用词"},{"w":"estimer","p":"v.","cn":"认为；估计、估算；尊重、器重","ex":"J'estime qu'il a eu raison de démissionner.","exCn":"我认为他辞职是对的。","th":"观点与论证"},{"w":"exagérer","p":"v.","cn":"夸大、夸张；（做得）过分","ex":"Les médias ont exagéré la gravité de l'incident.","exCn":"媒体夸大了这起事件的严重性。","th":"描述与状态"},{"w":"examiner","p":"v.","cn":"检查、审查；仔细研究、考虑","ex":"Le médecin a examiné ma gorge avant de me prescrire des antibiotiques.","exCn":"医生检查了我的喉咙，然后给我开了抗生素。","th":"工作与学习"},{"w":"exception","p":"n.f.","cn":"例外；cf. à l'exception de 除…之外","ex":"Je ferai une exception, juste cette fois.","exCn":"这次我就破个例，仅此一次。","th":"常用词"},{"w":"exceptionnel","p":"adj.","cn":"特殊的、罕见的；杰出的、非凡的","ex":"En raison de circonstances exceptionnelles, le musée sera fermé ce dimanche.","exCn":"由于特殊情况，博物馆本周日闭馆。","th":"常用词"},{"w":"excitant","p":"adj.","cn":"令人兴奋的、激动人心的","ex":"Partir vivre à l'étranger est une aventure à la fois excitante et effrayante.","exCn":"移居国外是一场既令人兴奋又让人害怕的冒险。","th":"人物与身份"},{"w":"excès","p":"n.m.","cn":"过度、过量；（复数）放纵、过分行为","ex":"Tout excès est mauvais pour la santé, même le sport.","exCn":"凡事过度都对健康不好，运动也不例外。","th":"常用词"},{"w":"exemplaire","p":"n.m.","cn":"（书报等的）份、册；模范的、堪称表率的","ex":"J'ai acheté un exemplaire dédicacé de son dernier roman.","exCn":"我买了一本他最新小说的签名本。","th":"常用词"},{"w":"exercer","p":"v.","cn":"施加、行使；从事（职业）；锻炼、训练；（s'~）练习","ex":"Les lobbys exercent une forte pression sur le gouvernement.","exCn":"游说团体对政府施加了很大压力。","th":"健康与身体"},{"w":"exigeant","p":"adj.","cn":"要求高的、苛刻的","ex":"Ce professeur est exigeant avec ses étudiants, mais il les aide beaucoup.","exCn":"这位教授对学生要求严格，但也给了他们很多帮助。","th":"描述与状态"},{"w":"exiger","p":"v.","cn":"要求","ex":"Le propriétaire exige un dépôt de garantie.","exCn":"房东要求押金。","th":"工作与学习"},{"w":"existence","p":"n.f.","cn":"存在；生活、生涯","ex":"Les chercheurs ont prouvé l'existence d'une nouvelle espèce de poisson dans ce lac.","exCn":"研究人员证实了这座湖里存在一种新的鱼类。","th":"常用词"},{"w":"exister","p":"v.","cn":"存在","ex":"Ce métier n'existait pas il y a vingt ans.","exCn":"这个职业二十年前还不存在。","th":"常用词"},{"w":"exotique","p":"adj.","cn":"异国情调的、外来的","ex":"Ce marché propose des fruits exotiques comme la mangue, le litchi et la papaye.","exCn":"这个市场卖芒果、荔枝、木瓜等异国水果。","th":"常用词"},{"w":"expert","p":"n.","cn":"专家、行家","ex":"Nous avons fait appel à un expert pour évaluer les dégâts après l'inondation.","exCn":"洪水过后，我们请了一位专家来评估损失。","th":"常用词"},{"w":"exploration","p":"n.f.","cn":"探索、探险","ex":"L'exploration spatiale coûte cher, mais elle fait progresser la science.","exCn":"太空探索花费高昂，但推动了科学进步。","th":"常用词"},{"w":"explorer","p":"v.","cn":"探索、考察","ex":"Nous avons loué une voiture pour explorer la région de Charlevoix.","exCn":"我们租了一辆车，去探访夏洛瓦地区。","th":"常用词"},{"w":"exploser","p":"v.","cn":"爆炸；激增、暴涨","ex":"Une bouteille de gaz a explosé dans la cuisine du restaurant.","exCn":"餐馆厨房里的一个煤气罐爆炸了。","th":"常用词"},{"w":"explosion","p":"n.f.","cn":"爆炸；爆发、激增","ex":"On a entendu une forte explosion près du port.","exCn":"港口附近传来一声巨大的爆炸声。","th":"常用词"},{"w":"exporter","p":"v.","cn":"出口、输出；（文件）导出","ex":"La France exporte beaucoup de vin et de fromage.","exCn":"法国出口大量葡萄酒和奶酪。","th":"常用词"},{"w":"exposer","p":"v.","cn":"展出、陈列；陈述、阐述；使暴露于、使面临","ex":"Le musée des beaux-arts expose actuellement des œuvres de peintres québécois.","exCn":"美术馆目前正在展出魁北克画家的作品。","th":"常用词"},{"w":"exposé","p":"n.m.","cn":"（口头）报告、发言；阐述、陈述","ex":"Je dois préparer un exposé sur l'environnement pour lundi.","exCn":"我得在周一前准备一个关于环境的报告。","th":"常用词"},{"w":"exprès","p":"adv.","cn":"故意地；特意、专门","ex":"Excuse-moi, je ne l'ai pas fait exprès.","exCn":"对不起，我不是故意的。","th":"常用词"},{"w":"expédier","p":"v.","cn":"寄送、发送；草草了结","ex":"Votre commande sera expédiée sous 48 heures.","exCn":"您的订单将在48小时内发货。","th":"常用词"},{"w":"expédition","p":"n.f.","cn":"寄送、发货；远征、探险","ex":"L'expédition de votre colis a été retardée à cause de la grève.","exCn":"由于罢工，您的包裹延迟发货。","th":"常用词"},{"w":"expérimenté","p":"adj.","cn":"有经验的、老练的","ex":"Un avocat plus expérimenté aurait traité l'affaire différemment.","exCn":"要是换个更有经验的律师，这个案子会处理得不一样。","th":"常用词"},{"w":"extrait","p":"n.m.","cn":"摘录、片段；提取物","ex":"Le professeur nous a fait lire un court extrait du roman.","exCn":"老师让我们读了这部小说的一小段。","th":"常用词"},{"w":"extrême","p":"adj.","cn":"极端的、极度的","ex":"Ces derniers étés, les épisodes de chaleur extrême sont de plus en plus fréquents.","exCn":"最近几个夏天，极端高温天气越来越频繁。","th":"常用词"},{"w":"extrêmement","p":"adv.","cn":"极其、非常","ex":"Ce champignon est extrêmement toxique : ne le touchez surtout pas.","exCn":"这种蘑菇毒性极强，千万别碰。","th":"常用词"},{"w":"fabricant","p":"n.m.","cn":"制造商、厂家","ex":"Un fabricant québécois de meubles vient d'ouvrir une usine en Ontario.","exCn":"一家魁北克家具制造商刚在安大略开了一家工厂。","th":"常用词"},{"w":"fabrication","p":"n.f.","cn":"制造、生产","ex":"Cette usine assure la fabrication de pièces pour l'industrie automobile.","exCn":"这家工厂负责生产汽车零部件。","th":"常用词"},{"w":"fabuleux","p":"adj.","cn":"惊人的、极好的；神话的、传说中的","ex":"Il a gagné une somme fabuleuse à la loterie et a tout dépensé en deux ans.","exCn":"他中彩票赢了一笔惊人的巨款，结果两年就花光了。","th":"人物与身份"},{"w":"face","p":"n.f.","cn":"（物体的）面、正面；面子；脸（魁北克，口语）；cf. en face（de）在（…）对面；faire face à 面对、应对；pile ou face 掷硬币猜正反面","ex":"La face cachée de la Lune n'est jamais visible depuis la Terre.","exCn":"月球背向地球的那一面，在地球上永远看不到。","th":"常用词"},{"w":"face à","p":"prép.","cn":"面对（困难等）；正对着、朝向","ex":"Il est resté calme face à ce client agressif.","exCn":"面对这位咄咄逼人的顾客，他始终很冷静。","th":"抽象与概念"},{"w":"faciliter","p":"v.","cn":"使便利、使容易","ex":"Le nouveau métro facilitera les déplacements entre la banlieue et le centre-ville.","exCn":"新地铁将方便郊区和市中心之间的往来。","th":"描述与状态"},{"w":"faculté","p":"n.f.","cn":"（大学的）学院、系；能力、官能；cf. la fac 大学（口语）","ex":"Elle s'est inscrite à la faculté de droit de l'Université Laval.","exCn":"她报读了拉瓦尔大学法学院。","th":"工作与学习"},{"w":"faiblesse","p":"n.f.","cn":"虚弱、无力；弱点、短处","ex":"Sa plus grande faiblesse, c'est qu'il ne sait pas dire non.","exCn":"他最大的弱点就是不会拒绝别人。","th":"描述与状态"},{"w":"faire semblant","p":"v.","cn":"（~ de + 不定式）假装、装作","ex":"Mon fils fait semblant de dormir quand je viens éteindre la lumière.","exCn":"我去关灯时，儿子就装睡。","th":"常用词"},{"w":"faisable","p":"adj.","cn":"可行的、做得到的","ex":"Ce projet est ambitieux, mais tout à fait faisable en deux ans.","exCn":"这个项目很有雄心，但两年内完全做得到。","th":"常用词"},{"w":"fait","p":"n.m.","cn":"事实；事件、事情；cf. en fait /ɑ̃fɛt/ 其实、实际上；au fait /ofɛt/ 对了、顺便问一下；tout à fait 完全、正是","ex":"Le journaliste s'est contenté de rapporter les faits, sans donner son avis.","exCn":"这位记者只是报道了事实，没有发表个人看法。","th":"观点与论证"},{"w":"falaise","p":"n.f.","cn":"悬崖、峭壁","ex":"Les falaises d'Étretat attirent des milliers de touristes chaque été.","exCn":"埃特勒塔的悬崖每年夏天都吸引成千上万的游客。","th":"常用词"},{"w":"fameux","p":"adj.","cn":"著名的、出名的；cf. pas fameux（口语）不怎么样、不太好","ex":"Nous avons enfin goûté la fameuse poutine dont tout le monde parle.","exCn":"我们终于尝到了大家都在说的那道有名的肉汁奶酪薯条。","th":"描述与状态"},{"w":"familier","p":"adj.","cn":"熟悉的、眼熟的；（语言）口语的、通俗的；（举止）随便的","ex":"Ce visage m'est familier, mais je ne me souviens plus de son nom.","exCn":"这张脸我很眼熟，但想不起他叫什么了。","th":"常用词"},{"w":"fantôme","p":"n.m.","cn":"鬼、幽灵；（作同位语）空无一人的、有名无实的（ville ~ 鬼城）","ex":"Depuis la fermeture de la mine, cette petite ville est devenue une ville fantôme.","exCn":"自从矿山关闭后，这座小城就成了一座鬼城。","th":"人物与身份"},{"w":"fascinant","p":"adj.","cn":"迷人的、引人入胜的","ex":"J'ai vu un documentaire fascinant sur les baleines du Saint-Laurent.","exCn":"我看了一部关于圣劳伦斯河鲸鱼的纪录片，非常引人入胜。","th":"人物与身份"},{"w":"faveur","p":"n.f.","cn":"恩惠、好意；（en ~ de）支持…、有利于…","ex":"La majorité des habitants se sont prononcés en faveur du nouveau parc.","exCn":"大多数居民表态支持建新公园。","th":"观点与论证"},{"w":"favorable","p":"adj.","cn":"有利的；赞成的、支持的","ex":"Nous attendons un moment favorable pour vendre la maison.","exCn":"我们在等一个有利的时机把房子卖掉。","th":"观点与论证"},{"w":"favoriser","p":"v.","cn":"有利于、促进；偏袒、优待","ex":"Le soleil et la chaleur favorisent la croissance des tomates.","exCn":"阳光和温暖有利于西红柿生长。","th":"常用词"},{"w":"façade","p":"n.f.","cn":"（建筑）正面、外墙；（喻）外表、门面","ex":"La façade de l'immeuble a été entièrement rénovée l'été dernier.","exCn":"这栋楼的外墙去年夏天全面翻新了。","th":"居住与环境"},{"w":"femelle","p":"n.f.","cn":"雌性、雌性动物；雌性的、母的","ex":"Seuls les moustiques femelles piquent les humains.","exCn":"只有雌蚊才会叮人。","th":"居住与环境"},{"w":"fer","p":"n.m.","cn":"铁；熨斗","ex":"Le portail du jardin est en fer forgé.","exCn":"花园的大门是锻铁做的。","th":"常用词"},{"w":"fermier","p":"n.","cn":"农场的、农家的；农场主、农民","ex":"J'achète toujours des œufs fermiers au marché.","exCn":"我总是在市场上买农家鸡蛋。","th":"常用词"},{"w":"fesse","p":"n.f.","cn":"臀部、屁股","ex":"L'infirmière lui a fait une piqûre dans la fesse.","exCn":"护士在他屁股上打了一针。","th":"常用词"},{"w":"feuilleton","p":"n.m.","cn":"电视连续剧；（报刊）连载小说；cf. le téléroman（魁北克）电视连续剧","ex":"Ma grand-mère regarde son feuilleton tous les soirs.","exCn":"我奶奶每天晚上都看她的连续剧。","th":"描述与状态"},{"w":"feutre","p":"n.m.","cn":"水彩笔、记号笔；毛毡","ex":"Écris ton nom sur l'étiquette avec un gros feutre noir.","exCn":"用粗的黑色记号笔把你的名字写在标签上。","th":"常用词"},{"w":"fiable","p":"adj.","cn":"可靠的","ex":"Je cherche une voiture d'occasion fiable et pas trop chère.","exCn":"我在找一辆可靠又不太贵的二手车。","th":"常用词"},{"w":"fiancé","p":"n.","cn":"未婚夫、未婚妻；已订婚的","ex":"Je te présente Marc, mon fiancé : nous nous marions en juin.","exCn":"给你介绍一下，这是马克，我的未婚夫，我们六月结婚。","th":"时间与数量"},{"w":"ficher","p":"v.","cn":"干、做（口语）；放、扔（口语）；（se ~ de）不在乎、取笑（口语）","ex":"Mais qu'est-ce que tu fiches ? On va rater le train !","exCn":"你到底在干什么？我们要赶不上火车了！","th":"日常动作"},{"w":"fiction","p":"n.f.","cn":"虚构、杜撰；虚构作品（小说、影视剧等）","ex":"Ce que raconte cet article relève de la pure fiction.","exCn":"这篇文章讲的纯属虚构。","th":"描述与状态"},{"w":"fidèle","p":"adj.","cn":"忠诚的、忠实的；准确的、如实的","ex":"Il a toujours été fidèle à sa femme.","exCn":"他一直对妻子很忠诚。","th":"常用词"},{"w":"fidélité","p":"n.f.","cn":"忠诚、忠实；cf. carte de fidélité 会员卡、积分卡","ex":"Avec ma carte de fidélité, j'ai droit à dix pour cent de réduction.","exCn":"有了会员卡，我能享受九折优惠。","th":"购物与金钱"},{"w":"fier","p":"adj.","cn":"自豪的；骄傲的","ex":"Mon père est fier de moi.","exCn":"我父亲为我骄傲。","th":"情绪与性格"},{"w":"fierté","p":"n.f.","cn":"自豪、自尊心","ex":"Ses parents ont assisté à la remise des diplômes avec une immense fierté.","exCn":"他的父母满怀自豪地出席了毕业典礼。","th":"常用词"},{"w":"figure","p":"n.f.","cn":"脸、面孔；图、插图；（重要）人物","ex":"La figure 2 montre l'évolution des loyers depuis dix ans.","exCn":"图2显示了近十年来房租的变化。","th":"人物与身份"},{"w":"fil","p":"n.m.","cn":"线、丝线；电线；cf. le fils = 儿子；la file = 队列；coup de fil（口语）一通电话；au fil de 随着…","ex":"Elle a tiré sur un fil et tout le pull s'est défait.","exCn":"她扯了一根线，整件毛衣就散开了。","th":"常用词"},{"w":"file","p":"n.f.","cn":"队列、行列；车道；（faire la ~）排队（魁北克用语）；cf. le fil = 线","ex":"Les enfants marchaient en file indienne derrière la maîtresse.","exCn":"孩子们在老师后面排成一列往前走。","th":"出行与旅行"},{"w":"filet","p":"n.m.","cn":"网、网兜；（鱼、肉）里脊、鱼柳；（un ~ de）少许（油、柠檬汁等）","ex":"Le pêcheur répare son filet sur le port.","exCn":"渔夫在港口修补渔网。","th":"饮食"},{"w":"fillette","p":"n.f.","cn":"小女孩","ex":"Une fillette de six ans s'est perdue au centre commercial.","exCn":"一个六岁的小女孩在商场里走丢了。","th":"人物与身份"},{"w":"filtre","p":"n.m.","cn":"过滤器；（摄影）滤镜","ex":"Pensez à changer le filtre de la hotte tous les trois mois.","exCn":"记得每三个月换一次抽油烟机的过滤网。","th":"常用词"},{"w":"final","p":"adj.","cn":"最后的、最终的","ex":"La décision finale sera prise par le comité la semaine prochaine.","exCn":"最终决定将由委员会在下周做出。","th":"常用词"},{"w":"finale","p":"n.f.","cn":"决赛","ex":"Des amis viennent regarder la finale à la maison dimanche soir.","exCn":"周日晚上有朋友来家里一起看决赛。","th":"常用词"},{"w":"financer","p":"v.","cn":"资助、为…提供资金","ex":"Ses parents l'aident à financer ses études universitaires.","exCn":"他父母帮他负担上大学的费用。","th":"常用词"},{"w":"financier","p":"adj.","cn":"财务的、金融的","ex":"L'entreprise traverse de graves difficultés financières.","exCn":"公司正面临严重的财务困难。","th":"常用词"},{"w":"fixe","p":"adj.","cn":"固定的、不变的；（目光）凝视的、发直的","ex":"Il n'a pas encore de travail fixe.","exCn":"他还没有固定工作。","th":"常用词"},{"w":"fixer","p":"v.","cn":"确定、定下（日期、价格等）；固定；盯着、注视","ex":"Nous avons fixé la date de la réunion au 15 mars.","exCn":"我们把会议日期定在了3月15日。","th":"购物与金钱"},{"w":"flash","p":"n.m.","cn":"闪光灯；（新闻）快讯","ex":"Il est interdit d'utiliser le flash pendant la visite du musée.","exCn":"参观博物馆时禁止使用闪光灯。","th":"社会与新闻"},{"w":"fleuri","p":"adj.","cn":"开满花的；（布料）碎花的、印花的","ex":"Au printemps, leur balcon est toujours très fleuri.","exCn":"春天的时候，他们的阳台总是开满鲜花。","th":"居住与环境"},{"w":"fleurir","p":"v.","cn":"开花；兴盛、大量涌现","ex":"À Montréal, les lilas fleurissent généralement à la fin du mois de mai.","exCn":"在蒙特利尔，丁香一般在五月底开花。","th":"居住与环境"},{"w":"flèche","p":"n.f.","cn":"箭；箭头（指示标志）；（monter en ~）飙升、猛涨","ex":"Suivez les flèches jaunes jusqu'au service des urgences.","exCn":"沿着黄色箭头走，就能到急诊科。","th":"常用词"},{"w":"foie","p":"n.m.","cn":"肝、肝脏；cf. la foi 信仰；la fois 次","ex":"Les analyses de sang montrent que son foie fonctionne normalement.","exCn":"验血结果显示他的肝功能正常。","th":"描述与状态"},{"w":"folie","p":"n.f.","cn":"疯狂、精神失常；荒唐事、蠢事","ex":"Acheter une voiture neuve maintenant, ce serait une folie.","exCn":"现在买辆新车，那就太荒唐了。","th":"常用词"},{"w":"foncer","p":"v.","cn":"猛冲、飞奔（口语）；放手去干、别犹豫（口语）","ex":"Le bus arrive, il faut foncer si on veut l'attraper !","exCn":"车来了，想赶上的话得赶紧跑！","th":"常用词"},{"w":"fonction","p":"n.f.","cn":"功能、作用；职务、职位；（la ~ publique）公职、公务员系统；cf. en fonction de 根据、视…而定","ex":"Cette application a une fonction qui traduit automatiquement les messages.","exCn":"这个应用有一个自动翻译消息的功能。","th":"人物与身份"},{"w":"fonctionnaire","p":"n.","cn":"公务员","ex":"Mon frère est fonctionnaire au ministère des Finances.","exCn":"我哥哥在财政部当公务员。","th":"人物与身份"},{"w":"fonder","p":"v.","cn":"创立、创建；（~ sur）以…为依据","ex":"Ses grands-parents ont fondé cette boulangerie en 1965.","exCn":"他的祖父母于1965年创办了这家面包店。","th":"常用词"},{"w":"fondre","p":"v.","cn":"融化、熔化；骤减、锐减；（~ en larmes）一下子哭起来","ex":"Faites fondre le chocolat au bain-marie avant de le mélanger aux œufs.","exCn":"先把巧克力隔水融化，再和鸡蛋拌在一起。","th":"常用词"},{"w":"forcer","p":"v.","cn":"强迫；强行打开、撬开；（se ~ à）勉强自己（做…）","ex":"Personne ne peut te forcer à signer ce contrat.","exCn":"谁也不能强迫你签这份合同。","th":"描述与状态"},{"w":"forcément","p":"adv.","cn":"必然、必定；当然；（pas ~）不一定","ex":"Ce n'est pas forcément vrai.","exCn":"这不一定是真的。","th":"常用词"},{"w":"forfait","p":"n.m.","cn":"套餐、包价；（déclarer ~）弃权、退赛","ex":"Mon forfait de ski est valable pour toute la saison.","exCn":"我的滑雪季票整个雪季都有效。","th":"饮食"},{"w":"formalité","p":"n.f.","cn":"手续；走过场的事","ex":"Les formalités administratives prennent beaucoup de temps.","exCn":"行政手续很费时间。","th":"常用词"},{"w":"formation","p":"n.f.","cn":"培训；学习经历","ex":"Elle suit une formation en informatique.","exCn":"她在参加一个计算机培训。","th":"工作与学习"},{"w":"former","p":"v.","cn":"组成、形成；培训、培养","ex":"Les élèves ont formé des groupes de quatre pour le projet.","exCn":"学生们组成四人小组来做这个项目。","th":"工作与学习"},{"w":"formuler","p":"v.","cn":"表述、表达；提出","ex":"J'ai encore du mal à formuler mes idées clairement en français.","exCn":"我还是很难用法语把想法表达清楚。","th":"常用词"},{"w":"fortement","p":"adv.","cn":"强烈地、极力；大幅地","ex":"Je vous recommande fortement de réserver votre billet à l'avance.","exCn":"我强烈建议您提前订票。","th":"描述与状态"},{"w":"fortune","p":"n.f.","cn":"财富、财产；（faire ~）发财；cf. tenter fortune 碰运气；de fortune 临时凑合的","ex":"Il a fait fortune dans l'immobilier.","exCn":"他靠房地产发了财。","th":"常用词"},{"w":"foule","p":"n.f.","cn":"人群；（une foule de）大量、许多","ex":"La foule s'est dispersée après le feu d'artifice.","exCn":"烟花放完后，人群渐渐散去了。","th":"人物与身份"},{"w":"fourmi","p":"n.f.","cn":"蚂蚁；（avoir des ~s）（手脚）发麻","ex":"Ne laisse pas de sucre sur la table, sinon les fourmis vont envahir la cuisine.","exCn":"别把糖留在桌上，不然蚂蚁会爬满厨房。","th":"常用词"},{"w":"fournir","p":"v.","cn":"提供、供应","ex":"Une banane fournit de l'énergie rapidement, c'est pourquoi beaucoup de sportifs en mangent pendant l'effort.","exCn":"香蕉能迅速提供能量，所以很多运动员会在运动过程中吃香蕉。","th":"常用词"},{"w":"fournisseur","p":"n.m.","cn":"供应商、提供者","ex":"Le restaurant a changé de fournisseur de légumes pour réduire ses coûts.","exCn":"这家餐厅为了降低成本，换了蔬菜供应商。","th":"常用词"},{"w":"fourniture","p":"n.f.","cn":"（多用复数）用品、用具；供应、供给","ex":"J'ai acheté toutes les fournitures scolaires pour la rentrée.","exCn":"我为开学买齐了所有学习用品。","th":"常用词"},{"w":"foyer","p":"n.m.","cn":"家庭、家；（学生、老人等的）宿舍、之家；（火灾、疫情的）源头；（魁北克）壁炉","ex":"Pendant ma première année d'université, j'ai logé dans un foyer d'étudiants.","exCn":"大学第一年，我住在学生宿舍里。","th":"工作与学习"},{"w":"fracture","p":"n.f.","cn":"骨折；（社会的）分裂、鸿沟","ex":"Elle a glissé sur le verglas et s'est fait une fracture du poignet.","exCn":"她在结冰的路面上滑倒，手腕骨折了。","th":"社会与新闻"},{"w":"franc","p":"adj.","cn":"真诚的、坦率的","ex":"Sois franc avec moi : cette robe ne me va pas du tout, c'est ça ?","exCn":"跟我说实话：这条裙子我穿着一点都不好看，对吧？","th":"常用词"},{"w":"franchement","p":"adv.","cn":"坦率地、老实说；（加强语气）实在、真的","ex":"Franchement, ce film était trop long ; j'ai failli m'endormir.","exCn":"说实话，这部电影太长了，我差点睡着。","th":"描述与状态"},{"w":"francophonie","p":"n.f.","cn":"法语世界、法语国家和地区；（la Francophonie）法语国家组织","ex":"Le 20 mars, on célèbre la Journée internationale de la Francophonie.","exCn":"3月20日是国际法语日。","th":"居住与环境"},{"w":"fraternité","p":"n.f.","cn":"博爱、兄弟情谊","ex":"« Liberté, égalité, fraternité » est la devise de la République française.","exCn":"“自由、平等、博爱”是法兰西共和国的格言。","th":"情绪与性格"},{"w":"fraîcheur","p":"n.f.","cn":"凉爽、凉意；新鲜","ex":"Après cette journée de canicule, on a profité de la fraîcheur du soir pour aller marcher.","exCn":"热了一整天，我们趁着傍晚凉快出去散了散步。","th":"描述与状态"},{"w":"frein","p":"n.m.","cn":"刹车、制动器；（比喻）阻碍、制约","ex":"Le conducteur a donné un coup de frein pour éviter un piéton.","exCn":"司机猛踩刹车，以免撞到行人。","th":"出行与旅行"},{"w":"fric","p":"n.m.","cn":"钱（口语）","ex":"Je n'ai plus de fric, il faut que j'attende ma paie.","exCn":"我没钱了，得等发工资。","th":"购物与金钱"},{"w":"frire","p":"v.","cn":"油炸、油煎","ex":"Évitez de faire frire vos aliments trop souvent : c'est mauvais pour le cœur.","exCn":"别太常吃油炸的东西，对心脏不好。","th":"常用词"},{"w":"front","p":"n.m.","cn":"额头；前线、阵线","ex":"Elle s'est cogné le front contre la porte du placard.","exCn":"她的额头撞到了壁橱门上。","th":"常用词"},{"w":"frontière","p":"n.f.","cn":"边境、国界","ex":"Il faut présenter son passeport à la frontière entre le Canada et les États-Unis.","exCn":"过加美边境时要出示护照。","th":"常用词"},{"w":"fréquent","p":"adj.","cn":"频繁的、常见的","ex":"Les retards sont fréquents sur cette ligne de bus.","exCn":"这条公交线路经常晚点。","th":"常用词"},{"w":"fréquenter","p":"v.","cn":"常去（某地）；与…交往","ex":"Il fréquente la bibliothèque municipale tous les samedis.","exCn":"他每个星期六都去市立图书馆。","th":"常用词"},{"w":"fuir","p":"v.","cn":"逃跑、逃离；逃避、躲避；（水龙头、容器等）漏水、漏气","ex":"Des milliers de personnes ont fui leur pays à cause de la guerre.","exCn":"成千上万的人因战争逃离了自己的国家。","th":"日常动作"},{"w":"fuite","p":"n.f.","cn":"逃跑、逃逸；（水、气、信息）泄漏","ex":"Le voleur a pris la fuite à pied.","exCn":"小偷徒步逃走了。","th":"日常动作"},{"w":"fumée","p":"n.f.","cn":"烟雾","ex":"Une épaisse fumée noire sortait de l'immeuble en feu.","exCn":"着火的大楼里冒出浓浓的黑烟。","th":"常用词"},{"w":"furieux","p":"adj.","cn":"狂怒的、暴怒的","ex":"Les passagers étaient furieux contre la compagnie aérienne après l'annulation du vol.","exCn":"航班取消后，乘客们对航空公司怒不可遏。","th":"常用词"},{"w":"fâcher","p":"v.","cn":"（se ~）生气、发火；（se ~ avec）与…闹翻","ex":"Mon père se fâche quand on rentre tard sans prévenir.","exCn":"我们晚回家又不提前说一声，我爸就会发火。","th":"情绪与性格"},{"w":"fédéral","p":"adj.","cn":"联邦的","ex":"Elle travaille pour une agence fédérale à Gatineau.","exCn":"她在加蒂诺的一家联邦机构工作。","th":"常用词"},{"w":"fée","p":"n.f.","cn":"仙女；cf. avoir des doigts de fée 心灵手巧","ex":"La fée a transformé la citrouille en carrosse.","exCn":"仙女把南瓜变成了马车。","th":"人物与身份"},{"w":"féministe","p":"n.","cn":"女权主义的；女权主义者","ex":"Ce mouvement féministe se bat pour l'égalité salariale entre les hommes et les femmes.","exCn":"这一女权运动为男女同工同酬而斗争。","th":"人物与身份"},{"w":"gagnant","p":"n.","cn":"获胜者、赢家；获胜的、中奖的","ex":"Le gagnant du concours recevra un voyage pour deux personnes en Gaspésie.","exCn":"比赛的获胜者将赢得一次加斯佩半岛双人游。","th":"常用词"},{"w":"gai","p":"adj.","cn":"快乐的、愉快的；（颜色）鲜艳的；（魁北克）同性恋的","ex":"Même le lundi matin, il arrive au bureau gai comme un pinson.","exCn":"哪怕是周一早上，他来上班时也快活得像只小鸟。","th":"描述与状态"},{"w":"gamin","p":"n.","cn":"小孩、孩子（口语）","ex":"Quand j'étais gamin, je passais tous mes étés chez mes grands-parents.","exCn":"我小时候每年夏天都在爷爷奶奶家过。","th":"人物与身份"},{"w":"gamme","p":"n.f.","cn":"（产品）系列、种类；（音乐）音阶；cf. haut de gamme 高端的；bas de gamme 低端的","ex":"Cette marque vient de lancer une nouvelle gamme de téléphones.","exCn":"这个品牌刚推出了一个新的手机系列。","th":"描述与状态"},{"w":"garagiste","p":"n.","cn":"修车厂老板、修车师傅","ex":"Le garagiste m'a dit qu'il fallait changer les freins avant l'hiver.","exCn":"修车师傅跟我说，入冬前得把刹车换了。","th":"出行与旅行"},{"w":"garantie","p":"n.f.","cn":"保证、担保；（商品）保修","ex":"Mon ordinateur est encore sous garantie, la réparation sera donc gratuite.","exCn":"我的电脑还在保修期内，所以维修是免费的。","th":"购物与金钱"},{"w":"garantir","p":"v.","cn":"保证、确保；担保、保修","ex":"Je ne peux pas te garantir que je serai à l'heure : il y a des travaux sur l'autoroute.","exCn":"我不敢保证能准时到，高速公路上在修路。","th":"常用词"},{"w":"garde","p":"n.f.","cn":"照看、看护、监护（权）；值班；（魁北克）（service de ~）托儿服务、课后托管；cf. mettre en garde 提醒、警告；le garde = 看守、警卫","ex":"Après le divorce, la mère a obtenu la garde des enfants.","exCn":"离婚后，母亲获得了孩子的监护权。","th":"工作与学习"},{"w":"gasoil","p":"n.m.","cn":"柴油；cf. 也写作 gazole；魁北克多说 le diesel","ex":"Ma voiture roule au gasoil.","exCn":"我的车烧柴油。","th":"常用词"},{"w":"gaspillage","p":"n.m.","cn":"浪费","ex":"Pour lutter contre le gaspillage alimentaire, ce supermarché vend ses invendus à moitié prix.","exCn":"为了减少食物浪费，这家超市把卖剩的商品半价出售。","th":"常用词"},{"w":"gaspiller","p":"v.","cn":"浪费","ex":"Arrête de gaspiller ton argent en cafés à cinq dollars !","exCn":"别再把钱浪费在五块钱一杯的咖啡上了！","th":"常用词"},{"w":"gastronomie","p":"n.f.","cn":"美食、烹饪艺术","ex":"La gastronomie française est célèbre dans le monde entier.","exCn":"法国美食闻名全世界。","th":"常用词"},{"w":"gaz","p":"n.m.","cn":"燃气、煤气；气体；（魁北克口语）汽油","ex":"Avant de partir en vacances, vérifie que le gaz est bien fermé.","exCn":"去度假之前，检查一下煤气有没有关好。","th":"常用词"},{"w":"geler","p":"v.","cn":"结冰、冻住；冷得要命（口语）；（喻）冻结（资金、价格）；（魁北克）（打针）局部麻醉","ex":"Il a fait si froid cette nuit que le lac a gelé.","exCn":"昨晚冷得连湖面都结冰了。","th":"购物与金钱"},{"w":"gelé","p":"adj.","cn":"结冰的、冻住的；（人）冻僵的、冷坏了；（资产、价格）冻结的；（吸毒后）嗨了的（魁北克口语）","ex":"Le sol est encore gelé : impossible de planter les tulipes avant avril.","exCn":"地面还冻着，四月之前没法种郁金香。","th":"购物与金钱"},{"w":"gendarme","p":"n.","cn":"（法国）宪兵；（加拿大）皇家骑警（GRC）警员","ex":"Sur la route des vacances, les gendarmes contrôlent la vitesse des automobilistes.","exCn":"在度假的路上，宪兵在检查驾车者的车速。","th":"描述与状态"},{"w":"gendarmerie","p":"n.f.","cn":"宪兵队；宪兵队驻地","ex":"Après le cambriolage, ils sont allés porter plainte à la gendarmerie.","exCn":"家里被盗后，他们去宪兵队报了案。","th":"常用词"},{"w":"gendre","p":"n.m.","cn":"女婿","ex":"Poli, drôle et bon cuisinier, mon beau-frère est le gendre idéal aux yeux de mes parents.","exCn":"我姐夫有礼貌、幽默，还做得一手好菜，在我父母眼里是理想的女婿。","th":"人物与身份"},{"w":"gentillesse","p":"n.f.","cn":"善意、好心","ex":"Je te suis reconnaissant pour ta gentillesse.","exCn":"谢谢你的好意，我很感激。","th":"描述与状态"},{"w":"gentiment","p":"adv.","cn":"友好地、和气地、温和地","ex":"Le serveur nous a gentiment offert le café.","exCn":"服务员很客气地请我们喝了咖啡。","th":"描述与状态"},{"w":"geste","p":"n.m.","cn":"手势、动作；举动、表示","ex":"Ce geste de la main, poli chez nous, est considéré comme une insulte dans certains pays.","exCn":"这个手势在我们这儿很礼貌，但在有些国家却被视为侮辱。","th":"常用词"},{"w":"gestion","p":"n.f.","cn":"管理、经营","ex":"Elle a obtenu un diplôme en gestion des ressources humaines.","exCn":"她拿到了人力资源管理专业的文凭。","th":"常用词"},{"w":"gigantesque","p":"adj.","cn":"巨大的、庞大的","ex":"Le nouveau centre commercial est gigantesque : on s'y perd facilement.","exCn":"新购物中心大得惊人，很容易迷路。","th":"描述与状态"},{"w":"glacial","p":"adj.","cn":"冰冷的、严寒的；冷淡的","ex":"En janvier, un vent glacial souffle sur la ville de Québec.","exCn":"一月份，魁北克城刮着刺骨的寒风。","th":"居住与环境"},{"w":"glacé","p":"adj.","cn":"冰镇的、冰的；冰冷的、冻僵的；（态度）冷冰冰的","ex":"En été, je bois du thé glacé au lieu du café.","exCn":"夏天我喝冰茶，不喝咖啡。","th":"居住与环境"},{"w":"glissant","p":"adj.","cn":"滑的","ex":"Ce poisson est glissant, il m'a échappé des mains.","exCn":"这条鱼滑溜溜的，从我手里溜走了。","th":"常用词"},{"w":"glisser","p":"v.","cn":"滑、滑倒；（把东西）塞进、悄悄放入","ex":"Mon téléphone a glissé de ma poche et est tombé entre les sièges du taxi.","exCn":"我的手机从口袋里滑了出来，掉进了出租车座位之间的缝里。","th":"常用词"},{"w":"global","p":"adj.","cn":"总体的、全面的；cf. 「全球的」一般用 mondial","ex":"Le coût global des travaux dépasse deux millions de dollars.","exCn":"工程总造价超过两百万加元。","th":"常用词"},{"w":"gorille","p":"n.m.","cn":"大猩猩","ex":"Au Rwanda, nous avons observé un gorille et ses petits à quelques mètres seulement, dans un silence total.","exCn":"在卢旺达，我们在仅几米远的地方静静观察了一只大猩猩和它的幼崽。","th":"描述与状态"},{"w":"goutte","p":"n.f.","cn":"滴、水滴；（复数）滴剂、药水；cf. C'est la goutte d'eau qui fait déborder le vase. 这是压垮骆驼的最后一根稻草。","ex":"Ma fille a mal à l'oreille : le médecin lui a prescrit des gouttes pendant cinq jours.","exCn":"我女儿耳朵疼，医生给她开了滴耳液，要用五天。","th":"健康与身体"},{"w":"graine","p":"n.f.","cn":"种子","ex":"Chaque graine doit être plantée à deux centimètres de profondeur.","exCn":"每粒种子都要种在两厘米深的地方。","th":"常用词"},{"w":"graisse","p":"n.f.","cn":"脂肪、油脂；润滑脂、润滑油","ex":"Le sport aide à brûler la graisse accumulée sur le ventre.","exCn":"运动有助于燃烧腹部堆积的脂肪。","th":"常用词"},{"w":"grandeur","p":"n.f.","cn":"大小、规模；（魁北克）（衣物）尺码；伟大、崇高","ex":"Les deux chambres sont à peu près de la même grandeur.","exCn":"两间卧室大小差不多。","th":"描述与状态"},{"w":"graphique","p":"n.m.","cn":"图表、曲线图","ex":"Ce graphique montre l'évolution des prix.","exCn":"这张图表显示了价格的变化。","th":"常用词"},{"w":"gratin","p":"n.m.","cn":"焗菜","ex":"Ce soir, je fais un gratin de pommes de terre.","exCn":"今晚我做焗土豆。","th":"饮食"},{"w":"gratitude","p":"n.f.","cn":"感激、感谢","ex":"Je tiens à vous exprimer toute ma gratitude pour votre aide.","exCn":"我想向您表达我由衷的感激，谢谢您的帮助。","th":"常用词"},{"w":"gratter","p":"v.","cn":"刮、刮掉；挠、抓（痒）","ex":"Il a gratté son billet de loterie et a gagné vingt dollars.","exCn":"他刮开彩票，中了二十块钱。","th":"常用词"},{"w":"gratuitement","p":"adv.","cn":"免费地；无端地","ex":"Les enfants de moins de six ans voyagent gratuitement dans les transports en commun.","exCn":"六岁以下儿童可以免费乘坐公共交通。","th":"常用词"},{"w":"gravement","p":"adv.","cn":"严重地","ex":"Sa mère est tombée gravement malade quelques mois après sa retraite.","exCn":"她母亲退休几个月后就得了重病。","th":"描述与状态"},{"w":"grenier","p":"n.m.","cn":"阁楼、顶楼","ex":"On a trouvé de vieilles photos au grenier.","exCn":"我们在阁楼上找到了一些老照片。","th":"居住与环境"},{"w":"grignoter","p":"v.","cn":"啃、一点点地吃；吃零食；（喻）蚕食","ex":"J'essaie de ne plus grignoter entre les repas.","exCn":"我尽量不在两餐之间吃零食了。","th":"饮食"},{"w":"grillade","p":"n.f.","cn":"烤肉","ex":"Ce week-end, on fait des grillades dans le jardin.","exCn":"这个周末我们在花园里烤肉。","th":"饮食"},{"w":"grille-pain","p":"n.m.","cn":"烤面包机","ex":"Le grille-pain ne marche plus.","exCn":"烤面包机坏了。","th":"饮食"},{"w":"grimace","p":"n.f.","cn":"鬼脸、怪相","ex":"L'enfant fait des grimaces devant le miroir.","exCn":"孩子对着镜子做鬼脸。","th":"常用词"},{"w":"grimper","p":"v.","cn":"攀爬、爬上；（价格、温度等）飙升、上涨","ex":"Le chat a grimpé sur le toit et n'arrive plus à descendre.","exCn":"猫爬上了屋顶，现在下不来了。","th":"购物与金钱"},{"w":"grippé","p":"adj.","cn":"得了流感的","ex":"Je ne peux pas venir, je suis grippé.","exCn":"我来不了，我得了流感。","th":"常用词"},{"w":"grossesse","p":"n.f.","cn":"怀孕","ex":"Elle a eu une grossesse difficile et a dû rester alitée pendant deux mois.","exCn":"她怀孕过程很辛苦，不得不卧床休息了两个月。","th":"常用词"},{"w":"grotte","p":"n.f.","cn":"洞穴、岩洞","ex":"Avec une lampe frontale, nous avons exploré une grotte où vivent des centaines de chauves-souris.","exCn":"我们戴着头灯，探索了一个栖息着数百只蝙蝠的洞穴。","th":"常用词"},{"w":"grâce à","p":"loc.","cn":"多亏；借助","ex":"Grâce à ton aide, j'ai fini à temps.","exCn":"多亏你帮忙，我按时完成了。","th":"观点与论证"},{"w":"grève","p":"n.f.","cn":"罢工","ex":"Les transports sont bloqués à cause de la grève.","exCn":"因为罢工交通瘫痪了。","th":"工作与学习"},{"w":"grêle","p":"n.f.","cn":"冰雹","ex":"Il est tombé de la grêle pendant dix minutes, et toutes les voitures de la rue sont cabossées.","exCn":"冰雹下了十分钟，街上的车全被砸得坑坑洼洼。","th":"常用词"},{"w":"guichet","p":"n.m.","cn":"（售票、办事）窗口；（~ automatique）自动取款机","ex":"Adressez-vous au guichet numéro trois.","exCn":"请到三号窗口办理。","th":"出行与旅行"},{"w":"guider","p":"v.","cn":"引导、带路；指导","ex":"Un employé nous a guidés jusqu'à la salle d'attente.","exCn":"一位工作人员把我们领到了候诊室。","th":"出行与旅行"},{"w":"guéri","p":"adj.","cn":"痊愈的","ex":"Elle n'est pas encore guérie, mais elle a déjà repris le travail.","exCn":"她还没痊愈，就已经回去上班了。","th":"常用词"},{"w":"guérir","p":"v.","cn":"治愈、康复","ex":"Il vaut mieux prévenir que guérir.","exCn":"预防胜于治疗。","th":"常用词"},{"w":"gâcher","p":"v.","cn":"浪费、毁掉","ex":"Tu gâches ton temps avec ce jeu.","exCn":"你玩这个游戏是在浪费时间。","th":"常用词"},{"w":"géant","p":"n.","cn":"巨人；（行业）巨头；巨大的","ex":"Ce géant de la distribution va fermer une vingtaine de magasins au Canada.","exCn":"这家零售业巨头将关闭在加拿大的二十来家门店。","th":"人物与身份"},{"w":"généraliste","p":"n.","cn":"全科医生；全科的；综合性的、非专科的","ex":"Prenez d'abord rendez-vous chez votre généraliste.","exCn":"请先预约您的全科医生。","th":"健康与身体"},{"w":"génération","p":"n.f.","cn":"一代人、世代","ex":"Les jeunes de ma génération passent beaucoup de temps sur leur téléphone.","exCn":"我们这一代年轻人花很多时间看手机。","th":"人物与身份"},{"w":"généreux","p":"adj.","cn":"慷慨的、大方的","ex":"Vous nous invitez au restaurant ? C'est très généreux de votre part.","exCn":"您请我们去餐馆吃饭？您真是太大方了。","th":"描述与状态"},{"w":"générosité","p":"n.f.","cn":"慷慨、大方","ex":"Grâce à la générosité des donateurs, l'association a pu ouvrir un nouveau refuge.","exCn":"多亏捐赠者慷慨解囊，协会得以开设一个新的收容所。","th":"描述与状态"},{"w":"gérant","p":"n.","cn":"经理、店长","ex":"Si le problème persiste, demandez à parler au gérant du magasin.","exCn":"如果问题还是没解决，可以要求和店长谈谈。","th":"描述与状态"},{"w":"gérer","p":"v.","cn":"管理、经营；应对、处理（问题、局面）；搞得定（口语）","ex":"Elle gère une petite entreprise de nettoyage à Laval.","exCn":"她在拉瓦尔经营一家小型清洁公司。","th":"常用词"},{"w":"gênant","p":"adj.","cn":"令人尴尬的、让人难为情的；碍事的、妨碍人的","ex":"C'était un peu gênant d'avoir oublié son prénom devant tout le monde.","exCn":"当着大家的面忘了他的名字，真有点尴尬。","th":"人物与身份"},{"w":"gêner","p":"v.","cn":"打扰、妨碍；使尴尬、使难为情；（se ~）拘束、客气","ex":"Est-ce que la musique vous gêne ? Je peux baisser le son.","exCn":"音乐打扰到您了吗？我可以把声音调小。","th":"交际与礼貌"},{"w":"gêné","p":"adj.","cn":"尴尬的；拘束的","ex":"Elle était gênée de demander de l'aide.","exCn":"她不好意思开口求助。","th":"情绪与性格"},{"w":"gîte","p":"n.m.","cn":"乡村民宿；cf. le gîte et le couvert 食宿","ex":"Nous avons loué un gîte en Bretagne pour l'été.","exCn":"我们夏天在布列塔尼租了一间乡村民宿。","th":"居住与环境"},{"w":"habit","p":"n.m.","cn":"（常用复数）衣服；礼服、（特定）服装；（魁北克）西装","ex":"Il a mis ses plus beaux habits pour son premier rendez-vous avec elle.","exCn":"第一次和她约会，他穿上了自己最好看的衣服。","th":"常用词"},{"w":"habitation","p":"n.f.","cn":"住所、住宅；居住","ex":"Après trois ans d'attente, ma tante a enfin obtenu un logement dans une habitation à loyer modique.","exCn":"等了三年，我姨妈终于住进了廉租房。","th":"居住与环境"},{"w":"habituel","p":"adj.","cn":"通常的、惯常的","ex":"Nous nous sommes retrouvés à notre café habituel, près de la gare.","exCn":"我们在车站附近那家常去的咖啡馆碰了头。","th":"常用词"},{"w":"habitué","p":"n.","cn":"（~ à）习惯于…的；常客、老顾客","ex":"Le patron du café connaît tous ses habitués par leur prénom.","exCn":"咖啡馆老板叫得出所有常客的名字。","th":"常用词"},{"w":"haine","p":"n.f.","cn":"仇恨、憎恨","ex":"Il n'éprouve aucune haine envers ceux qui l'ont trahi.","exCn":"他对那些背叛过他的人没有任何仇恨。","th":"情绪与性格"},{"w":"hall","p":"n.m.","cn":"大厅、门厅","ex":"Je t'attends dans le hall de l'hôtel à huit heures.","exCn":"我八点在酒店大堂等你。","th":"描述与状态"},{"w":"handicap","p":"n.m.","cn":"残疾；劣势、不利条件","ex":"Il vit avec un handicap depuis sa naissance.","exCn":"他生来就有残疾。","th":"抽象与概念"},{"w":"handicapé","p":"n.","cn":"残疾的；残疾人","ex":"Ce restaurant solidaire emploie une dizaine de jeunes handicapés, formés au service en salle.","exCn":"这家公益餐厅雇用了十来个残疾青年，他们都接受过餐厅服务培训。","th":"人物与身份"},{"w":"hausse","p":"n.f.","cn":"上涨、增长","ex":"La hausse des loyers inquiète de nombreux locataires.","exCn":"房租上涨让许多租户感到担忧。","th":"描述与状态"},{"w":"haut-parleur","p":"n.m.","cn":"扬声器、喇叭","ex":"Le haut-parleur annonce le départ du train.","exCn":"喇叭里正在广播火车发车的消息。","th":"常用词"},{"w":"hauteur","p":"n.f.","cn":"高度；（être à la ~）称职、胜任","ex":"Les camions ne peuvent pas passer : la hauteur maximale est de trois mètres.","exCn":"卡车过不去：限高三米。","th":"描述与状态"},{"w":"haïr","p":"v.","cn":"憎恨、痛恨；现在时单数不带分音符：je hais, tu hais, il hait（读 /ɛ/）","ex":"Je hais le mensonge.","exCn":"我痛恨谎言。","th":"健康与身体"},{"w":"hebdomadaire","p":"n.m.","cn":"每周的；周刊","ex":"Nous avons une réunion hebdomadaire le lundi.","exCn":"我们每周一都开例会。","th":"时间与数量"},{"w":"high-tech","p":"n.m.","cn":"高科技的；高科技（产品）","ex":"Leur nouvelle cuisine est entièrement high-tech : on peut tout contrôler avec son téléphone.","exCn":"他们的新厨房全是高科技：用手机就能控制一切。","th":"描述与状态"},{"w":"historien","p":"n.","cn":"历史学家","ex":"Cet historien a écrit un livre sur la Révolution française.","exCn":"这位历史学家写了一本关于法国大革命的书。","th":"常用词"},{"w":"honneur","p":"n.m.","cn":"荣誉、光荣；（en l'~ de）为纪念…、向…致敬","ex":"C'est un grand honneur pour moi de recevoir ce prix.","exCn":"获得这个奖项对我来说是莫大的荣誉。","th":"常用词"},{"w":"honnête","p":"adj.","cn":"诚实的、正直的","ex":"Pour être honnête, je n'ai pas du tout aimé ce film.","exCn":"说实话，我一点也不喜欢这部电影。","th":"常用词"},{"w":"honnêtement","p":"adv.","cn":"说实话、老实说；诚实地、正当地","ex":"Honnêtement, je ne pense pas que ce projet soit réaliste.","exCn":"说实话，我觉得这个计划不太现实。","th":"常用词"},{"w":"honnêteté","p":"n.f.","cn":"诚实","ex":"Elle a répondu aux questions avec une grande honnêteté.","exCn":"她非常坦诚地回答了这些问题。","th":"常用词"},{"w":"honte","p":"n.f.","cn":"羞愧、羞耻；（avoir ~ de）为…感到羞愧、不好意思；耻辱","ex":"J'avais honte d'avouer que je n'avais pas fait mes devoirs.","exCn":"我不好意思承认自己没写作业。","th":"描述与状态"},{"w":"hop","p":"interj.","cn":"嘿、走（催促或伴随快速动作）；（et ~）一下子就…","ex":"Allez, hop ! Tout le monde dans la voiture !","exCn":"好了，走吧！大家都上车！","th":"描述与状态"},{"w":"horizon","p":"n.m.","cn":"地平线；视野、前景","ex":"Le soleil disparaît lentement à l'horizon.","exCn":"太阳慢慢消失在地平线上。","th":"常用词"},{"w":"horizontal","p":"adj.","cn":"水平的、横的","ex":"Tracez une ligne horizontale en haut de la page.","exCn":"在页面顶部画一条横线。","th":"常用词"},{"w":"horreur","p":"n.f.","cn":"恐怖、恐惧；（avoir ~ de）厌恶、极讨厌","ex":"Les rescapés ont raconté l'horreur qu'ils ont vécue pendant l'incendie.","exCn":"幸存者讲述了他们在火灾中经历的恐怖场面。","th":"情绪与性格"},{"w":"hors","p":"prép.","cn":"（~ / ~ de）在…之外、超出…；cf. hors service 停用、出故障；hors de question 绝对不行","ex":"Nous préférons partir en vacances hors saison : les plages sont presque désertes.","exCn":"我们更喜欢淡季去度假：海滩上几乎没什么人。","th":"常用词"},{"w":"hospitaliser","p":"v.","cn":"使住院、送医治疗","ex":"Le médecin a décidé de l'hospitaliser tout de suite.","exCn":"医生决定马上让他住院。","th":"健康与身体"},{"w":"hospitalisé","p":"adj.","cn":"住院的","ex":"Mon grand-père est hospitalisé depuis lundi.","exCn":"我爷爷从周一起就住院了。","th":"居住与环境"},{"w":"humanitaire","p":"adj.","cn":"人道主义的","ex":"Elle travaille pour une organisation humanitaire en Afrique.","exCn":"她在非洲为一家人道主义组织工作。","th":"人物与身份"},{"w":"humanité","p":"n.f.","cn":"人类；人性、人道","ex":"Le changement climatique est l'un des plus grands défis de l'humanité.","exCn":"气候变化是人类面临的最大挑战之一。","th":"人物与身份"},{"w":"humide","p":"adj.","cn":"潮湿的、湿润的","ex":"Notre appartement au sous-sol est trop humide : il y a de la moisissure sur les murs.","exCn":"我们住的地下室公寓太潮湿了，墙上都长霉了。","th":"常用词"},{"w":"humidité","p":"n.f.","cn":"潮湿、湿度","ex":"En hiver, l'air des maisons est très sec : un humidificateur permet de garder un bon taux d'humidité.","exCn":"冬天屋里的空气很干燥，用加湿器可以保持适宜的湿度。","th":"常用词"},{"w":"hurler","p":"v.","cn":"大喊、尖叫、呼啸","ex":"Les supporters ont hurlé de joie au moment du but.","exCn":"进球那一刻，球迷们兴奋得大声尖叫。","th":"描述与状态"},{"w":"hygiène","p":"n.f.","cn":"卫生","ex":"Une bonne hygiène des mains limite la propagation des virus.","exCn":"良好的手部卫生可以减少病毒传播。","th":"常用词"},{"w":"hâte","p":"n.f.","cn":"匆忙、急忙；（avoir ~ de）迫不及待想…、盼着","ex":"Ce rapport a été rédigé à la hâte et contient beaucoup d'erreurs.","exCn":"这份报告写得很仓促，错误百出。","th":"常用词"},{"w":"héberger","p":"v.","cn":"留宿、收容；（网站、数据）托管","ex":"Mes cousins m'ont hébergé pendant deux semaines à mon arrivée à Montréal.","exCn":"我刚到蒙特利尔时，表兄弟们让我在他们家住了两个星期。","th":"日常动作"},{"w":"hélas","p":"interj.","cn":"唉、可惜、遗憾的是","ex":"Nous espérions du beau temps pour le mariage, mais hélas, il a plu toute la journée.","exCn":"我们本来盼着婚礼那天天气晴好，可惜下了一整天的雨。","th":"常用词"},{"w":"héritage","p":"n.m.","cn":"遗产","ex":"À la mort de son oncle, il a reçu un héritage important.","exCn":"叔叔去世后，他得到了一大笔遗产。","th":"常用词"},{"w":"hésitant","p":"adj.","cn":"犹豫的、迟疑的","ex":"Les clients restent hésitants face aux nouvelles voitures électriques.","exCn":"面对新款电动车，顾客们仍然犹豫不决。","th":"常用词"},{"w":"hésitation","p":"n.f.","cn":"犹豫、迟疑","ex":"Après une longue hésitation, il a finalement accepté l'offre d'emploi.","exCn":"犹豫了很久，他最终接受了这份工作。","th":"常用词"},{"w":"hôte","p":"n.m.","cn":"主人；客人；女主人：l'hôtesse；女客人：l'hôte","ex":"Pendant notre séjour à Québec, notre hôte s'est montré très accueillant.","exCn":"我们在魁北克城逗留期间，接待我们的主人非常热情。","th":"人物与身份"},{"w":"identifier","p":"v.","cn":"识别、辨认；确定、查明；（s'~）登录；（s'~ à）认同","ex":"Cette application permet d'identifier une plante à partir d'une simple photo.","exCn":"这款应用只需一张照片就能识别出植物。","th":"常用词"},{"w":"identique","p":"adj.","cn":"相同的、一模一样的","ex":"Les deux appartements sont presque identiques, mais l'un est plus lumineux.","exCn":"这两套公寓几乎一模一样，不过其中一套更亮堂。","th":"常用词"},{"w":"ignorant","p":"adj.","cn":"无知的；（~ de）不了解…的","ex":"Récemment arrivée au Québec, elle était ignorante des démarches administratives.","exCn":"她刚到魁北克时，对各种行政手续一无所知。","th":"常用词"},{"w":"ignorer","p":"v.","cn":"不知道；不理睬、无视","ex":"J'ignorais que tu parlais japonais !","exCn":"我都不知道你会说日语！","th":"常用词"},{"w":"il s'agit de","p":"loc.","cn":"（所谈的）是；涉及","ex":"Dans ce texte, il s'agit de l'immigration.","exCn":"这篇文章讲的是移民问题。","th":"观点与论证"},{"w":"illusion","p":"n.f.","cn":"幻想；错觉、幻觉","ex":"Il a longtemps vécu avec la douce illusion qu'elle finirait par revenir.","exCn":"很长一段时间里，他一直抱着一个美好的幻想，以为她终究会回来。","th":"常用词"},{"w":"illustration","p":"n.f.","cn":"插图、插画；例证、说明","ex":"Ce livre pour enfants contient de très belles illustrations.","exCn":"这本童书里有很漂亮的插图。","th":"常用词"},{"w":"illustrer","p":"v.","cn":"给…配插图；举例说明、阐明；（s'~）出名、著称","ex":"Ce guide de randonnée est illustré de nombreuses cartes et photos.","exCn":"这本徒步指南配有大量地图和照片。","th":"常用词"},{"w":"illégal","p":"adj.","cn":"非法的、违法的","ex":"Il est illégal de stationner devant une borne d'incendie.","exCn":"在消防栓前停车是违法的。","th":"常用词"},{"w":"imagination","p":"n.f.","cn":"想象力、想象","ex":"Ce romancier a une imagination débordante.","exCn":"这位小说家的想象力非常丰富。","th":"常用词"},{"w":"imiter","p":"v.","cn":"模仿、仿效","ex":"Les enfants imitent souvent le comportement de leurs parents.","exCn":"孩子们常常模仿父母的行为。","th":"常用词"},{"w":"immigration","p":"n.f.","cn":"（外来）移民、移入","ex":"Le Québec mène sa propre politique d'immigration et sélectionne ses travailleurs qualifiés.","exCn":"魁北克实行自己的移民政策，自行甄选技术移民。","th":"社会与新闻"},{"w":"immigrer","p":"v.","cn":"移民（入境）、移居；cf. émigrer 移居国外（从本国迁出）","ex":"Mes grands-parents ont immigré au Canada dans les années soixante.","exCn":"我祖父母在六十年代移民到了加拿大。","th":"社会与新闻"},{"w":"immigré","p":"n.","cn":"（外来）移民；移民的、移居来的；cf. 加拿大更常说 immigrant, immigrante（名词、形容词）","ex":"De nombreux immigrés travaillent dans le bâtiment.","exCn":"许多移民在建筑业工作。","th":"社会与新闻"},{"w":"immobilier","p":"n.m.","cn":"房地产的、不动产的；房地产、房地产业","ex":"Elle travaille comme agente immobilière depuis dix ans.","exCn":"她当房产经纪人已经十年了。","th":"居住与环境"},{"w":"immédiat","p":"adj.","cn":"立即的、即刻的；直接的、紧邻的","ex":"Le médecin a recommandé une hospitalisation immédiate.","exCn":"医生建议立即住院。","th":"常用词"},{"w":"impact","p":"n.m.","cn":"影响；撞击、冲击","ex":"Cette nouvelle loi aura un impact important sur les petites entreprises.","exCn":"这项新法律将对小企业产生重大影响。","th":"抽象与概念"},{"w":"impatience","p":"n.f.","cn":"不耐烦、急躁；（avec ~）迫不及待地","ex":"J'attends avec impatience les résultats de mon examen.","exCn":"我迫不及待地等着考试结果。","th":"常用词"},{"w":"impatient","p":"adj.","cn":"没耐心的、不耐烦的；（~ de）迫不及待的、急于…的","ex":"Ne sois pas si impatient, ton tour va arriver.","exCn":"别那么着急，马上就轮到你了。","th":"情绪与性格"},{"w":"imperméable","p":"n.m.","cn":"雨衣；防水的、不透水的","ex":"N'oublie pas ton imperméable, il va pleuvoir tout l'après-midi.","exCn":"别忘了带雨衣，整个下午都会下雨。","th":"居住与环境"},{"w":"impoli","p":"adj.","cn":"不礼貌的、无礼的","ex":"Il est impoli de regarder son téléphone pendant un repas de famille.","exCn":"家庭聚餐时看手机是不礼貌的。","th":"交际与礼貌"},{"w":"importance","p":"n.f.","cn":"重要性","ex":"Le directeur accorde une grande importance à la ponctualité.","exCn":"主任非常看重守时。","th":"抽象与概念"},{"w":"importer","p":"v.","cn":"进口；（无人称）要紧、重要","ex":"La France importe une grande partie de son gaz.","exCn":"法国很大一部分天然气靠进口。","th":"人物与身份"},{"w":"imposer","p":"v.","cn":"强加、强制；对…征税；（s'~）胜出、确立地位；（s'~）势在必行","ex":"Le gouvernement a imposé de nouvelles règles aux propriétaires de logements.","exCn":"政府对房东强制推行了新规定。","th":"社会与新闻"},{"w":"impressionnant","p":"adj.","cn":"令人印象深刻的、惊人的","ex":"Le nombre de bénévoles venus aider après la tempête était impressionnant.","exCn":"暴风雨过后前来帮忙的志愿者多得惊人。","th":"人物与身份"},{"w":"impressionner","p":"v.","cn":"使印象深刻；使胆怯、震慑","ex":"Son discours a impressionné tout le jury.","exCn":"他的演讲给全体评委留下了深刻印象。","th":"常用词"},{"w":"imprudent","p":"adj.","cn":"不谨慎的、冒失的","ex":"Il serait imprudent de signer ce contrat sans l'avoir lu attentivement.","exCn":"不仔细读一遍就签这份合同，未免太不谨慎了。","th":"常用词"},{"w":"imprévu","p":"n.m.","cn":"意外情况、突发事件；意外的、出乎意料的","ex":"Désolé, j'ai eu un imprévu au travail, j'arrive dans une demi-heure.","exCn":"抱歉，我工作上出了点意外情况，半小时后到。","th":"抽象与概念"},{"w":"impulsif","p":"adj.","cn":"冲动的","ex":"Faites une liste avant d'aller au supermarché pour éviter les achats impulsifs.","exCn":"去超市前先列好清单，避免冲动购物。","th":"常用词"},{"w":"impôt","p":"n.m.","cn":"税、税款","ex":"Une partie de nos impôts sert à financer les hôpitaux.","exCn":"我们缴的税有一部分用来资助医院。","th":"社会与新闻"},{"w":"inacceptable","p":"adj.","cn":"不可接受的","ex":"Pour nos clients, un retard de trois semaines est inacceptable.","exCn":"对我们的客户来说，拖延三个星期是不可接受的。","th":"常用词"},{"w":"inattendu","p":"adj.","cn":"意外的、出乎意料的","ex":"Hier soir, nous avons reçu la visite inattendue de mon oncle de Vancouver.","exCn":"昨晚，我舅舅从温哥华突然来看我们。","th":"常用词"},{"w":"inauguration","p":"n.f.","cn":"落成典礼、揭幕仪式","ex":"Le maire a assisté à l'inauguration de la nouvelle bibliothèque.","exCn":"市长出席了新图书馆的落成典礼。","th":"常用词"},{"w":"incapable","p":"adj.","cn":"（~ de）不能…的、无力…的；无能的","ex":"J'étais tellement fatigué que j'étais incapable de lire plus de deux pages.","exCn":"我累得连两页书都读不下去。","th":"常用词"},{"w":"incendie","p":"n.m.","cn":"火灾","ex":"Trois familles ont perdu leur logement dans l'incendie de l'immeuble voisin.","exCn":"隔壁楼的那场火灾让三户人家失去了住所。","th":"常用词"},{"w":"incident","p":"n.m.","cn":"意外事件、小事故","ex":"Le vol s'est déroulé sans incident.","exCn":"这趟航班一路顺利，没出什么状况。","th":"描述与状态"},{"w":"inclure","p":"v.","cn":"包括、纳入；附上、附寄","ex":"Le prix du séjour inclut le petit-déjeuner et le transfert à l'aéroport.","exCn":"住宿价格包括早餐和机场接送。","th":"常用词"},{"w":"inconfortable","p":"adj.","cn":"不舒适的；（处境）尴尬的、为难的","ex":"Le siège de l'avion était si inconfortable que je n'ai pas dormi de la nuit.","exCn":"飞机座椅太不舒服了，我一整夜都没睡着。","th":"常用词"},{"w":"inconvénient","p":"n.m.","cn":"缺点、弊端；不便、麻烦","ex":"Le principal inconvénient de cet appartement, c'est le bruit de la rue.","exCn":"这套公寓最大的缺点就是街上的噪音。","th":"常用词"},{"w":"indication","p":"n.f.","cn":"指示、说明；迹象、线索","ex":"Suivez les indications du GPS pour trouver l'entrée du stationnement.","exCn":"按照导航的指示找到停车场入口。","th":"常用词"},{"w":"indifférent","p":"adj.","cn":"漠不关心的","ex":"Il est indifférent aux critiques.","exCn":"他对批评无动于衷。","th":"情绪与性格"},{"w":"indispensable","p":"adj.","cn":"必不可少的、不可或缺的","ex":"Il est indispensable de prendre rendez-vous avant de se présenter au bureau.","exCn":"去办事处之前务必先预约。","th":"常用词"},{"w":"individu","p":"n.m.","cn":"个人、个体；（贬，新闻用语）家伙、某人","ex":"Face au stress, chaque individu réagit à sa manière.","exCn":"面对压力，每个人的反应都不一样。","th":"人物与身份"},{"w":"individuel","p":"adj.","cn":"个人的、个体的；单人的；（住宅）独栋的","ex":"Chaque élève aura un entretien individuel avec le professeur.","exCn":"每个学生都会和老师进行一次个人面谈。","th":"人物与身份"},{"w":"industrie","p":"n.f.","cn":"工业；产业、行业","ex":"Le tourisme est devenu une industrie essentielle pour l'économie québécoise.","exCn":"旅游业已经成为魁北克经济中的一个重要产业。","th":"常用词"},{"w":"industriel","p":"adj.","cn":"工业的；（食品）工业化生产的","ex":"La ville possède une grande zone industrielle.","exCn":"这座城市有一个大型工业区。","th":"常用词"},{"w":"indépendance","p":"n.f.","cn":"独立、自主","ex":"Le Sénégal a obtenu son indépendance en 1960.","exCn":"塞内加尔于1960年获得独立。","th":"常用词"},{"w":"indépendant","p":"adj.","cn":"独立的；（职业）自由职业的；cf.（魁北克）自由职业者常说 travailleur autonome","ex":"Depuis qu'elle travaille, elle est financièrement indépendante de ses parents.","exCn":"自从工作以来，她在经济上已经不依赖父母了。","th":"工作与学习"},{"w":"infection","p":"n.f.","cn":"感染","ex":"Les infections respiratoires sont fréquentes en hiver.","exCn":"冬天呼吸道感染很常见。","th":"健康与身体"},{"w":"influence","p":"n.f.","cn":"影响、影响力","ex":"Les réseaux sociaux ont une grande influence sur les jeunes.","exCn":"社交媒体对年轻人有很大的影响。","th":"抽象与概念"},{"w":"influencer","p":"v.","cn":"影响","ex":"La publicité influence nos choix de consommation.","exCn":"广告影响我们的消费选择。","th":"抽象与概念"},{"w":"inférieur","p":"adj.","cn":"较低的、低于…的；下面的、下部的","ex":"Cette année, les températures ont été inférieures à la moyenne saisonnière.","exCn":"今年的气温低于往年同期的平均水平。","th":"描述与状态"},{"w":"inhabituel","p":"adj.","cn":"不寻常的、异常的、罕见的","ex":"Il fait une chaleur inhabituelle pour un mois d'octobre.","exCn":"十月份这么热，实属罕见。","th":"常用词"},{"w":"initiale","p":"n.f.","cn":"（单词、姓名的）首字母","ex":"Écrivez vos initiales en bas de chaque page du contrat.","exCn":"请在合同每一页的底部写上您姓名的首字母。","th":"常用词"},{"w":"initiative","p":"n.f.","cn":"倡议、举措；主动（性）","ex":"La ville a lancé une nouvelle initiative pour réduire les déchets plastiques.","exCn":"市政府推出了一项减少塑料垃圾的新举措。","th":"常用词"},{"w":"injoignable","p":"adj.","cn":"联系不上的","ex":"Depuis ce matin, il est injoignable sur son portable.","exCn":"从早上开始，他的手机就一直联系不上。","th":"常用词"},{"w":"injuste","p":"adj.","cn":"不公平的、不公正的","ex":"Je trouve injuste que les stagiaires ne soient pas payés.","exCn":"我觉得实习生拿不到工资很不公平。","th":"人物与身份"},{"w":"injustice","p":"n.f.","cn":"不公正、不公平","ex":"Enfant, il ne supportait déjà pas l'injustice.","exCn":"他从小就看不得不公平的事。","th":"人物与身份"},{"w":"innocent","p":"n.","cn":"无辜的、清白的；天真的、单纯的；无辜者；（faire l'~）装傻、装糊涂","ex":"Après deux ans de procédure, l'accusée a été reconnue innocente.","exCn":"经过两年的诉讼，女被告被判无罪。","th":"时间与数量"},{"w":"inondation","p":"n.f.","cn":"洪水、水灾","ex":"Les fortes pluies ont provoqué une inondation dans le sous-sol de l'immeuble.","exCn":"暴雨导致大楼的地下室被淹。","th":"常用词"},{"w":"inquiétant","p":"adj.","cn":"令人担忧的、令人不安的","ex":"Il tousse depuis trois semaines, c'est un peu inquiétant.","exCn":"他咳了三个星期了，有点让人担心。","th":"人物与身份"},{"w":"inquiétude","p":"n.f.","cn":"担忧、不安","ex":"Les parents d'élèves ont exprimé leur inquiétude face à la pénurie d'enseignants.","exCn":"学生家长们对教师短缺表示担忧。","th":"常用词"},{"w":"insecte","p":"n.m.","cn":"昆虫","ex":"Avec une loupe, les enfants observent les insectes du jardin.","exCn":"孩子们拿着放大镜观察花园里的昆虫。","th":"常用词"},{"w":"insister","p":"v.","cn":"坚持；（~ sur）强调","ex":"Il a insisté pour payer l'addition.","exCn":"他坚持要付账。","th":"描述与状态"},{"w":"insolite","p":"adj.","cn":"奇特的、不寻常的","ex":"Ce guide présente les lieux les plus insolites de Montréal.","exCn":"这本指南介绍了蒙特利尔最奇特的地方。","th":"常用词"},{"w":"inspecteur","p":"n.","cn":"检查员、视察员；（警察）督察、探长","ex":"Un inspecteur de la ville est venu vérifier les travaux de rénovation.","exCn":"市政府的一名检查员来检查装修工程。","th":"社会与新闻"},{"w":"inspiration","p":"n.f.","cn":"灵感、启发；吸气","ex":"Le peintre a puisé son inspiration dans les paysages de la Gaspésie.","exCn":"这位画家从加斯佩西的风景中汲取灵感。","th":"常用词"},{"w":"inspirer","p":"v.","cn":"启发、给…灵感；使产生（信任、好感等）；吸气","ex":"Ce roman est inspiré d'une histoire vraie.","exCn":"这部小说取材于一个真实的故事。","th":"描述与状态"},{"w":"installation","p":"n.f.","cn":"安装、安置；（常复）设施、设备","ex":"Si vous achetez ce lave-vaisselle avant dimanche, l'installation est gratuite.","exCn":"周日前购买这款洗碗机，可享受免费安装。","th":"常用词"},{"w":"institut","p":"n.m.","cn":"研究所、学院、机构；cf. institut de beauté 美容院","ex":"Il fait ses recherches dans un institut spécialisé en biologie marine.","exCn":"他在一家专门研究海洋生物学的研究所做研究。","th":"工作与学习"},{"w":"instituteur","p":"n.","cn":"小学教师；cf. le / la professeur des écoles（法国现行正式名称）；魁北克多说 enseignant / enseignante au primai…","ex":"L'institutrice de mon fils organise une sortie au musée la semaine prochaine.","exCn":"我儿子的小学老师下周组织大家去博物馆参观。","th":"描述与状态"},{"w":"instruction","p":"n.f.","cn":"（常复）指示、说明；教育、学识","ex":"J'ai suivi toutes les instructions affichées à l'écran, mais le logiciel refuse de s'installer.","exCn":"屏幕上显示的指示我都照做了，可软件就是装不上。","th":"社会与新闻"},{"w":"insulte","p":"n.f.","cn":"侮辱、辱骂","ex":"Est-ce un compliment ou une insulte ?","exCn":"这是恭维还是侮辱？","th":"常用词"},{"w":"insulter","p":"v.","cn":"辱骂、侮辱","ex":"Sur les réseaux sociaux, certains n'hésitent pas à insulter des inconnus pour un simple désaccord.","exCn":"在社交媒体上，有些人仅仅因为意见不合就肆意辱骂陌生人。","th":"常用词"},{"w":"insupportable","p":"adj.","cn":"难以忍受的；（人）令人讨厌的","ex":"Il faisait une chaleur insupportable dans le métro.","exCn":"地铁里热得让人受不了。","th":"情绪与性格"},{"w":"insécurité","p":"n.f.","cn":"治安差、不安全；不安全感","ex":"Beaucoup de femmes ressentent un sentiment d'insécurité dans le métro la nuit.","exCn":"很多女性夜里坐地铁会有不安全感。","th":"常用词"},{"w":"intellectuel","p":"n.","cn":"智力的、脑力的；知识分子","ex":"Les mots croisés sont une bonne activité intellectuelle pour les personnes âgées.","exCn":"填字游戏对老年人来说是一项很好的益智活动。","th":"常用词"},{"w":"intelligence","p":"n.f.","cn":"智力、智能","ex":"L'intelligence artificielle transforme déjà le monde du travail.","exCn":"人工智能已经在改变职场。","th":"常用词"},{"w":"intense","p":"adj.","cn":"强烈的、剧烈的；紧张的、密集的","ex":"Le froid intense a fait geler toutes les canalisations.","exCn":"严寒把所有水管都冻住了。","th":"情绪与性格"},{"w":"intention","p":"n.f.","cn":"意图、打算","ex":"Elle a l'intention de reprendre ses études l'année prochaine.","exCn":"她打算明年重新开始读书。","th":"常用词"},{"w":"interactif","p":"adj.","cn":"互动的、交互式的","ex":"Le musée des sciences propose une exposition interactive pour les enfants.","exCn":"科学博物馆为孩子们推出了一个互动展览。","th":"常用词"},{"w":"interdiction","p":"n.f.","cn":"禁止、禁令","ex":"La ville a annoncé une interdiction totale des sacs en plastique à usage unique.","exCn":"市政府宣布全面禁止一次性塑料袋。","th":"常用词"},{"w":"intermédiaire","p":"n.","cn":"中间的、中级的；中间人、中介；cf. par l'intermédiaire de 通过、经由","ex":"Pour cette randonnée, choisissez le parcours intermédiaire : le plus long est réservé aux marcheurs expérimentés.","exCn":"这次徒步请选择中等难度的路线：最长的那条只适合经验丰富的徒步者。","th":"人物与身份"},{"w":"interne","p":"n.","cn":"内部的；住院实习医生；寄宿生","ex":"L'entreprise a lancé une enquête interne après la fuite de documents confidentiels.","exCn":"机密文件泄露后，公司展开了内部调查。","th":"健康与身体"},{"w":"interphone","p":"n.m.","cn":"（楼宇）对讲机、门禁对讲","ex":"Sonnez à l'interphone, je vous ouvrirai la porte.","exCn":"按一下门口的对讲机，我给您开门。","th":"居住与环境"},{"w":"interprète","p":"n.","cn":"口译员、翻译；（歌曲、角色）演绎者","ex":"Au tribunal, un interprète traduisait les questions du juge en espagnol.","exCn":"在法庭上，一名口译员把法官的提问翻译成西班牙语。","th":"常用词"},{"w":"interpréter","p":"v.","cn":"解释、解读；演绎、扮演（角色）","ex":"Il a mal interprété mon silence et s'est vexé.","exCn":"他误解了我的沉默，结果生气了。","th":"常用词"},{"w":"interroger","p":"v.","cn":"询问、提问；审问；（s'~）自问、思考","ex":"Beaucoup de jeunes s'interrogent sur l'utilité de faire de longues études.","exCn":"很多年轻人都在思考读那么多年书到底有没有用。","th":"常用词"},{"w":"interrompre","p":"v.","cn":"打断；中断、中止","ex":"Excusez-moi de vous interrompre, mais vous avez un appel urgent.","exCn":"抱歉打断您，您有一个紧急电话。","th":"常用词"},{"w":"interrupteur","p":"n.m.","cn":"（电）开关；cf.（魁北克）也常说 le commutateur","ex":"Il y a un interrupteur à côté de la porte pour allumer la lumière du couloir.","exCn":"门边有个开关，可以打开走廊的灯。","th":"常用词"},{"w":"intervention","p":"n.f.","cn":"介入、干预；发言；（外科）手术","ex":"L'intervention de la ministre à la radio a fait beaucoup réagir.","exCn":"部长在电台的发言引起了很大反响。","th":"健康与身体"},{"w":"interview","p":"n.f.","cn":"采访、访谈；cf.（魁北克）多说 l'entrevue（也指求职面试）","ex":"Le ministre a accordé une interview exclusive à un grand quotidien.","exCn":"部长接受了一家大报的独家专访。","th":"工作与学习"},{"w":"interviewer","p":"v.","cn":"采访","ex":"Pour son reportage, elle a interviewé une dizaine de nouveaux arrivants.","exCn":"为了做这篇报道，她采访了十来位新移民。","th":"常用词"},{"w":"intituler","p":"v.","cn":"给…加标题、命名；（s'~）题为、名叫","ex":"Le documentaire s'intitule « Vivre à Montréal sans voiture ».","exCn":"这部纪录片名为《在蒙特利尔无车生活》。","th":"常用词"},{"w":"introduction","p":"n.f.","cn":"引入、引进；引言、导论","ex":"L'introduction de nouvelles technologies a changé notre façon de travailler.","exCn":"新技术的引进改变了我们的工作方式。","th":"常用词"},{"w":"intégrer","p":"v.","cn":"纳入、使融入；加入、考入（团队、学校）；（s'~）融入（社会、集体）","ex":"Le gouvernement veut mieux intégrer les immigrants au marché du travail.","exCn":"政府希望让移民更好地融入劳动力市场。","th":"工作与学习"},{"w":"intérêt","p":"n.m.","cn":"兴趣；利益、好处；利息","ex":"Il a suivi la conférence avec un grand intérêt.","exCn":"他饶有兴趣地听完了这场讲座。","th":"描述与状态"},{"w":"inventeur","p":"n.","cn":"发明者、发明家","ex":"Benjamin Franklin était un inventeur et homme politique américain.","exCn":"本杰明 · 富兰克林是美国的发明家和政治家。","th":"常用词"},{"w":"invention","p":"n.f.","cn":"发明；捏造、虚构","ex":"L'imprimerie est une invention qui a transformé la diffusion du savoir.","exCn":"印刷术这项发明改变了知识的传播方式。","th":"常用词"},{"w":"invisible","p":"adj.","cn":"看不见的、隐形的","ex":"Ces bactéries sont invisibles à l'œil nu.","exCn":"这些细菌肉眼是看不见的。","th":"常用词"},{"w":"inégalité","p":"n.f.","cn":"不平等","ex":"Les inégalités salariales persistent.","exCn":"工资不平等依然存在。","th":"社会与新闻"},{"w":"inévitable","p":"adj.","cn":"不可避免的","ex":"Avec trois enfants, un peu de désordre est inévitable.","exCn":"家里有三个孩子，乱一点在所难免。","th":"常用词"},{"w":"ironique","p":"adj.","cn":"讽刺的、反讽的","ex":"Son sourire ironique montrait bien qu'il ne croyait pas un mot de mon histoire.","exCn":"他那嘲讽的笑容清楚地表明，他对我的话一个字都不信。","th":"常用词"},{"w":"irresponsable","p":"adj.","cn":"不负责任的","ex":"Il est irresponsable de laisser un enfant seul dans une voiture en plein été.","exCn":"盛夏把孩子独自留在车里是不负责任的。","th":"常用词"},{"w":"isoler","p":"v.","cn":"隔离、孤立；隔热、绝缘","ex":"Le patient a été isolé pour éviter la contagion.","exCn":"病人被隔离起来，以防传染。","th":"居住与环境"},{"w":"isolé","p":"adj.","cn":"孤立的、偏僻的；个别的、单独的；（房屋）隔热的、隔音的","ex":"Ils habitent dans une maison isolée au milieu de la forêt.","exCn":"他们住在森林深处一栋偏僻的房子里。","th":"居住与环境"},{"w":"israélien","p":"n.","cn":"以色列的；以色列人","ex":"Le Premier ministre israélien a rencontré le président américain à Washington.","exCn":"以色列总理在华盛顿会见了美国总统。","th":"人物与身份"},{"w":"jalousie","p":"n.f.","cn":"嫉妒、妒忌","ex":"Elle ne supporte plus la jalousie maladive de son mari.","exCn":"她再也受不了丈夫病态的嫉妒心了。","th":"情绪与性格"},{"w":"jeunesse","p":"n.f.","cn":"青年时期、年轻人","ex":"Dans sa jeunesse, mon grand-père a travaillé dans une ferme en Gaspésie.","exCn":"我祖父年轻时在加斯佩西的一家农场干过活。","th":"人物与身份"},{"w":"job","p":"n.m.","cn":"工作、差事（口语）；（petit ~）零工、兼职","ex":"Pendant ses études, il a fait plein de petits jobs pour payer son loyer.","exCn":"上学期间，他打了很多零工来付房租。","th":"工作与学习"},{"w":"joindre","p":"v.","cn":"联系上（某人）；连接、附上；（se ~ à）加入、参加","ex":"J'ai essayé de vous joindre toute la journée, mais votre téléphone était éteint.","exCn":"我一整天都在设法联系您，可您的手机一直关机。","th":"人物与身份"},{"w":"journalisme","p":"n.m.","cn":"新闻业、新闻工作","ex":"Après ses études de journalisme, elle a trouvé un stage dans une radio locale.","exCn":"读完新闻专业后，她在一家地方电台找到了实习。","th":"工作与学习"},{"w":"juge","p":"n.","cn":"法官；（体育）裁判","ex":"Le juge a ordonné une expertise psychiatrique de l'accusé avant le procès.","exCn":"法官下令在开庭审理前对被告进行精神鉴定。","th":"常用词"},{"w":"juger","p":"v.","cn":"判断、认为；审判","ex":"Il ne faut pas juger les gens sur leur apparence.","exCn":"不要以貌取人。","th":"观点与论证"},{"w":"jungle","p":"n.f.","cn":"丛林；（喻）弱肉强食的环境","ex":"Les explorateurs ont marché pendant des jours dans la jungle.","exCn":"探险者们在丛林里走了好几天。","th":"饮食"},{"w":"jurer","p":"v.","cn":"发誓、宣誓；咒骂、说脏话","ex":"Il m'a juré qu'il ne recommencerait plus.","exCn":"他向我发誓再也不会这样了。","th":"描述与状态"},{"w":"jury","p":"n.m.","cn":"评审团、陪审团","ex":"Le jury du festival est présidé par une actrice québécoise.","exCn":"电影节评审团由一位魁北克女演员担任主席。","th":"常用词"},{"w":"jusqu'à ce que","p":"conj.","cn":"（+ 虚拟式）直到…为止","ex":"Attends-moi ici jusqu'à ce que je revienne.","exCn":"在这儿等我，等到我回来。","th":"常用词"},{"w":"justement","p":"adv.","cn":"正是、恰好","ex":"Tu parles de Marie ? Justement, je viens de la croiser au marché.","exCn":"你说的是玛丽？巧了，我刚在市场上碰到她。","th":"描述与状态"},{"w":"justice","p":"n.f.","cn":"正义、公正；司法、法院","ex":"La justice sociale est au cœur de son programme politique.","exCn":"社会公正是他政治纲领的核心。","th":"人物与身份"},{"w":"justificatif","p":"n.m.","cn":"证明文件、凭证；证明的","ex":"Il faut fournir un justificatif de domicile de moins de trois mois.","exCn":"需要提供三个月内的住址证明。","th":"观点与论证"},{"w":"justifier","p":"v.","cn":"为…辩解、证明…合理；（~ de）提供…的证明","ex":"Rien ne justifie un tel retard : le colis devait arriver il y a trois semaines.","exCn":"这样的延误毫无道理：包裹三个星期前就该到了。","th":"观点与论证"},{"w":"kiosque","p":"n.m.","cn":"报亭；（公园里的）亭子；（展会、商场的）摊位、展位","ex":"J'achète mon journal au kiosque en bas de chez moi.","exCn":"我在楼下的报亭买报纸。","th":"人物与身份"},{"w":"kit","p":"n.m.","cn":"套件、成套用品；（en ~）需自行组装的","ex":"J'ai acheté un kit de premiers secours pour la voiture.","exCn":"我给车买了一套急救包。","th":"常用词"},{"w":"labo","p":"n.m.","cn":"实验室、化验室（口语）","ex":"Le labo m'enverra les résultats de ma prise de sang demain.","exCn":"化验室明天会把我的验血结果发给我。","th":"居住与环境"},{"w":"laine","p":"n.f.","cn":"羊毛、毛线","ex":"Les moutons sont tondus au printemps pour récupérer leur laine.","exCn":"每年春天给羊剪毛，收集羊毛。","th":"常用词"},{"w":"lancer","p":"v.","cn":"发起、推出；扔、投掷；（se ~ dans）投身于、着手","ex":"Il a lancé la balle très loin.","exCn":"他把球扔得很远。","th":"日常动作"},{"w":"langage","p":"n.m.","cn":"语言能力、言语；用语、措辞；cf. la langue = （具体的）语言；舌头","ex":"Chez l'enfant, le langage se développe surtout entre deux et cinq ans.","exCn":"儿童的语言能力主要在两到五岁之间发展。","th":"抽象与概念"},{"w":"largeur","p":"n.f.","cn":"宽度；（~ d'esprit）思想开明、心胸宽广","ex":"La piscine fait vingt-cinq mètres de longueur et dix mètres de largeur.","exCn":"游泳池长25米，宽10米。","th":"描述与状态"},{"w":"larme","p":"n.f.","cn":"眼泪、泪水；（饮料）少许、一点儿","ex":"Une larme a coulé sur sa joue quand il a dit au revoir à sa mère.","exCn":"跟母亲道别时，一滴眼泪从他脸颊上滑落。","th":"常用词"},{"w":"latin","p":"n.m.","cn":"拉丁的、拉丁语的；拉丁民族的；拉丁语","ex":"Le français, l'espagnol et l'italien sont des langues latines.","exCn":"法语、西班牙语和意大利语都属于拉丁语族。","th":"日常动作"},{"w":"lavage","p":"n.m.","cn":"洗、清洗；（魁北克）（faire le ~）洗衣服","ex":"Le dimanche, je fais mon lavage à la buanderie du coin.","exCn":"每个星期天，我都去街角的自助洗衣店洗衣服。","th":"日常动作"},{"w":"laverie","p":"n.f.","cn":"自助洗衣店；cf. la buanderie 自助洗衣店（魁北克常用）","ex":"Notre immeuble n'a pas de machine à laver, alors je vais à la laverie une fois par semaine.","exCn":"我们楼里没有洗衣机，所以我每周去一次自助洗衣店。","th":"日常动作"},{"w":"lequel","p":"pron.","cn":"（关系代词）…的那个；（疑问）哪一个","ex":"Lequel de ces deux appartements préfères-tu ?","exCn":"这两套公寓你更喜欢哪一套？","th":"功能词与连接"},{"w":"librement","p":"adv.","cn":"自由地、随意地；坦率地","ex":"Dans ce musée, les visiteurs circulent librement entre les salles.","exCn":"在这座博物馆里，参观者可以在各展厅之间自由走动。","th":"常用词"},{"w":"libérer","p":"v.","cn":"释放、解放；腾出、空出","ex":"Ce nouveau logiciel nous libère de nombreuses tâches répétitives.","exCn":"这个新软件让我们摆脱了很多重复性的工作。","th":"描述与状态"},{"w":"licence","p":"n.f.","cn":"许可证、执照；（大学）学士学位；cf.（魁北克）学士学位叫 le baccalauréat","ex":"Ce restaurant a obtenu une licence pour vendre de l'alcool.","exCn":"这家餐馆拿到了卖酒的执照。","th":"工作与学习"},{"w":"licencier","p":"v.","cn":"解雇、辞退；cf. mettre à pied（魁北克常用）裁员、临时解雇","ex":"L'usine va licencier deux cents employés l'année prochaine.","exCn":"这家工厂明年将裁员两百人。","th":"常用词"},{"w":"lien","p":"n.m.","cn":"联系、纽带；（网络）链接","ex":"Il existe un lien étroit entre l'alimentation et la santé.","exCn":"饮食与健康之间有着密切的联系。","th":"常用词"},{"w":"lier","p":"v.","cn":"联系、关联；捆、绑","ex":"Selon l'étude, ces problèmes de santé sont liés au manque de sommeil.","exCn":"研究表明，这些健康问题与睡眠不足有关。","th":"常用词"},{"w":"lime","p":"n.f.","cn":"锉刀；青柠；cf. le citron vert 青柠（法国更常用；魁北克多说 lime）","ex":"Passe-moi la lime à ongles, s'il te plaît.","exCn":"请把指甲锉递给我。","th":"常用词"},{"w":"limitation","p":"n.f.","cn":"限制","ex":"La limitation de vitesse est de 50 km/h en ville.","exCn":"城区限速每小时50公里。","th":"常用词"},{"w":"limite","p":"n.f.","cn":"限度、极限；界限、边界；cf. date limite 截止日期","ex":"J'ai trente-six ans : j'ai dépassé d'un an la limite d'âge pour le visa vacances-travail.","exCn":"我三十六岁了，比打工度假签证的年龄上限超出了一岁。","th":"常用词"},{"w":"limiter","p":"v.","cn":"限制、限定","ex":"Le médecin m'a conseillé de limiter ma consommation de sucre.","exCn":"医生建议我少吃糖。","th":"常用词"},{"w":"limité","p":"adj.","cn":"有限的、受限的","ex":"Le nombre de places est limité, inscrivez-vous rapidement.","exCn":"名额有限，请尽快报名。","th":"常用词"},{"w":"linge","p":"n.m.","cn":"（待洗或洗好的）衣物；家用织物（床单、毛巾等）；（魁北克）衣服","ex":"N'oublie pas de sortir le linge de la sécheuse, sinon il sera tout froissé.","exCn":"别忘了把衣服从烘干机里拿出来，不然会皱巴巴的。","th":"描述与状态"},{"w":"linguistique","p":"n.f.","cn":"语言的；语言学的；语言学","ex":"Elle a fait un séjour linguistique à Québec pour améliorer son français.","exCn":"她去魁北克城参加语言游学，提高自己的法语。","th":"常用词"},{"w":"liquide","p":"n.m.","cn":"液体；现金；液体的、液态的","ex":"Après son opération, il ne pourra manger que des aliments liquides pendant une semaine.","exCn":"手术后的一周里，他只能吃流食。","th":"购物与金钱"},{"w":"lister","p":"v.","cn":"列出、列清单","ex":"Avant le déménagement, j'ai listé tous les objets fragiles à emballer.","exCn":"搬家前，我把所有要打包的易碎物品都列了出来。","th":"常用词"},{"w":"littéraire","p":"adj.","cn":"文学的；文科的","ex":"Le français littéraire est très différent de la langue parlée.","exCn":"文学作品里的法语和日常口语差别很大。","th":"常用词"},{"w":"livrer","p":"v.","cn":"送货、交付、投递；（se ~ à）从事、沉溺于","ex":"Le magasin livre gratuitement les meubles à domicile.","exCn":"这家店免费送家具上门。","th":"常用词"},{"w":"localiser","p":"v.","cn":"定位","ex":"Grâce à son téléphone, les secours ont pu localiser le randonneur perdu.","exCn":"救援人员通过手机定位到了那名迷路的徒步者。","th":"常用词"},{"w":"locataire","p":"n.","cn":"房客、租户","ex":"La locataire précédente avait laissé l'appartement dans un état impeccable.","exCn":"前一位女租客把公寓收拾得干干净净。","th":"购物与金钱"},{"w":"loger","p":"v.","cn":"提供住处、安顿；住、寄宿","ex":"Ma tante peut nous loger pendant notre séjour à Québec.","exCn":"我们在魁北克城期间，姑妈可以让我们住她家。","th":"居住与环境"},{"w":"logiciel","p":"n.m.","cn":"软件","ex":"Notre entreprise utilise un logiciel de comptabilité très simple.","exCn":"我们公司用的是一款非常简单的会计软件。","th":"常用词"},{"w":"logique","p":"n.f.","cn":"逻辑；合乎逻辑的","ex":"Je ne comprends pas la logique de cette décision.","exCn":"我不明白这个决定背后的逻辑。","th":"常用词"},{"w":"logo","p":"n.m.","cn":"标志、徽标","ex":"Le logo de la marque est imprimé sur chaque bouteille.","exCn":"品牌标志印在每一个瓶子上。","th":"常用词"},{"w":"lointain","p":"adj.","cn":"遥远的、远方的；（时间）久远的","ex":"Elle rêve de partir vers des contrées lointaines.","exCn":"她梦想去遥远的异国他乡。","th":"时间与数量"},{"w":"longuement","p":"adv.","cn":"长时间地；详细地","ex":"Nous avons longuement discuté avant de prendre cette décision.","exCn":"做出这个决定之前，我们讨论了很久。","th":"时间与数量"},{"w":"longueur","p":"n.f.","cn":"长度、篇幅；cf. à longueur de journée 整天、一天到晚","ex":"La longueur du texte ne doit pas dépasser deux pages.","exCn":"文章篇幅不得超过两页。","th":"时间与数量"},{"w":"look","p":"n.m.","cn":"造型、打扮；风格、外观（口语）","ex":"Avec sa nouvelle coupe de cheveux, il a complètement changé de look.","exCn":"换了新发型以后，他整个人的造型都变了。","th":"居住与环境"},{"w":"lors de","p":"prép.","cn":"在…的时候、在…期间","ex":"Lors de notre séjour à Paris, nous avons visité le musée d'Orsay.","exCn":"我们在巴黎逗留期间参观了奥赛博物馆。","th":"常用词"},{"w":"lorsque","p":"conj.","cn":"当…的时候","ex":"Lorsque l'avion a commencé à trembler, ma voisine de siège m'a agrippé le bras.","exCn":"飞机开始颠簸时，邻座的女士一把抓住了我的胳膊。","th":"常用词"},{"w":"loterie","p":"n.f.","cn":"彩票、抽奖","ex":"Si je gagnais à la loterie, j'arrêterais de travailler.","exCn":"要是中了彩票，我就不上班了。","th":"出行与旅行"},{"w":"loyal","p":"adj.","cn":"忠诚的；正直的、公平的","ex":"Il est resté loyal envers son entreprise pendant trente ans.","exCn":"三十年来，他一直对公司忠心耿耿。","th":"人物与身份"},{"w":"luge","p":"n.f.","cn":"（小）雪橇","ex":"Les enfants font de la luge sur la colline.","exCn":"孩子们在山坡上滑雪橇。","th":"居住与环境"},{"w":"lutte","p":"n.f.","cn":"斗争、搏斗","ex":"La lutte pour l'égalité continue.","exCn":"争取平等的斗争仍在继续。","th":"常用词"},{"w":"lutter","p":"v.","cn":"斗争、抗争、努力对抗","ex":"La ville a lancé un plan pour lutter contre la pollution de l'air.","exCn":"市政府推出了一项对抗空气污染的计划。","th":"常用词"},{"w":"luxe","p":"n.m.","cn":"奢华、奢侈","ex":"Ils ont passé leur lune de miel dans un hôtel de luxe.","exCn":"他们在一家豪华酒店度的蜜月。","th":"常用词"},{"w":"luxueux","p":"adj.","cn":"豪华的、奢华的","ex":"Ce chanteur célèbre vit dans une villa luxueuse avec piscine et salle de cinéma.","exCn":"这位知名歌手住在一栋带泳池和家庭影院的豪华别墅里。","th":"常用词"},{"w":"lycéen","p":"n.","cn":"高中生","ex":"Les lycéens passent le bac en juin.","exCn":"高中生在六月参加高中会考。","th":"描述与状态"},{"w":"là-dedans","p":"adv.","cn":"在这里面、在那里面；在这件事里（口语）","ex":"Qu'est-ce que tu as mis là-dedans ? Ta valise pèse une tonne !","exCn":"你在里面装了什么？箱子重得要命！","th":"常用词"},{"w":"là-dessus","p":"adv.","cn":"在那上面；关于这一点；随即、于是","ex":"Il y a une petite table près de l'entrée : tu peux poser tes clés là-dessus.","exCn":"门口有张小桌子，你可以把钥匙放在上面。","th":"常用词"},{"w":"lâcher","p":"v.","cn":"松开、放开；抛下、放弃；（绳子、刹车等）断掉、失灵；cf. Lâche pas !（魁北克口语）别放弃、挺住","ex":"Ne lâche pas la main de ton petit frère dans le métro.","exCn":"在地铁里别松开你弟弟的手。","th":"出行与旅行"},{"w":"légal","p":"adj.","cn":"合法的；法定的","ex":"Au Canada, il est légal de travailler pendant ses études, sous certaines conditions.","exCn":"在加拿大，留学期间在一定条件下打工是合法的。","th":"常用词"},{"w":"légende","p":"n.f.","cn":"传说；传奇人物；（图片的）说明、图例","ex":"Cette chanteuse est une légende vivante de la musique québécoise.","exCn":"这位女歌手是魁北克乐坛活着的传奇。","th":"人物与身份"},{"w":"légèrement","p":"adv.","cn":"轻微地、稍微；轻轻地；（穿得）单薄","ex":"Le conducteur a été légèrement blessé dans l'accident.","exCn":"司机在事故中受了轻伤。","th":"描述与状态"},{"w":"machin","p":"n.m.","cn":"东西、玩意儿（口语）；（Machin）那个谁（口语）","ex":"C'est quoi, ce machin sur la table ? — Un chargeur pour la voiture.","exCn":"桌上这玩意儿是什么？——车载充电器。","th":"常用词"},{"w":"magicien","p":"n.","cn":"魔术师；魔法师、巫师","ex":"Le magicien a demandé un volontaire dans le public.","exCn":"魔术师请观众中的一位志愿者上台。","th":"常用词"},{"w":"magie","p":"n.f.","cn":"魔法；魔力、魅力","ex":"Le lendemain, ma douleur au dos avait disparu comme par magie.","exCn":"第二天，我的背痛奇迹般地消失了。","th":"常用词"},{"w":"maintenir","p":"v.","cn":"维持、保持；坚持（说法、决定）；（活动等）照常进行、不取消","ex":"La mairie a maintenu le festival malgré la pluie annoncée.","exCn":"尽管预报有雨，市政府仍照常举办了节日活动。","th":"常用词"},{"w":"majeur","p":"adj.","cn":"重大的、主要的；成年的","ex":"La pollution de l'air est une préoccupation majeure pour les habitants de la ville.","exCn":"空气污染是这座城市居民的一大担忧。","th":"时间与数量"},{"w":"majorité","p":"n.f.","cn":"大多数；（选举、议会中的）多数；成年","ex":"La majorité de mes amis ont des enfants maintenant, alors on sort moins le soir.","exCn":"我的朋友现在大多有了孩子，所以我们晚上很少出去玩了。","th":"时间与数量"},{"w":"mal à l'aise","p":"loc.","cn":"不自在、局促不安","ex":"Je me sens mal à l'aise quand on parle de moi.","exCn":"别人谈论我的时候，我会觉得不自在。","th":"常用词"},{"w":"maladroit","p":"adj.","cn":"笨拙的、笨手笨脚的；（言行）欠妥的、不得体的","ex":"Il est si maladroit qu'il a encore cassé un verre.","exCn":"他笨手笨脚的，又打碎了一个杯子。","th":"常用词"},{"w":"malaise","p":"n.m.","cn":"身体不适、晕厥；不安、尴尬","ex":"Il a fait un malaise dans le métro ce matin.","exCn":"他今天早上在地铁里突然晕倒了。","th":"健康与身体"},{"w":"malchance","p":"n.f.","cn":"厄运、霉运","ex":"Par malchance, mon vol a été annulé le jour de mon entretien.","exCn":"倒霉的是，我的航班偏偏在面试当天被取消了。","th":"常用词"},{"w":"malentendu","p":"n.m.","cn":"误会","ex":"Il y a eu un malentendu.","exCn":"这中间有误会。","th":"常用词"},{"w":"malgré","p":"prép.","cn":"尽管（+名词）","ex":"Malgré la fatigue, elle a continué.","exCn":"尽管很累，她还是继续了。","th":"观点与论证"},{"w":"malheur","p":"n.m.","cn":"不幸、灾祸、厄运","ex":"Ce malheur a rapproché toute la famille.","exCn":"这场不幸让全家人更加团结。","th":"常用词"},{"w":"malhonnête","p":"adj.","cn":"不诚实的","ex":"Un commerçant malhonnête a vendu des produits périmés à ses clients.","exCn":"一个不诚实的商贩把过期商品卖给了顾客。","th":"常用词"},{"w":"malin","p":"adj.","cn":"聪明的、机灵的；狡猾的；（人、动物）凶的、脾气坏的（魁北克口语）；（肿瘤）恶性的；cf. faire le malin 耍小聪明、逞能（口语）","ex":"Mon voisin a trouvé un moyen malin de réduire sa facture d'électricité.","exCn":"我邻居想出了一个降低电费的聪明办法。","th":"人物与身份"},{"w":"manager","p":"n.","cn":"经理、管理者","ex":"Notre nouveau manager organise une réunion d'équipe chaque lundi.","exCn":"我们的新经理每周一召开团队会议。","th":"常用词"},{"w":"manche","p":"n.f.","cn":"袖子；（比赛的）一局、一盘；cf. le manche = 柄、把手","ex":"J'ai taché la manche de ma chemise avec du café.","exCn":"我把咖啡洒在衬衫袖子上了。","th":"常用词"},{"w":"manifestant","p":"n.","cn":"示威者、游行者","ex":"Une jeune manifestante brandissait une pancarte : « Il n'y a pas de planète B ».","exCn":"一位年轻的女示威者举着一块牌子，上面写着：“我们没有第二个地球”。","th":"常用词"},{"w":"manifestation","p":"n.f.","cn":"示威游行；（文化、体育）活动","ex":"Une manifestation pour le climat bloquera le centre-ville samedi après-midi.","exCn":"周六下午将有一场气候游行，市中心交通会受阻。","th":"常用词"},{"w":"manifester","p":"v.","cn":"表示、表现出；游行示威；（se ~）显现、出现；（se ~）出面、联系","ex":"Plusieurs habitants ont manifesté leur mécontentement lors de la réunion publique.","exCn":"好几位居民在公开会议上表达了不满。","th":"常用词"},{"w":"mannequin","p":"n.m.","cn":"模特；人体模型","ex":"Elle travaille comme mannequin pour une marque de vêtements de sport.","exCn":"她给一个运动服装品牌当模特。","th":"人物与身份"},{"w":"manque","p":"n.m.","cn":"缺乏、不足；（情感上的）空虚、失落","ex":"Beaucoup d'étudiants souffrent d'un manque de sommeil.","exCn":"很多学生睡眠不足。","th":"描述与状态"},{"w":"manuel","p":"n.m.","cn":"教材；说明书；手工的","ex":"J'ai jeté le manuel d'utilisation, et maintenant je ne sais plus comment régler l'imprimante.","exCn":"我把使用说明书扔了，现在不知道该怎么设置打印机了。","th":"常用词"},{"w":"manège","p":"n.m.","cn":"旋转木马、游乐设施；花招、把戏","ex":"Les enfants font un tour de manège à la fête foraine.","exCn":"孩子们在游乐场坐了一圈旋转木马。","th":"居住与环境"},{"w":"maquillage","p":"n.m.","cn":"化妆、妆容","ex":"Au travail, elle porte très peu de maquillage.","exCn":"上班时她只化很淡的妆。","th":"常用词"},{"w":"marathon","p":"n.m.","cn":"马拉松","ex":"Le marathon de New York est le plus grand du monde.","exCn":"纽约马拉松是世界上规模最大的马拉松。","th":"日常动作"},{"w":"marchand","p":"n.","cn":"商人、商贩","ex":"Le marchand de fruits installe son étal au marché chaque samedi.","exCn":"那个卖水果的商贩每周六都在市场上摆摊。","th":"人物与身份"},{"w":"marchander","p":"v.","cn":"讨价还价、砍价","ex":"Au marché aux puces, tout le monde marchande.","exCn":"在跳蚤市场，大家都讨价还价。","th":"购物与金钱"},{"w":"marchandise","p":"n.f.","cn":"商品、货物","ex":"Au port, des grues déchargent la marchandise des porte-conteneurs jour et nuit.","exCn":"在港口，起重机日夜不停地从集装箱船上卸货。","th":"购物与金钱"},{"w":"marin","p":"n.m.","cn":"水手；海的","ex":"Son grand-père, un ancien marin, a fait plusieurs fois le tour du monde.","exCn":"他爷爷以前是水手，曾多次环游世界。","th":"居住与环境"},{"w":"marqueur","p":"n.m.","cn":"记号笔、马克笔；标志、标记物；（体育）进球者、得分手","ex":"J'ai écrit l'adresse au marqueur sur le colis.","exCn":"我用记号笔在包裹上写了地址。","th":"常用词"},{"w":"marteau","p":"n.m.","cn":"锤子","ex":"Mon voisin donne des coups de marteau depuis sept heures du matin.","exCn":"我邻居从早上七点就开始叮叮当当地敲锤子。","th":"常用词"},{"w":"master","p":"n.m.","cn":"硕士（学位）；cf. la maîtrise 硕士学位（魁北克用语）","ex":"Après sa licence, elle prépare un master en droit.","exCn":"读完本科后，她正在攻读法学硕士。","th":"常用词"},{"w":"matelas","p":"n.m.","cn":"床垫","ex":"Nous avons acheté un nouveau matelas, car l'ancien me donnait mal au dos.","exCn":"我们买了个新床垫，因为旧的睡得我背疼。","th":"常用词"},{"w":"maternité","p":"n.f.","cn":"产科医院、妇产科；母亲身份、生育","ex":"Le bébé est né à la maternité du centre-ville.","exCn":"宝宝是在市中心的妇产医院出生的。","th":"健康与身体"},{"w":"matinal","p":"adj.","cn":"早晨的；（人）早起的","ex":"Je fais une promenade matinale avant d'aller travailler.","exCn":"上班前我会出去晨间散步。","th":"人物与身份"},{"w":"matériel","p":"n.m.","cn":"器材、设备、装备；（电脑）硬件；物质的","ex":"Le club fournit tout le matériel de ski aux débutants.","exCn":"俱乐部为初学者提供全套滑雪装备。","th":"常用词"},{"w":"maître","p":"n.","cn":"主人、主宰；（小学）老师；大师、名家；（Maître）对律师、公证人的尊称；cf. la maîtresse 另有「情妇」的意思","ex":"Le chien attend son maître devant le supermarché.","exCn":"狗在超市门口等它的主人。","th":"工作与学习"},{"w":"maîtriser","p":"v.","cn":"掌握、精通；控制、制服","ex":"Pour travailler ici, il faut maîtriser le français et l'anglais.","exCn":"要在这里工作，必须精通法语和英语。","th":"常用词"},{"w":"maïs","p":"n.m.","cn":"玉米；cf.（魁北克）le blé d'Inde 玉米","ex":"En été, nous faisons griller du maïs sur le barbecue.","exCn":"夏天我们会在烧烤架上烤玉米。","th":"常用词"},{"w":"menace","p":"n.f.","cn":"威胁","ex":"Le réchauffement climatique représente une menace sérieuse pour la biodiversité.","exCn":"全球变暖对生物多样性构成了严重威胁。","th":"常用词"},{"w":"menacer","p":"v.","cn":"威胁、恐吓；（~ de）有…的危险","ex":"Le syndicat menace la direction d'une grève si les salaires ne sont pas revalorisés.","exCn":"工会威胁资方，如果不上调工资就举行罢工。","th":"常用词"},{"w":"mener","p":"v.","cn":"开展；带领","ex":"Une équipe mène l'enquête depuis un an.","exCn":"一个团队已调查一年。","th":"社会与新闻"},{"w":"mensonge","p":"n.m.","cn":"谎言、谎话","ex":"L'enfant a dit un mensonge à ses parents au sujet de son bulletin.","exCn":"那孩子在成绩单的事上对父母撒了谎。","th":"常用词"},{"w":"mensuel","p":"n.m.","cn":"每月的；月刊","ex":"Mon loyer mensuel est de 900 euros.","exCn":"我每月的房租是900欧元。","th":"时间与数量"},{"w":"mental","p":"adj.","cn":"精神的、心理的；脑力的（calcul ~ 心算）","ex":"La santé mentale des étudiants s'est dégradée pendant la pandémie.","exCn":"疫情期间，大学生的心理健康状况恶化了。","th":"常用词"},{"w":"menteur","p":"n.","cn":"说谎者","ex":"Ne le crois pas : c'est un menteur.","exCn":"别相信他，他是个爱撒谎的人。","th":"常用词"},{"w":"mentionner","p":"v.","cn":"提到、提及","ex":"Le candidat a oublié de mentionner son expérience à l'étranger dans son CV.","exCn":"这位求职者忘了在简历里提到自己的海外经历。","th":"常用词"},{"w":"merveille","p":"n.f.","cn":"奇迹、奇观；极好的东西；cf. à merveille 好极了、非常好","ex":"La pyramide de Khéops est la seule des sept merveilles du monde antique encore debout.","exCn":"胡夫金字塔是古代世界七大奇迹中唯一至今仍屹立不倒的。","th":"描述与状态"},{"w":"messagerie","p":"n.f.","cn":"（电子）邮箱、语音信箱；（~ instantanée）即时通讯","ex":"Je n'arrive pas à me connecter à ma messagerie depuis ce matin.","exCn":"从今天早上起我就登不上邮箱了。","th":"常用词"},{"w":"mesure","p":"n.f.","cn":"措施；尺度","ex":"Le gouvernement a pris des mesures urgentes.","exCn":"政府已采取紧急措施。","th":"社会与新闻"},{"w":"metteur en scène","p":"n.","cn":"（戏剧、电影）导演","ex":"Le metteur en scène a choisi de jeunes acteurs.","exCn":"导演选了几位年轻演员。","th":"常用词"},{"w":"mien","p":"pron.","cn":"我的（那个、那些）；（les miens）我的家人","ex":"Ta voiture est plus récente que la mienne.","exCn":"你的车比我的新。","th":"人物与身份"},{"w":"migraine","p":"n.f.","cn":"偏头痛、头痛","ex":"J'ai une migraine terrible, je vais m'allonger dans le noir.","exCn":"我偏头痛得厉害，要去暗处躺一会儿。","th":"健康与身体"},{"w":"militaire","p":"n.","cn":"军人；军事的、军队的","ex":"Un militaire en uniforme surveille l'entrée de l'ambassade.","exCn":"一名穿制服的军人在大使馆门口站岗。","th":"人物与身份"},{"w":"milliard","p":"n.m.","cn":"十亿","ex":"La fortune de cet homme d'affaires est estimée à trois milliards d'euros.","exCn":"这位商人的财富估计达三十亿欧元。","th":"常用词"},{"w":"milliardaire","p":"n.","cn":"亿万富翁；身家亿万的","ex":"Ce jeune entrepreneur est devenu milliardaire avant trente ans grâce à son application.","exCn":"这位年轻的企业家靠自己开发的应用，不到三十岁就成了亿万富翁。","th":"时间与数量"},{"w":"millier","p":"n.m.","cn":"约一千；（des ~s）成千上万","ex":"Un millier de spectateurs ont assisté au concert gratuit dans le parc.","exCn":"约有一千名观众在公园里观看了这场免费音乐会。","th":"时间与数量"},{"w":"millionnaire","p":"n.","cn":"百万富翁；身家百万的","ex":"Ce millionnaire a donné la moitié de sa fortune à des associations caritatives.","exCn":"这位百万富翁把一半的财产捐给了慈善机构。","th":"时间与数量"},{"w":"mine","p":"n.f.","cn":"气色、脸色；矿、矿井；cf. mine de rien 不动声色地、看似不经意（口语）；faire mine de 假装","ex":"Tu as bonne mine, tu es partie en vacances ?","exCn":"你气色真好，去度假了吗？","th":"常用词"},{"w":"mineur","p":"n.","cn":"未成年的；次要的；未成年人；矿工","ex":"Au Québec, il est interdit de vendre de l'alcool à un mineur.","exCn":"在魁北克，禁止向未成年人出售酒类。","th":"人物与身份"},{"w":"mini-jupe","p":"n.f.","cn":"超短裙、迷你裙","ex":"Dans les années 1960, la mini-jupe a choqué beaucoup de parents.","exCn":"在20世纪60年代，迷你裙让很多家长大为震惊。","th":"描述与状态"},{"w":"minimum","p":"n.m.","cn":"最低限度、最小值；最低的、最小的；cf. salaire minimum 最低工资","ex":"Il faut un minimum de trois ans d'expérience pour postuler à ce poste.","exCn":"申请这个职位至少需要三年工作经验。","th":"工作与学习"},{"w":"ministre","p":"n.","cn":"部长、大臣","ex":"La ministre de la Santé a annoncé de nouvelles mesures contre la grippe.","exCn":"卫生部长宣布了新的流感防控措施。","th":"描述与状态"},{"w":"ministère","p":"n.m.","cn":"（政府的）部","ex":"Pour faire évaluer mon diplôme étranger, j'ai envoyé mon dossier au ministère de l'Immigration du Québec.","exCn":"为了给我的国外学历做评估，我把材料寄给了魁北克移民部。","th":"社会与新闻"},{"w":"minuscule","p":"adj.","cn":"极小的、微小的；（字母）小写的","ex":"À Paris, nous habitions dans un studio minuscule sous les toits.","exCn":"在巴黎时，我们住在顶楼一间极小的单间公寓里。","th":"描述与状态"},{"w":"miracle","p":"n.m.","cn":"奇迹","ex":"C'est un miracle que personne n'ait été blessé dans l'accident.","exCn":"事故中竟然没有人受伤，真是个奇迹。","th":"常用词"},{"w":"mise","p":"n.f.","cn":"（~ en / à…）放、置（如 mise en place 落实、mise à jour 更新）；赌注","ex":"La mise en place du projet prendra six mois.","exCn":"这个项目的落实需要六个月。","th":"描述与状态"},{"w":"mise en scène","p":"n.f.","cn":"（戏剧、电影）导演、执导；（喻）作秀、刻意安排","ex":"La mise en scène de cette pièce est très originale.","exCn":"这出戏的导演手法很有新意。","th":"常用词"},{"w":"mission","p":"n.f.","cn":"任务、使命；使团、代表团","ex":"Mon patron m'a confié une mission délicate : annoncer les nouveaux horaires à toute l'équipe.","exCn":"老板交给我一项棘手的任务：向整个团队宣布新的工作时间安排。","th":"工作与学习"},{"w":"mixeur","p":"n.m.","cn":"搅拌机、料理机；cf. le mélangeur 搅拌机（魁北克用语）","ex":"Passez la soupe au mixeur avant de servir.","exCn":"上桌前把汤用搅拌机打碎。","th":"常用词"},{"w":"mobile","p":"n.m.","cn":"可移动的、活动的；（犯罪等的）动机；手机","ex":"Une clinique mobile se rend dans les villages éloignés pour vacciner les habitants.","exCn":"一家流动诊所前往偏远村庄为村民接种疫苗。","th":"社会与新闻"},{"w":"mobiliser","p":"v.","cn":"动员、调动；（se ~）行动起来","ex":"Le gouvernement a mobilisé l'armée pour aider les victimes des inondations.","exCn":"政府调动军队援助洪灾灾民。","th":"常用词"},{"w":"modeste","p":"adj.","cn":"谦虚的；简朴的、不起眼的；（收入等）微薄的","ex":"Il est trop modeste pour se vanter de ses médailles ; c'est sa femme qui nous les a montrées.","exCn":"他太谦虚了，从不炫耀自己的奖牌，是他妻子拿给我们看的。","th":"购物与金钱"},{"w":"modifier","p":"v.","cn":"修改、改变","ex":"Vous pouvez modifier votre réservation en ligne jusqu'à 24 heures avant le départ.","exCn":"您最晚可在出发前24小时在线修改预订。","th":"常用词"},{"w":"moniteur","p":"n.","cn":"（驾驶、运动等）教练；（夏令营等）辅导员；显示器、监视器","ex":"Mon moniteur d'auto-école reste toujours calme, même quand je fais des erreurs.","exCn":"我的驾校教练总是很冷静，哪怕我出错也一样。","th":"时间与数量"},{"w":"monstre","p":"n.m.","cn":"怪物、怪兽；恶魔般的人；（放在名词后）巨大的、惊人的（口语）","ex":"Mon fils croit qu'un monstre se cache sous son lit et refuse d'éteindre la lumière.","exCn":"我儿子以为床底下藏着怪物，不肯关灯。","th":"人物与身份"},{"w":"mont","p":"n.m.","cn":"山峰","ex":"Le mont Blanc, le plus haut sommet des Alpes, attire chaque année des milliers d'alpinistes.","exCn":"勃朗峰是阿尔卑斯山脉的最高峰，每年吸引成千上万的登山者。","th":"居住与环境"},{"w":"montant","p":"n.m.","cn":"金额","ex":"Le montant total de la facture s'élève à deux cents dollars.","exCn":"账单总金额为两百加元。","th":"常用词"},{"w":"moral","p":"n.m.","cn":"士气、精神状态、情绪；道德的；精神上的、心理上的；cf. la morale = 道德；寓意；faire la morale à qqn 对某人说教","ex":"Après son licenciement, il n'avait plus le moral.","exCn":"被解雇之后，他情绪一直很低落。","th":"人物与身份"},{"w":"mordre","p":"v.","cn":"咬","ex":"Le chien du voisin a mordu un enfant qui jouait dans le parc.","exCn":"邻居家的狗咬了一个在公园里玩耍的孩子。","th":"常用词"},{"w":"motif","p":"n.m.","cn":"动机、理由；图案、花纹","ex":"À l'accueil de la clinique, on m'a demandé le motif de ma consultation.","exCn":"在诊所前台，工作人员问我来看病的原因。","th":"居住与环境"},{"w":"motivation","p":"n.f.","cn":"积极性、干劲；动机、理由；cf. la lettre de motivation 求职信","ex":"Une forte motivation est indispensable pour apprendre une langue.","exCn":"要学好一门语言，必须有很强的动力。","th":"观点与论证"},{"w":"motiver","p":"v.","cn":"激励、激发；成为…的理由","ex":"Le coach sait motiver ses joueurs avant chaque match.","exCn":"这位教练很会在每场比赛前给球员们打气。","th":"观点与论证"},{"w":"motivé","p":"adj.","cn":"有动力的；积极的","ex":"Il est très motivé par ce travail.","exCn":"他对这份工作很有动力。","th":"情绪与性格"},{"w":"mou","p":"adj.","cn":"mou 元音前 mol / molle；软的、柔软的；（人）软弱的、没劲的","ex":"Ce matelas est trop mou pour mon dos.","exCn":"这个床垫太软，对我的背不好。","th":"人物与身份"},{"w":"mouche","p":"n.f.","cn":"苍蝇；（faire ~）命中、击中要害","ex":"Une mouche tourne autour de la lampe.","exCn":"一只苍蝇绕着灯飞来飞去。","th":"常用词"},{"w":"mouiller","p":"v.","cn":"弄湿、浸湿；（il ~）下雨（魁北克口语）；（se ~）表态、担风险（口语）","ex":"Mouille un peu le linge avant de le repasser.","exCn":"熨衣服之前先把衣服稍微弄湿。","th":"居住与环境"},{"w":"moulin","p":"n.m.","cn":"磨坊；（咖啡、胡椒等的）研磨器","ex":"On a visité un vieux moulin au bord de la rivière.","exCn":"我们参观了河边的一座老磨坊。","th":"饮食"},{"w":"mousse","p":"n.f.","cn":"泡沫；慕斯（甜点）；苔藓","ex":"Il y a trop de mousse dans ma bière.","exCn":"我的啤酒泡沫太多了。","th":"饮食"},{"w":"mouvement","p":"n.m.","cn":"动作、移动；（社会、政治）运动","ex":"Après l'opération, évitez tout mouvement brusque.","exCn":"手术后要避免任何突然的动作。","th":"社会与新闻"},{"w":"Moyen Âge","p":"n.m.","cn":"中世纪","ex":"Ce château date du Moyen Âge.","exCn":"这座城堡建于中世纪。","th":"时间与数量"},{"w":"moyenne","p":"n.f.","cn":"平均数、平均值；（考试）及格分","ex":"En moyenne, je dors sept heures par nuit.","exCn":"我平均每晚睡七个小时。","th":"工作与学习"},{"w":"muet","p":"adj.","cn":"哑的；沉默的、无声的","ex":"Il est né muet et communique en langue des signes.","exCn":"他天生不会说话，用手语交流。","th":"常用词"},{"w":"multicolore","p":"adj.","cn":"多色的、五颜六色的","ex":"Les façades multicolores de ce petit port de pêche font le bonheur des photographes.","exCn":"这个小渔港五颜六色的房屋外墙让摄影爱好者们大饱眼福。","th":"常用词"},{"w":"multimédia","p":"n.m.","cn":"多媒体","ex":"Il travaille dans le secteur du multimédia.","exCn":"他在多媒体行业工作。","th":"社会与新闻"},{"w":"multiple","p":"adj.","cn":"多次的、众多的；多种的、多项的","ex":"Malgré de multiples relances, l'entreprise ne m'a jamais remboursé.","exCn":"虽然我多次催促，公司还是一直没给我退款。","th":"常用词"},{"w":"multiplier","p":"v.","cn":"大量增加、增多；（数学）乘","ex":"Le gouvernement multiplie les mesures contre la pollution.","exCn":"政府不断出台治理污染的措施。","th":"描述与状态"},{"w":"municipal","p":"adj.","cn":"市政的、市镇的","ex":"Les taxes municipales ont encore augmenté cette année.","exCn":"今年市政税又涨了。","th":"常用词"},{"w":"murmurer","p":"v.","cn":"低声说、喃喃地说","ex":"« Je suis désolé », a-t-il murmuré en baissant les yeux.","exCn":"“对不起。”他垂下眼睛，低声说道。","th":"描述与状态"},{"w":"muscler","p":"v.","cn":"锻炼（某部位的）肌肉；（se ~）锻炼肌肉、练肌肉；（喻）加强","ex":"Je fais du sport pour me muscler.","exCn":"我运动是为了练肌肉。","th":"饮食"},{"w":"musculation","p":"n.f.","cn":"力量训练、健身","ex":"Il fait de la musculation trois fois par semaine.","exCn":"他每周做三次力量训练。","th":"常用词"},{"w":"musulman","p":"n.","cn":"穆斯林；穆斯林的、伊斯兰教的","ex":"Un musulman pratiquant prie cinq fois par jour.","exCn":"虔诚的穆斯林每天祈祷五次。","th":"常用词"},{"w":"mystère","p":"n.m.","cn":"神秘、谜","ex":"La disparition du tableau reste un mystère pour la police.","exCn":"那幅画是怎么失踪的，对警方来说仍是个谜。","th":"常用词"},{"w":"mystérieux","p":"adj.","cn":"神秘的","ex":"Un homme mystérieux a laissé une lettre à la réception de l'hôtel.","exCn":"一个神秘男子在酒店前台留下了一封信。","th":"常用词"},{"w":"mécanique","p":"n.f.","cn":"机械的；力学；机械学、机械","ex":"Le train est en retard à cause d'un problème mécanique.","exCn":"火车因机械故障晚点了。","th":"常用词"},{"w":"mécontent","p":"adj.","cn":"不满的、不满意的","ex":"Mon chef était mécontent de mon rapport et m'a demandé de le refaire.","exCn":"老板对我的报告不满意，让我重写一份。","th":"描述与状态"},{"w":"médaille","p":"n.f.","cn":"奖牌、勋章","ex":"Tous les participants du marathon reçoivent une médaille à l'arrivée, peu importe leur temps.","exCn":"所有马拉松参赛者跑到终点都能领到一枚奖牌，不论成绩如何。","th":"常用词"},{"w":"média","p":"n.m.","cn":"媒体、传媒","ex":"Les grands médias nationaux ont beaucoup parlé de cette affaire.","exCn":"全国各大媒体都对这起事件做了大量报道。","th":"社会与新闻"},{"w":"méditerranéen","p":"adj.","cn":"地中海的","ex":"Le régime méditerranéen est réputé bon pour la santé.","exCn":"地中海饮食被认为有益健康。","th":"居住与环境"},{"w":"médiéval","p":"adj.","cn":"中世纪的","ex":"Nous avons visité un château médiéval en Dordogne.","exCn":"我们参观了多尔多涅的一座中世纪城堡。","th":"时间与数量"},{"w":"mélange","p":"n.m.","cn":"混合物；混合","ex":"La population de Montréal est un mélange de cultures venues du monde entier.","exCn":"蒙特利尔的人口融合了来自世界各地的文化。","th":"常用词"},{"w":"mélangé","p":"adj.","cn":"混合的、掺杂的","ex":"Le public était très mélangé : des étudiants, des familles et des retraités.","exCn":"观众成分很杂：有学生，有一家老小，还有退休老人。","th":"常用词"},{"w":"mélodie","p":"n.f.","cn":"旋律、曲调","ex":"Je n'arrive pas à me sortir cette mélodie de la tête.","exCn":"这段旋律一直在我脑子里挥之不去。","th":"常用词"},{"w":"mémoire","p":"n.f.","cn":"记忆、记忆力；（电脑）内存；cf. le mémoire = 学位论文；les mémoires = 回忆录","ex":"Avec l'âge, ma grand-mère commence à perdre la mémoire.","exCn":"奶奶上了年纪，记性开始变差了。","th":"常用词"},{"w":"ménager","p":"v.","cn":"节省、爱惜（体力等）；家务的、家用的","ex":"Après l'opération, le médecin lui a conseillé de ménager ses forces.","exCn":"手术后，医生建议他节省体力，别太劳累。","th":"情绪与性格"},{"w":"mériter","p":"v.","cn":"应得、值得","ex":"Après tous ces efforts, tu mérites bien quelques jours de repos.","exCn":"付出了这么多努力，你理应好好休息几天。","th":"常用词"},{"w":"métal","p":"n.m.","cn":"金属","ex":"Le cuivre est un métal qui conduit très bien l'électricité.","exCn":"铜是一种导电性能很好的金属。","th":"常用词"},{"w":"métallique","p":"adj.","cn":"金属的、金属制的；（声音、颜色）金属般的","ex":"Rangez les dossiers confidentiels dans l'armoire métallique du bureau.","exCn":"把机密文件放进办公室的金属柜里。","th":"描述与状态"},{"w":"méthode","p":"n.f.","cn":"方法、方式；（语言）教材","ex":"Cette nouvelle méthode de travail nous fait gagner beaucoup de temps.","exCn":"这种新的工作方法为我们节省了很多时间。","th":"抽象与概念"},{"w":"métropole","p":"n.f.","cn":"大都市；（la ~）法国本土","ex":"Montréal est la deuxième plus grande métropole du Canada.","exCn":"蒙特利尔是加拿大第二大都市。","th":"描述与状态"},{"w":"mûr","p":"adj.","cn":"（果实）熟的；（人）成熟的","ex":"Ces tomates ne sont pas encore assez mûres pour être cueillies.","exCn":"这些西红柿还不够熟，还不能摘。","th":"人物与身份"},{"w":"nage","p":"n.f.","cn":"游泳、泳姿；（en ~）满身大汗","ex":"Il a traversé la rivière à la nage.","exCn":"他游泳横渡了那条河。","th":"描述与状态"},{"w":"nageur","p":"n.","cn":"游泳者、游泳运动员","ex":"À cause de l'orage, le sauveteur a demandé à tous les nageurs de sortir de l'eau.","exCn":"因为有雷雨，救生员让所有游泳的人都上岸。","th":"常用词"},{"w":"nappe","p":"n.f.","cn":"桌布；（水、油、雾等）一片、一层","ex":"Mets une nappe propre sur la table.","exCn":"在桌上铺一块干净的桌布。","th":"常用词"},{"w":"natal","p":"adj.","cn":"出生的、故乡的","ex":"Après sa retraite, il est retourné vivre dans son village natal.","exCn":"退休后，他回到了家乡的村子生活。","th":"常用词"},{"w":"nation","p":"n.f.","cn":"国家；民族","ex":"Le Canada est une nation multiculturelle et bilingue.","exCn":"加拿大是一个多元文化的双语国家。","th":"常用词"},{"w":"nausée","p":"n.f.","cn":"恶心、反胃；（比喻）厌恶","ex":"Le matin, les femmes enceintes ont souvent la nausée.","exCn":"孕妇早上常常会恶心。","th":"常用词"},{"w":"navette","p":"n.f.","cn":"班车；cf. faire la navette 往返奔波、来回跑","ex":"L'hôtel met une navette à la disposition de ses clients pour aller à la plage.","exCn":"酒店为住客提供去海滩的班车。","th":"出行与旅行"},{"w":"naviguer","p":"v.","cn":"航行；（在网上）浏览","ex":"Nous avons navigué sur le Saint-Laurent jusqu'à Tadoussac pour voir les baleines.","exCn":"我们沿着圣劳伦斯河一路航行到塔杜萨克去看鲸鱼。","th":"常用词"},{"w":"naïf","p":"adj.","cn":"天真的、单纯的；轻信的、幼稚的","ex":"Il a été assez naïf pour prêter de l'argent à un inconnu.","exCn":"他竟然天真到把钱借给一个陌生人。","th":"时间与数量"},{"w":"nerf","p":"n.m.","cn":"神经；（复数）情绪、精神状态；活力、劲头；cf. taper sur les nerfs 让人心烦；perdre ses nerfs 失去冷静","ex":"Le nerf optique transmet les images au cerveau.","exCn":"视神经把图像传送到大脑。","th":"人物与身份"},{"w":"net","p":"adj.","cn":"明显的、清楚的；（金额、重量）净的","ex":"On constate une nette amélioration de la situation.","exCn":"情况有了明显好转。","th":"描述与状态"},{"w":"nettoyage","p":"n.m.","cn":"清洁、打扫；cf. le nettoyage à sec 干洗","ex":"Le grand nettoyage de printemps nous a pris deux jours.","exCn":"春季大扫除花了我们两天时间。","th":"日常动作"},{"w":"nid","p":"n.m.","cn":"巢、窝；cf. le nid-de-poule 路面坑洼","ex":"Les enfants ont trouvé un nid avec trois œufs dans la haie.","exCn":"孩子们在树篱里发现了一个有三个蛋的鸟窝。","th":"出行与旅行"},{"w":"noble","p":"n.","cn":"高尚的、崇高的；贵族的；贵族","ex":"Elle a consacré sa vie à une noble cause : l'éducation des filles.","exCn":"她把一生献给了一项崇高的事业：女童教育。","th":"购物与金钱"},{"w":"nocturne","p":"n.f.","cn":"夜间的；（动物）夜行的；（商店、博物馆）夜间开放；夜场","ex":"Les chauves-souris sont des animaux nocturnes qui se nourrissent d'insectes.","exCn":"蝙蝠是夜行动物，以昆虫为食。","th":"购物与金钱"},{"w":"noisette","p":"n.f.","cn":"榛子；（黄油等）一小块","ex":"J'adore le chocolat aux noisettes.","exCn":"我超爱榛子巧克力。","th":"描述与状态"},{"w":"nommer","p":"v.","cn":"任命；命名、称呼","ex":"Il a été nommé ambassadeur au Japon.","exCn":"他被任命为驻日本大使。","th":"交际与礼貌"},{"w":"nostalgie","p":"n.f.","cn":"怀旧、怀念；思乡（之情）","ex":"Elle regarde ses photos d'enfance avec nostalgie.","exCn":"她带着怀旧之情翻看童年的照片。","th":"描述与状态"},{"w":"notamment","p":"adv.","cn":"尤其；其中包括","ex":"Certains secteurs, notamment la santé, recrutent.","exCn":"有些行业，尤其是医疗，在招人。","th":"观点与论证"},{"w":"nourrir","p":"v.","cn":"喂养、养育、滋养","ex":"Les oiseaux nourrissent leurs petits plusieurs fois par heure.","exCn":"鸟一个小时要喂好几次幼鸟。","th":"常用词"},{"w":"nouveauté","p":"n.f.","cn":"新事物、新产品；新颖、新奇","ex":"Ce salon présente toutes les nouveautés de l'année.","exCn":"这个展会展出了今年所有的新产品。","th":"描述与状态"},{"w":"noyer","p":"v.","cn":"（se ~）淹死、溺水；淹没、使淹死","ex":"Un enfant a failli se noyer dans la piscine municipale.","exCn":"一个孩子差点在市立游泳池溺水。","th":"常用词"},{"w":"nu","p":"adj.","cn":"裸的、光着的；（à l'œil ~）肉眼；空荡的、无装饰的","ex":"Les enfants courent pieds nus sur la plage.","exCn":"孩子们光着脚在沙滩上跑。","th":"饮食"},{"w":"nucléaire","p":"adj.","cn":"核的、核能的","ex":"La France tire l'essentiel de son électricité de l'énergie nucléaire.","exCn":"法国的电力主要来自核能。","th":"常用词"},{"w":"numérique","p":"adj.","cn":"数字的、数码的；数量上的","ex":"J'ai acheté un appareil photo numérique.","exCn":"我买了一台数码相机。","th":"时间与数量"},{"w":"nécessairement","p":"adv.","cn":"必然、一定","ex":"Le plus cher n'est pas nécessairement le meilleur.","exCn":"最贵的不一定是最好的。","th":"常用词"},{"w":"nécessité","p":"n.f.","cn":"必要性；需要、需求","ex":"Le ministre a souligné la nécessité de construire davantage de logements sociaux.","exCn":"部长强调了建造更多社会住房的必要性。","th":"抽象与概念"},{"w":"négatif","p":"adj.","cn":"形容词；阳性 m. / 阴性 f.；négatif / négative；négatifs / négatives；负面的、消极的；否定的；（检测结果）阴性的","ex":"Le stress a des effets négatifs sur le sommeil.","exCn":"压力会对睡眠产生负面影响。","th":"抽象与概念"},{"w":"négociation","p":"n.f.","cn":"谈判、协商","ex":"Après une longue négociation, nous avons obtenu un loyer plus bas.","exCn":"经过长时间的协商，我们争取到了更低的房租。","th":"常用词"},{"w":"négocier","p":"v.","cn":"谈判、协商","ex":"Les deux pays négocient un cessez-le-feu.","exCn":"两国正在就停火进行谈判。","th":"常用词"},{"w":"nôtre","p":"pron.","cn":"我们的（那个、那些）","ex":"Leur jardin est deux fois plus grand que le nôtre.","exCn":"他们家的花园比我们的大一倍。","th":"常用词"},{"w":"objectif","p":"n.m.","cn":"目标；（相机的）镜头；客观的","ex":"Notre objectif principal est de réduire nos déchets de moitié d'ici 2030.","exCn":"我们的主要目标是到2030年把垃圾量减少一半。","th":"常用词"},{"w":"obligation","p":"n.f.","cn":"义务、责任","ex":"C'est une obligation légale de déclarer ses revenus chaque année.","exCn":"每年申报收入是一项法定义务。","th":"常用词"},{"w":"observer","p":"v.","cn":"观察；注意到、发现；遵守（规定）、保持（~ une minute de silence 默哀一分钟）","ex":"Les scientifiques observent le comportement des baleines dans le Saint-Laurent.","exCn":"科学家们在圣劳伦斯河观察鲸鱼的行为。","th":"时间与数量"},{"w":"obstacle","p":"n.m.","cn":"障碍、阻碍","ex":"En hiver, les trottoirs mal déneigés sont un véritable obstacle pour les personnes en fauteuil roulant.","exCn":"冬天，没铲干净雪的人行道对坐轮椅的人来说是实实在在的障碍。","th":"常用词"},{"w":"obéir","p":"v.","cn":"服从、听从","ex":"Tu dois obéir à tes parents.","exCn":"你必须听父母的话。","th":"常用词"},{"w":"occidental","p":"adj.","cn":"西方的；西部的","ex":"La musique occidentale est enseignée dans la plupart des conservatoires chinois.","exCn":"中国大多数音乐学院都教授西方音乐。","th":"常用词"},{"w":"officiel","p":"adj.","cn":"官方的、正式的","ex":"Le résultat officiel de l'élection sera annoncé demain matin.","exCn":"选举的正式结果将于明天上午公布。","th":"常用词"},{"w":"officiellement","p":"adv.","cn":"正式地、官方地","ex":"Le nouveau pont sera officiellement inauguré le mois prochain.","exCn":"新大桥将于下个月正式启用。","th":"常用词"},{"w":"offre","p":"n.f.","cn":"提议、报价；（商家的）优惠（如 ~ spéciale 特价）；（经济）供给","ex":"J'ai reçu une offre d'emploi d'une entreprise de Montréal.","exCn":"我收到了蒙特利尔一家公司的工作邀约。","th":"购物与金钱"},{"w":"olympique","p":"adj.","cn":"奥林匹克的、奥运的","ex":"Notre ville vient d'inaugurer une piscine olympique toute neuve.","exCn":"我们市刚落成了一座全新的奥运标准游泳池。","th":"常用词"},{"w":"ombre","p":"n.f.","cn":"阴影处、影子","ex":"Il fait 35 degrés, allons nous asseoir à l'ombre.","exCn":"气温35度，我们去阴凉处坐坐吧。","th":"常用词"},{"w":"ongle","p":"n.m.","cn":"指甲","ex":"Elle s'est cassé un ongle en ouvrant un carton de déménagement.","exCn":"她拆搬家纸箱时弄断了一片指甲。","th":"常用词"},{"w":"opinion","p":"n.f.","cn":"意见、看法；舆论","ex":"Elle a une opinion très positive du télétravail.","exCn":"她对远程办公的看法非常正面。","th":"观点与论证"},{"w":"opposer","p":"v.","cn":"（s'~ à）反对；使对立、使对抗","ex":"Les habitants se sont opposés à la construction d'une nouvelle autoroute.","exCn":"居民们反对修建新的高速公路。","th":"观点与论证"},{"w":"optimisme","p":"n.m.","cn":"乐观、乐观主义","ex":"Malgré la crise, le ministre affiche un optimisme prudent.","exCn":"尽管身处危机，部长仍表现出谨慎的乐观。","th":"情绪与性格"},{"w":"option","p":"n.f.","cn":"选项","ex":"Dans les paramètres, activez l'option « mode sombre » pour moins fatiguer vos yeux le soir.","exCn":"在设置里开启“深色模式”选项，晚上眼睛就不那么累了。","th":"常用词"},{"w":"opérateur","p":"n.","cn":"（电信等）运营商；操作员","ex":"Mon opérateur a coupé ma ligne parce que j'avais oublié de payer la facture.","exCn":"我忘了交话费，运营商就把我的线路停了。","th":"常用词"},{"w":"opération","p":"n.f.","cn":"行动；手术；（银行）交易、业务；运算","ex":"Ma mère a subi une opération du genou et doit rester trois jours à l'hôpital.","exCn":"我母亲做了膝盖手术，需要住院三天。","th":"健康与身体"},{"w":"opérer","p":"v.","cn":"给…动手术；实施、进行","ex":"Ma fille doit se faire opérer des amygdales le mois prochain.","exCn":"我女儿下个月要做扁桃体手术。","th":"健康与身体"},{"w":"orageux","p":"adj.","cn":"有雷雨的；（讨论、关系）激烈的、动荡的","ex":"Le temps sera orageux en fin de journée.","exCn":"傍晚会有雷雨天气。","th":"居住与环境"},{"w":"oral","p":"n.m.","cn":"口头的、口语的；口试","ex":"L'examen comporte une partie écrite et une partie orale.","exCn":"考试包括笔试和口试两部分。","th":"常用词"},{"w":"orchestre","p":"n.m.","cn":"管弦乐队","ex":"L'orchestre a joué une valse et tout le monde s'est mis à danser.","exCn":"乐队奏起了华尔兹，大家都跳起舞来。","th":"常用词"},{"w":"ordinaire","p":"n.m.","cn":"普通的、平常的；差劲的、不厚道的（魁北克口语）；平常、寻常；（d'~）通常","ex":"Ce n'était pas une journée ordinaire : il neigeait en plein mois de mai.","exCn":"那可不是寻常的一天：五月里居然下起了雪。","th":"常用词"},{"w":"ordure","p":"n.f.","cn":"（多用复数）垃圾；（骂人）混蛋、人渣（粗俗）","ex":"Tu peux descendre les ordures en partant ? La poubelle de la cuisine est pleine.","exCn":"你出门时能顺便把垃圾拿下去吗？厨房的垃圾桶满了。","th":"人物与身份"},{"w":"organisme","p":"n.m.","cn":"机构、组织；机体、生物体","ex":"Cet organisme sans but lucratif rend visite aux personnes âgées isolées.","exCn":"这家非营利机构定期探望独居老人。","th":"社会与新闻"},{"w":"orientation","p":"n.f.","cn":"方向、取向；（升学、就业）指导","ex":"J'ai un très mauvais sens de l'orientation : je me perds même avec un GPS.","exCn":"我方向感特别差，就算开着导航也会迷路。","th":"常用词"},{"w":"originaire","p":"adj.","cn":"（~ de）出生于…的、原产于…的","ex":"Ma voisine est originaire du Sénégal, mais elle vit à Québec depuis vingt ans.","exCn":"我的女邻居原籍塞内加尔，不过她已经在魁北克城住了二十年。","th":"常用词"},{"w":"originalité","p":"n.f.","cn":"新颖、独创性；独特之处","ex":"Le jury a récompensé ce projet pour son originalité et son faible coût.","exCn":"这个项目新颖且成本低，因此获得了评委会的嘉奖。","th":"描述与状态"},{"w":"orphelin","p":"n.","cn":"孤儿；失去父母（或其中一方）的","ex":"Cet orphelin a été adopté par une famille de Québec.","exCn":"这个孤儿被魁北克城的一户人家收养了。","th":"人物与身份"},{"w":"orteil","p":"n.m.","cn":"脚趾","ex":"Je me suis cogné le petit orteil contre le pied du lit.","exCn":"我的小脚趾撞到了床脚上。","th":"常用词"},{"w":"os","p":"n.m.","cn":"骨头；复数 les os 传统读 /o/，现在也常读 /ɔs/","ex":"Après sa chute, la radio a montré qu'aucun os n'était cassé.","exCn":"摔倒后拍了片子，没有骨折。","th":"时间与数量"},{"w":"oser","p":"v.","cn":"敢、敢于","ex":"Comment oses-tu me parler sur ce ton ?","exCn":"你怎么敢用这种口气跟我说话？","th":"常用词"},{"w":"ovale","p":"adj.","cn":"椭圆形的","ex":"Elle a un visage ovale, donc presque toutes les coiffures lui vont.","exCn":"她是鹅蛋脸，所以几乎什么发型都适合她。","th":"常用词"},{"w":"oxygène","p":"n.m.","cn":"氧气、氧；（喻）喘息之机、新的活力","ex":"Les arbres produisent de l'oxygène grâce à la photosynthèse.","exCn":"树木通过光合作用产生氧气。","th":"描述与状态"},{"w":"pack","p":"n.m.","cn":"（饮料等）一提、一组；（产品、服务）套装","ex":"Tu peux monter le pack d'eau ? Il est resté dans le coffre de la voiture.","exCn":"你能把那提水搬上来吗？还在车后备箱里呢。","th":"常用词"},{"w":"paie","p":"n.f.","cn":"工资、薪水；cf. 也写作 la paye","ex":"Je reçois ma paie toutes les deux semaines.","exCn":"我每两周领一次工资。","th":"工作与学习"},{"w":"paiement","p":"n.m.","cn":"付款、支付","ex":"Le paiement du loyer doit se faire au plus tard le premier jour du mois.","exCn":"房租最迟须在每月第一天支付。","th":"购物与金钱"},{"w":"paille","p":"n.f.","cn":"稻草、麦秆；吸管","ex":"Dans l'étable, les vaches se couchent sur de la paille fraîche.","exCn":"牛棚里，奶牛躺在新铺的稻草上。","th":"常用词"},{"w":"palais","p":"n.m.","cn":"宫殿；上颚；cf. palais de justice 法院；palais des congrès 会议中心","ex":"Les touristes font la queue devant le palais royal pour voir la relève de la garde.","exCn":"游客们在王宫前排队观看卫兵换岗。","th":"工作与学习"},{"w":"palmier","p":"n.m.","cn":"棕榈树；（点心）蝴蝶酥","ex":"Il rêve de passer l'hiver sous les palmiers, loin de la neige.","exCn":"他梦想着去棕榈树下过冬，远离冰天雪地。","th":"居住与环境"},{"w":"panique","p":"n.f.","cn":"恐慌、惊慌","ex":"Pas de panique : il nous reste encore deux heures avant le départ du train.","exCn":"别慌：离火车开车还有两个小时呢。","th":"常用词"},{"w":"paniquer","p":"v.","cn":"惊慌、恐慌","ex":"Il n'y a pas de quoi paniquer, le vol est simplement retardé.","exCn":"没什么好慌的，航班只是延误了。","th":"常用词"},{"w":"panorama","p":"n.m.","cn":"全景；（比喻）概况、综述","ex":"Depuis la terrasse, on profite d'un panorama exceptionnel sur le fleuve Saint-Laurent.","exCn":"从露台上可以饱览圣劳伦斯河的绝佳全景。","th":"常用词"},{"w":"pansement","p":"n.m.","cn":"敷料、绷带；创可贴；cf.（魁北克）le diachylon 创可贴","ex":"L'infirmière doit changer le pansement deux fois par jour pour éviter toute infection.","exCn":"护士每天要换两次敷料，以防感染。","th":"常用词"},{"w":"pantoufle","p":"n.f.","cn":"（室内）拖鞋","ex":"À la maison, je mets toujours mes vieilles pantoufles.","exCn":"在家里我总是穿那双旧拖鞋。","th":"居住与环境"},{"w":"pape","p":"n.m.","cn":"教皇","ex":"Des milliers de fidèles se sont rassemblés sur la place Saint-Pierre pour écouter le pape.","exCn":"数千名信徒聚集在圣彼得广场，聆听教皇讲话。","th":"常用词"},{"w":"par exemple","p":"loc.","cn":"例如","ex":"Certains métiers, par exemple la santé, recrutent beaucoup.","exCn":"有些行业，比如医疗，招人很多。","th":"观点与论证"},{"w":"par-dessus","p":"prép.","cn":"越过、从…上方；在…外面（加穿、加盖）；cf. par-dessus tout 尤其、最重要的是；en avoir par-dessus la tête 受够了（口语）","ex":"Le chat a sauté par-dessus le mur.","exCn":"猫跳过了墙。","th":"抽象与概念"},{"w":"paradis","p":"n.m.","cn":"天堂；乐园；cf. le paradis fiscal 避税天堂","ex":"Ma grand-mère croyait que les gens généreux allaient au paradis.","exCn":"我奶奶相信，慷慨的人会上天堂。","th":"时间与数量"},{"w":"paragraphe","p":"n.m.","cn":"段落","ex":"Il faut aller à la ligne au début de chaque paragraphe.","exCn":"每个段落开头都要另起一行。","th":"常用词"},{"w":"parasol","p":"n.m.","cn":"遮阳伞","ex":"On a installé un parasol sur la plage.","exCn":"我们在海滩上撑了一把遮阳伞。","th":"常用词"},{"w":"paraître","p":"v.","cn":"似乎、显得；出版、问世；（il paraît que）据说、听说","ex":"Elle paraît beaucoup plus jeune que son âge.","exCn":"她看起来比实际年龄年轻得多。","th":"常用词"},{"w":"parcourir","p":"v.","cn":"走遍、走过（路程）；浏览、翻阅","ex":"Ce cycliste a parcouru plus de 3 000 kilomètres à travers le Canada.","exCn":"这位骑行者横穿加拿大，骑了三千多公里。","th":"出行与旅行"},{"w":"parcours","p":"n.m.","cn":"路线、行程；（学习、职业的）经历","ex":"Le parcours du marathon passe par le centre-ville.","exCn":"马拉松的路线经过市中心。","th":"出行与旅行"},{"w":"pardonner","p":"v.","cn":"原谅、宽恕","ex":"Elle ne lui a jamais pardonné son mensonge.","exCn":"她始终没有原谅他撒的谎。","th":"描述与状态"},{"w":"parfumerie","p":"n.f.","cn":"香水店、美妆店；香水业","ex":"Je lui ai acheté un cadeau à la parfumerie.","exCn":"我在香水店给她买了一份礼物。","th":"常用词"},{"w":"parier","p":"v.","cn":"打赌、下注","ex":"Je te parie qu'il va encore arriver en retard.","exCn":"我跟你打赌，他又会迟到。","th":"常用词"},{"w":"parlement","p":"n.m.","cn":"议会、国会","ex":"La bibliothèque du Parlement, à Ottawa, a échappé au grand incendie de 1916.","exCn":"位于渥太华的国会图书馆在1916年的大火中幸免于难。","th":"常用词"},{"w":"parmi","p":"prép.","cn":"在…之中","ex":"Parmi tous les candidats, c'est elle qui a le plus d'expérience.","exCn":"在所有候选人中，她的经验最丰富。","th":"常用词"},{"w":"parole","p":"n.f.","cn":"言语、说话能力；发言权（prendre la ~ 发言）；诺言；（复数）歌词","ex":"Le maire a pris la parole au début de la réunion.","exCn":"市长在会议开始时发言了。","th":"抽象与概念"},{"w":"partage","p":"n.m.","cn":"分享、分配、分担","ex":"Pour moi, l'amitié, c'est avant tout le partage.","exCn":"对我来说，友谊首先就是分享。","th":"常用词"},{"w":"partant","p":"n.","cn":"（être ~ pour）愿意参加的、乐意的（口语）；参赛者","ex":"Le premier partant prendra le départ à huit heures précises.","exCn":"第一位参赛者将于八点整出发。","th":"常用词"},{"w":"partenaire","p":"n.","cn":"合作伙伴、搭档；（生活）伴侣","ex":"Notre entreprise cherche un partenaire pour se développer en Europe.","exCn":"我们公司正在寻找合作伙伴，以便拓展欧洲市场。","th":"常用词"},{"w":"parti","p":"n.m.","cn":"政党；（prendre ~）表明立场、偏袒一方；cf. tirer parti de 利用","ex":"Elle est membre d'un parti de gauche.","exCn":"她是一个左翼政党的成员。","th":"观点与论证"},{"w":"participation","p":"n.f.","cn":"参与、参加；出资、股份","ex":"Le taux de participation aux dernières élections municipales était très faible.","exCn":"上次市政选举的投票率非常低。","th":"常用词"},{"w":"particularité","p":"n.f.","cn":"特点、特色、特殊性","ex":"La particularité de ce quartier, c'est son marché ouvert toute l'année.","exCn":"这个街区的特色是它全年开放的集市。","th":"抽象与概念"},{"w":"particulier","p":"adj.","cn":"特别的、特定的；私人的、个人的；cf. en particulier 尤其、特别是；un particulier（相对于企业、机构的）个人、私人","ex":"Ce fromage a un goût très particulier que tout le monde n'apprécie pas.","exCn":"这种奶酪的味道很特别，不是人人都喜欢。","th":"人物与身份"},{"w":"particulièrement","p":"adv.","cn":"特别、尤其","ex":"Cet hiver a été particulièrement froid à Montréal.","exCn":"今年冬天蒙特利尔特别冷。","th":"常用词"},{"w":"parvenir","p":"v.","cn":"（~ à）成功做到、达成；到达、（信件等）送达","ex":"Elle est enfin parvenue à trouver un emploi dans son domaine.","exCn":"她终于在自己的专业领域找到了工作。","th":"出行与旅行"},{"w":"passant","p":"n.","cn":"行人、路人；（街道）行人多的、热闹的；cf. en passant 顺便（说一句）","ex":"Un passant a appelé les secours après avoir vu l'accident.","exCn":"一位路人看到事故后叫了急救。","th":"出行与旅行"},{"w":"passionner","p":"v.","cn":"使着迷、使很感兴趣；（se ~ pour）热衷于","ex":"L'histoire de la Nouvelle-France passionne mon fils depuis qu'il a visité la ville de Québec.","exCn":"自从去过魁北克城，我儿子就迷上了新法兰西的历史。","th":"居住与环境"},{"w":"patate","p":"n.f.","cn":"土豆（口语；魁北克为日常通用词）；（~ douce）红薯；cf. avoir la patate 精力充沛（口语）","ex":"Ce soir, je fais un pâté chinois avec du bœuf haché, du maïs et des patates.","exCn":"今晚我做 pâté chinois，用牛肉末、玉米和土豆。","th":"描述与状态"},{"w":"paternel","p":"adj.","cn":"父亲的、父爱的；父系的","ex":"Il n'a jamais connu l'amour paternel.","exCn":"他从没感受过父爱。","th":"情绪与性格"},{"w":"patiemment","p":"adv.","cn":"耐心地","ex":"Avant l'ouverture, les clients attendaient patiemment devant la boulangerie.","exCn":"开门前，顾客们在面包店门口耐心地等着。","th":"情绪与性格"},{"w":"patinage","p":"n.m.","cn":"滑冰","ex":"Ma fille fait du patinage artistique.","exCn":"我女儿练花样滑冰。","th":"常用词"},{"w":"patiner","p":"v.","cn":"滑冰；（车轮）打滑、空转","ex":"Elle patine depuis l'âge de quatre ans.","exCn":"她从四岁起就开始滑冰。","th":"出行与旅行"},{"w":"patineur","p":"n.","cn":"滑冰者、滑冰运动员","ex":"Chaque hiver, des milliers de patineurs glissent sur le canal Rideau, à Ottawa.","exCn":"每年冬天，成千上万的滑冰者在渥太华的丽都运河上滑冰。","th":"常用词"},{"w":"patinoire","p":"n.f.","cn":"滑冰场、溜冰场","ex":"Samedi, on va à la patinoire avec les enfants.","exCn":"周六我们带孩子们去滑冰场。","th":"常用词"},{"w":"patrimoine","p":"n.m.","cn":"（文化、自然）遗产；财产、家产","ex":"Le Vieux-Québec est inscrit au patrimoine mondial de l'UNESCO.","exCn":"魁北克老城被列入了联合国教科文组织的世界遗产名录。","th":"居住与环境"},{"w":"patte","p":"n.f.","cn":"（动物的）腿、爪子；（口语）人的腿、手；cf. à quatre pattes 四肢着地、爬着","ex":"Le chat s'est assis et a commencé à se lécher les pattes.","exCn":"猫坐下来开始舔爪子。","th":"人物与身份"},{"w":"pauvreté","p":"n.f.","cn":"贫穷、贫困；贫乏","ex":"La pauvreté a reculé dans la région grâce à la création d'emplois.","exCn":"由于创造了就业机会，这一地区的贫困有所减少。","th":"常用词"},{"w":"paysan","p":"n.","cn":"农民","ex":"Le paysan vend ses légumes au marché du village chaque samedi.","exCn":"那位农民每周六都在村里的集市上卖菜。","th":"常用词"},{"w":"payé","p":"adj.","cn":"有报酬的、带薪的；已付款的","ex":"Ce travail est bien payé, mais très fatigant.","exCn":"这份工作报酬高，但很累。","th":"购物与金钱"},{"w":"peine","p":"n.f.","cn":"痛苦、悲伤；辛苦、麻烦；刑罚；cf. ce n'est pas la peine 不必、用不着；ça vaut la peine 值得；à peine 几乎不、刚刚","ex":"Le conducteur ivre a écopé d'une peine de six mois de prison avec sursis.","exCn":"那名醉驾司机被判处六个月监禁，缓期执行。","th":"健康与身体"},{"w":"peint","p":"adj.","cn":"上了漆的、粉刷过的；（手）绘的","ex":"La porte d'entrée est peinte en bleu.","exCn":"大门漆成了蓝色。","th":"常用词"},{"w":"pelle","p":"n.f.","cn":"铲子、铁锹","ex":"Après la tempête de neige, il a pris une pelle pour dégager l'entrée du garage.","exCn":"暴风雪过后，他拿起铲子清理车库门口的积雪。","th":"常用词"},{"w":"pelouse","p":"n.f.","cn":"草坪、草地；cf. le gazon 草坪（魁北克更常用）","ex":"Avec la canicule, la pelouse est devenue toute jaune.","exCn":"热浪持续，草坪全都枯黄了。","th":"常用词"},{"w":"pencher","p":"v.","cn":"倾斜、使倾斜；（se ~）俯身、弯腰；（se ~ sur）研究、关注（问题）；（~ pour）倾向于（某选择）","ex":"Ce vieux mur penche dangereusement vers la rue.","exCn":"这堵老墙朝街道倾斜得很危险。","th":"工作与学习"},{"w":"pensée","p":"n.f.","cn":"想法、念头；思想","ex":"Elle était perdue dans ses pensées.","exCn":"她陷入了沉思。","th":"常用词"},{"w":"pente","p":"n.f.","cn":"斜坡、坡度","ex":"En hiver, cette rue en forte pente devient très glissante.","exCn":"冬天，这条陡坡路会变得非常滑。","th":"常用词"},{"w":"perdant","p":"n.","cn":"输家、失败者","ex":"Il est mauvais perdant : il se fâche chaque fois qu'il perd aux cartes.","exCn":"他输不起：每次打牌输了都会发脾气。","th":"常用词"},{"w":"perfectionner","p":"v.","cn":"完善、改进；（se ~ en）进修、提高（某方面）","ex":"L'équipe a perfectionné l'application grâce aux commentaires des utilisateurs.","exCn":"团队根据用户的反馈完善了这个应用。","th":"描述与状态"},{"w":"perfectionniste","p":"adj.","cn":"追求完美的、完美主义的","ex":"Elle est très perfectionniste : elle refait son gâteau jusqu'à ce qu'il soit parfait.","exCn":"她特别追求完美，蛋糕要一遍遍重做，直到满意为止。","th":"常用词"},{"w":"perle","p":"n.f.","cn":"珍珠；（比喻）瑰宝、难得的人才","ex":"Pour leurs trente ans de mariage, il lui a offert un collier de perles.","exCn":"结婚三十周年时，他送了她一条珍珠项链。","th":"人物与身份"},{"w":"permanence","p":"n.f.","cn":"持久、永久性；值班、接待（时间）；（en ~）一直、不断","ex":"La députée tient une permanence tous les vendredis matin pour rencontrer les habitants.","exCn":"这位女议员每周五上午设接待时间，会见本区居民。","th":"时间与数量"},{"w":"permanent","p":"adj.","cn":"永久的、持续的；cf. la résidence permanente 永久居留权（加拿大）","ex":"Le musée propose une exposition permanente consacrée à l'histoire de la ville.","exCn":"这家博物馆设有一个介绍城市历史的常设展览。","th":"描述与状态"},{"w":"permission","p":"n.f.","cn":"允许、许可","ex":"Le soir du Nouvel An, les enfants ont la permission de rester debout jusqu'à minuit.","exCn":"除夕夜，孩子们可以熬到半夜才睡。","th":"常用词"},{"w":"personnalité","p":"n.f.","cn":"个性、性格；知名人士","ex":"Ces deux sœurs ont des personnalités complètement opposées : l'une est timide, l'autre très bavarde.","exCn":"这对姐妹性格完全相反：一个害羞，一个话很多。","th":"情绪与性格"},{"w":"perspective","p":"n.f.","cn":"（复数）前景、前途；（~ de）对…的预期、想到…；视角、角度","ex":"Ce secteur offre de bonnes perspectives d'emploi pour les jeunes diplômés.","exCn":"这个行业给应届毕业生提供了很好的就业前景。","th":"常用词"},{"w":"persuader","p":"v.","cn":"说服、劝服；（être persuadé que）确信","ex":"J'ai fini par persuader mes parents de me laisser étudier au Canada.","exCn":"我最终说服了父母让我去加拿大留学。","th":"常用词"},{"w":"perte","p":"n.f.","cn":"失去、丧失；损失、亏损；（复数）伤亡","ex":"Cette réunion était une vraie perte de temps : rien n'a été décidé.","exCn":"这次会开得纯属浪费时间：什么都没定下来。","th":"健康与身体"},{"w":"pesticide","p":"n.m.","cn":"农药、杀虫剂","ex":"Ce pesticide a été interdit car il est dangereux pour les abeilles.","exCn":"这种农药因危害蜜蜂而被禁用。","th":"健康与身体"},{"w":"peuple","p":"n.m.","cn":"人民；民族","ex":"Le président a promis d'écouter la voix du peuple.","exCn":"总统承诺倾听人民的声音。","th":"人物与身份"},{"w":"peureux","p":"adj.","cn":"胆小的、胆怯的","ex":"Mon chat est très peureux avec les inconnus.","exCn":"我的猫见到陌生人就很胆小。","th":"描述与状态"},{"w":"phare","p":"n.m.","cn":"（汽车）前灯；灯塔；（同位语）标志性的、主打的（produit ~ 主打产品）","ex":"La nuit, n'oubliez pas d'allumer vos phares.","exCn":"夜里别忘了打开车灯。","th":"出行与旅行"},{"w":"philosophe","p":"n.","cn":"哲学家；达观的、看得开的","ex":"Le philosophe René Descartes a passé une grande partie de sa vie aux Pays-Bas.","exCn":"哲学家笛卡尔一生中有很长时间住在荷兰。","th":"常用词"},{"w":"philosophie","p":"n.f.","cn":"哲学；理念、人生观","ex":"En France, la philosophie est une matière obligatoire au lycée.","exCn":"在法国，哲学是高中的必修课。","th":"人物与身份"},{"w":"photocopieuse","p":"n.f.","cn":"复印机","ex":"Il y a toujours la queue devant la photocopieuse de la bibliothèque à la veille des examens.","exCn":"每到考试前夕，图书馆的复印机前总是排着长队。","th":"常用词"},{"w":"photographie","p":"n.f.","cn":"摄影；照片","ex":"Il a suivi un cours de photographie pour apprendre à utiliser son nouvel appareil.","exCn":"为了学会用新相机，他上了一门摄影课。","th":"常用词"},{"w":"physiquement","p":"adv.","cn":"身体上、体力上；外表上；物理上","ex":"Le métier de déménageur est physiquement très exigeant.","exCn":"搬家工这份工作对体力要求很高。","th":"健康与身体"},{"w":"phénomène","p":"n.m.","cn":"现象；怪人、奇人（口语）","ex":"Les aurores boréales, un phénomène naturel spectaculaire, attirent chaque hiver de nombreux touristes au Yukon.","exCn":"北极光是一种壮观的自然现象，每年冬天都吸引大批游客前往育空地区。","th":"人物与身份"},{"w":"pigeon","p":"n.m.","cn":"鸽子；（口语）冤大头、容易上当的人","ex":"Il est interdit de nourrir les pigeons dans ce parc.","exCn":"这个公园禁止喂鸽子。","th":"人物与身份"},{"w":"pile","p":"n.f.","cn":"电池；（一）叠、（一）堆；（口语）正好、整（à huit heures ~ 八点整）；cf. pile ou face 抛硬币猜正反面","ex":"Ma montre s'est arrêtée, je dois remplacer la pile.","exCn":"我的表停了，得换电池。","th":"描述与状态"},{"w":"pilule","p":"n.f.","cn":"药丸、药片；（la ~）避孕药","ex":"Elle prend la pilule depuis plusieurs années.","exCn":"她服用避孕药已经好几年了。","th":"健康与身体"},{"w":"piment","p":"n.m.","cn":"辣椒；（喻）情趣、刺激","ex":"Tu peux mettre le piment à part ? Les enfants n'aiment pas ça.","exCn":"辣椒能另外放吗？孩子们不吃辣。","th":"饮食"},{"w":"piquer","p":"v.","cn":"刺、扎；（虫）叮、蜇；（辣、烟等）刺激、辣；偷（口语）","ex":"Elle s'est piqué le doigt avec une aiguille en cousant.","exCn":"她缝衣服时被针扎了手指。","th":"饮食"},{"w":"piqûre","p":"n.f.","cn":"（蚊虫）叮咬、蜇伤；打针、注射","ex":"Une piqûre de guêpe peut être dangereuse pour les personnes allergiques.","exCn":"被黄蜂蜇伤对过敏的人来说可能很危险。","th":"健康与身体"},{"w":"pirate","p":"n.","cn":"海盗；（网络）黑客","ex":"Le navire a été attaqué par des pirates au large de la Somalie.","exCn":"这艘船在索马里附近海域遭到海盗袭击。","th":"居住与环境"},{"w":"pirater","p":"v.","cn":"（黑客）入侵；盗版","ex":"Mon compte a été piraté : quelqu'un envoie des messages à mes amis en se faisant passer pour moi.","exCn":"我的账号被盗了：有人冒充我给朋友们发消息。","th":"描述与状态"},{"w":"pistache","p":"n.f.","cn":"开心果","ex":"Elle décore toujours ses gâteaux de pistaches concassées.","exCn":"她总是用碎开心果装饰自己做的蛋糕。","th":"情绪与性格"},{"w":"piste","p":"n.f.","cn":"跑道、场地；（滑雪的）雪道；线索、踪迹；cf. piste cyclable 自行车道","ex":"L'avion attend sur la piste avant de décoller.","exCn":"飞机在跑道上等待起飞。","th":"出行与旅行"},{"w":"pitié","p":"n.f.","cn":"怜悯、同情；（par ~）求求你、行行好","ex":"J'ai eu pitié de ce chien abandonné, alors je l'ai ramené à la maison.","exCn":"我可怜那只被遗弃的狗，就把它带回了家。","th":"描述与状态"},{"w":"piège","p":"n.m.","cn":"陷阱、圈套","ex":"Ne tombez pas dans le piège des offres trop belles pour être vraies.","exCn":"别落入那些好得令人难以置信的优惠陷阱。","th":"常用词"},{"w":"piéton","p":"n.","cn":"行人；步行的、行人专用的","ex":"Attention aux piétons qui traversent la rue !","exCn":"注意过马路的行人！","th":"人物与身份"},{"w":"placer","p":"v.","cn":"放、放置；安排（座位等）；投资（钱）","ex":"Placez vos bagages sous le siège devant vous.","exCn":"请把行李放在您前面的座位下方。","th":"购物与金钱"},{"w":"plafond","p":"n.m.","cn":"天花板；上限、最高限额","ex":"Il y a une tache d'humidité au plafond de la salle de bain.","exCn":"浴室的天花板上有一块水渍。","th":"时间与数量"},{"w":"plaindre","p":"v.","cn":"（se ~）抱怨；同情、可怜","ex":"Les locataires se plaignent du bruit des travaux depuis des semaines.","exCn":"几个星期以来，租户们一直在抱怨施工噪音。","th":"常用词"},{"w":"plaine","p":"n.f.","cn":"平原","ex":"Entre Montréal et Québec, l'autoroute traverse une vaste plaine agricole.","exCn":"从蒙特利尔到魁北克城，高速公路穿过一大片农业平原。","th":"常用词"},{"w":"plainte","p":"n.f.","cn":"投诉、控告；（porter ~）报案、起诉；cf. la plante = 植物","ex":"Victime d'une arnaque sur un site de petites annonces, elle a décidé de porter plainte.","exCn":"她在一个二手交易网站上被骗了，决定去报案。","th":"常用词"},{"w":"plaisanterie","p":"n.f.","cn":"玩笑","ex":"Ne le prends pas au sérieux : c'était juste une plaisanterie.","exCn":"别当真，那只是个玩笑。","th":"常用词"},{"w":"planche","p":"n.f.","cn":"木板、板子；cf. planche à roulettes 滑板；（魁北克）planche à neige 单板滑雪板","ex":"Il a fixé une planche au mur pour ranger ses livres.","exCn":"他在墙上固定了一块木板用来放书。","th":"居住与环境"},{"w":"planifier","p":"v.","cn":"计划、规划","ex":"Il vaut mieux planifier son budget avant de déménager.","exCn":"搬家之前最好先做好预算规划。","th":"常用词"},{"w":"plaque","p":"n.f.","cn":"板、金属板；牌子、标牌；车牌；cf. être à côté de la plaque 搞错、不得要领（口语）","ex":"Ce cycliste a noté la plaque de la voiture qui l'a renversé.","exCn":"这位骑车人记下了撞倒他的那辆车的车牌。","th":"出行与旅行"},{"w":"plateau","p":"n.m.","cn":"托盘；高原","ex":"Le serveur a apporté les cafés sur un plateau.","exCn":"服务员用托盘端来了咖啡。","th":"描述与状态"},{"w":"plateforme","p":"n.f.","cn":"（网络）平台；台子；（竞选）纲领","ex":"Cette série québécoise est disponible sur plusieurs plateformes de streaming.","exCn":"这部魁北克剧在好几个流媒体平台上都能看到。","th":"常用词"},{"w":"plier","p":"v.","cn":"折、折叠；弯曲","ex":"Il a plié soigneusement ses chemises avant de les ranger dans la valise.","exCn":"他把衬衫仔细叠好，再放进行李箱。","th":"常用词"},{"w":"plié","p":"adj.","cn":"叠好的、折起的；（膝盖等）弯曲的；cf. être plié de rire 笑弯了腰（口语）","ex":"J'ai mis les vêtements pliés dans le tiroir.","exCn":"我把叠好的衣服放进了抽屉。","th":"描述与状态"},{"w":"plonger","p":"v.","cn":"跳水、潜水；把…浸入、放入","ex":"Elle aime plonger pour observer les poissons tropicaux.","exCn":"她喜欢潜水观察热带鱼。","th":"常用词"},{"w":"plongée","p":"n.f.","cn":"潜水；深入探索、沉浸","ex":"Nous avons fait de la plongée sous-marine pendant nos vacances au Mexique.","exCn":"我们在墨西哥度假时去潜水了。","th":"常用词"},{"w":"plume","p":"n.f.","cn":"羽毛；笔、笔尖","ex":"Ce sac de voyage est léger comme une plume.","exCn":"这个旅行包轻得像一根羽毛。","th":"常用词"},{"w":"pneu","p":"n.m.","cn":"轮胎","ex":"Au Québec, les pneus d'hiver sont obligatoires du 1er décembre au 15 mars.","exCn":"在魁北克，每年12月1日至3月15日必须使用冬季轮胎。","th":"常用词"},{"w":"poignet","p":"n.m.","cn":"手腕","ex":"Elle est tombée sur la glace et s'est cassé le poignet.","exCn":"她在冰上摔了一跤，摔断了手腕。","th":"常用词"},{"w":"poignée","p":"n.f.","cn":"把手、拉手；（une ~ de）一把、少数几个；cf. poignée de main 握手","ex":"Seule une poignée d'élèves ont réussi l'examen.","exCn":"只有寥寥几个学生通过了考试。","th":"日常动作"},{"w":"poil","p":"n.m.","cn":"（人或动物身上的）毛、体毛；（un ~）一点点（口语）；cf. à poil 光着身子；être de bon / mauvais poil 心情好 / 不好（均为口语）","ex":"Il y a un poil de chat sur ton pull noir.","exCn":"你的黑毛衣上有一根猫毛。","th":"人物与身份"},{"w":"poing","p":"n.m.","cn":"拳头；cf. le point = 点；le poignet = 手腕","ex":"Furieux, il a tapé du poing sur la table.","exCn":"他气坏了，一拳砸在桌子上。","th":"常用词"},{"w":"point de vue","p":"n.m.","cn":"观点；角度","ex":"De mon point de vue, la décision est juste.","exCn":"从我的角度看，这个决定是对的。","th":"观点与论证"},{"w":"poison","p":"n.m.","cn":"毒药；cf. le poisson = 鱼","ex":"Certaines plantes contiennent un poison dangereux pour les animaux.","exCn":"有些植物含有对动物有害的毒素。","th":"饮食"},{"w":"poitrine","p":"n.f.","cn":"胸部","ex":"Sur scène, il sentait son cœur battre très fort dans sa poitrine.","exCn":"站在台上，他感觉心在胸口怦怦直跳。","th":"常用词"},{"w":"poliment","p":"adv.","cn":"礼貌地、客气地","ex":"Le serveur nous a poliment fait remarquer que la cuisine fermait dans dix minutes.","exCn":"服务员客气地提醒我们，厨房十分钟后就要关了。","th":"交际与礼貌"},{"w":"politicien","p":"n.","cn":"政客、政治人物","ex":"Ce politicien a promis de baisser les impôts, mais il n'a rien fait.","exCn":"这位政客承诺过减税，却什么也没做。","th":"人物与身份"},{"w":"politique","p":"n.f.","cn":"政治；政策；政治的；cf. homme / femme politique 政治人物","ex":"Mon père s'intéresse beaucoup à la politique internationale.","exCn":"我父亲对国际政治很感兴趣。","th":"人物与身份"},{"w":"polluant","p":"adj.","cn":"造成污染的、有污染的","ex":"Les vieilles voitures diesel sont très polluantes.","exCn":"老式柴油车污染很严重。","th":"居住与环境"},{"w":"polluer","p":"v.","cn":"污染","ex":"Les usines polluent la rivière depuis des années.","exCn":"多年来工厂一直在污染这条河。","th":"居住与环境"},{"w":"pommade","p":"n.f.","cn":"药膏、软膏","ex":"Le pharmacien m'a conseillé une pommade contre les piqûres d'insectes.","exCn":"药剂师给我推荐了一种治蚊虫叮咬的药膏。","th":"健康与身体"},{"w":"pop","p":"n.f.","cn":"流行（音乐）的；波普（艺术）的；流行音乐","ex":"Ma fille écoute surtout de la musique pop coréenne.","exCn":"我女儿主要听韩国流行音乐。","th":"常用词"},{"w":"popularité","p":"n.f.","cn":"受欢迎程度、人气","ex":"La popularité du premier ministre a chuté après l'annonce de la hausse des impôts.","exCn":"宣布加税之后，总理的支持率大幅下滑。","th":"人物与身份"},{"w":"population","p":"n.f.","cn":"人口；居民、民众","ex":"La population du Canada dépasse aujourd'hui quarante millions d'habitants.","exCn":"加拿大人口如今已超过四千万。","th":"人物与身份"},{"w":"portail","p":"n.m.","cn":"（院子、花园的）大门；（网站）门户、在线平台","ex":"Pense à bien fermer le portail, sinon le chien va s'échapper.","exCn":"记得把大门关好，不然狗会跑出去。","th":"居住与环境"},{"w":"porte-bonheur","p":"n.m.","cn":"幸运物、吉祥物","ex":"Ce trèfle à quatre feuilles est mon porte-bonheur.","exCn":"这片四叶草是我的幸运物。","th":"常用词"},{"w":"positif","p":"adj.","cn":"形容词；阳性 m. / 阴性 f.；positif / positive；positifs / positives；积极的、正面的；（检测）阳性的","ex":"Cette expérience a eu un effet positif sur sa confiance en elle.","exCn":"这段经历对她的自信心产生了积极的影响。","th":"常用词"},{"w":"position","p":"n.f.","cn":"位置；立场","ex":"Le GPS indique notre position exacte sur la carte.","exCn":"GPS在地图上显示出我们的确切位置。","th":"观点与论证"},{"w":"posséder","p":"v.","cn":"拥有、占有","ex":"À part son vélo et quelques livres, il ne possède presque rien.","exCn":"除了一辆自行车和几本书，他几乎一无所有。","th":"常用词"},{"w":"poster","p":"v.","cn":"（在网上）发布、发帖；邮寄、投寄（信件）；cf. le poster /pɔstɛʁ/ = 海报","ex":"Il a posté un message sur le forum pour demander de l'aide.","exCn":"他在论坛上发了个帖子求助。","th":"居住与环境"},{"w":"potable","p":"adj.","cn":"可饮用的；（口语）还过得去的、凑合的","ex":"Ici, l'eau du robinet est potable.","exCn":"这里的自来水可以直接喝。","th":"常用词"},{"w":"pote","p":"n.","cn":"朋友、哥们（口语）","ex":"C'est un vieux pote de lycée.","exCn":"他是我高中时的老哥们。","th":"人物与身份"},{"w":"pouce","p":"n.m.","cn":"大拇指；英寸；cf. manger sur le pouce 匆匆吃点东西；donner un coup de pouce 帮一把；（魁北克）faire du pouce 搭便车","ex":"Il m'a fait signe du pouce que tout allait bien.","exCn":"他冲我竖了竖大拇指，表示一切都好。","th":"饮食"},{"w":"poudre","p":"n.f.","cn":"粉末","ex":"Les douaniers ont trouvé une poudre blanche dans la valise d'un passager.","exCn":"海关人员在一名乘客的行李箱里发现了一种白色粉末。","th":"常用词"},{"w":"pouls","p":"n.m.","cn":"脉搏","ex":"Je dois vous prendre le pouls.","exCn":"我得给您量一下脉搏。","th":"常用词"},{"w":"poumon","p":"n.m.","cn":"肺","ex":"Fumer augmente fortement le risque de cancer du poumon.","exCn":"吸烟会大大增加患肺癌的风险。","th":"常用词"},{"w":"pour que","p":"conj.","cn":"（+ 虚拟式）为了、以便；cf. pour + 不定式（前后主语相同时）","ex":"Je te prête mon vélo pour que tu puisses aller à la gare.","exCn":"我把自行车借给你，好让你能去火车站。","th":"常用词"},{"w":"pourcentage","p":"n.m.","cn":"百分比；提成、佣金","ex":"Le pourcentage de logements vacants à Montréal reste très bas.","exCn":"蒙特利尔的空置房比例仍然很低。","th":"时间与数量"},{"w":"poursuivre","p":"v.","cn":"继续；追赶、追捕；追求（目标、梦想）；（~ qqn en justice）起诉","ex":"Après sa licence, elle souhaite poursuivre ses études au Canada.","exCn":"本科毕业后，她希望去加拿大继续深造。","th":"日常动作"},{"w":"pourtant","p":"adv.","cn":"然而、可是；（强调）明明","ex":"Ce restaurant est cher, et pourtant il est toujours plein.","exCn":"这家餐厅很贵，可总是座无虚席。","th":"功能词与连接"},{"w":"pourvu que","p":"conj.","cn":"（+ 虚拟式）只要；（用在句首）但愿","ex":"Tu peux prendre ma voiture, pourvu que tu me la rendes avant ce soir.","exCn":"你可以开我的车，只要今晚之前还给我。","th":"常用词"},{"w":"poussin","p":"n.m.","cn":"小鸡、雏鸡","ex":"À la ferme, les enfants ont pu tenir un poussin dans leurs mains.","exCn":"在农场里，孩子们可以把小鸡捧在手心。","th":"描述与状态"},{"w":"poussière","p":"n.f.","cn":"灰尘、尘土","ex":"Je suis allergique à la poussière, alors je fais le ménage avec un masque.","exCn":"我对灰尘过敏，所以打扫卫生时要戴口罩。","th":"常用词"},{"w":"poète","p":"n.","cn":"诗人","ex":"Émile Nelligan est un poète québécois très célèbre.","exCn":"埃米尔 · 内利冈是一位非常有名的魁北克诗人。","th":"人物与身份"},{"w":"prairie","p":"n.f.","cn":"草地、草原；（les Prairies）加拿大草原诸省","ex":"Les vaches broutent tranquillement dans la prairie.","exCn":"奶牛在草地上悠闲地吃草。","th":"描述与状态"},{"w":"pratiquement","p":"adv.","cn":"几乎、差不多；实际上、在实践中","ex":"Ce quartier est pratiquement désert le dimanche.","exCn":"这个街区周日几乎空无一人。","th":"常用词"},{"w":"presse","p":"n.f.","cn":"新闻界、报刊","ex":"La presse locale a beaucoup parlé de cet accident.","exCn":"当地媒体对这起事故做了大量报道。","th":"社会与新闻"},{"w":"presser","p":"v.","cn":"（se ~）赶紧、急忙；挤压、榨；催促；cf. ça presse 事情紧急；rien ne presse 不着急","ex":"Il s'est pressé de terminer son rapport avant la réunion.","exCn":"他赶紧在开会前把报告写完。","th":"常用词"},{"w":"pressing","p":"n.m.","cn":"干洗店；cf. le nettoyeur 干洗店（魁北克常用）","ex":"Je dois déposer mon costume au pressing.","exCn":"我得把西装送去干洗店。","th":"日常动作"},{"w":"pression","p":"n.f.","cn":"压力；（une ~）扎啤、生啤","ex":"Les étudiants subissent une forte pression avant les examens.","exCn":"考试前，学生们承受着很大的压力。","th":"常用词"},{"w":"prestigieux","p":"adj.","cn":"有声望的、著名的","ex":"Cet hôtel prestigieux a accueilli de nombreux chefs d'État.","exCn":"这家著名的酒店接待过许多国家元首。","th":"常用词"},{"w":"preuve","p":"n.f.","cn":"证据、证明；cf. faire preuve de 表现出（勇气、耐心等）","ex":"L'avocat affirme que ces photos sont la preuve de l'innocence de son client.","exCn":"律师声称这些照片能证明其当事人的清白。","th":"情绪与性格"},{"w":"prime","p":"n.f.","cn":"奖金、补贴；（保险的）保费","ex":"Avec cette nouvelle assurance, ma prime mensuelle a baissé de vingt dollars.","exCn":"换了这份新保险后，我每月的保费少了二十元。","th":"常用词"},{"w":"principalement","p":"adv.","cn":"主要地","ex":"Je communique principalement avec ma famille par messages vocaux.","exCn":"我和家人主要通过语音消息联系。","th":"常用词"},{"w":"principe","p":"n.m.","cn":"原则；原理；cf. en principe 原则上、按理说","ex":"C'est une question de principe.","exCn":"这是原则问题。","th":"抽象与概念"},{"w":"priorité","p":"n.f.","cn":"优先、优先权；首要任务","ex":"Au carrefour, les piétons ont la priorité sur les voitures.","exCn":"在路口，行人比汽车享有优先通行权。","th":"工作与学习"},{"w":"prise","p":"n.f.","cn":"拿、取（如 ~ de sang 抽血）；（电源）插座；cf. la prise en charge 负责、承担（费用、照护）；la prise de conscience 意识到…","ex":"La prise de médicaments sans ordonnance peut être dangereuse.","exCn":"不凭处方乱吃药可能很危险。","th":"健康与身体"},{"w":"prisonnier","p":"n.","cn":"囚犯；俘虏","ex":"Un prisonnier s'est évadé pendant son transfert à l'hôpital.","exCn":"一名囚犯在被转送医院途中逃跑了。","th":"常用词"},{"w":"privé","p":"n.m.","cn":"私人的、私有的；私营部门；cf. en privé 私下","ex":"C'est une propriété privée, l'entrée est interdite.","exCn":"这是私人财产，禁止入内。","th":"人物与身份"},{"w":"prière","p":"n.f.","cn":"祈祷、祷告；请求","ex":"Avant le repas, la famille récite une courte prière.","exCn":"饭前，全家人会念一段简短的祷告。","th":"交际与礼貌"},{"w":"pro","p":"n.","cn":"专业人士、行家（口语）；专业的、职业的（口语）","ex":"C'est un vrai pro du barbecue !","exCn":"他是个烧烤高手！","th":"工作与学习"},{"w":"probable","p":"adj.","cn":"很可能的","ex":"Il est probable qu'il neigera demain matin.","exCn":"明天早上很可能会下雪。","th":"抽象与概念"},{"w":"prochainement","p":"adv.","cn":"不久、近期","ex":"Le nouveau centre sportif ouvrira prochainement ses portes.","exCn":"新的体育中心即将开放。","th":"常用词"},{"w":"producteur","p":"n.","cn":"生产者、生产商；（影视）制片人","ex":"Nous achetons nos légumes directement à un petit producteur de la région.","exCn":"我们的蔬菜直接从本地的一个小生产者那里买。","th":"人物与身份"},{"w":"production","p":"n.f.","cn":"生产、制作；产量","ex":"L'usine a dû arrêter la production à cause d'une panne.","exCn":"工厂因设备故障不得不停产。","th":"常用词"},{"w":"produire","p":"v.","cn":"生产、制造；（se ~）发生","ex":"Le Brésil produit à lui seul plus d'un tiers du café mondial.","exCn":"仅巴西一国就生产了全球三分之一以上的咖啡。","th":"常用词"},{"w":"profil","p":"n.m.","cn":"（个人）概况、资料；侧面、轮廓","ex":"L'entreprise recherche des profils variés : ingénieurs, designers et commerciaux.","exCn":"公司在招各种背景的人：工程师、设计师和销售。","th":"人物与身份"},{"w":"profond","p":"adj.","cn":"深的；深刻的、深沉的","ex":"Attention, la piscine est très profonde de ce côté.","exCn":"注意，泳池这一边很深。","th":"常用词"},{"w":"profondeur","p":"n.f.","cn":"深度","ex":"Le lac atteint une profondeur de cent mètres à certains endroits.","exCn":"这个湖有些地方深达一百米。","th":"常用词"},{"w":"programmer","p":"v.","cn":"安排、排定；编程","ex":"Le festival a programmé une vingtaine de concerts gratuits cet été.","exCn":"音乐节今年夏天安排了二十来场免费音乐会。","th":"常用词"},{"w":"progresser","p":"v.","cn":"进步；提高","ex":"Tu progresses vite en compréhension orale.","exCn":"你的听力进步很快。","th":"工作与学习"},{"w":"progressivement","p":"adv.","cn":"逐渐地、逐步地","ex":"Le nouveau système de paiement sera mis en place progressivement dans toutes les stations de métro.","exCn":"新的支付系统将在所有地铁站逐步推行。","th":"常用词"},{"w":"projeter","p":"v.","cn":"计划、打算；投射、放映","ex":"Nous projetons de partir au Canada l'année prochaine.","exCn":"我们计划明年去加拿大。","th":"常用词"},{"w":"prolonger","p":"v.","cn":"延长、延期","ex":"Le musée a décidé de prolonger l'exposition jusqu'à la fin du mois.","exCn":"博物馆决定把展览延长到月底。","th":"描述与状态"},{"w":"promesse","p":"n.f.","cn":"承诺、诺言","ex":"Il a tenu sa promesse et il est venu m'aider à déménager.","exCn":"他信守诺言，来帮我搬家了。","th":"常用词"},{"w":"promotion","p":"n.f.","cn":"促销、推广；晋升、升职","ex":"Cette semaine, les fraises sont en promotion au supermarché.","exCn":"这周超市的草莓在促销。","th":"日常动作"},{"w":"propos","p":"n.m.","cn":"（多用复数）言论、话；主旨、意图；cf. à propos de 关于；à propos 顺便说一下","ex":"Ses propos sur les femmes au volant ont choqué une bonne partie du public.","exCn":"他关于女司机的言论让不少观众感到震惊。","th":"常用词"},{"w":"propreté","p":"n.f.","cn":"干净、清洁；（幼儿）如厕自理","ex":"La propreté des toilettes laisse à désirer dans cette gare.","exCn":"这个车站厕所的卫生状况不尽如人意。","th":"描述与状态"},{"w":"propriété","p":"n.f.","cn":"所有权；房产、地产；特性、性质","ex":"Ils ont acheté une grande propriété à la campagne.","exCn":"他们在乡下买了一大片地产。","th":"居住与环境"},{"w":"protection","p":"n.f.","cn":"保护","ex":"Cette crème offre une bonne protection contre le soleil.","exCn":"这款面霜的防晒效果很好。","th":"常用词"},{"w":"prouver","p":"v.","cn":"证明","ex":"Je veux prouver que je peux le faire.","exCn":"我想证明我能做到。","th":"观点与论证"},{"w":"provenir","p":"v.","cn":"（~ de）来自、源于","ex":"En hiver, la plupart des fruits vendus ici proviennent du Mexique.","exCn":"冬天，这里卖的水果大多来自墨西哥。","th":"常用词"},{"w":"provision","p":"n.f.","cn":"储备、存货","ex":"Avant la tempête, on a fait des provisions d'eau.","exCn":"暴风雨来临前，我们储备了水。","th":"常用词"},{"w":"provisoire","p":"adj.","cn":"临时的、暂时的","ex":"En attendant votre carte définitive, vous recevrez un permis provisoire.","exCn":"正式驾照下来之前，您会先拿到一张临时驾照。","th":"常用词"},{"w":"provoquer","p":"v.","cn":"引起、导致；挑衅","ex":"Ce médicament peut provoquer une légère somnolence : évitez de conduire après l'avoir pris.","exCn":"这种药可能引起轻微嗜睡，服药后请避免开车。","th":"常用词"},{"w":"proximité","p":"n.f.","cn":"邻近、附近；亲近、贴近（民众等）","ex":"Nous cherchons un logement à proximité d'une station de métro.","exCn":"我们在找地铁站附近的住处。","th":"常用词"},{"w":"prudent","p":"adj.","cn":"谨慎的、小心的","ex":"Sois prudente en rentrant à vélo, il fait déjà nuit.","exCn":"骑车回家路上小心点，天已经黑了。","th":"描述与状态"},{"w":"pré","p":"n.m.","cn":"草地、牧场；cf. près 近、在附近（同音）","ex":"Au printemps, le pré derrière l'école se couvre de fleurs sauvages.","exCn":"春天，学校后面的草地上开满了野花。","th":"常用词"},{"w":"précieux","p":"adj.","cn":"宝贵的","ex":"Merci pour vos conseils, ils m'ont été très précieux.","exCn":"谢谢您的建议，对我来说非常宝贵。","th":"购物与金钱"},{"w":"précis","p":"adj.","cn":"精确的、准确的；明确的、具体的","ex":"Il nous faut l'heure précise de votre arrivée pour réserver la navette.","exCn":"我们需要知道您到达的确切时间，才能预订接驳车。","th":"常用词"},{"w":"préciser","p":"v.","cn":"明确说明、具体指出；（se ~）变得明确","ex":"Le formulaire ne précise pas quels documents il faut joindre.","exCn":"表格上没有具体说明要附上哪些文件。","th":"常用词"},{"w":"précision","p":"n.f.","cn":"精确、准确；（常用复数）详细说明","ex":"Cette montre suisse est réputée pour sa grande précision.","exCn":"这款瑞士手表以走时精准著称。","th":"常用词"},{"w":"précisément","p":"adv.","cn":"准确地、精确地；恰恰、正是","ex":"Il est arrivé à huit heures précisément.","exCn":"他八点整到的。","th":"常用词"},{"w":"précédent","p":"n.m.","cn":"前面的、前一个的；先例","ex":"Il avait déjà réservé son billet la semaine précédente.","exCn":"他在前一周就已经订好票了。","th":"常用词"},{"w":"préférable","p":"adj.","cn":"更好的、更可取的","ex":"Il est préférable de réserver une table le samedi soir.","exCn":"周六晚上最好提前订位。","th":"描述与状态"},{"w":"préférence","p":"n.f.","cn":"偏爱、喜好；优先（权）；cf. de préférence 最好、尽量","ex":"Je n'ai pas de préférence particulière : choisis le restaurant que tu veux.","exCn":"我没什么特别的偏好，你想去哪家餐厅都行。","th":"情绪与性格"},{"w":"préparation","p":"n.f.","cn":"准备、筹备；（食品、药剂的）配制","ex":"La préparation au TCF m'a pris près de six mois.","exCn":"备考TCF花了我将近六个月。","th":"健康与身体"},{"w":"présence","p":"n.f.","cn":"出席、在场；存在","ex":"Votre présence à la réunion de lundi est obligatoire.","exCn":"周一的会议您必须出席。","th":"常用词"},{"w":"présentateur","p":"n.","cn":"（节目）主持人、播音员","ex":"Le présentateur du journal télévisé a annoncé la nouvelle en direct.","exCn":"电视新闻主播现场播报了这条消息。","th":"人物与身份"},{"w":"préserver","p":"v.","cn":"保护、维护","ex":"Il faut préserver les espaces verts dans les grandes villes.","exCn":"大城市必须保护好绿地。","th":"常用词"},{"w":"présidence","p":"n.f.","cn":"总统职位、主席职位；任期；总统府","ex":"Pendant sa présidence, il a fait adopter une réforme des retraites.","exCn":"他在任总统期间，推动通过了一项退休制度改革。","th":"常用词"},{"w":"présidentiel","p":"adj.","cn":"总统的、总统选举的","ex":"L'élection présidentielle aura lieu au printemps prochain.","exCn":"总统选举将于明年春天举行。","th":"社会与新闻"},{"w":"prétendre","p":"v.","cn":"声称；cf. faire semblant 假装（prétendre 没有「假装」的意思）","ex":"Il prétend avoir tout lu, mais je n'y crois pas.","exCn":"他声称全都读过了，可我不信。","th":"常用词"},{"w":"prétexte","p":"n.m.","cn":"借口","ex":"Pour mon fils, tous les prétextes sont bons pour ne pas ranger sa chambre.","exCn":"我儿子为了不收拾房间，什么借口都找得出来。","th":"常用词"},{"w":"prévenir","p":"v.","cn":"通知；预防","ex":"Préviens-moi si tu arrives en retard.","exCn":"如果你要晚到，告诉我一声。","th":"工作与学习"},{"w":"prévision","p":"n.f.","cn":"预测、预报；（en ~ de）预先考虑到","ex":"Selon les dernières prévisions météo, il pleuvra demain.","exCn":"根据最新的天气预报，明天会下雨。","th":"常用词"},{"w":"psychologie","p":"n.f.","cn":"心理学；心理、心态","ex":"J'ai lu un livre de psychologie passionnant sur la façon dont nous prenons nos décisions.","exCn":"我读了一本很有意思的心理学书，讲的是我们如何做决定。","th":"常用词"},{"w":"psychologique","p":"adj.","cn":"心理的、心理上的","ex":"Avant une compétition importante, la préparation psychologique compte autant que l'entraînement physique.","exCn":"大赛之前，心理准备和体能训练同样重要。","th":"常用词"},{"w":"psychologue","p":"n.","cn":"心理咨询师、心理医生；心理学家","ex":"L'école a engagé une psychologue pour accompagner les élèves en difficulté.","exCn":"学校聘请了一位心理咨询师，为有困难的学生提供辅导。","th":"健康与身体"},{"w":"pub","p":"n.f.","cn":"广告（口语）；（faire de la ~）做宣传；cf. le pub /pœb/ 酒吧","ex":"Il y a de plus en plus de pubs au milieu des vidéos en ligne.","exCn":"网上视频中间插的广告越来越多了。","th":"饮食"},{"w":"publicitaire","p":"n.","cn":"广告的；广告从业者、广告人","ex":"Les panneaux publicitaires sont interdits dans ce quartier historique.","exCn":"这个历史街区禁止设立广告牌。","th":"人物与身份"},{"w":"publier","p":"v.","cn":"发表、出版；公布、发布","ex":"Cet auteur québécois a publié son premier roman à vingt-deux ans.","exCn":"这位魁北克作家二十二岁时出版了第一部小说。","th":"人物与身份"},{"w":"puisque","p":"conj.","cn":"既然、因为","ex":"Puisqu'il pleut, nous resterons à la maison cet après-midi.","exCn":"既然下雨了，我们今天下午就待在家里吧。","th":"功能词与连接"},{"w":"puissant","p":"adj.","cn":"强大的、强劲的；有权势的","ex":"Cette tempête a été l'une des plus puissantes de la décennie.","exCn":"这场风暴是近十年来最强的之一。","th":"描述与状态"},{"w":"punir","p":"v.","cn":"惩罚、处罚","ex":"Les parents ont puni leur fils parce qu'il avait menti.","exCn":"儿子撒了谎，父母惩罚了他。","th":"常用词"},{"w":"punition","p":"n.f.","cn":"惩罚、处罚","ex":"Comme punition, l'enfant a été privé de télévision pendant une semaine.","exCn":"作为惩罚，孩子一个星期不许看电视。","th":"常用词"},{"w":"pur","p":"adj.","cn":"纯的、纯净的；纯粹的","ex":"L'eau de cette source est si pure qu'on peut la boire directement.","exCn":"这处泉水非常纯净，可以直接饮用。","th":"常用词"},{"w":"puzzle","p":"n.m.","cn":"拼图","ex":"Il manque une pièce à ce puzzle.","exCn":"这幅拼图少了一块。","th":"常用词"},{"w":"pyramide","p":"n.f.","cn":"金字塔","ex":"Au Louvre, on entre dans le musée par une immense pyramide de verre.","exCn":"在卢浮宫，游客要从一座巨大的玻璃金字塔进入博物馆。","th":"常用词"},{"w":"pâle","p":"adj.","cn":"（脸色）苍白的；（颜色）浅的、淡的","ex":"Tu es toute pâle, tu veux t'asseoir un moment ?","exCn":"你脸色好苍白，要不要坐一会儿？","th":"描述与状态"},{"w":"pédale","p":"n.f.","cn":"踏板","ex":"Appuyez doucement sur la pédale de frein à l'approche du feu rouge.","exCn":"快到红灯时，轻踩刹车踏板。","th":"常用词"},{"w":"pédaler","p":"v.","cn":"蹬踏板、骑车","ex":"Il faut pédaler fort pour monter cette côte.","exCn":"要骑上这个坡得使劲蹬。","th":"出行与旅行"},{"w":"pénible","p":"adj.","cn":"艰苦的、难受的；烦人的","ex":"Déménager en plein hiver a été une expérience pénible.","exCn":"大冬天搬家真是一段痛苦的经历。","th":"人物与身份"},{"w":"périmé","p":"adj.","cn":"过期的；过时的","ex":"Ce yaourt est périmé depuis trois jours.","exCn":"这个酸奶已经过期三天了。","th":"常用词"},{"w":"pétanque","p":"n.f.","cn":"（法式）滚球游戏","ex":"L'été, les retraités du village jouent à la pétanque sur la place.","exCn":"夏天，村里的退休老人在广场上玩滚球。","th":"常用词"},{"w":"pétrole","p":"n.m.","cn":"石油","ex":"On dit qu'il a fait fortune dans le pétrole.","exCn":"据说他靠石油发了财。","th":"常用词"},{"w":"pêcheur","p":"n.","cn":"渔民；钓鱼的人；cf. le pécheur 罪人（无长音符）","ex":"Les pêcheurs vendent leurs homards directement sur le quai du port.","exCn":"渔民们直接在港口码头上卖龙虾。","th":"饮食"},{"w":"qualifier","p":"v.","cn":"（se ~）获得资格、晋级；（~ de）把…称为、形容为","ex":"La France s'est qualifiée pour la finale.","exCn":"法国队晋级决赛。","th":"常用词"},{"w":"quant à","p":"loc.","cn":"至于","ex":"Quant à moi, je reste prudent.","exCn":"至于我，我保持谨慎。","th":"观点与论证"},{"w":"quinzaine","p":"n.f.","cn":"（une ~ de）十五个左右；两周、半个月","ex":"À huit heures, une quinzaine de personnes attendaient déjà devant la mairie.","exCn":"八点钟，已经有十五六个人在市政厅门前等着了。","th":"时间与数量"},{"w":"quotidiennement","p":"adv.","cn":"每天、天天","ex":"Ce médicament doit être pris quotidiennement, de préférence le matin.","exCn":"这种药需要每天服用，最好在早上。","th":"时间与数量"},{"w":"raccompagner","p":"v.","cn":"送（某人）回去","ex":"Il est tard, je vais te raccompagner chez toi.","exCn":"很晚了，我送你回家吧。","th":"人物与身份"},{"w":"raccourci","p":"n.m.","cn":"近路、捷径；（电脑）快捷方式","ex":"Si on prend ce raccourci par le parc, on arrivera dix minutes plus tôt.","exCn":"如果我们抄公园这条近路，能早到十分钟。","th":"出行与旅行"},{"w":"raccrocher","p":"v.","cn":"挂断（电话）；（se ~ à）抓住、依靠","ex":"Au milieu de notre dispute, elle m'a raccroché au nez.","exCn":"我们吵到一半，她就直接挂了我的电话。","th":"居住与环境"},{"w":"racheter","p":"v.","cn":"再买、多买；收购、买下","ex":"Il n'y a plus de lait, il faut en racheter.","exCn":"没牛奶了，得再买点。","th":"购物与金钱"},{"w":"racine","p":"n.f.","cn":"（植物的）根；根源","ex":"Une racine de ce vieux chêne a soulevé le trottoir.","exCn":"这棵老橡树的一条根把人行道顶了起来。","th":"常用词"},{"w":"racisme","p":"n.m.","cn":"种族主义、种族歧视","ex":"L'école organise une semaine de sensibilisation contre le racisme.","exCn":"学校举办了为期一周的反种族歧视宣传活动。","th":"常用词"},{"w":"raciste","p":"n.","cn":"种族主义的；种族主义者","ex":"Le joueur a été victime d'insultes racistes pendant le match.","exCn":"这名球员在比赛中遭到了种族主义辱骂。","th":"常用词"},{"w":"radar","p":"n.m.","cn":"雷达；（道路）测速雷达、测速摄像头","ex":"Je me suis fait flasher par un radar sur l'autoroute.","exCn":"我在高速公路上被测速摄像头拍了。","th":"出行与旅行"},{"w":"radiateur","p":"n.m.","cn":"暖气片；（汽车）散热器","ex":"Le radiateur de ma chambre ne chauffe plus depuis hier.","exCn":"我卧室的暖气片从昨天起就不热了。","th":"出行与旅行"},{"w":"radis","p":"n.m.","cn":"小萝卜、樱桃萝卜","ex":"Le radis se mange cru, avec un peu de beurre et de sel.","exCn":"小萝卜可以生吃，配一点黄油和盐。","th":"描述与状态"},{"w":"rafraîchir","p":"v.","cn":"使凉爽、使变凉；（se ~）（天气）转凉；刷新、更新（网页）","ex":"Après la canicule, le temps va enfin se rafraîchir ce week-end.","exCn":"热浪过后，这个周末天气终于要转凉了。","th":"时间与数量"},{"w":"raisonnable","p":"adj.","cn":"讲道理的、明智的；（价格等）合理的","ex":"Les prix de ce restaurant sont très raisonnables.","exCn":"这家餐厅的价格很实惠。","th":"购物与金钱"},{"w":"rajouter","p":"v.","cn":"再加、添加；补充说","ex":"Tu peux rajouter une chaise ? Ma sœur vient aussi.","exCn":"你能再加一把椅子吗？我姐姐也来。","th":"常用词"},{"w":"ralentir","p":"v.","cn":"减速；使放慢、减缓","ex":"Le chauffeur du bus a brusquement ralenti pour éviter un cycliste.","exCn":"公交车司机为了避让一个骑车的人，猛地减了速。","th":"描述与状态"},{"w":"rallumer","p":"v.","cn":"重新点燃；重新打开（灯、电器）；重新挑起（争论等）","ex":"Le technicien m'a conseillé d'éteindre puis de rallumer l'ordinateur.","exCn":"技术员建议我把电脑关掉再重新打开。","th":"观点与论证"},{"w":"randonneur","p":"n.","cn":"徒步旅行者、远足者","ex":"De nombreux randonneurs empruntent ce sentier.","exCn":"许多徒步者走这条小路。","th":"出行与旅行"},{"w":"rang","p":"n.m.","cn":"排；名次；地位；（魁北克）乡间道路","ex":"Au cinéma, je préfère toujours m'asseoir dans les derniers rangs.","exCn":"看电影时，我总是喜欢坐在最后几排。","th":"出行与旅行"},{"w":"rapidité","p":"n.f.","cn":"迅速、快速","ex":"J'ai été surpris par la rapidité du service : mon passeport est arrivé en cinq jours.","exCn":"办事速度之快让我很惊讶：护照五天就寄到了。","th":"描述与状态"},{"w":"rappel","p":"n.m.","cn":"提醒、提示；召回；（疫苗）加强针","ex":"Vous recevrez un rappel par courriel la veille de votre rendez-vous.","exCn":"预约的前一天，您会收到一封提醒邮件。","th":"描述与状态"},{"w":"rapport","p":"n.m.","cn":"关系、联系；报告；cf. par rapport à 相对于、与…相比；rapport qualité-prix 性价比","ex":"Je ne vois pas le rapport entre ton histoire et ce dont on est en train de discuter.","exCn":"我看不出你讲的事和我们正在讨论的有什么关系。","th":"购物与金钱"},{"w":"rapporter","p":"v.","cn":"带回、送回；报道、转述；带来（收益）、赚钱；打小报告（口语）","ex":"N'oublie pas de rapporter les livres à la bibliothèque avant samedi.","exCn":"别忘了周六之前把书还回图书馆。","th":"购物与金钱"},{"w":"rapprocher","p":"v.","cn":"拉近、挪近；使亲近；（se ~ de）靠近、接近","ex":"Rapproche ta chaise de la table, tu seras mieux installé.","exCn":"把椅子往桌子边挪近一点，你会坐得更舒服。","th":"日常动作"},{"w":"rasoir","p":"n.m.","cn":"剃刀、剃须刀","ex":"Pour la fête des Pères, on lui a offert un rasoir électrique dernier cri.","exCn":"父亲节时，我们送了他一个最新款的电动剃须刀。","th":"常用词"},{"w":"rassembler","p":"v.","cn":"聚集、收集、集中","ex":"Avant de déposer votre demande, rassemblez tous les documents nécessaires.","exCn":"提交申请之前，请把所有需要的材料收集齐。","th":"常用词"},{"w":"rassurant","p":"adj.","cn":"令人安心的","ex":"Le médecin avait une voix calme et rassurante.","exCn":"医生的声音平静，让人安心。","th":"人物与身份"},{"w":"rassurer","p":"v.","cn":"使安心、使放心","ex":"Le médecin m'a rassuré : ce n'est qu'une petite infection.","exCn":"医生让我放心：只是个小感染。","th":"常用词"},{"w":"rat","p":"n.m.","cn":"大老鼠、耗子；cf. un rat de bibliothèque 书虫、书呆子","ex":"Un rat est sorti des poubelles derrière le restaurant.","exCn":"一只大老鼠从餐馆后面的垃圾桶里钻了出来。","th":"描述与状态"},{"w":"rattraper","p":"v.","cn":"追上、补上","ex":"Marche moins vite, je n'arrive pas à te rattraper !","exCn":"走慢点，我追不上你了！","th":"常用词"},{"w":"raté","p":"adj.","cn":"失败的、搞砸的；（车、机会）错过的","ex":"C'était une soirée ratée : il pleuvait et le restaurant était fermé.","exCn":"那晚真是糟透了：下着雨，餐厅还关门了。","th":"出行与旅行"},{"w":"ravissant","p":"adj.","cn":"迷人的、漂亮的","ex":"Nous avons découvert un village ravissant perché sur une colline.","exCn":"我们发现了一个坐落在山丘上的迷人小村庄。","th":"人物与身份"},{"w":"rayon","p":"n.m.","cn":"光线；半径、范围；（商店的）货架、专柜","ex":"Les premiers rayons du soleil entraient par la fenêtre.","exCn":"清晨的第一缕阳光从窗户照了进来。","th":"购物与金钱"},{"w":"rayure","p":"n.f.","cn":"条纹；划痕","ex":"J'adore ce pull à rayures bleues.","exCn":"我很喜欢这件蓝条纹毛衣。","th":"常用词"},{"w":"recoller","p":"v.","cn":"重新粘上、粘好","ex":"J'ai recollé l'anse de la tasse.","exCn":"我把杯子的把手粘回去了。","th":"描述与状态"},{"w":"recommandation","p":"n.f.","cn":"建议、劝告；推荐","ex":"Elle a suivi les recommandations de son professeur et elle a beaucoup progressé.","exCn":"她听从了老师的建议，进步很大。","th":"日常动作"},{"w":"reconnaissant","p":"adj.","cn":"（~ à qqn de qqch）感激的、感谢的","ex":"Je vous suis très reconnaissante de m'avoir aidée à remplir ce dossier.","exCn":"非常感谢您帮我填好这份材料。","th":"常用词"},{"w":"reconstruire","p":"v.","cn":"重建","ex":"Après l'incendie, il a fallu deux ans pour reconstruire l'école.","exCn":"火灾之后，花了两年时间才把学校重建起来。","th":"描述与状态"},{"w":"record","p":"n.m.","cn":"纪录；创纪录的","ex":"Les travaux ont été terminés en un temps record.","exCn":"工程以创纪录的速度完工了。","th":"常用词"},{"w":"recruter","p":"v.","cn":"招聘、招募","ex":"L'hôpital recrute des infirmières pour son nouveau service d'urgence.","exCn":"医院正在为新开的急诊科招聘护士。","th":"工作与学习"},{"w":"rectangle","p":"n.m.","cn":"长方形、矩形","ex":"Dessine un rectangle sur ta feuille.","exCn":"在纸上画一个长方形。","th":"描述与状态"},{"w":"rectangulaire","p":"adj.","cn":"长方形的、矩形的","ex":"Je préfère les montures rectangulaires : les rondes ne vont pas du tout à mon visage.","exCn":"我更喜欢长方形的镜框，圆框完全不适合我的脸型。","th":"描述与状态"},{"w":"reculer","p":"v.","cn":"后退、倒车；推迟、延后；退缩","ex":"Elle a reculé d'un pas en voyant le chien s'approcher.","exCn":"看到那条狗走过来，她往后退了一步。","th":"出行与旅行"},{"w":"recyclage","p":"n.m.","cn":"回收利用；（职业）进修、再培训","ex":"Le recyclage du plastique reste insuffisant.","exCn":"塑料的回收利用仍然不足。","th":"工作与学习"},{"w":"recycler","p":"v.","cn":"回收利用；（se ~）转行、进修","ex":"Dans notre immeuble, on recycle le verre et le papier.","exCn":"我们楼里回收玻璃和纸张。","th":"常用词"},{"w":"redescendre","p":"v.","cn":"再下来、重新下去；（温度、价格）回落","ex":"J'ai oublié mes clés dans la voiture, je dois redescendre au parking.","exCn":"我把钥匙忘在车里了，得再下一趟停车场。","th":"购物与金钱"},{"w":"redonner","p":"v.","cn":"再给、归还；使恢复、重新给予（信心等）","ex":"Tu peux me redonner ton numéro ? J'ai perdu mon ancien téléphone.","exCn":"你能再告诉我一次你的号码吗？我旧手机丢了。","th":"描述与状态"},{"w":"redoubler","p":"v.","cn":"留级；（~ de）加倍、更加","ex":"Avec ses mauvaises notes, il risque de redoubler.","exCn":"成绩这么差，他可能要留级。","th":"时间与数量"},{"w":"redémarrer","p":"v.","cn":"重启、重新启动；（经济）复苏、回升","ex":"Redémarre ton ordinateur pour installer la mise à jour.","exCn":"重启电脑以安装更新。","th":"社会与新闻"},{"w":"refermer","p":"v.","cn":"关上、（打开后）再关上；（se ~）（门、伤口）合上","ex":"N'oublie pas de refermer le frigo, sinon tout va s'abîmer.","exCn":"别忘了把冰箱门关好，不然东西都会坏。","th":"健康与身体"},{"w":"refroidir","p":"v.","cn":"（使）冷却、变凉；（喻）使冷淡、挫伤（热情）","ex":"Laissez refroidir le gâteau dix minutes avant de le démouler.","exCn":"先让蛋糕冷却十分钟再脱模。","th":"健康与身体"},{"w":"refuge","p":"n.m.","cn":"避难所、庇护所；（山间）小屋","ex":"Surpris par la tempête, les randonneurs ont passé la nuit dans un refuge.","exCn":"徒步者遭遇暴风雨，在山间小屋里过了一夜。","th":"居住与环境"},{"w":"refus","p":"n.m.","cn":"拒绝","ex":"Il a essuyé un refus de la banque pour son prêt immobilier.","exCn":"他申请房贷，被银行拒绝了。","th":"常用词"},{"w":"regard","p":"n.m.","cn":"目光、眼神；看法、视角","ex":"Elle a jeté un regard inquiet vers la porte.","exCn":"她不安地朝门口望了一眼。","th":"常用词"},{"w":"regret","p":"n.m.","cn":"遗憾、后悔","ex":"Il a quitté sa ville natale sans aucun regret.","exCn":"他毫无遗憾地离开了家乡。","th":"情绪与性格"},{"w":"regrouper","p":"v.","cn":"汇集、集中；合并；（se ~）聚在一起、联合起来","ex":"Ce site regroupe toutes les offres d'emploi de la région.","exCn":"这个网站汇集了本地区所有的招聘信息。","th":"常用词"},{"w":"rejeter","p":"v.","cn":"拒绝、驳回；排放、排出","ex":"Ses parents l'ont rejeté quand il a annoncé qu'il quittait l'université.","exCn":"他宣布退学后，父母不认他了。","th":"常用词"},{"w":"relativement","p":"adv.","cn":"相对地、比较","ex":"Ce téléphone est relativement récent : il a à peine deux ans.","exCn":"这部手机还算比较新，才用了不到两年。","th":"常用词"},{"w":"relier","p":"v.","cn":"连接、联系；装订（书籍）","ex":"Un nouveau pont reliera bientôt les deux rives du fleuve.","exCn":"一座新桥不久将把河的两岸连接起来。","th":"常用词"},{"w":"religieux","p":"adj.","cn":"宗教的；虔诚的","ex":"Dans ce quartier, il y a plusieurs bâtiments religieux : une église, une mosquée et une synagogue.","exCn":"这个街区有好几座宗教建筑：一座教堂、一座清真寺和一座犹太会堂。","th":"常用词"},{"w":"remarque","p":"n.f.","cn":"评论、意见","ex":"Il fait toujours des remarques sur ce que je mange, ça m'énerve.","exCn":"他总对我吃什么说三道四，真让我烦。","th":"观点与论证"},{"w":"remarquer","p":"v.","cn":"注意到、察觉；（faire ~）指出、提醒","ex":"Mon collègue m'a fait remarquer que j'avais oublié de signer le formulaire.","exCn":"同事提醒我，表格上我忘了签名。","th":"常用词"},{"w":"remboursable","p":"adj.","cn":"可退款的、可报销的；（贷款）可偿还的","ex":"Ce billet de train n'est pas remboursable.","exCn":"这张火车票不能退款。","th":"购物与金钱"},{"w":"remboursement","p":"n.m.","cn":"退款、报销；偿还、还款","ex":"J'attends toujours le remboursement de mon billet d'avion.","exCn":"我还在等机票的退款。","th":"常用词"},{"w":"rembourser","p":"v.","cn":"偿还；退款、报销","ex":"Il lui faudra dix ans pour rembourser son prêt étudiant.","exCn":"他得花十年才能还清学生贷款。","th":"常用词"},{"w":"remerciement","p":"n.m.","cn":"感谢、谢意","ex":"Il est parti sans un mot de remerciement.","exCn":"他连句谢谢都没说就走了。","th":"常用词"},{"w":"remettre","p":"v.","cn":"交给、递交；放回（原处）、重新穿上；（~ à plus tard）推迟；（se ~ de）从…中恢复","ex":"J'ai remis les clés de l'appartement au propriétaire le jour du déménagement.","exCn":"搬家那天，我把公寓钥匙交给了房东。","th":"描述与状态"},{"w":"remise","p":"n.f.","cn":"折扣、优惠；交付、颁发；（放工具等的）储物棚、小仓库","ex":"Le magasin offre une remise de 20 % aujourd'hui.","exCn":"这家店今天优惠20%。","th":"描述与状态"},{"w":"remonter","p":"v.","cn":"再上去、回到上面；回升；（~ à）追溯到；（~ le moral）使振作","ex":"Cette tradition remonte au Moyen Âge.","exCn":"这个传统可以追溯到中世纪。","th":"常用词"},{"w":"remplacement","p":"n.m.","cn":"替换、更换；代理、代班","ex":"Le remplacement des vieilles fenêtres permettra de réduire la facture de chauffage.","exCn":"更换旧窗户可以降低暖气费。","th":"常用词"},{"w":"remplaçant","p":"n.","cn":"替补（队员）、接替者；代课老师、代班的人","ex":"Notre professeur est malade, c'est une remplaçante qui fait le cours cette semaine.","exCn":"我们老师病了，这周由一位代课老师来上课。","th":"工作与学习"},{"w":"remporter","p":"v.","cn":"赢得、夺得（比赛、选举等）；带回、拿走","ex":"Notre école a remporté le concours de robotique de la province.","exCn":"我们学校赢得了全省机器人大赛。","th":"社会与新闻"},{"w":"remède","p":"n.m.","cn":"药、疗法；（~ à）对策、解决办法","ex":"Le rire est le meilleur des remèdes.","exCn":"笑是最好的良药。","th":"健康与身体"},{"w":"renard","p":"n.m.","cn":"狐狸；狡猾的人","ex":"Un renard s'est introduit cette nuit dans le poulailler du voisin.","exCn":"昨天夜里，一只狐狸钻进了邻居家的鸡舍。","th":"人物与身份"},{"w":"renoncer","p":"v.","cn":"（~ à）放弃、打消（念头）","ex":"Après sa blessure, elle a dû renoncer à son rêve de devenir danseuse.","exCn":"受伤之后，她不得不放弃了当舞蹈演员的梦想。","th":"常用词"},{"w":"renoncer à","p":"v.","cn":"放弃","ex":"Il a renoncé à son projet.","exCn":"他放弃了自己的计划。","th":"工作与学习"},{"w":"renouvelable","p":"adj.","cn":"可再生的；可续期的","ex":"Le pays investit massivement dans les énergies renouvelables.","exCn":"该国大力投资可再生能源。","th":"常用词"},{"w":"renouveler","p":"v.","cn":"更新、换新；续签、续期","ex":"Mon bail se termine en juin, mais je vais le renouveler pour un an.","exCn":"我的租约六月到期，不过我会再续一年。","th":"描述与状态"},{"w":"renouvellement","p":"n.m.","cn":"（证件、合同）续签、更新；更替、换新","ex":"Le renouvellement du passeport prend environ dix jours.","exCn":"护照续签大约需要十天。","th":"描述与状态"},{"w":"renverser","p":"v.","cn":"打翻；撞倒；推翻","ex":"Le serveur a renversé du café sur ma chemise.","exCn":"服务员打翻了咖啡，洒在了我的衬衫上。","th":"日常动作"},{"w":"renvoyer","p":"v.","cn":"退回、寄回；开除、辞退；（~ à）参见、让…去查阅","ex":"Le colis était abîmé, alors je l'ai renvoyé au vendeur.","exCn":"包裹破损了，所以我把它退回给了卖家。","th":"常用词"},{"w":"reparler","p":"v.","cn":"（~ de）再谈、重提；（~ à）重新和…说话","ex":"On en reparlera demain, je suis trop fatiguée ce soir.","exCn":"我们明天再谈吧，我今晚太累了。","th":"描述与状态"},{"w":"repeindre","p":"v.","cn":"重新粉刷、重新上漆","ex":"Nous allons repeindre la cuisine en blanc.","exCn":"我们打算把厨房重新刷成白色。","th":"描述与状态"},{"w":"repenser","p":"v.","cn":"重新考虑、重新设计；（~ à）回想起、又想到","ex":"La ville veut repenser l'aménagement du centre-ville pour les piétons.","exCn":"市政府想为行人重新规划市中心。","th":"描述与状态"},{"w":"reportage","p":"n.m.","cn":"新闻报道、专题报道","ex":"J'ai vu un reportage passionnant sur la fonte des glaciers.","exCn":"我看了一篇关于冰川融化的精彩专题报道。","th":"社会与新闻"},{"w":"reporter","p":"v.","cn":"推迟、延期；（se ~ à）参阅、参看；cf. le / la reporter /ʁəpɔʁtɛʁ/ = 记者","ex":"Faute de budget, les travaux du pont ont été reportés à l'été prochain.","exCn":"由于预算不足，桥梁工程推迟到了明年夏天。","th":"日常动作"},{"w":"reporter #2","p":"n.","cn":"记者；cf. 动词 reporter /ʁəpɔʁte/ = 推迟、改期","ex":"Un reporter de la télévision locale a interviewé les habitants après l'incendie.","exCn":"火灾发生后，当地电视台的一名记者采访了居民。","th":"日常动作"},{"w":"reposé","p":"adj.","cn":"休息好的、精神饱满的；（à tête ~e）冷静地","ex":"Après une bonne nuit, je me sens bien reposé.","exCn":"睡了个好觉，我感觉精神饱满。","th":"居住与环境"},{"w":"repousser","p":"v.","cn":"推迟；推开；拒绝；（头发、植物）重新长出","ex":"La réunion a été repoussée à la semaine prochaine.","exCn":"会议被推迟到下周了。","th":"描述与状态"},{"w":"reproche","p":"n.m.","cn":"责备、指责","ex":"Ses parents lui ont fait des reproches parce qu'il était rentré tard.","exCn":"他回家晚了，父母责备了他。","th":"常用词"},{"w":"reprocher","p":"v.","cn":"责备、指责","ex":"Ma mère me reproche de passer trop de temps sur mon téléphone.","exCn":"我妈妈怪我在手机上花的时间太多。","th":"常用词"},{"w":"représentant","p":"n.","cn":"代表；（商业）推销员","ex":"Chaque classe élit un représentant au conseil des élèves.","exCn":"每个班选出一名代表进入学生会。","th":"日常动作"},{"w":"représenter","p":"v.","cn":"代表；描绘、表现；占（比例）、意味着","ex":"Que représente ce tableau ?","exCn":"这幅画画的是什么？","th":"常用词"},{"w":"repérer","p":"v.","cn":"发现、认出、找到","ex":"J'ai repéré un petit restaurant italien près de la gare.","exCn":"我在火车站附近发现了一家意大利小餐馆。","th":"常用词"},{"w":"requin","p":"n.m.","cn":"鲨鱼","ex":"La plage a été fermée après qu'on a aperçu un requin près du rivage.","exCn":"有人在岸边附近看到一条鲨鱼后，海滩被关闭了。","th":"饮食"},{"w":"respect","p":"n.m.","cn":"尊重、尊敬","ex":"Il a toujours parlé de ses parents avec beaucoup de respect.","exCn":"他谈起父母时总是充满敬意。","th":"描述与状态"},{"w":"respectueux","p":"adj.","cn":"恭敬的、有礼貌的；（~ de）尊重…的","ex":"Les élèves doivent rester respectueux envers leurs enseignants.","exCn":"学生对老师应当始终保持尊敬。","th":"交际与礼貌"},{"w":"respiration","p":"n.f.","cn":"呼吸","ex":"Pour vous détendre, essayez quelques exercices de respiration.","exCn":"想放松的话，试着做几组呼吸练习。","th":"健康与身体"},{"w":"responsabilité","p":"n.f.","cn":"责任；（复数）职责、职务","ex":"La direction décline toute responsabilité en cas de vol dans les vestiaires.","exCn":"如更衣室发生失窃，管理方概不负责。","th":"常用词"},{"w":"ressentir","p":"v.","cn":"感受到","ex":"Après l'opération, il ressentait encore une légère douleur au genou.","exCn":"手术后，他的膝盖还隐隐作痛。","th":"常用词"},{"w":"ressortir","p":"v.","cn":"再出去、又出来；突出、醒目；（il ~ de…）由…可见","ex":"Je suis rentrée à six heures, mais je suis ressortie pour faire des courses.","exCn":"我六点回到家，后来又出门买东西了。","th":"常用词"},{"w":"ressource","p":"n.f.","cn":"资源；（复数）收入、生活来源","ex":"Le Canada est riche en ressources naturelles.","exCn":"加拿大自然资源丰富。","th":"购物与金钱"},{"w":"restant","p":"adj.","cn":"剩下的","ex":"Les places restantes seront vendues à l'entrée.","exCn":"剩下的座位将在入口处出售。","th":"常用词"},{"w":"restauration","p":"n.f.","cn":"餐饮业；修复、整修","ex":"Le secteur de la restauration a du mal à recruter des serveurs.","exCn":"餐饮业很难招到服务员。","th":"饮食"},{"w":"retarder","p":"v.","cn":"推迟、延误；（钟表）走慢","ex":"Les travaux ont retardé de six mois l'ouverture de la nouvelle piscine.","exCn":"施工让新游泳池的开放推迟了六个月。","th":"描述与状态"},{"w":"retenir","p":"v.","cn":"记住；留住、拦住；（申请、方案）选中、采纳；（se ~）忍住","ex":"J'ai du mal à retenir les noms de mes nouveaux collègues.","exCn":"我总记不住新同事的名字。","th":"居住与环境"},{"w":"retrait","p":"n.m.","cn":"撤出、撤回；取款、提取","ex":"Le retrait des troupes est prévu pour la fin de l'année.","exCn":"撤军计划在年底进行。","th":"常用词"},{"w":"revendre","p":"v.","cn":"转卖、转售；（à ~）有的是、富余","ex":"Avant de déménager, j'ai revendu mon vélo sur Internet.","exCn":"搬家前，我把自行车在网上转卖了。","th":"购物与金钱"},{"w":"revenu","p":"n.m.","cn":"收入、所得","ex":"Leurs revenus ont baissé depuis la crise.","exCn":"危机以来，他们的收入减少了。","th":"购物与金钱"},{"w":"revue","p":"n.f.","cn":"期刊、杂志；cf. passer en revue 逐一检查、审视","ex":"Il écrit régulièrement des articles pour une revue d'histoire.","exCn":"他经常给一本历史期刊写文章。","th":"常用词"},{"w":"reçu","p":"n.m.","cn":"收据、收条；（考试）通过的、被录取的；cf. idée reçue 成见、固有观念","ex":"Gardez bien le reçu, il vous servira de preuve d'achat.","exCn":"请保管好收据，它可以作为购物凭证。","th":"工作与学习"},{"w":"rhum","p":"n.m.","cn":"朗姆酒；cf. le rhume 感冒（易混）","ex":"Pour le gâteau, ajoutez une cuillère à soupe de rhum à la pâte.","exCn":"做蛋糕时，往面糊里加一汤匙朗姆酒。","th":"饮食"},{"w":"richesse","p":"n.f.","cn":"财富；丰富、富饶","ex":"Le pétrole est la principale richesse de ce pays.","exCn":"石油是这个国家最主要的财富。","th":"描述与状态"},{"w":"ride","p":"n.f.","cn":"皱纹","ex":"Avec les années, une ride profonde s'est creusée sur son front.","exCn":"随着岁月流逝，他的额头上出现了一道深深的皱纹。","th":"常用词"},{"w":"ridicule","p":"adj.","cn":"可笑的、荒谬的；（金额等）少得可怜的","ex":"Il avait peur d'avoir l'air ridicule avec son nouveau chapeau.","exCn":"他怕戴着新帽子会显得很可笑。","th":"常用词"},{"w":"rigoler","p":"v.","cn":"笑、玩得开心（口语）；开玩笑（口语）","ex":"On a bien rigolé à la fête d'anniversaire de Julie.","exCn":"我们在朱莉的生日派对上玩得很开心。","th":"情绪与性格"},{"w":"rigolo","p":"adj.","cn":"好笑的、有趣的、逗的（口语）","ex":"Ton petit frère est vraiment rigolo quand il imite le prof.","exCn":"你弟弟模仿老师的时候真逗。","th":"情绪与性格"},{"w":"rincer","p":"v.","cn":"冲洗、漂洗（餐具、衣物、蔬菜等）；（se ~）冲洗身体、漱（口）","ex":"Après la piscine, je me rince toujours sous la douche.","exCn":"游完泳后，我总会冲个澡。","th":"饮食"},{"w":"risque","p":"n.m.","cn":"风险、危险","ex":"Il y a un risque d'orages en fin de journée, alors on reporte le barbecue.","exCn":"傍晚可能有雷暴，所以我们把烧烤改期了。","th":"居住与环境"},{"w":"risquer","p":"v.","cn":"冒…的风险；（~ de）有可能、恐怕会","ex":"Les pompiers ont risqué leur vie pour sauver les habitants de l'immeuble.","exCn":"消防员冒着生命危险救出了楼里的居民。","th":"居住与环境"},{"w":"risqué","p":"adj.","cn":"冒险的、有风险的；（玩笑等）大胆的、露骨的","ex":"Investir tout ton argent là-dedans, c'est trop risqué.","exCn":"把你所有的钱都投进去，风险太大了。","th":"居住与环境"},{"w":"rive","p":"n.f.","cn":"（河、湖）岸","ex":"Nous avons marché le long de la rive jusqu'au vieux moulin.","exCn":"我们沿着河岸一直走到那座老磨坊。","th":"常用词"},{"w":"roche","p":"n.f.","cn":"岩石；（魁北克）石头、石块","ex":"Ces falaises sont formées d'une roche calcaire très ancienne.","exCn":"这些悬崖由一种非常古老的石灰岩构成。","th":"常用词"},{"w":"rocher","p":"n.m.","cn":"岩石、大石块；礁石","ex":"Les enfants cherchent des crabes entre les rochers.","exCn":"孩子们在礁石间找螃蟹。","th":"描述与状态"},{"w":"romain","p":"adj.","cn":"罗马的、古罗马的","ex":"Sur cette vieille horloge, les heures sont indiquées en chiffres romains.","exCn":"这座老钟上的时间是用罗马数字标的。","th":"常用词"},{"w":"romancier","p":"n.","cn":"小说家","ex":"Ma romancière préférée écrit surtout des romans policiers.","exCn":"我最喜欢的那位女小说家主要写侦探小说。","th":"描述与状态"},{"w":"rosé","p":"n.m.","cn":"（葡萄酒）桃红的；淡粉红色的；桃红葡萄酒","ex":"En été, on boit souvent du vin rosé bien frais.","exCn":"夏天人们常喝冰镇的桃红葡萄酒。","th":"饮食"},{"w":"rougir","p":"v.","cn":"脸红；变红","ex":"Elle rougit chaque fois qu'on lui fait un compliment.","exCn":"每次有人夸她，她都会脸红。","th":"描述与状态"},{"w":"roulant","p":"adj.","cn":"带轮子的、滚动的；cf. fauteuil roulant 轮椅；escalier roulant 自动扶梯；tapis roulant 传送带、跑步机","ex":"Depuis son accident, il se déplace en fauteuil roulant.","exCn":"出事以后，他一直坐轮椅出行。","th":"日常动作"},{"w":"rouleau","p":"n.m.","cn":"卷、卷筒；滚筒、滚子","ex":"Elle a utilisé trois rouleaux de papier cadeau pour emballer les jouets de Noël.","exCn":"她用了三卷礼品纸来包圣诞玩具。","th":"常用词"},{"w":"routier","p":"n.","cn":"公路的、道路的；长途卡车司机","ex":"Avant les vacances, le gouvernement lance une campagne de sécurité routière.","exCn":"假期前，政府开展了一场交通安全宣传活动。","th":"出行与旅行"},{"w":"routine","p":"n.f.","cn":"惯例、常规；（单调的）日常生活","ex":"Ne vous inquiétez pas, c'est un simple contrôle de routine.","exCn":"别担心，这只是例行检查。","th":"常用词"},{"w":"rouvrir","p":"v.","cn":"重新打开；重新开放、恢复营业；重启（讨论、调查）","ex":"La piscine municipale rouvrira ses portes le 1er juin après six mois de travaux.","exCn":"市立游泳池施工半年后，将于6月1日重新开放。","th":"观点与论证"},{"w":"royal","p":"adj.","cn":"王室的、皇家的；（喻）极好的、隆重的","ex":"La famille royale britannique est très suivie par les médias.","exCn":"英国王室备受媒体关注。","th":"居住与环境"},{"w":"royaume","p":"n.m.","cn":"王国","ex":"Le Royaume-Uni a quitté l'Union européenne en 2020.","exCn":"英国（联合王国）于2020年脱离了欧盟。","th":"常用词"},{"w":"rubrique","p":"n.f.","cn":"（报刊）栏目、专栏；类别、条目","ex":"Je lis toujours d'abord la rubrique des sports.","exCn":"我总是先看体育栏目。","th":"常用词"},{"w":"ruelle","p":"n.f.","cn":"小巷、胡同","ex":"Le café se trouve dans une petite ruelle derrière la cathédrale.","exCn":"那家咖啡馆在大教堂后面的一条小巷里。","th":"描述与状态"},{"w":"ruine","p":"n.f.","cn":"破产、毁灭；（复数）废墟、遗址","ex":"Cette crise a conduit de nombreux petits commerces à la ruine.","exCn":"这场危机让许多小商家破产了。","th":"常用词"},{"w":"ruisseau","p":"n.m.","cn":"小溪","ex":"Un petit ruisseau traverse le terrain derrière notre chalet.","exCn":"我们木屋后面的那块地上有一条小溪流过。","th":"描述与状态"},{"w":"rumeur","p":"n.f.","cn":"谣言、传闻","ex":"Je me demande si cette rumeur est vraie.","exCn":"我不知道这个传闻是不是真的。","th":"常用词"},{"w":"rural","p":"adj.","cn":"农村的、乡村的","ex":"Elle a grandi dans une petite commune rurale.","exCn":"她在一个小乡镇长大。","th":"居住与环境"},{"w":"rythme","p":"n.m.","cn":"节奏；速度、步调","ex":"J'aime cette chanson pour son rythme entraînant.","exCn":"我喜欢这首歌，因为它节奏明快。","th":"常用词"},{"w":"râler","p":"v.","cn":"发牢骚、抱怨（口语）；cf. chialer 发牢骚（魁北克口语）","ex":"Mon père râle chaque fois qu'il doit payer le stationnement en ville.","exCn":"我爸每次在市区付停车费都要发牢骚。","th":"常用词"},{"w":"râper","p":"v.","cn":"擦成丝、磨碎","ex":"Râpe un peu de parmesan sur les pâtes.","exCn":"在意面上擦点帕尔马干酪。","th":"常用词"},{"w":"règlement","p":"n.m.","cn":"规章、规定；支付、结算；（争端的）解决","ex":"Le règlement du concours est disponible sur notre site.","exCn":"比赛规则可以在我们的网站上查看。","th":"购物与金钱"},{"w":"réaction","p":"n.f.","cn":"反应、回应","ex":"J'ai eu une réaction allergique après avoir mangé des crevettes.","exCn":"我吃了虾之后出现了过敏反应。","th":"常用词"},{"w":"réagir","p":"v.","cn":"作出反应、回应","ex":"Comment as-tu réagi quand tu as appris la nouvelle ?","exCn":"你听到这个消息时是什么反应？","th":"常用词"},{"w":"réalisation","p":"n.f.","cn":"实现、完成；（影视）执导、制作","ex":"La réalisation de ce projet prendra au moins trois ans.","exCn":"这个项目至少需要三年才能完成。","th":"常用词"},{"w":"réaliser","p":"v.","cn":"实现、完成；意识到；执导、拍摄（电影）","ex":"Elle a enfin réalisé son rêve d'ouvrir une boulangerie.","exCn":"她终于实现了开一家面包店的梦想。","th":"常用词"},{"w":"réaliste","p":"adj.","cn":"现实的、切合实际的；写实的、逼真的","ex":"Il faut se fixer des objectifs réalistes si l'on veut réussir le TCF.","exCn":"想通过TCF，就得给自己定切合实际的目标。","th":"日常动作"},{"w":"récent","p":"adj.","cn":"最近的、新近的","ex":"Les photos les plus récentes de mon téléphone ont disparu après la mise à jour.","exCn":"手机更新之后，我最近拍的那些照片都不见了。","th":"描述与状态"},{"w":"réchauffement","p":"n.m.","cn":"变暖、升温","ex":"Ce réchauffement soudain a fait fondre toute la neige en deux jours.","exCn":"这次突然回暖，两天就把雪全化光了。","th":"常用词"},{"w":"réchauffer","p":"v.","cn":"使暖和；（se ~）取暖、暖和身子；（重新）加热（食物）","ex":"Viens te réchauffer au coin du feu.","exCn":"快到炉火边来暖和暖和吧。","th":"居住与环境"},{"w":"réchauffé","p":"adj.","cn":"重新加热的、热过的；（口语）老调重弹的、炒冷饭的","ex":"Ce soir, on mange les restes réchauffés.","exCn":"今晚我们吃热过的剩菜。","th":"饮食"},{"w":"récit","p":"n.m.","cn":"叙述、讲述；故事、记叙文","ex":"Il nous a fait le récit de son voyage.","exCn":"他给我们讲述了他的旅行经历。","th":"常用词"},{"w":"réciter","p":"v.","cn":"背诵、朗诵","ex":"Chaque élève doit réciter un poème devant la classe.","exCn":"每个学生都要在全班面前背诵一首诗。","th":"常用词"},{"w":"réclamation","p":"n.f.","cn":"投诉、申诉；索赔、理赔申请","ex":"J'ai fait une réclamation auprès du service client.","exCn":"我向客服提出了投诉。","th":"交际与礼貌"},{"w":"réclamer","p":"v.","cn":"要求、索要；需要（时间、耐心等）","ex":"Après l'annulation du spectacle, de nombreux spectateurs ont réclamé le remboursement de leurs billets.","exCn":"演出取消后，许多观众要求退还票款。","th":"情绪与性格"},{"w":"récolte","p":"n.f.","cn":"收成、收获","ex":"Notre petit potager nous a donné une belle récolte de tomates cet été.","exCn":"今年夏天，我们的小菜园收获了不少西红柿。","th":"常用词"},{"w":"récompense","p":"n.f.","cn":"奖赏、报酬","ex":"Les propriétaires offrent une récompense à la personne qui retrouvera leur chien.","exCn":"狗主人悬赏：谁找回他们的狗，就给予酬谢。","th":"常用词"},{"w":"récompenser","p":"v.","cn":"奖励、酬谢","ex":"Pour récompenser les enfants de leur patience, on les a emmenés manger une glace.","exCn":"为了奖励孩子们的耐心，我们带他们去吃了冰淇淋。","th":"常用词"},{"w":"récupérer","p":"v.","cn":"取回、拿回；接（人）（口语）；恢复（体力）","ex":"Je dois passer récupérer mon colis au bureau de poste avant 18 h.","exCn":"我得在18点前去邮局取包裹。","th":"人物与身份"},{"w":"rédacteur","p":"n.","cn":"编辑、撰稿人；cf. le rédacteur en chef 主编","ex":"Il travaille comme rédacteur pour un site d'information.","exCn":"他在一家新闻网站当撰稿人。","th":"人物与身份"},{"w":"rédaction","p":"n.f.","cn":"撰写、起草；（学生的）作文；编辑部","ex":"La rédaction du rapport annuel m'a pris toute la semaine.","exCn":"写年度报告花了我整整一周。","th":"工作与学习"},{"w":"rédiger","p":"v.","cn":"撰写、起草","ex":"À l'examen, les candidats doivent rédiger un texte argumentatif en une heure.","exCn":"考试中，考生须在一小时内写完一篇议论文。","th":"常用词"},{"w":"réduire","p":"v.","cn":"减少；降低","ex":"L'entreprise a réduit ses déchets.","exCn":"这家企业减少了垃圾。","th":"社会与新闻"},{"w":"réduit","p":"adj.","cn":"降低的、优惠的；有限的、少的；cf. personne à mobilité réduite（PMR）行动不便者","ex":"La visibilité est très réduite à cause du brouillard.","exCn":"因为有雾，能见度很低。","th":"描述与状态"},{"w":"réel","p":"adj.","cn":"真实的、实际的","ex":"Avec les taxes, le prix réel du billet est presque le double du prix affiché.","exCn":"加上税费，这张票的实际价格几乎是标价的两倍。","th":"常用词"},{"w":"réellement","p":"adv.","cn":"真正地、确实、实际上","ex":"Cette application permet-elle réellement d'économiser de l'énergie ?","exCn":"这个应用真的能节省能源吗？","th":"常用词"},{"w":"réflexion","p":"n.f.","cn":"思考、考虑；评论、议论","ex":"Après mûre réflexion, j'ai décidé de refuser cette offre d'emploi.","exCn":"经过深思熟虑，我决定拒绝这份工作邀请。","th":"常用词"},{"w":"réforme","p":"n.f.","cn":"改革","ex":"Depuis la réforme du bac, les élèves choisissent leurs spécialités dès la première.","exCn":"自从高中会考改革以来，学生从高二起就要选定专业方向课程。","th":"社会与新闻"},{"w":"réfugié","p":"n.","cn":"难民；避难的、流亡的","ex":"Le pays a accueilli des milliers de réfugiés.","exCn":"该国接收了数千名难民。","th":"常用词"},{"w":"référence","p":"n.f.","cn":"参考、参照；出处、参考文献；（复数，求职）推荐人；cf. faire référence à 提到、援引","ex":"Dans son discours, la ministre a fait référence au dernier rapport sur le climat.","exCn":"部长在讲话中援引了最新的气候报告。","th":"人物与身份"},{"w":"régional","p":"adj.","cn":"地区的、地方的","ex":"J'ai pris le train régional jusqu'à Rouen : c'est moins cher que le TGV.","exCn":"我坐地区列车去了鲁昂，比坐TGV高铁便宜。","th":"居住与环境"},{"w":"régulier","p":"adj.","cn":"有规律的、定期的；合乎规定的、正规的；（魁北克）普通的、常规的（prix ~ 原价）","ex":"Mon médecin m'a conseillé un suivi régulier de ma tension.","exCn":"医生建议我定期监测血压。","th":"购物与金钱"},{"w":"rénovation","p":"n.f.","cn":"翻新、整修；革新、更新","ex":"Nous avons obtenu une subvention pour la rénovation énergétique de notre maison.","exCn":"我们申请到了一笔补贴，用来给房子做节能改造。","th":"描述与状态"},{"w":"rénover","p":"v.","cn":"翻新、整修；革新、改革","ex":"La ville va rénover toutes les écoles du quartier cet été.","exCn":"今年夏天，市政府要翻修街区里所有的学校。","th":"社会与新闻"},{"w":"réparateur","p":"n.","cn":"修理工；（睡眠等）恢复精力的、消除疲劳的","ex":"Le réparateur passera demain pour la machine à laver.","exCn":"修理工明天会来修洗衣机。","th":"健康与身体"},{"w":"réparation","p":"n.f.","cn":"修理、维修；赔偿、补偿","ex":"Ma voiture est en réparation au garage jusqu'à vendredi.","exCn":"我的车在修车厂修，要到周五才能取。","th":"常用词"},{"w":"républicain","p":"adj.","cn":"共和的、共和国的；共和党的","ex":"Ils défendent les valeurs républicaines de la France.","exCn":"他们捍卫法国的共和价值观。","th":"常用词"},{"w":"réputation","p":"n.f.","cn":"名声、声誉","ex":"Ce restaurant a une excellente réputation dans le quartier.","exCn":"这家餐厅在街坊中口碑极好。","th":"常用词"},{"w":"répétition","p":"n.f.","cn":"重复；排练、排演","ex":"La répétition est essentielle pour apprendre du vocabulaire.","exCn":"重复对记单词至关重要。","th":"描述与状态"},{"w":"réseau","p":"n.m.","cn":"网络；（地下）组织、团伙；（手机）信号","ex":"Le réseau de métro de Montréal compte quatre lignes.","exCn":"蒙特利尔的地铁网共有四条线路。","th":"社会与新闻"},{"w":"réseaux sociaux","p":"n.m.pl.","cn":"社交媒体","ex":"Les réseaux sociaux changent la façon de s'informer.","exCn":"社交媒体改变了人们获取信息的方式。","th":"社会与新闻"},{"w":"réserve","p":"n.f.","cn":"储备、库存；保留、保留意见；（自然）保护区、（原住民）保留地","ex":"Il nous reste des réserves de nourriture pour une semaine.","exCn":"我们剩下的食物储备还够一周。","th":"居住与环境"},{"w":"résider","p":"v.","cn":"居住；（~ dans）在于","ex":"Pour obtenir cette aide, il faut résider au Québec depuis au moins un an.","exCn":"要申请这项补助，必须在魁北克居住满一年。","th":"居住与环境"},{"w":"résistance","p":"n.f.","cn":"抵抗、反抗；抵抗力、耐力","ex":"Les employés ont opposé une forte résistance au nouveau règlement.","exCn":"员工们强烈抵制新规定。","th":"常用词"},{"w":"résistant","p":"adj.","cn":"结实的、耐用的；（~ à）耐…的、抗…的","ex":"Pour la randonnée, choisissez des chaussures légères mais résistantes.","exCn":"徒步时，要选轻便又结实的鞋。","th":"常用词"},{"w":"résister","p":"v.","cn":"抵抗、反抗；经受住、耐（热等）","ex":"Il n'a pas pu résister à la tentation de manger un dernier morceau de gâteau.","exCn":"他没能抵挡住诱惑，又吃了最后一块蛋糕。","th":"居住与环境"},{"w":"résoudre","p":"v.","cn":"解决、解答；（se ~ à）下决心","ex":"Le technicien a résolu le problème en moins d'une heure.","exCn":"技术员不到一个小时就解决了问题。","th":"常用词"},{"w":"résumer","p":"v.","cn":"概括、总结；（se ~ à）归结为","ex":"Pouvez-vous résumer cet article en quelques phrases ?","exCn":"您能用几句话概括一下这篇文章吗？","th":"常用词"},{"w":"résumé","p":"n.m.","cn":"概要、摘要","ex":"Lisez le texte, puis rédigez un résumé de 150 mots.","exCn":"阅读这篇文章，然后写一篇150词的摘要。","th":"常用词"},{"w":"réussite","p":"n.f.","cn":"成功","ex":"La fête des voisins a été une vraie réussite.","exCn":"这次邻里聚会办得非常成功。","th":"常用词"},{"w":"réveillon","p":"n.m.","cn":"（圣诞夜或除夕的）守夜晚宴","ex":"Nous passons le réveillon de Noël chez mes parents.","exCn":"我们在父母家过平安夜。","th":"时间与数量"},{"w":"réviser","p":"v.","cn":"复习；修订、调整；（车辆）检修、保养","ex":"Je dois réviser mes cours de chimie pour l'examen de vendredi.","exCn":"我得为周五的考试复习化学课的内容。","th":"出行与旅行"},{"w":"révision","p":"n.f.","cn":"修订、修改；复习；（汽车）保养、检修","ex":"Le gouvernement prépare une révision complète de la loi sur l'immigration.","exCn":"政府正在准备全面修订移民法。","th":"出行与旅行"},{"w":"révolution","p":"n.f.","cn":"革命、变革；cf. la Révolution tranquille 寂静革命（魁北克1960年代的社会变革）","ex":"Internet a provoqué une véritable révolution dans notre façon de travailler.","exCn":"互联网给我们的工作方式带来了一场真正的变革。","th":"时间与数量"},{"w":"révolutionnaire","p":"n.","cn":"革命的、革命性的；革命者","ex":"Cette entreprise a mis au point un traitement révolutionnaire contre le diabète.","exCn":"这家公司研发出了一种治疗糖尿病的革命性疗法。","th":"常用词"},{"w":"révéler","p":"v.","cn":"揭露、显示出；（se ~）原来是、证明是","ex":"Il a fini par révéler son secret à sa sœur.","exCn":"他最后把秘密告诉了姐姐。","th":"观点与论证"},{"w":"rôtir","p":"v.","cn":"烤、烘烤","ex":"J'aime faire rôtir des légumes au four.","exCn":"我喜欢把蔬菜放进烤箱烤。","th":"常用词"},{"w":"sachet","p":"n.m.","cn":"小袋、小包","ex":"Mettez un sachet de thé dans l'eau chaude.","exCn":"把一个茶包放进热水里。","th":"描述与状态"},{"w":"sacrifice","p":"n.m.","cn":"牺牲","ex":"Ses parents ont fait beaucoup de sacrifices pour lui payer ses études.","exCn":"他的父母为了供他上学做出了很多牺牲。","th":"常用词"},{"w":"sacré","p":"adj.","cn":"神圣的；（名词前）十足的、了不起的、该死的（口语）","ex":"Pour les habitants, cette montagne est un lieu sacré.","exCn":"对当地居民来说，这座山是一处圣地。","th":"常用词"},{"w":"s'adapter à","p":"v.","cn":"适应","ex":"Il faut s'adapter au nouveau rythme.","exCn":"需要适应新的节奏。","th":"工作与学习"},{"w":"saigner","p":"v.","cn":"流血、出血","ex":"Ses gencives saignent quand il se brosse les dents.","exCn":"他刷牙时牙龈会出血。","th":"健康与身体"},{"w":"sain","p":"adj.","cn":"健康的、有益健康的；健全的、合理的；cf. sain et sauf 安然无恙","ex":"Pour rester en forme, il faut avoir une alimentation saine.","exCn":"想保持好身体，饮食就要健康。","th":"健康与身体"},{"w":"saint","p":"n.","cn":"圣人、圣徒；神圣的；cf. la Saint-Jean 圣让节（6月24日，魁北克国庆节）","ex":"Jérusalem est un lieu saint pour trois religions.","exCn":"耶路撒冷是三大宗教的圣地。","th":"人物与身份"},{"w":"saisir","p":"v.","cn":"抓住；理解、领会；（电脑）输入、录入；（警方、海关）查获、扣押","ex":"Elle a saisi l'occasion de changer de carrière.","exCn":"她抓住机会转了行。","th":"居住与环境"},{"w":"saladier","p":"n.m.","cn":"沙拉碗、大碗","ex":"Mélangez tous les ingrédients dans un grand saladier.","exCn":"把所有配料放进一个大沙拉碗里拌匀。","th":"描述与状态"},{"w":"salarié","p":"n.","cn":"雇员、受薪者；受雇的、领工资的","ex":"L'entreprise compte environ deux cents salariés.","exCn":"这家公司大约有两百名员工。","th":"工作与学习"},{"w":"saleté","p":"n.f.","cn":"脏、污垢；（常复数）垃圾食品（口语）；讨厌的东西、破玩意儿（口语）","ex":"Après trois jours de camping, les enfants étaient couverts de saleté de la tête aux pieds.","exCn":"露营三天后，孩子们从头到脚都脏兮兮的。","th":"情绪与性格"},{"w":"salir","p":"v.","cn":"弄脏；玷污（名誉）","ex":"Enlève tes bottes, tu vas salir le plancher !","exCn":"把靴子脱了，你会把地板弄脏的！","th":"描述与状态"},{"w":"salière","p":"n.f.","cn":"盐瓶、盐罐","ex":"Le bouchon de la salière était mal vissé, et tout le sel est tombé dans ma soupe !","exCn":"盐瓶的盖子没拧紧，盐全掉进我的汤里了！","th":"饮食"},{"w":"sang","p":"n.m.","cn":"血、血液；血统；cf. Bon sang ! 天哪！（表示恼火、惊讶）；se faire du mauvais sang 担心、着急","ex":"Chaque don de sang peut sauver jusqu'à trois vies.","exCn":"每一次献血最多可以挽救三条生命。","th":"健康与身体"},{"w":"sans cesse","p":"adv.","cn":"不断地、不停地","ex":"Le téléphone sonne sans cesse depuis ce matin.","exCn":"从早上开始电话就响个不停。","th":"常用词"},{"w":"satellite","p":"n.m.","cn":"卫星","ex":"Le Canada a lancé un nouveau satellite pour surveiller les forêts du pays.","exCn":"加拿大发射了一颗新卫星，用来监测全国的森林。","th":"常用词"},{"w":"satisfaction","p":"n.f.","cn":"满意、满足","ex":"Terminer un puzzle de mille pièces procure une grande satisfaction.","exCn":"拼完一幅一千片的拼图会带来很大的满足感。","th":"描述与状态"},{"w":"satisfaire","p":"v.","cn":"使满意；满足（要求）","ex":"Ce nouveau service ne satisfait pas tous les clients.","exCn":"这项新服务并没有让所有顾客都满意。","th":"描述与状态"},{"w":"saut","p":"n.m.","cn":"跳跃；（faire un ~）顺便去一下（口语）","ex":"Le saut en longueur est mon épreuve préférée aux Jeux olympiques.","exCn":"跳远是我最喜欢的奥运项目。","th":"常用词"},{"w":"sauvegarder","p":"v.","cn":"（文件）保存、备份；保护、维护","ex":"N'oublie pas de sauvegarder ton document avant de fermer.","exCn":"关闭前别忘了保存你的文件。","th":"常用词"},{"w":"savoureux","p":"adj.","cn":"美味的、可口的；（故事等）有趣的、耐人寻味的","ex":"Ce petit restaurant propose des plats simples mais savoureux.","exCn":"这家小餐馆的菜简单却很可口。","th":"情绪与性格"},{"w":"saxophone","p":"n.m.","cn":"萨克斯管","ex":"Mon frère joue du saxophone dans un groupe de jazz.","exCn":"我哥哥在一个爵士乐队里吹萨克斯。","th":"常用词"},{"w":"science-fiction","p":"n.f.","cn":"科幻","ex":"J'adore les films de science-fiction.","exCn":"我很喜欢科幻电影。","th":"常用词"},{"w":"scolarité","p":"n.f.","cn":"学业、就学；（frais de ~）学费","ex":"La scolarité est obligatoire jusqu'à seize ans.","exCn":"十六岁之前必须上学。","th":"常用词"},{"w":"score","p":"n.m.","cn":"比分、得分","ex":"Le match s'est terminé sur le score de 3 à 1.","exCn":"比赛最终以3比1的比分结束。","th":"常用词"},{"w":"sculpteur","p":"n.","cn":"雕塑家、雕刻家","ex":"Ce sculpteur inuit travaille surtout la pierre à savon.","exCn":"这位因纽特雕刻家主要用皂石创作。","th":"常用词"},{"w":"sculpture","p":"n.f.","cn":"雕塑、雕刻","ex":"Le musée expose une sculpture en bronze de Rodin.","exCn":"博物馆正在展出一件罗丹的青铜雕塑。","th":"常用词"},{"w":"scène","p":"n.f.","cn":"场面、场景；舞台；cf. faire une scène (à qqn)（跟某人）大吵大闹","ex":"Des passants ont filmé la scène avec leur téléphone.","exCn":"路人用手机拍下了这一幕。","th":"人物与身份"},{"w":"se débrouiller","p":"v.","cn":"应付；自己搞定","ex":"Ne t'inquiète pas, je me débrouille.","exCn":"别担心，我自己能搞定。","th":"社会与新闻"},{"w":"se démaquiller","p":"v.","cn":"卸妆","ex":"Elle se démaquille toujours avant de dormir.","exCn":"她睡前总会卸妆。","th":"常用词"},{"w":"se dérouler","p":"v.","cn":"举行、进行；（故事情节）发生","ex":"Le concert se déroulera samedi soir dans le parc.","exCn":"音乐会将于周六晚上在公园举行。","th":"常用词"},{"w":"se moquer de","p":"v.","cn":"嘲笑、取笑；不在乎","ex":"Les autres élèves se moquaient de lui à cause de son accent.","exCn":"其他学生因为他的口音而嘲笑他。","th":"常用词"},{"w":"se moucher","p":"v.","cn":"擤鼻涕","ex":"Il s'est mouché bruyamment pendant le concert.","exCn":"他在音乐会上大声地擤鼻涕。","th":"常用词"},{"w":"se méfier","p":"v.","cn":"（~ de）提防、不信任","ex":"Méfie-toi des inconnus sur Internet.","exCn":"要提防网上的陌生人。","th":"常用词"},{"w":"se parfumer","p":"v.","cn":"喷香水","ex":"Elle se parfume toujours avant de sortir.","exCn":"她出门前总要喷点香水。","th":"常用词"},{"w":"se plaindre de","p":"v.","cn":"抱怨","ex":"Les clients se plaignent du bruit.","exCn":"客户抱怨噪音。","th":"情绪与性格"},{"w":"se recoiffer","p":"v.","cn":"重新梳头","ex":"Avec ce vent, je vais devoir me recoiffer avant la réunion.","exCn":"风这么大，开会前我得重新梳一下头。","th":"描述与状态"},{"w":"se remarier","p":"v.","cn":"再婚","ex":"Après son divorce, elle s'est remariée avec un collègue.","exCn":"离婚后，她和一位同事再婚了。","th":"常用词"},{"w":"se régaler","p":"v.","cn":"吃得开心、大饱口福；尽情享受","ex":"Le buffet était à volonté, et tout le monde s'est régalé.","exCn":"自助餐随便吃，大家都吃得很过瘾。","th":"饮食"},{"w":"seau","p":"n.m.","cn":"桶、水桶","ex":"Remplis le seau d'eau savonneuse pour laver la voiture.","exCn":"往桶里装满肥皂水，用来洗车。","th":"常用词"},{"w":"second","p":"adj.","cn":"第二的；cf. la seconde 秒；deuxième 第二（日常更常用）","ex":"Tout le monde mérite une seconde chance.","exCn":"每个人都应该有第二次机会。","th":"时间与数量"},{"w":"secondaire","p":"adj.","cn":"次要的；（教育）中等的；cf. le secondaire（魁北克）中学（阶段）","ex":"Ce détail est secondaire, concentrons-nous sur l'essentiel.","exCn":"这个细节是次要的，我们先抓重点。","th":"社会与新闻"},{"w":"secouer","p":"v.","cn":"摇晃、抖动；（喻）使震惊","ex":"Secouez bien le flacon avant chaque utilisation.","exCn":"每次使用前请把瓶子充分摇匀。","th":"常用词"},{"w":"secours","p":"n.m.","cn":"救援、援助；（les ~）救援人员；（de ~）备用的、应急的；cf. Au secours ! 救命！；les premiers secours 急救","ex":"Les secours sont arrivés sur place dix minutes après l'accident.","exCn":"事故发生十分钟后，救援人员赶到了现场。","th":"人物与身份"},{"w":"secrètement","p":"adv.","cn":"秘密地、暗中","ex":"Ils se sont mariés secrètement à Las Vegas.","exCn":"他们在拉斯维加斯秘密结了婚。","th":"描述与状态"},{"w":"secrétariat","p":"n.m.","cn":"秘书处、办公室；秘书工作","ex":"Pour obtenir votre relevé de notes, adressez-vous au secrétariat de la faculté.","exCn":"要拿成绩单，请到学院办公室办理。","th":"工作与学习"},{"w":"secteur","p":"n.m.","cn":"部门、行业；区域、地段","ex":"Elle a quitté le secteur privé pour devenir enseignante, et elle gagne deux fois moins.","exCn":"她离开私营部门当了老师，收入少了一半。","th":"居住与环境"},{"w":"section","p":"n.f.","cn":"部分、段落；部门、分部","ex":"Vous trouverez les réponses aux questions fréquentes dans la section « Aide » du site.","exCn":"常见问题的答案可以在网站的“帮助”栏目中找到。","th":"常用词"},{"w":"semelle","p":"n.f.","cn":"鞋底；鞋垫","ex":"Ces baskets ont une semelle très épaisse, idéale pour marcher longtemps.","exCn":"这双运动鞋的鞋底很厚，非常适合长时间走路。","th":"常用词"},{"w":"semestre","p":"n.m.","cn":"半年；学期","ex":"Les cours du premier semestre commencent début septembre.","exCn":"第一学期的课九月初开始。","th":"时间与数量"},{"w":"s'enfuir","p":"v.","cn":"逃跑、逃走","ex":"Le voleur s'est enfui en voyant arriver la police.","exCn":"小偷一看到警察来了就跑了。","th":"日常动作"},{"w":"sens","p":"n.m.","cn":"意义、意思；方向；感官、感觉；cf. le bon sens 常识、理智","ex":"Ça n'a aucun sens de partir maintenant : il neige beaucoup trop.","exCn":"现在出发毫无意义，雪下得太大了。","th":"抽象与概念"},{"w":"sensation","p":"n.f.","cn":"感觉；（faire ~）引起轰动","ex":"Après le massage, j'ai eu une agréable sensation de détente.","exCn":"按摩之后，我有一种很舒服的放松感。","th":"常用词"},{"w":"sensible","p":"adj.","cn":"敏感的；明显的、显著的","ex":"Je suis très sensible à la chaleur.","exCn":"我非常怕热。","th":"常用词"},{"w":"sentier","p":"n.m.","cn":"小路、小径","ex":"Nous avons suivi un sentier à travers la forêt jusqu'à une cascade.","exCn":"我们沿着一条林间小路一直走到一处瀑布。","th":"出行与旅行"},{"w":"sentiment","p":"n.m.","cn":"感情、情感；感觉、印象","ex":"J'ai le sentiment qu'on nous cache quelque chose.","exCn":"我感觉有人在瞒着我们什么。","th":"常用词"},{"w":"sentimental","p":"adj.","cn":"感情的、情感上的；多愁善感的","ex":"Cette bague ne vaut pas grand-chose, mais elle a une grande valeur sentimentale pour moi.","exCn":"这枚戒指不值什么钱，但对我来说情感价值很大。","th":"常用词"},{"w":"s'envoler","p":"v.","cn":"飞走、起飞；（乘飞机）飞往；被风吹走；（价格）飞涨","ex":"Demain matin, je m'envole pour Paris avec toute ma famille.","exCn":"明天早上我和全家一起飞巴黎。","th":"出行与旅行"},{"w":"serre","p":"n.f.","cn":"温室、暖房","ex":"Mon père cultive des tomates dans une petite serre au fond du jardin.","exCn":"我父亲在花园尽头的一个小温室里种西红柿。","th":"居住与环境"},{"w":"serrer","p":"v.","cn":"握紧、捏紧；拧紧、收紧；（衣服、鞋）太紧、夹脚；（~ dans ses bras）拥抱；（魁北克）收好、放好（口语）","ex":"Il m'a serré la main très fort en me félicitant.","exCn":"他紧紧握住我的手，向我道贺。","th":"描述与状态"},{"w":"serrure","p":"n.f.","cn":"锁","ex":"La clé ne tourne plus dans la serrure, il faut appeler un serrurier.","exCn":"钥匙在锁里转不动了，得叫个锁匠来。","th":"常用词"},{"w":"serré","p":"adj.","cn":"紧的、紧身的；（时间、预算）紧张的、紧凑的；（比赛）势均力敌的","ex":"Ce pantalon est trop serré pour moi.","exCn":"这条裤子我穿太紧了。","th":"购物与金钱"},{"w":"serviable","p":"adj.","cn":"乐于助人的、热心的","ex":"Ma voisine est très serviable : elle arrose mes plantes quand je pars en vacances.","exCn":"我的邻居很热心，我去度假时她会帮我浇花。","th":"人物与身份"},{"w":"s'exclamer","p":"v.","cn":"惊呼、感叹、大声说","ex":"« Quelle vue magnifique ! » s'est exclamée ma mère en arrivant au sommet.","exCn":"“景色太美了！”妈妈登上山顶时惊叹道。","th":"功能词与连接"},{"w":"sexe","p":"n.m.","cn":"性别；性、性行为","ex":"Aucun candidat ne doit être écarté en raison de son sexe ou de son âge.","exCn":"任何求职者都不应因性别或年龄而被拒之门外。","th":"常用词"},{"w":"sexuel","p":"adj.","cn":"性的、性方面的","ex":"Le harcèlement sexuel au travail est puni par la loi.","exCn":"职场性骚扰会受到法律惩处。","th":"常用词"},{"w":"sida","p":"n.m.","cn":"艾滋病","ex":"Le sida se transmet notamment par voie sexuelle et par le sang.","exCn":"艾滋病主要通过性接触和血液传播。","th":"健康与身体"},{"w":"sien","p":"pron.","cn":"他的、她的、它的（那个）；（les siens）家人、亲人","ex":"J'avais oublié mon parapluie, alors Marie m'a prêté le sien.","exCn":"我忘了带伞，玛丽就把她的借给了我。","th":"人物与身份"},{"w":"siffler","p":"v.","cn":"吹口哨、吹哨；喝倒彩","ex":"Mon voisin siffle toujours en travaillant dans son jardin.","exCn":"我邻居在院子里干活时总是吹着口哨。","th":"饮食"},{"w":"sifflet","p":"n.m.","cn":"哨子；（复数）嘘声","ex":"Le maître-nageur porte toujours un sifflet autour du cou pour alerter les baigneurs.","exCn":"救生员脖子上总挂着一个哨子，用来提醒游泳的人。","th":"常用词"},{"w":"signal","p":"n.m.","cn":"信号","ex":"Au signal du départ, les coureurs se sont élancés sous les applaudissements.","exCn":"发令信号一响，选手们在掌声中冲了出去。","th":"常用词"},{"w":"signaler","p":"v.","cn":"指出、提醒；报告、举报；（魁北克）拨（电话号码）","ex":"Un voisin a signalé à la police la présence d'un individu suspect.","exCn":"一位邻居向警方举报有可疑人员出没。","th":"常用词"},{"w":"signature","p":"n.f.","cn":"签名、签字；（条约等的）签署","ex":"Il me manque encore votre signature en bas de la page.","exCn":"页面底部还缺您的签名。","th":"常用词"},{"w":"signification","p":"n.f.","cn":"意义、含义","ex":"Connais-tu la signification de ce panneau routier ?","exCn":"你知道这个交通标志是什么意思吗？","th":"抽象与概念"},{"w":"signifier","p":"v.","cn":"意味着、表示","ex":"Que signifie l'abréviation « RAMQ » sur ce formulaire ?","exCn":"这张表格上的缩写RAMQ是什么意思？","th":"常用词"},{"w":"silencieux","p":"adj.","cn":"安静的、无声的；沉默的、不作声的","ex":"Les élèves sont restés silencieux pendant toute la durée de l'examen.","exCn":"整个考试期间，学生们都安安静静的。","th":"描述与状态"},{"w":"similaire","p":"adj.","cn":"类似的、相似的","ex":"J'ai déjà vécu une situation similaire dans mon ancien travail.","exCn":"我以前工作时也遇到过类似的情况。","th":"常用词"},{"w":"simplicité","p":"n.f.","cn":"简单、简便；朴素、平易","ex":"Cette application séduit par sa simplicité : trois clics suffisent pour payer.","exCn":"这个应用胜在简单，点三下就能付款。","th":"描述与状态"},{"w":"sincère","p":"adj.","cn":"真诚的","ex":"Entre elles, c'est une amitié sincère qui dure depuis le lycée.","exCn":"她们之间的友谊很真挚，从高中一直持续到现在。","th":"常用词"},{"w":"sincèrement","p":"adv.","cn":"真诚地、衷心地；说实话","ex":"Elle croit sincèrement qu'elle a raison.","exCn":"她真心认为自己是对的。","th":"常用词"},{"w":"sincérité","p":"n.f.","cn":"真诚、诚意","ex":"Je ne doute pas de la sincérité de ses excuses.","exCn":"我不怀疑他道歉的诚意。","th":"常用词"},{"w":"slip","p":"n.m.","cn":"三角内裤","ex":"J'ai acheté un lot de trois slips en coton au supermarché.","exCn":"我在超市买了一组三条装的纯棉三角内裤。","th":"常用词"},{"w":"soi","p":"pron.","cn":"自己（泛指，用于 on、chacun、personne 等之后）；cf. cela va de soi 不言而喻","ex":"Dans une crise, chacun pense d'abord à soi.","exCn":"危机当中，人人都先想到自己。","th":"常用词"},{"w":"soie","p":"n.f.","cn":"丝绸、丝","ex":"Pour que la soie garde son éclat, lavez-la à la main à l'eau froide.","exCn":"要让丝绸保持光泽，请用冷水手洗。","th":"常用词"},{"w":"soigné","p":"adj.","cn":"精心的、细致的；（外表）整洁的、讲究的","ex":"Le jardin de nos voisins est toujours très soigné.","exCn":"邻居家的花园总是打理得井井有条。","th":"常用词"},{"w":"soin","p":"n.m.","cn":"细心、用心；（复数）护理、治疗；cf. prendre soin de 照顾","ex":"Au Canada, les soins dentaires ne sont pas toujours couverts par l'assurance maladie.","exCn":"在加拿大，牙科治疗并不都在医保报销范围内。","th":"健康与身体"},{"w":"soit","p":"conj.","cn":"（~… ~…）或者…或者…；即、也就是；cf. Soit ! /swat/ 好吧、就这样吧","ex":"On se retrouve soit chez toi, soit au café, comme tu veux.","exCn":"我们要么在你家见，要么在咖啡馆见，随你。","th":"功能词与连接"},{"w":"sol","p":"n.m.","cn":"地面、地板；土壤","ex":"Attention, le sol de la cuisine est encore mouillé.","exCn":"小心，厨房地板还湿着。","th":"常用词"},{"w":"solaire","p":"adj.","cn":"太阳的、太阳能的；防晒的","ex":"Le pharmacien m'a conseillé une protection solaire adaptée aux peaux sensibles.","exCn":"药剂师给我推荐了一款适合敏感肌肤的防晒产品。","th":"居住与环境"},{"w":"solidarité","p":"n.f.","cn":"团结、互助","ex":"Après l'inondation, une grande vague de solidarité s'est organisée dans le quartier.","exCn":"洪水过后，街区里掀起了一股互助热潮。","th":"常用词"},{"w":"solide","p":"adj.","cn":"坚固的、结实的；扎实的、可靠的；（人）健壮的","ex":"Cette étagère n'est pas assez solide pour supporter tous ces livres.","exCn":"这个书架不够结实，放不下这么多书。","th":"人物与身份"},{"w":"solitaire","p":"adj.","cn":"孤独的；单独的、独自的","ex":"Mon fils est un enfant plutôt solitaire : il préfère lire dans sa chambre plutôt que de jouer dehors.","exCn":"我儿子是个比较孤僻的孩子：他宁愿在房间里看书，也不愿意出去玩。","th":"常用词"},{"w":"solitude","p":"n.f.","cn":"孤独、独处","ex":"Le télétravail à temps plein peut entraîner un sentiment de solitude chez certains salariés.","exCn":"全职居家办公可能会让一些员工产生孤独感。","th":"常用词"},{"w":"sombre","p":"adj.","cn":"昏暗的、黑暗的；阴郁的、忧郁的","ex":"L'appartement est un peu sombre parce qu'il donne sur une cour.","exCn":"这套公寓有点暗，因为窗户朝着院子。","th":"描述与状态"},{"w":"somme","p":"n.f.","cn":"金额、款项；总和、总数；cf. le somme = 小睡；en somme 总之","ex":"Il a dû payer une grosse somme pour réparer sa voiture.","exCn":"他不得不花一大笔钱修车。","th":"描述与状态"},{"w":"sommet","p":"n.m.","cn":"山顶、顶峰；峰会","ex":"Après quatre heures de marche, nous avons enfin atteint le sommet.","exCn":"走了四个小时，我们终于登上了山顶。","th":"居住与环境"},{"w":"sondage","p":"n.m.","cn":"民意调查","ex":"Selon un sondage récent, la majorité des Canadiens soutiennent cette mesure.","exCn":"根据最近的一项民意调查，大多数加拿大人支持这项措施。","th":"常用词"},{"w":"sonnerie","p":"n.f.","cn":"铃声；铃、闹铃","ex":"Je n'ai pas entendu la sonnerie du réveil ce matin.","exCn":"我今天早上没听见闹钟响。","th":"常用词"},{"w":"sonnette","p":"n.f.","cn":"门铃；铃；cf. tirer la sonnette d'alarme 敲响警钟","ex":"La sonnette ne marche plus, frappez fort à la porte.","exCn":"门铃坏了，请用力敲门。","th":"常用词"},{"w":"sou","p":"n.m.","cn":"（sans un ~、pas un ~）分文、小钱；（复数）钱（口语）；（加拿大）分（货币单位）","ex":"Il est parti sans un sou en poche.","exCn":"他身无分文地走了。","th":"购物与金钱"},{"w":"souci","p":"n.m.","cn":"忧虑、担心；麻烦、问题","ex":"Pas de souci !","exCn":"没问题！","th":"情绪与性格"},{"w":"soudain","p":"adj.","cn":"突然；突然的","ex":"Soudain, toutes les lumières de l'immeuble se sont éteintes.","exCn":"突然，整栋楼的灯全灭了。","th":"常用词"},{"w":"soudainement","p":"adv.","cn":"突然","ex":"Le patient s'est soudainement senti mal dans la salle d'attente.","exCn":"病人在候诊室里突然感到不适。","th":"常用词"},{"w":"souffle","p":"n.m.","cn":"呼吸、气息；（新的）活力、动力","ex":"Après la course, il était à bout de souffle.","exCn":"跑完步后他上气不接下气。","th":"健康与身体"},{"w":"souffler","p":"v.","cn":"（风）刮、吹；吹气；喘口气、歇一歇；低声提示、悄悄告诉","ex":"Il a soufflé sur ses mains gelées pour les réchauffer.","exCn":"他朝冻僵的双手哈气取暖。","th":"居住与环境"},{"w":"souffrir","p":"v.","cn":"受苦、疼痛；（~ de）患有、遭受","ex":"Elle souffre de migraines depuis l'adolescence.","exCn":"她从青春期起就患有偏头痛。","th":"健康与身体"},{"w":"souhait","p":"n.m.","cn":"愿望、心愿；cf. À tes souhaits !（对打喷嚏的人说）长命百岁","ex":"Mon plus grand souhait est de m'installer au Canada avec ma famille.","exCn":"我最大的心愿是和家人一起在加拿大定居。","th":"人物与身份"},{"w":"soulager","p":"v.","cn":"减轻、缓解（痛苦）；使宽慰、使轻松","ex":"Ce médicament soulage rapidement les maux de tête.","exCn":"这种药能迅速缓解头痛。","th":"健康与身体"},{"w":"soulever","p":"v.","cn":"抬起、举起；引起、提出（问题）","ex":"Ce carton est trop lourd, je n'arrive pas à le soulever tout seul.","exCn":"这个纸箱太重了，我一个人抬不起来。","th":"常用词"},{"w":"soulier","p":"n.m.","cn":"鞋（魁北克常用）","ex":"Enlève tes souliers avant d'entrer, le plancher vient d'être lavé.","exCn":"进门前把鞋脱了，地板刚擦过。","th":"常用词"},{"w":"souligner","p":"v.","cn":"强调","ex":"Il souligne l'importance de la formation.","exCn":"他强调培训的重要性。","th":"观点与论证"},{"w":"souper","p":"n.m.","cn":"（魁北克、比利时、瑞士）晚饭；（法国）夜宵；吃晚饭；（法国）吃夜宵；cf.（魁北克）le déjeuner 早饭；le dîner 午饭","ex":"Le souper est prêt, venez à table !","exCn":"晚饭做好了，快来吃吧！","th":"饮食"},{"w":"souple","p":"adj.","cn":"柔软的、柔韧的；灵活的、可变通的","ex":"Avec ces chaussures à semelle souple, on peut marcher des heures sans se fatiguer.","exCn":"穿这种软底鞋，走上几个小时都不会累。","th":"常用词"},{"w":"source","p":"n.f.","cn":"来源、根源；泉、水源","ex":"Vérifiez toujours que l'information vient d'une source fiable.","exCn":"一定要核实信息是否来自可靠的来源。","th":"常用词"},{"w":"sourd","p":"n.","cn":"聋的；（声音）低沉的、闷的；聋人","ex":"Depuis son accident, elle est devenue sourde d'une oreille.","exCn":"那次事故以后，她一只耳朵聋了。","th":"人物与身份"},{"w":"soustraction","p":"n.f.","cn":"减法","ex":"Les enfants apprennent l'addition et la soustraction.","exCn":"孩子们在学加法和减法。","th":"常用词"},{"w":"soutenir","p":"v.","cn":"支持；坚称、主张；（~ une thèse）进行论文答辩","ex":"Mes parents m'ont toujours soutenu dans mes études.","exCn":"我父母一直支持我读书。","th":"观点与论证"},{"w":"soutien","p":"n.m.","cn":"支持、支援","ex":"Merci pour votre soutien pendant cette période difficile.","exCn":"感谢您在这段艰难时期给予的支持。","th":"观点与论证"},{"w":"spacieux","p":"adj.","cn":"宽敞的","ex":"Cet appartement est lumineux et spacieux, avec trois grandes chambres.","exCn":"这套公寓明亮宽敞，有三间大卧室。","th":"描述与状态"},{"w":"sparadrap","p":"n.m.","cn":"胶布、橡皮膏；cf. le pansement 创可贴；le diachylon 创可贴（魁北克）","ex":"Mets un morceau de sparadrap sur ta coupure.","exCn":"在伤口上贴块胶布。","th":"常用词"},{"w":"spectaculaire","p":"adj.","cn":"壮观的、惊人的","ex":"Le cascadeur a réalisé un saut spectaculaire.","exCn":"特技演员完成了一次惊人的跳跃。","th":"人物与身份"},{"w":"splendide","p":"adj.","cn":"壮丽的、华美的；极好的、非常漂亮的","ex":"Le mariage a eu lieu dans un splendide jardin au bord du lac.","exCn":"婚礼在湖边一座美丽的花园里举行。","th":"描述与状态"},{"w":"spontané","p":"adj.","cn":"自发的、主动的；率真的、直率的","ex":"J'ai envoyé une candidature spontanée à cette entreprise.","exCn":"我向这家公司主动投了简历。","th":"常用词"},{"w":"spécialisé","p":"adj.","cn":"专门的、专业的","ex":"Il travaille dans une librairie spécialisée en bandes dessinées.","exCn":"他在一家漫画专营书店工作。","th":"工作与学习"},{"w":"square","p":"n.m.","cn":"街心公园、街心花园","ex":"L'après-midi, les parents se retrouvent au square avec leurs enfants.","exCn":"下午，家长们带着孩子在街心公园碰面。","th":"出行与旅行"},{"w":"squash","p":"n.m.","cn":"壁球","ex":"Je joue au squash avec un collègue le mardi.","exCn":"我每周二和同事打壁球。","th":"常用词"},{"w":"stable","p":"adj.","cn":"稳定的、稳固的","ex":"Il cherche un emploi stable avec un bon salaire.","exCn":"他在找一份薪水不错的稳定工作。","th":"常用词"},{"w":"stagiaire","p":"n.","cn":"实习生、受训者","ex":"La stagiaire a présenté son rapport de fin de stage devant toute l'équipe.","exCn":"那位实习生当着全组人的面做了实习总结汇报。","th":"工作与学习"},{"w":"stand","p":"n.m.","cn":"展台、摊位；（~ de tir）射击场","ex":"Notre entreprise aura un stand au salon de l'emploi de Montréal.","exCn":"我们公司会在蒙特利尔招聘会上设一个展位。","th":"常用词"},{"w":"standard","p":"n.m.","cn":"标准的；标准、规范；（电话）总机","ex":"La chambre standard comprend un lit double et une petite salle de bain.","exCn":"标准间有一张双人床和一个小卫生间。","th":"常用词"},{"w":"stationnement","p":"n.m.","cn":"停车；停车位、停车场","ex":"À la sortie de l'école, le stationnement en double file bloque toute la rue.","exCn":"放学时，并排停车把整条街都堵住了。","th":"出行与旅行"},{"w":"stationner","p":"v.","cn":"停车、停放；（军队）驻扎","ex":"Vous pouvez stationner gratuitement dans cette rue après 19 heures.","exCn":"晚上七点以后，可以在这条街上免费停车。","th":"出行与旅行"},{"w":"statue","p":"n.f.","cn":"雕像","ex":"La statue de la Liberté a été offerte par la France aux États-Unis.","exCn":"自由女神像是法国送给美国的礼物。","th":"常用词"},{"w":"stretching","p":"n.m.","cn":"拉伸运动","ex":"Je fais dix minutes de stretching après mon footing.","exCn":"慢跑后我做十分钟拉伸。","th":"日常动作"},{"w":"strict","p":"adj.","cn":"严格的、严厉的；（le ~ minimum）最起码的","ex":"Les règles de sécurité sont très strictes dans ce laboratoire.","exCn":"这个实验室的安全规定非常严格。","th":"常用词"},{"w":"structure","p":"n.f.","cn":"结构、构造；机构、组织","ex":"La structure de ce roman est originale : chaque chapitre est raconté par un personnage différent.","exCn":"这部小说的结构很新颖：每一章都由不同的人物来讲述。","th":"社会与新闻"},{"w":"subir","p":"v.","cn":"遭受、承受；接受（手术、检查等）","ex":"Le patient doit subir une série d'examens avant l'opération.","exCn":"手术前，病人要接受一系列检查。","th":"健康与身体"},{"w":"suffisamment","p":"adv.","cn":"足够地","ex":"Nous n'avons pas suffisamment d'argent pour acheter une maison cette année.","exCn":"我们今年没有足够的钱买房。","th":"常用词"},{"w":"suffisant","p":"adj.","cn":"足够的、充分的；（神态、语气）自负的、自以为是的","ex":"Sans preuve suffisante, le juge ne peut pas condamner l'accusé.","exCn":"没有充分的证据，法官不能给被告定罪。","th":"常用词"},{"w":"suggestion","p":"n.f.","cn":"建议、提议","ex":"N'hésitez pas à nous faire part de vos suggestions pour améliorer le service.","exCn":"如果您有改进服务的建议，欢迎告诉我们。","th":"常用词"},{"w":"suggérer","p":"v.","cn":"建议、提议；暗示、使人联想","ex":"Personne n'arrivait à se décider, alors j'ai suggéré qu'on tire le restaurant au sort.","exCn":"大家都拿不定主意，于是我提议抽签决定去哪家餐厅。","th":"人物与身份"},{"w":"supplément","p":"n.m.","cn":"补充、增补；（营养）补充剂；附加费、加价","ex":"Pour une chambre avec vue sur la mer, il faut payer un supplément de vingt euros.","exCn":"要住海景房，得另付二十欧元。","th":"购物与金钱"},{"w":"supplémentaire","p":"adj.","cn":"额外的、附加的","ex":"Cette semaine, j'ai fait dix heures supplémentaires au bureau.","exCn":"这周我在公司加了十个小时的班。","th":"常用词"},{"w":"supporter","p":"v.","cn":"忍受","ex":"Je ne supporte pas le bruit la nuit.","exCn":"我受不了夜里的噪音。","th":"情绪与性格"},{"w":"supposer","p":"v.","cn":"猜想、假设；意味着、以…为前提","ex":"Je suppose que tu as déjà réservé l'hôtel ?","exCn":"我猜你已经订好酒店了吧？","th":"观点与论证"},{"w":"supprimer","p":"v.","cn":"删除、去掉；取消、废除","ex":"Supprimez les applications que vous n'utilisez plus pour libérer de l'espace.","exCn":"把不再用的应用删掉，腾出空间。","th":"常用词"},{"w":"supérieur","p":"n.","cn":"（~ à）高于…的、优于…的；上部的、上级的；高等的；上司、上级","ex":"Les températures seront supérieures à la normale cette semaine.","exCn":"本周气温将高于常年同期。","th":"描述与状态"},{"w":"surface","p":"n.f.","cn":"表面；面积；cf. une grande surface 大型超市、大卖场","ex":"Des déchets plastiques flottent à la surface de l'océan.","exCn":"塑料垃圾漂浮在海面上。","th":"购物与金钱"},{"w":"surnom","p":"n.m.","cn":"绰号、外号","ex":"Louis XIV portait le surnom de Roi-Soleil.","exCn":"路易十四的绰号是“太阳王”。","th":"常用词"},{"w":"surprenant","p":"adj.","cn":"令人惊讶的","ex":"C'est surprenant de voir autant de monde à la plage en octobre.","exCn":"十月份海滩上还有这么多人，真让人意外。","th":"情绪与性格"},{"w":"surprendre","p":"v.","cn":"使惊讶、使吃惊；撞见、当场发现","ex":"Le surveillant l'a surpris en train de fumer derrière le gymnase.","exCn":"学监撞见他在体育馆后面抽烟。","th":"饮食"},{"w":"surveillance","p":"n.f.","cn":"监视、监控；监督、看管","ex":"Le suspect a été placé sous surveillance policière.","exCn":"嫌疑人已被置于警方的监视之下。","th":"常用词"},{"w":"surveillant","p":"n.","cn":"看守、监管员；（学校）学监、监考员","ex":"Le surveillant a confisqué le téléphone d'un élève pendant l'examen.","exCn":"考试时，监考老师没收了一名学生的手机。","th":"工作与学习"},{"w":"surveiller","p":"v.","cn":"看管、照看；监视、监控","ex":"Des caméras surveillent l'entrée du parking jour et nuit.","exCn":"摄像头日夜监控着停车场入口。","th":"常用词"},{"w":"surveillé","p":"adj.","cn":"有人看管的；受监视的","ex":"Sur cette plage, la baignade est surveillée de 10 h à 18 h.","exCn":"这片海滩10点到18点有救生员看护游泳。","th":"人物与身份"},{"w":"survivre","p":"v.","cn":"幸存、活下来","ex":"Seuls deux passagers ont survécu à l'accident.","exCn":"只有两名乘客在事故中幸存。","th":"常用词"},{"w":"suspect","p":"n.","cn":"嫌疑人、嫌犯；可疑的","ex":"Le suspect a été arrêté mardi matin à son domicile de Laval.","exCn":"嫌疑人周二上午在拉瓦尔的家中被捕。","th":"人物与身份"},{"w":"suspense","p":"n.m.","cn":"悬念、悬疑","ex":"Le suspense est insupportable : qui va gagner ?","exCn":"悬念让人受不了：到底谁会赢？","th":"常用词"},{"w":"syllabe","p":"n.f.","cn":"音节","ex":"En français, on met généralement l'accent sur la dernière syllabe du mot.","exCn":"在法语里，重音一般落在词的最后一个音节上。","th":"常用词"},{"w":"symbole","p":"n.m.","cn":"象征；符号","ex":"En France, on évite d'offrir des chrysanthèmes : c'est un symbole de deuil.","exCn":"在法国，人们避免送菊花，因为菊花是哀悼的象征。","th":"常用词"},{"w":"symboliser","p":"v.","cn":"象征、代表","ex":"Sur le drapeau canadien, la feuille d'érable symbolise le pays tout entier.","exCn":"加拿大国旗上的枫叶象征着整个国家。","th":"常用词"},{"w":"sympathie","p":"n.f.","cn":"好感；同情、慰问","ex":"Ce candidat a gagné la sympathie du public grâce à son humour.","exCn":"这位候选人凭借幽默感赢得了公众的好感。","th":"描述与状态"},{"w":"symptôme","p":"n.m.","cn":"症状；征兆、迹象","ex":"La fièvre et la toux sont les principaux symptômes de la grippe.","exCn":"发烧和咳嗽是流感的主要症状。","th":"常用词"},{"w":"syndicat","p":"n.m.","cn":"工会","ex":"Le syndicat des enseignants a appelé à la grève pour jeudi.","exCn":"教师工会号召周四罢工。","th":"常用词"},{"w":"système","p":"n.m.","cn":"系统、体系；制度","ex":"Le système de santé canadien est financé en grande partie par les impôts.","exCn":"加拿大的医疗体系大部分靠税收资助。","th":"常用词"},{"w":"séance","p":"n.f.","cn":"（一次）会议；（活动的）一场、一节","ex":"La séance du conseil municipal est ouverte au public.","exCn":"市议会的会议对公众开放。","th":"工作与学习"},{"w":"séduire","p":"v.","cn":"吸引、打动；勾引、引诱","ex":"Ce quartier séduit de plus en plus de jeunes familles.","exCn":"这个街区吸引了越来越多的年轻家庭。","th":"常用词"},{"w":"séisme","p":"n.m.","cn":"地震；（喻）剧烈震荡","ex":"Lors du dernier séisme, les habitants ont dû passer la nuit dehors.","exCn":"上次地震时，居民们不得不在户外过夜。","th":"常用词"},{"w":"séjourner","p":"v.","cn":"逗留、暂住","ex":"Nous avons séjourné une semaine à Montréal.","exCn":"我们在蒙特利尔住了一个星期。","th":"居住与环境"},{"w":"sélection","p":"n.f.","cn":"选择、选拔；精选（的物品）","ex":"La sélection des candidats se fait sur dossier et entretien.","exCn":"候选人的选拔通过材料审核和面试进行。","th":"常用词"},{"w":"sélectionner","p":"v.","cn":"挑选、选拔；（电脑）选中、选择","ex":"Seuls vingt candidats seront sélectionnés pour l'entretien.","exCn":"只有二十名候选人会被选中参加面试。","th":"常用词"},{"w":"séparation","p":"n.f.","cn":"分离、分开；分手、分居","ex":"Depuis la séparation de leurs parents, les enfants passent une semaine chez leur père et une semaine chez leur mère.","exCn":"父母分开以后，孩子们在爸爸家住一周，再到妈妈家住一周。","th":"常用词"},{"w":"sérieusement","p":"adv.","cn":"认真地、严肃地；严重地；（口语，单用）真的吗、说真的","ex":"Elle pense sérieusement à changer de travail.","exCn":"她在认真考虑换工作。","th":"描述与状态"},{"w":"s'évader","p":"v.","cn":"逃跑、越狱；摆脱日常、散心","ex":"Deux détenus se sont évadés de la prison pendant la nuit.","exCn":"两名囚犯夜里越狱了。","th":"日常动作"},{"w":"s'évanouir","p":"v.","cn":"昏倒、晕过去；消失、破灭","ex":"Il n'avait pas déjeuné et il s'est évanoui en plein cours de sport.","exCn":"他没吃早饭，上体育课上到一半就晕倒了。","th":"时间与数量"},{"w":"sévère","p":"adj.","cn":"严厉的、严格的；严重的、惨重的","ex":"Notre professeur de mathématiques était sévère mais juste avec les élèves.","exCn":"我们的数学老师对学生严厉，但很公正。","th":"描述与状态"},{"w":"tablier","p":"n.m.","cn":"围裙","ex":"Mets un tablier pour faire la cuisine.","exCn":"做饭时系上围裙。","th":"常用词"},{"w":"tache","p":"n.f.","cn":"污点、斑点；cf. la tâche 任务","ex":"Le léopard a un pelage couvert de taches.","exCn":"豹子的皮毛上布满了斑点。","th":"工作与学习"},{"w":"taire","p":"v.","cn":"隐瞒、不说出；（se ~）住口、沉默；cf. Tais-toi ! 闭嘴！","ex":"Il a préféré taire la vérité pour ne pas la blesser.","exCn":"他宁愿隐瞒真相，以免伤害她。","th":"居住与环境"},{"w":"talent","p":"n.m.","cn":"才能、天赋；人才","ex":"Ce jeune chanteur a beaucoup de talent.","exCn":"这位年轻歌手很有才华。","th":"人物与身份"},{"w":"talentueux","p":"adj.","cn":"有才华的、有天赋的","ex":"Ce jeune cuisinier talentueux vient d'ouvrir son propre restaurant.","exCn":"这位才华横溢的年轻厨师刚开了自己的餐厅。","th":"时间与数量"},{"w":"talon","p":"n.m.","cn":"脚后跟；鞋跟","ex":"J'ai mal au talon droit depuis que je cours tous les matins.","exCn":"自从每天早上跑步以来，我右脚后跟就一直疼。","th":"常用词"},{"w":"tambour","p":"n.m.","cn":"鼓；（洗衣机）滚筒","ex":"Mon fils apprend à jouer du tambour dans la fanfare de l'école.","exCn":"我儿子在学校的乐队里学打鼓。","th":"日常动作"},{"w":"tandis que","p":"conj.","cn":"而、然而（对比）；当…的时候","ex":"Mon frère adore l'hiver, tandis que moi, je ne supporte pas le froid.","exCn":"我哥哥很喜欢冬天，而我受不了寒冷。","th":"功能词与连接"},{"w":"tant","p":"adv.","cn":"那么、如此（地）；（~ de）那么多的；cf. tant que 只要、在…期间；en tant que 作为；tant mieux 太好了","ex":"Il a tant changé que je ne l'ai pas reconnu.","exCn":"他变化太大了，我都没认出他来。","th":"描述与状态"},{"w":"tarder","p":"v.","cn":"拖延、耽搁；（il me tarde de）急于、盼望","ex":"Le propriétaire tarde à faire les réparations dans notre appartement.","exCn":"房东迟迟不来修我们的公寓。","th":"常用词"},{"w":"tas","p":"n.m.","cn":"堆；cf. un tas de / des tas de（口语）一大堆、许多","ex":"J'ai des tas de choses à faire avant de partir en vacances.","exCn":"放假前我有一大堆事要做。","th":"描述与状态"},{"w":"tatouage","p":"n.m.","cn":"文身","ex":"Il s'est fait faire un tatouage sur le bras pour ses trente ans.","exCn":"他三十岁生日时在胳膊上文了个文身。","th":"常用词"},{"w":"taureau","p":"n.m.","cn":"公牛；（Taureau）金牛座；cf. prendre le taureau par les cornes 迎难而上","ex":"Attention, ne traverse pas ce champ : il y a un taureau !","exCn":"小心，别从这片田里穿过去，里面有头公牛！","th":"人物与身份"},{"w":"taux","p":"n.m.","cn":"率、比率","ex":"Ce quartier a l'un des taux de criminalité les plus bas de la ville.","exCn":"这个街区的犯罪率是全市最低的之一。","th":"常用词"},{"w":"taxe","p":"n.f.","cn":"税、税费；cf. l'impôt 税（尤指所得税等直接税）","ex":"Au Québec, la taxe de vente s'ajoute au prix affiché au moment de payer.","exCn":"在魁北克，销售税是在结账时另外加到标价上的。","th":"社会与新闻"},{"w":"technique","p":"n.f.","cn":"技术、技巧；技术的","ex":"Ce chef utilise une technique de cuisson très ancienne.","exCn":"这位厨师采用一种非常古老的烹饪技法。","th":"常用词"},{"w":"technologie","p":"n.f.","cn":"技术、科技","ex":"La technologie évolue si vite que mon téléphone est déjà dépassé.","exCn":"科技发展得太快，我的手机已经过时了。","th":"常用词"},{"w":"technologique","p":"adj.","cn":"技术的、科技的","ex":"Le progrès technologique change notre façon de travailler.","exCn":"科技进步改变了我们的工作方式。","th":"常用词"},{"w":"tel","p":"adj.","cn":"这样的、如此的；（tel que）诸如、像","ex":"Je n'ai jamais vu une telle foule.","exCn":"我从没见过这么多人。","th":"常用词"},{"w":"temple","p":"n.m.","cn":"神庙、寺庙；（新教的）教堂","ex":"Nous avons visité un magnifique temple bouddhiste à Kyoto.","exCn":"我们在京都参观了一座壮观的佛寺。","th":"描述与状态"},{"w":"temporaire","p":"adj.","cn":"临时的、暂时的","ex":"Il a trouvé un emploi temporaire pour l'été.","exCn":"他找到了一份暑期临时工作。","th":"常用词"},{"w":"tempête","p":"n.f.","cn":"暴风雨、风暴","ex":"Une tempête de neige a paralysé la ville pendant deux jours.","exCn":"一场暴风雪让全城瘫痪了两天。","th":"居住与环境"},{"w":"tendance","p":"n.f.","cn":"趋势","ex":"La tendance est à la baisse depuis deux ans.","exCn":"两年来趋势是下降的。","th":"观点与论证"},{"w":"tendre","p":"v.","cn":"伸出、递给；拉紧、绷紧；（~ à）趋向于、往往会；（肉、蔬菜等）嫩的、软的；温柔的、深情的","ex":"Laissez cuire la viande à feu doux pour qu'elle reste tendre.","exCn":"用小火慢慢煮，肉才会嫩。","th":"饮食"},{"w":"tension","p":"n.f.","cn":"血压；（局势、关系等的）紧张；张力、电压","ex":"Le médecin m'a pris la tension : elle est un peu élevée.","exCn":"医生给我量了血压，有点偏高。","th":"健康与身体"},{"w":"tentant","p":"adj.","cn":"诱人的、吸引人的","ex":"L'offre d'emploi est tentante, mais je n'ai pas envie de quitter Montréal.","exCn":"这份工作邀约很诱人，但我不想离开蒙特利尔。","th":"人物与身份"},{"w":"tenter","p":"v.","cn":"尝试、试图；吸引、诱惑；（ça me ~ de）想要、有兴致（口语）","ex":"Les pompiers ont tenté de sauver le bâtiment, mais il était trop tard.","exCn":"消防员试图抢救那栋楼，可惜为时已晚。","th":"常用词"},{"w":"tenue","p":"n.f.","cn":"服装、着装；（会议等的）举行","ex":"Une tenue de soirée est exigée pour le gala.","exCn":"晚会要求穿晚礼服。","th":"工作与学习"},{"w":"terme","p":"n.m.","cn":"词语、术语；期限、终点；cf. à court / à long terme 短期 / 长期；en d'autres termes 换句话说","ex":"Ce terme juridique est difficile à traduire en chinois.","exCn":"这个法律术语很难翻译成中文。","th":"描述与状态"},{"w":"terminal","p":"n.m.","cn":"（机场）航站楼；（电脑、通信）终端；末期的、最后的；cf. la terminale = 高中毕业班","ex":"Les vols internationaux partent du terminal A, à l'autre bout de l'aéroport.","exCn":"国际航班从机场另一头的A航站楼出发。","th":"出行与旅行"},{"w":"terriblement","p":"adv.","cn":"极其、非常","ex":"Je suis terriblement désolé pour ce retard.","exCn":"这次迟到，我真是万分抱歉。","th":"常用词"},{"w":"terrifiant","p":"adj.","cn":"可怕的、吓人的","ex":"Le dernier film de ce réalisateur est si terrifiant que j'ai dormi avec la lumière allumée.","exCn":"这位导演的新片太吓人了，我只好开着灯睡觉。","th":"人物与身份"},{"w":"terrifié","p":"adj.","cn":"吓坏的、惊恐的","ex":"L'enfant était terrifié par l'orage.","exCn":"孩子被雷雨吓坏了。","th":"描述与状态"},{"w":"territoire","p":"n.m.","cn":"领土、国土；地区、区域","ex":"Les forêts couvrent une grande partie du territoire canadien.","exCn":"森林覆盖了加拿大大部分国土。","th":"居住与环境"},{"w":"thème","p":"n.m.","cn":"主题、题目","ex":"Cette année, le festival a pour thème la protection de l'environnement.","exCn":"今年艺术节的主题是环境保护。","th":"常用词"},{"w":"théorie","p":"n.f.","cn":"理论、学说","ex":"En théorie, le train devrait arriver à midi, mais il a souvent du retard.","exCn":"理论上火车应该中午到，但它经常晚点。","th":"常用词"},{"w":"tien","p":"pron.","cn":"你的（那个、那些）；（les tiens）你的家人","ex":"Ce n'est pas mon stylo, c'est le tien.","exCn":"这不是我的笔，是你的。","th":"人物与身份"},{"w":"tiers","p":"n.m.","cn":"三分之一；第三方、第三者","ex":"J'ai déjà lu un tiers du livre.","exCn":"这本书我已经读了三分之一。","th":"常用词"},{"w":"timidité","p":"n.f.","cn":"羞怯、腼腆","ex":"Il a surmonté sa timidité pour parler en public.","exCn":"他克服了羞怯，当众讲话。","th":"常用词"},{"w":"tissu","p":"n.m.","cn":"布料；（生物）组织","ex":"Ce rideau est fait d'un tissu léger qui laisse passer la lumière.","exCn":"这款窗帘用的是一种透光的轻薄布料。","th":"社会与新闻"},{"w":"titre","p":"n.m.","cn":"标题、题目；头衔、称号；（~ de transport）车票、乘车凭证；（à ~ de）作为、以…身份","ex":"Quel est le titre du livre que tu lis en ce moment ?","exCn":"你现在读的那本书书名是什么？","th":"出行与旅行"},{"w":"tiède","p":"adj.","cn":"温的、微温的；冷淡的、不热情的","ex":"Lavez ce pull à l'eau tiède et faites-le sécher à plat.","exCn":"这件毛衣要用温水洗，然后平铺晾干。","th":"居住与环境"},{"w":"toast","p":"n.m.","cn":"（举杯）祝酒、干杯；烤面包片、吐司；cf.（魁北克）la rôtie 烤面包片","ex":"À la fin du repas, le père de la mariée a porté un toast aux jeunes mariés.","exCn":"宴席快结束时，新娘的父亲举杯向新人祝酒。","th":"饮食"},{"w":"tolérance","p":"n.f.","cn":"宽容、容忍；（医）耐受性","ex":"La police applique une tolérance zéro pour l'alcool au volant.","exCn":"警方对酒后驾车实行零容忍。","th":"健康与身体"},{"w":"tombe","p":"n.f.","cn":"坟墓","ex":"Chaque année, ils fleurissent la tombe de leur grand-père.","exCn":"每年他们都会给祖父的墓献花。","th":"常用词"},{"w":"tonne","p":"n.f.","cn":"吨；cf. des tonnes de 大量、一大堆（口语）","ex":"Une tonne de papier recyclé permet de sauver environ dix-sept arbres.","exCn":"回收一吨废纸大约可以少砍十七棵树。","th":"描述与状态"},{"w":"tonnerre","p":"n.m.","cn":"雷；cf. du tonnerre 棒极了（口语）","ex":"Mon chien se cache sous le lit dès qu'il entend le tonnerre.","exCn":"我家的狗一听到打雷就躲到床底下。","th":"常用词"},{"w":"top","p":"n.m.","cn":"（le ~）最好的、顶级（口语）；排行榜（如 top 10）；（女式）上衣；超棒的、一流的（口语）","ex":"Pour l'été, elle s'est acheté un top sans manches.","exCn":"她为夏天买了一件无袖上衣。","th":"人物与身份"},{"w":"tornade","p":"n.f.","cn":"龙卷风","ex":"Une violente tornade a arraché le toit de plusieurs maisons près d'Ottawa.","exCn":"一场猛烈的龙卷风掀翻了渥太华附近好几栋房子的屋顶。","th":"居住与环境"},{"w":"tort","p":"n.m.","cn":"错、过错；（avoir ~）错了、不对；（faire du ~ à）损害、伤害；cf. à tort 错误地、冤枉地","ex":"Tu as eu tort de ne pas répondre à ce courriel.","exCn":"你没回那封邮件，这是你不对。","th":"健康与身体"},{"w":"totalement","p":"adv.","cn":"完全地、彻底地","ex":"J'avais totalement oublié ton anniversaire, désolé !","exCn":"我把你的生日忘得一干二净，对不起！","th":"常用词"},{"w":"touche","p":"n.f.","cn":"（键盘等的）键；（une ~ de）一点、少许","ex":"Appuyez sur la touche « Entrée » pour continuer.","exCn":"按“回车”键继续。","th":"常用词"},{"w":"tournage","p":"n.m.","cn":"（电影）拍摄","ex":"Le tournage du film a duré six mois.","exCn":"这部电影拍了六个月。","th":"常用词"},{"w":"tournoi","p":"n.m.","cn":"锦标赛","ex":"Elle a gagné le tournoi de tennis de sa ville.","exCn":"她赢得了本市的网球锦标赛。","th":"常用词"},{"w":"tournée","p":"n.f.","cn":"巡演、巡回演出；（邮递员等的）巡回路线；（请大家喝的）一轮酒（口语）","ex":"Le chanteur part en tournée en Asie cet été.","exCn":"这位歌手今年夏天要去亚洲巡演。","th":"饮食"},{"w":"trace","p":"n.f.","cn":"痕迹、踪迹","ex":"La police n'a trouvé aucune trace du suspect.","exCn":"警方没有找到嫌疑人的任何踪迹。","th":"常用词"},{"w":"traditionnellement","p":"adv.","cn":"传统上、按惯例；一向","ex":"Au Québec, on mange traditionnellement de la tourtière à Noël.","exCn":"在魁北克，圣诞节按传统要吃肉馅饼。","th":"常用词"},{"w":"trafic","p":"n.m.","cn":"交通、车流；非法买卖、走私","ex":"Ce matin, le trafic était perturbé sur la ligne orange du métro.","exCn":"今天早上地铁橙线运行受阻。","th":"出行与旅行"},{"w":"tragique","p":"adj.","cn":"悲惨的","ex":"Il a perdu la vie dans un accident tragique sur l'autoroute.","exCn":"他在高速公路上的一场惨烈车祸中丧生。","th":"常用词"},{"w":"tragédie","p":"n.f.","cn":"悲剧","ex":"Cet accident de bus a été une véritable tragédie pour tout le village.","exCn":"这起公交车事故对全村来说是一场真正的悲剧。","th":"常用词"},{"w":"trahir","p":"v.","cn":"背叛、出卖；泄露、暴露","ex":"Il a trahi la confiance de ses amis.","exCn":"他辜负了朋友们的信任。","th":"购物与金钱"},{"w":"trait","p":"n.m.","cn":"特点、特征；线条、笔画；（复数）五官、面容；cf. avoir trait à 涉及、与…有关；trait d'union 连字符；d'un trait 一口气（喝完、读完等）","ex":"L'un des traits marquants de cette région, c'est l'accueil chaleureux de ses habitants.","exCn":"这个地区的一大特点，就是当地人热情好客。","th":"饮食"},{"w":"traitement","p":"n.m.","cn":"治疗、疗法；处理、办理；对待、待遇","ex":"Le médecin lui a prescrit un traitement antibiotique de dix jours.","exCn":"医生给他开了十天的抗生素疗程。","th":"健康与身体"},{"w":"traiter","p":"v.","cn":"处理、办理；对待；治疗；（~ qqn de）骂…是…","ex":"Le service client traite environ deux cents appels par jour.","exCn":"客服部每天处理大约两百个电话。","th":"健康与身体"},{"w":"transformation","p":"n.f.","cn":"转变、变化；加工、改造","ex":"Le quartier a connu une profonde transformation en dix ans.","exCn":"十年间，这个街区发生了巨大的变化。","th":"抽象与概念"},{"w":"transformer","p":"v.","cn":"改变、转变；（~ en）改造成、变成","ex":"Ce voyage en Afrique a transformé sa vision du monde.","exCn":"这次非洲之旅改变了他看世界的眼光。","th":"常用词"},{"w":"transférer","p":"v.","cn":"转移、转送；转发（邮件）；转（账）","ex":"J'ai transféré cinq cents dollars sur le compte de ma fille.","exCn":"我给女儿的账户转了五百元。","th":"常用词"},{"w":"transmettre","p":"v.","cn":"传达、转交；传授、传给；传播、传染（疾病）","ex":"Pourriez-vous transmettre ce message à votre collègue ?","exCn":"您能把这条消息转达给您的同事吗？","th":"健康与身体"},{"w":"transparent","p":"adj.","cn":"透明的；（喻）公开的、不隐瞒的","ex":"Mettez vos liquides dans un sac en plastique transparent avant le contrôle de sécurité.","exCn":"安检前请把液体装进透明塑料袋里。","th":"人物与身份"},{"w":"transpirer","p":"v.","cn":"出汗；（消息）走漏","ex":"Je transpire toujours des mains avant un entretien d'embauche.","exCn":"每次面试前，我的手都会出汗。","th":"常用词"},{"w":"transporter","p":"v.","cn":"运送、搬运","ex":"Il a fallu quatre déménageurs pour transporter le vieux piano de mes parents jusque chez nous.","exCn":"动用了四个搬家工人，才把我父母那架旧钢琴运到我们家。","th":"日常动作"},{"w":"travailleur","p":"n.","cn":"劳动者、工人；勤劳的、勤奋的；cf.（魁北克）le travailleur autonome 自雇人士","ex":"Ma colocataire est très travailleuse : elle étudie même le dimanche.","exCn":"我室友非常勤奋，连星期天都在学习。","th":"人物与身份"},{"w":"travers","p":"n.m.","cn":"小毛病、缺点；（à ~）穿过、透过；（de ~）歪斜、不对劲","ex":"Chacun a ses petits travers.","exCn":"每个人都有些小毛病。","th":"健康与身体"},{"w":"traversée","p":"n.f.","cn":"横渡、穿越","ex":"La traversée de la Manche dure environ une heure et demie.","exCn":"横渡英吉利海峡大约需要一个半小时。","th":"日常动作"},{"w":"traîner","p":"v.","cn":"拖、拽；（东西）乱放、到处乱丢；磨蹭、闲逛（口语）","ex":"Elle traînait une lourde valise dans l'escalier du métro.","exCn":"她在地铁楼梯上拖着一个沉重的行李箱。","th":"常用词"},{"w":"trekking","p":"n.m.","cn":"徒步旅行、长途徒步","ex":"Cet été, nous allons faire du trekking au Népal.","exCn":"今年夏天，我们要去尼泊尔徒步旅行。","th":"出行与旅行"},{"w":"tremblement","p":"n.m.","cn":"颤抖、发抖；震动；（~ de terre）地震","ex":"Cette école a été construite pour résister aux tremblements de terre.","exCn":"这所学校是按抗震标准建造的。","th":"常用词"},{"w":"trembler","p":"v.","cn":"发抖、颤抖；震动、摇晃","ex":"L'enfant tremblait de froid en attendant l'autobus.","exCn":"孩子在等公交车时冻得直发抖。","th":"常用词"},{"w":"tremper","p":"v.","cn":"浸泡、浸湿；蘸","ex":"Laissez tremper les haricots secs toute la nuit avant de les cuire.","exCn":"干豆子要先泡一整夜再煮。","th":"常用词"},{"w":"trempé","p":"adj.","cn":"湿透的","ex":"Il pleuvait si fort que je suis arrivé trempé.","exCn":"雨下得太大，我到的时候浑身湿透了。","th":"常用词"},{"w":"tresse","p":"n.f.","cn":"辫子、发辫","ex":"Ma fille aime porter des tresses.","exCn":"我女儿喜欢扎辫子。","th":"常用词"},{"w":"tri","p":"n.m.","cn":"分类、分拣；挑选、筛选","ex":"Chez nous, on fait le tri des déchets.","exCn":"我们家会做垃圾分类。","th":"常用词"},{"w":"triangle","p":"n.m.","cn":"三角形","ex":"La somme des angles d'un triangle est égale à 180 degrés.","exCn":"三角形的内角和等于180度。","th":"常用词"},{"w":"tribunal","p":"n.m.","cn":"法院、法庭","ex":"Le locataire a porté l'affaire devant le tribunal.","exCn":"租客把这件事告上了法庭。","th":"社会与新闻"},{"w":"tricher","p":"v.","cn":"作弊","ex":"Il a été exclu de l'examen parce qu'il avait triché.","exCn":"他因为作弊被取消了考试资格。","th":"常用词"},{"w":"tricot","p":"n.m.","cn":"编织、织毛线；针织衫、毛衣","ex":"Le soir, ma grand-mère fait du tricot.","exCn":"晚上我奶奶织毛线。","th":"常用词"},{"w":"tricoter","p":"v.","cn":"编织、织（毛线）","ex":"Elle tricote une écharpe pour son petit-fils.","exCn":"她在给孙子织一条围巾。","th":"常用词"},{"w":"trier","p":"v.","cn":"分类、分拣；挑选、筛选","ex":"Ce week-end, j'ai enfin trié les vieux vêtements des enfants pour en donner une partie.","exCn":"这个周末，我终于把孩子们的旧衣服整理分类了一遍，打算送掉一部分。","th":"常用词"},{"w":"trimestre","p":"n.m.","cn":"季度；（三学期制的）学期","ex":"Les ventes de l'entreprise ont augmenté de 5 % au premier trimestre.","exCn":"公司第一季度的销售额增长了5%。","th":"常用词"},{"w":"triple","p":"n.m.","cn":"三倍的；三倍","ex":"Son salaire est le triple du mien.","exCn":"他的工资是我的三倍。","th":"时间与数量"},{"w":"tristesse","p":"n.f.","cn":"悲伤、忧伤","ex":"Une profonde tristesse l'a envahie quand elle a vidé la maison de son enfance.","exCn":"收拾清空童年住过的房子时，一阵深深的悲伤涌上她的心头。","th":"健康与身体"},{"w":"tromper","p":"v.","cn":"欺骗、蒙骗；（对伴侣）不忠、出轨；se tromper：弄错、搞错（se tromper de numéro 打错电话）","ex":"Ce vendeur a trompé plusieurs clients sur la qualité de ses produits.","exCn":"这个商贩在产品质量上欺骗了好几位顾客。","th":"常用词"},{"w":"tropical","p":"adj.","cn":"热带的","ex":"Ce fruit pousse dans les pays tropicaux.","exCn":"这种水果生长在热带国家。","th":"居住与环境"},{"w":"trésor","p":"n.m.","cn":"宝藏、财宝；（称呼）宝贝","ex":"Les archéologues ont découvert un trésor de pièces romaines dans ce champ.","exCn":"考古学家在这块田里发现了一批古罗马钱币宝藏。","th":"交际与礼貌"},{"w":"tube","p":"n.m.","cn":"管子；（牙膏等的）软管；热门歌曲、金曲（口语）","ex":"Il ne reste presque plus rien dans le tube de dentifrice.","exCn":"牙膏管里几乎挤不出什么了。","th":"居住与环境"},{"w":"tulipe","p":"n.f.","cn":"郁金香","ex":"Au printemps, les tulipes fleurissent dans le parc.","exCn":"春天，公园里的郁金香开花了。","th":"常用词"},{"w":"tunnel","p":"n.m.","cn":"隧道","ex":"Le tunnel sera fermé ce week-end pour des travaux d'entretien.","exCn":"这条隧道本周末因维修施工关闭。","th":"常用词"},{"w":"turc","p":"n.m.","cn":"土耳其的；土耳其人；土耳其语","ex":"Après le repas, il nous a servi un café turc très fort.","exCn":"饭后他给我们端来一杯很浓的土耳其咖啡。","th":"人物与身份"},{"w":"tutoiement","p":"n.m.","cn":"以 tu 相称；cf. le vouvoiement 以 vous 相称","ex":"Au Québec, le tutoiement est très courant.","exCn":"在魁北克，用 tu 称呼人非常普遍。","th":"常用词"},{"w":"tuyau","p":"n.m.","cn":"管子、管道；窍门、内部消息（口语）","ex":"Le tuyau sous l'évier fuit.","exCn":"水槽下面的管子漏水了。","th":"常用词"},{"w":"typiquement","p":"adv.","cn":"典型地、地道地","ex":"Dans ce quartier, on trouve des maisons typiquement montréalaises, avec leurs escaliers extérieurs en fer.","exCn":"在这个街区能看到典型的蒙特利尔式房子，带着铁制的室外楼梯。","th":"常用词"},{"w":"tâche","p":"n.f.","cn":"任务、工作；cf. la tache = 污点、斑点","ex":"Chez nous, les tâches ménagères sont partagées entre tous les membres de la famille.","exCn":"在我们家，家务活由全家人一起分担。","th":"工作与学习"},{"w":"téléfilm","p":"n.m.","cn":"电视电影","ex":"Ce soir, il y a un téléfilm policier à la télévision.","exCn":"今晚电视上有一部侦探电视电影。","th":"常用词"},{"w":"téléspectateur","p":"n.","cn":"电视观众","ex":"Des millions de téléspectateurs ont regardé le match.","exCn":"数百万电视观众观看了这场比赛。","th":"常用词"},{"w":"téléviseur","p":"n.m.","cn":"电视机","ex":"Les vieux téléviseurs ne vont pas à la poubelle : il faut les apporter à l'écocentre.","exCn":"旧电视机不能扔进垃圾桶，得送到回收站。","th":"常用词"},{"w":"télévisé","p":"adj.","cn":"电视播出的、电视的","ex":"Je regarde le journal télévisé tous les soirs.","exCn":"我每天晚上都看电视新闻。","th":"常用词"},{"w":"témoignage","p":"n.m.","cn":"证词、证言；（情感的）表示、证明","ex":"Le témoignage d'une voisine a permis d'identifier le suspect.","exCn":"一位女邻居的证词帮助警方认出了嫌疑人。","th":"观点与论证"},{"w":"témoigner","p":"v.","cn":"作证；（~ de）表明、证明","ex":"Trois personnes ont accepté de témoigner au procès.","exCn":"有三个人同意在庭审中出庭作证。","th":"观点与论证"},{"w":"témoin","p":"n.m.","cn":"证人、目击者；（婚礼的）证婚人","ex":"Un témoin a vu le conducteur s'enfuir juste après l'accident.","exCn":"一名目击者看到司机在事故发生后立刻逃跑了。","th":"人物与身份"},{"w":"têtu","p":"adj.","cn":"固执的、倔强的","ex":"Mon frère est têtu comme une mule : il ne change jamais d'avis.","exCn":"我哥哥倔得像头骡子，从来不改主意。","th":"描述与状态"},{"w":"uni","p":"adj.","cn":"团结的、和睦的；（布料）纯色的、素色的","ex":"C'est une famille très unie.","exCn":"这是一个非常和睦的家庭。","th":"常用词"},{"w":"uniforme","p":"n.m.","cn":"制服；一致的、均匀的","ex":"Dans cette école, les élèves doivent porter un uniforme.","exCn":"这所学校的学生必须穿校服。","th":"常用词"},{"w":"union","p":"n.f.","cn":"联盟、联合；团结","ex":"Ces deux pays ont formé une union économique pour faciliter les échanges.","exCn":"这两个国家结成了经济联盟，以促进贸易往来。","th":"常用词"},{"w":"unir","p":"v.","cn":"联合、团结；结合、连接","ex":"Les citoyens se sont unis pour protéger le parc contre un projet immobilier.","exCn":"市民们团结起来，保护公园不被房地产项目占用。","th":"常用词"},{"w":"unité","p":"n.f.","cn":"单位、单元；统一、团结","ex":"Ces bouteilles d'eau sont vendues un dollar l'unité.","exCn":"这些瓶装水一块钱一瓶。","th":"常用词"},{"w":"univers","p":"n.m.","cn":"宇宙；（某人的）世界、天地","ex":"Selon les scientifiques, l'univers est né il y a environ 13,8 milliards d'années.","exCn":"根据科学家的说法，宇宙诞生于大约138亿年前。","th":"人物与身份"},{"w":"universel","p":"adj.","cn":"普遍的、世界性的；通用的、万能的","ex":"La Déclaration universelle des droits de l'homme a été adoptée en 1948.","exCn":"《世界人权宣言》于1948年通过。","th":"时间与数量"},{"w":"universitaire","p":"n.","cn":"大学教师、学者；大学的","ex":"Une universitaire spécialisée en climatologie a été invitée à l'émission.","exCn":"一位研究气候学的女学者应邀参加了这档节目。","th":"工作与学习"},{"w":"urbain","p":"adj.","cn":"城市的、都市的","ex":"Les transports urbains seront perturbés demain à cause d'une grève.","exCn":"明天市内公共交通将因罢工受到影响。","th":"居住与环境"},{"w":"usage","p":"n.m.","cn":"使用、用法；惯例、习惯","ex":"Il a fait bon usage de cet argent.","exCn":"这笔钱他用得很得当。","th":"常用词"},{"w":"usé","p":"adj.","cn":"用旧的、磨损的；（人）精疲力竭的","ex":"Mes chaussures sont complètement usées.","exCn":"我的鞋子已经完全穿坏了。","th":"人物与身份"},{"w":"utilisation","p":"n.f.","cn":"使用、利用","ex":"L'utilisation de ce stationnement est réservée aux clients.","exCn":"这个停车场仅供顾客使用。","th":"常用词"},{"w":"vaccin","p":"n.m.","cn":"疫苗","ex":"Grâce au vaccin, cette maladie a presque disparu.","exCn":"多亏了疫苗，这种病几乎已经绝迹。","th":"常用词"},{"w":"vague","p":"n.f.","cn":"波浪；（喻）浪潮、一阵；模糊的；cf. le vague = 模糊、含糊","ex":"Une grosse vague a renversé le petit bateau de pêche.","exCn":"一个大浪把那条小渔船掀翻了。","th":"常用词"},{"w":"vainqueur","p":"n.","cn":"获胜者、征服者","ex":"Le vainqueur du concours recevra une bourse de dix mille dollars.","exCn":"比赛的获胜者将获得一万元奖金。","th":"常用词"},{"w":"valable","p":"adj.","cn":"有效的；（理由等）站得住脚的、合理的","ex":"Ce billet est valable pendant 90 minutes sur tout le réseau.","exCn":"这张车票在整个交通网内90分钟有效。","th":"居住与环境"},{"w":"valeur","p":"n.f.","cn":"价值；（复数）价值观","ex":"La valeur de cette maison a doublé en dix ans.","exCn":"这栋房子的价值十年里翻了一倍。","th":"购物与金钱"},{"w":"valider","p":"v.","cn":"确认、批准；（车票）打票验证；（课程、学分）通过、拿到","ex":"Le directeur doit encore valider ce projet.","exCn":"主任还得批准这个项目。","th":"出行与旅行"},{"w":"valoir","p":"v.","cn":"值、值得；（il vaut mieux）最好…","ex":"Selon l'expert, ce vieux tableau vaut plus de dix mille dollars.","exCn":"据专家估计，这幅旧画值一万多元。","th":"描述与状态"},{"w":"vapeur","p":"n.f.","cn":"蒸汽、水汽；（à la ~）清蒸","ex":"Une épaisse vapeur s'échappait de la casserole.","exCn":"一股浓浓的蒸汽从锅里冒了出来。","th":"常用词"},{"w":"variable","p":"adj.","cn":"多变的、可变的；不固定的、不等的","ex":"Demain, le temps sera variable avec quelques averses en après-midi.","exCn":"明天天气多变，下午有零星阵雨。","th":"常用词"},{"w":"varier","p":"v.","cn":"变化、有差异；使多样化、变换","ex":"Ma fille change tout le temps d'avis : ses goûts varient d'un jour à l'autre.","exCn":"我女儿老是变主意，口味一天一个样。","th":"抽象与概念"},{"w":"varié","p":"adj.","cn":"多样的、各种各样的、丰富的","ex":"Ce quartier attire des habitants d'origines très variées.","exCn":"这个街区吸引了出身背景各不相同的居民。","th":"描述与状态"},{"w":"variété","p":"n.f.","cn":"多样性、多种多样；品种、种类；（复数）综艺节目","ex":"Au Québec, on trouve une grande variété de paysages.","exCn":"魁北克的风景多种多样。","th":"常用词"},{"w":"vase","p":"n.m.","cn":"花瓶；cf. la vase = 淤泥","ex":"Elle a mis les roses dans un vase en cristal.","exCn":"她把玫瑰插进了一个水晶花瓶里。","th":"居住与环境"},{"w":"vaste","p":"adj.","cn":"广阔的、辽阔的；大规模的、庞大的","ex":"Le Canada est un pays si vaste qu'il compte six fuseaux horaires.","exCn":"加拿大幅员辽阔，横跨六个时区。","th":"描述与状态"},{"w":"vedette","p":"n.f.","cn":"明星、焦点；（voler la ~ à）抢…的风头；指男明星也用 la vedette","ex":"Le soir du concert, une foule de fans attendait la vedette à la sortie de l'hôtel.","exCn":"音乐会当晚，一大群粉丝守在酒店门口等那位明星出来。","th":"人物与身份"},{"w":"veille","p":"n.f.","cn":"前一天、前夕；守夜、值守；（en ~）（电器）待机","ex":"La veille de mon examen, je n'ai pas réussi à dormir.","exCn":"考试前一天晚上，我怎么也睡不着。","th":"时间与数量"},{"w":"vente","p":"n.f.","cn":"销售、出售；cf.（魁北克）la vente de garage 庭院旧物拍卖","ex":"La vente de gâteaux organisée par l'école a permis d'acheter de nouveaux livres pour la classe.","exCn":"靠着学校组织的蛋糕义卖，班上添置了一批新书。","th":"购物与金钱"},{"w":"ventilateur","p":"n.m.","cn":"风扇、电扇","ex":"Sans climatisation, nous dormons avec le ventilateur allumé tout l'été.","exCn":"家里没有空调，我们整个夏天都开着电扇睡觉。","th":"居住与环境"},{"w":"ver","p":"n.m.","cn":"虫、蠕虫；cf. 同音词 verre 玻璃杯、vert 绿色的、vers 朝向","ex":"Après la pluie, on voit beaucoup de vers de terre sur le trottoir.","exCn":"下过雨后，人行道上能看到很多蚯蚓。","th":"描述与状态"},{"w":"verglas","p":"n.m.","cn":"（路面）薄冰","ex":"Attention, il y a du verglas sur la route.","exCn":"小心，路面结了薄冰。","th":"出行与旅行"},{"w":"verser","p":"v.","cn":"倒、斟；支付、汇入（款项）","ex":"Pouvez-vous me verser un peu d'eau, s'il vous plaît ?","exCn":"能给我倒点水吗？","th":"购物与金钱"},{"w":"version","p":"n.f.","cn":"版本；（对事件的）说法","ex":"Téléchargez la dernière version de l'application pour profiter des nouvelles fonctions.","exCn":"下载最新版本的应用程序，就能使用新功能。","th":"常用词"},{"w":"vertige","p":"n.m.","cn":"眩晕、头晕；（avoir le ~）恐高","ex":"J'ai été pris d'un léger vertige en me levant trop vite.","exCn":"我起身太快，感到一阵轻微的头晕。","th":"描述与状态"},{"w":"vestiaire","p":"n.m.","cn":"更衣室；衣帽间","ex":"Les joueurs sont rentrés au vestiaire à la mi-temps.","exCn":"中场休息时，球员们回到了更衣室。","th":"居住与环境"},{"w":"veuve","p":"n.f.","cn":"寡妇；cf. le veuf 鳏夫；veuf / veuve 也作形容词「丧偶的」","ex":"Elle est devenue veuve à quarante ans et a élevé seule ses trois enfants.","exCn":"她四十岁就守了寡，独自把三个孩子拉扯大。","th":"常用词"},{"w":"via","p":"prép.","cn":"经由、通过","ex":"Nous avons pris un vol pour Vancouver via Toronto.","exCn":"我们坐飞机经多伦多转机去温哥华。","th":"常用词"},{"w":"victime","p":"n.f.","cn":"受害者","ex":"Mon frère a été victime d'une escroquerie en ligne le mois dernier.","exCn":"我哥哥上个月遭遇了网络诈骗。","th":"常用词"},{"w":"victoire","p":"n.f.","cn":"胜利","ex":"L'équipe a remporté une belle victoire hier soir.","exCn":"球队昨晚赢得了一场漂亮的胜利。","th":"常用词"},{"w":"vider","p":"v.","cn":"倒空、清空；使筋疲力尽（口语）","ex":"Peux-tu vider le lave-vaisselle, s'il te plaît ?","exCn":"你能把洗碗机里的碗碟拿出来吗？","th":"描述与状态"},{"w":"vieillard","p":"n.m.","cn":"老人、老头","ex":"Un vieillard au dos courbé traversait lentement la rue.","exCn":"一位驼背的老人正慢慢地过马路。","th":"人物与身份"},{"w":"vieillir","p":"v.","cn":"变老、衰老；使显老","ex":"En vingt ans, la population du Québec a beaucoup vieilli.","exCn":"二十年间，魁北克人口的老龄化大大加剧了。","th":"常用词"},{"w":"vif","p":"adj.","cn":"活泼的、机灵的；（颜色）鲜艳的；强烈的、激烈的","ex":"À quatre-vingt-dix ans, mon voisin a encore l'esprit vif et une mémoire étonnante.","exCn":"我邻居九十岁了，脑子依然灵活，记性也好得惊人。","th":"描述与状态"},{"w":"vigne","p":"n.f.","cn":"葡萄树；葡萄园","ex":"Mon grand-père cultive la vigne en Bourgogne.","exCn":"我爷爷在勃艮第种葡萄。","th":"居住与环境"},{"w":"vilain","p":"adj.","cn":"丑的、难看的；（天气、伤病等）糟糕的、严重的；（孩子）不乖的、淘气的","ex":"Depuis son accident, il a une vilaine cicatrice sur le bras.","exCn":"那次事故后，他手臂上留下了一道难看的伤疤。","th":"健康与身体"},{"w":"violence","p":"n.f.","cn":"暴力；猛烈、剧烈","ex":"Ce film contient des scènes de violence qui ne conviennent pas aux enfants.","exCn":"这部电影含有暴力镜头，不适合儿童观看。","th":"常用词"},{"w":"violent","p":"adj.","cn":"暴力的；猛烈的、剧烈的","ex":"Les enfants ne devraient pas regarder des films aussi violents.","exCn":"孩子们不应该看这么暴力的电影。","th":"常用词"},{"w":"virement","p":"n.m.","cn":"转账、汇款","ex":"Je vous paierai par virement bancaire.","exCn":"我会通过银行转账付款给您。","th":"常用词"},{"w":"virtuel","p":"adj.","cn":"虚拟的；潜在的、可能的","ex":"Grâce à la visite virtuelle, on peut découvrir le musée depuis chez soi.","exCn":"借助虚拟参观，在家里就能游览博物馆。","th":"抽象与概念"},{"w":"virus","p":"n.m.","cn":"病毒","ex":"Les antibiotiques ne servent à rien contre un virus comme celui de la grippe.","exCn":"抗生素对流感这类病毒毫无作用。","th":"健康与身体"},{"w":"visible","p":"adj.","cn":"可见的、看得见的；明显的","ex":"Cette éclipse de lune sera visible à l'œil nu dans tout le Québec.","exCn":"这次月食在魁北克全境都能用肉眼看到。","th":"常用词"},{"w":"vision","p":"n.f.","cn":"看法、眼光；视觉、视力","ex":"La nouvelle directrice a une vision claire de l'avenir de l'entreprise.","exCn":"新任女总监对公司的未来有清晰的构想。","th":"常用词"},{"w":"vitre","p":"n.f.","cn":"玻璃窗","ex":"Le ballon a cassé une vitre de l'école.","exCn":"球打碎了学校的一块玻璃窗。","th":"常用词"},{"w":"vitrine","p":"n.f.","cn":"橱窗；陈列柜、展示柜","ex":"J'ai vu une veste magnifique en vitrine, mais elle était hors de prix.","exCn":"我在橱窗里看到一件很漂亮的外套，可惜贵得离谱。","th":"常用词"},{"w":"vivement","p":"adv.","cn":"强烈地、深切地；（~ … !）真盼着…快来（口语）","ex":"Nous vous conseillons vivement de réserver vos places à l'avance.","exCn":"我们强烈建议您提前订座。","th":"描述与状态"},{"w":"vocal","p":"n.m.","cn":"声音的、嗓音的；语音的；语音消息（口语）","ex":"Le chanteur a dû annuler sa tournée à cause d'un problème aux cordes vocales.","exCn":"那位歌手因为声带出了问题，不得不取消巡演。","th":"常用词"},{"w":"voie","p":"n.f.","cn":"道路、途径；车道；（铁路）轨道；cf. en voie de 正在…中（espèce en voie de disparition 濒危物种）","ex":"Je pense que nous sommes sur la bonne voie.","exCn":"我觉得我们的方向是对的。","th":"出行与旅行"},{"w":"volant","p":"n.m.","cn":"方向盘；羽毛球（指球本身）","ex":"Il s'est endormi au volant et sa voiture a quitté la route.","exCn":"他开车睡着了，车子冲出了公路。","th":"常用词"},{"w":"volcan","p":"n.m.","cn":"火山","ex":"L'eau de cette source thermale est chauffée naturellement par un volcan tout proche.","exCn":"这处温泉的水是被附近的一座火山自然加热的。","th":"居住与环境"},{"w":"volet","p":"n.m.","cn":"百叶窗、护窗板；（计划、政策的）部分、方面","ex":"Ferme les volets, il fait trop chaud.","exCn":"把百叶窗关上，太热了。","th":"时间与数量"},{"w":"volontaire","p":"n.","cn":"自愿的、有意的；意志坚强的、有决心的；志愿者、自告奋勇的人","ex":"La participation à cette étude est volontaire.","exCn":"参加这项研究是自愿的。","th":"人物与身份"},{"w":"volonté","p":"n.f.","cn":"意志、心愿；cf. à volonté 随意、不限量","ex":"Il faut une grande volonté pour arrêter de fumer.","exCn":"戒烟需要很强的意志力。","th":"常用词"},{"w":"volume","p":"n.m.","cn":"体积、容量；音量；（书的）卷、册","ex":"Pourriez-vous baisser le volume de la musique ? Mon bébé dort.","exCn":"您能把音乐的音量调低一点吗？我的宝宝在睡觉。","th":"常用词"},{"w":"vote","p":"n.m.","cn":"投票、表决；选票","ex":"Le vote aura lieu à main levée à la fin de la réunion.","exCn":"会议结束时将举手表决。","th":"出行与旅行"},{"w":"voter","p":"v.","cn":"投票；表决通过","ex":"Au Canada, on peut voter à partir de dix-huit ans.","exCn":"在加拿大，年满十八岁就可以投票。","th":"出行与旅行"},{"w":"vouvoiement","p":"n.m.","cn":"以 vous 相称；cf. le tutoiement 以 tu 相称","ex":"Avec les clients, le vouvoiement est de rigueur.","exCn":"对客户必须用 vous 称呼。","th":"常用词"},{"w":"végétal","p":"n.m.","cn":"植物的、植物性的；植物","ex":"Je cuisine de plus en plus avec des protéines végétales comme les lentilles et le tofu.","exCn":"我做饭越来越多地用小扁豆、豆腐这类植物蛋白。","th":"常用词"},{"w":"véhicule","p":"n.m.","cn":"车辆、交通工具","ex":"Pour louer un véhicule, il faut avoir au moins vingt et un ans et un permis valide.","exCn":"租车必须年满二十一岁并持有有效驾照。","th":"出行与旅行"},{"w":"vérification","p":"n.f.","cn":"核实、检查","ex":"Après vérification, nous avons constaté une erreur dans votre facture.","exCn":"经核实，我们发现您的账单有误。","th":"常用词"},{"w":"véritable","p":"adj.","cn":"真正的、名副其实的","ex":"Mon beau-frère est un véritable cordon-bleu : on se régale chaque fois qu'il nous invite.","exCn":"我姐夫是个名副其实的烹饪高手：每次请我们吃饭，我们都吃得特别开心。","th":"常用词"},{"w":"vétérinaire","p":"n.","cn":"兽医；兽医的","ex":"Notre chat est malade, je dois l'emmener chez le vétérinaire.","exCn":"我们的猫病了，我得带它去看兽医。","th":"健康与身体"},{"w":"vœu","p":"n.m.","cn":"愿望、祝愿","ex":"Fais un vœu avant de souffler les bougies !","exCn":"吹蜡烛之前先许个愿！","th":"常用词"},{"w":"wagon","p":"n.m.","cn":"（火车）车厢","ex":"Nous sommes assis dans le troisième wagon.","exCn":"我们坐在第三节车厢。","th":"出行与旅行"},{"w":"western","p":"n.m.","cn":"西部片","ex":"Mon père adore regarder les vieux westerns.","exCn":"我爸特别爱看老西部片。","th":"常用词"},{"w":"à cause de","p":"loc.","cn":"由于（多含负面）","ex":"Le match a été annulé à cause de la pluie.","exCn":"比赛因为下雨取消了。","th":"观点与论证"},{"w":"à condition que","p":"loc.","cn":"只要；条件是（+虚拟式）","ex":"Le projet sera validé à condition que le budget soit voté.","exCn":"只要预算通过，项目就会获批。","th":"观点与论证"},{"w":"à l'heure","p":"loc.","cn":"准时","ex":"Le train est arrivé à l'heure.","exCn":"火车准点到站。","th":"社会与新闻"},{"w":"à l'étranger","p":"loc.","cn":"在国外","ex":"Elle travaille à l'étranger depuis un an.","exCn":"她在国外工作一年了。","th":"工作与学习"},{"w":"à moins que","p":"conj.","cn":"（+ 虚拟式）除非；cf. à moins de + 不定式；书面语常加虚词 ne：à moins qu'il ne pleuve","ex":"Je viendrai à vélo, à moins qu'il pleuve.","exCn":"我会骑车来，除非下雨。","th":"常用词"},{"w":"âme","p":"n.f.","cn":"灵魂、心灵","ex":"Elle a une âme d'artiste : elle peint depuis son enfance.","exCn":"她有一颗艺术家的心灵：从小就开始画画。","th":"常用词"},{"w":"âne","p":"n.","cn":"驴；（口语）笨蛋、蠢货","ex":"Les enfants ont fait une promenade à dos d'âne.","exCn":"孩子们骑驴溜达了一圈。","th":"常用词"},{"w":"écart","p":"n.m.","cn":"差距、差异；间隔；（à l'~ de）远离…、在…一旁","ex":"Il existe un écart important entre les salaires des hommes et ceux des femmes.","exCn":"男女工资之间存在相当大的差距。","th":"常用词"},{"w":"échangeable","p":"adj.","cn":"可调换的、可交换的","ex":"Les articles en solde ne sont pas échangeables.","exCn":"打折商品不可调换。","th":"常用词"},{"w":"échapper","p":"v.","cn":"逃跑、躲开；（~ à qqn）被忽略、一时想不起；（魁北克）失手掉落","ex":"Ce détail m'avait complètement échappé.","exCn":"这个细节我完全没注意到。","th":"日常动作"},{"w":"échec","p":"n.m.","cn":"失败；cf. les échecs 国际象棋","ex":"Son premier projet d'entreprise a été un échec, mais il ne s'est pas découragé.","exCn":"他的第一次创业失败了，但他并没有气馁。","th":"社会与新闻"},{"w":"échelle","p":"n.f.","cn":"梯子；规模、范围；比例、比例尺","ex":"Il est tombé d'une échelle en nettoyant les gouttières.","exCn":"他在清理屋檐排水槽时从梯子上摔了下来。","th":"抽象与概念"},{"w":"échouer","p":"v.","cn":"失败","ex":"J'ai échoué au test de conduite.","exCn":"我驾照考试没过。","th":"工作与学习"},{"w":"éclair","p":"n.m.","cn":"闪电；（en un ~）一眨眼、转眼间；（甜点）闪电泡芙；cf. la fermeture éclair 拉链","ex":"Pendant l'orage, chaque éclair illuminait la chambre comme en plein jour.","exCn":"暴风雨中，每一道闪电都把房间照得如同白昼。","th":"饮食"},{"w":"éclaircie","p":"n.f.","cn":"（雨后）短暂放晴；（局势）好转","ex":"On annonce quelques éclaircies cet après-midi.","exCn":"预报说今天下午会有短暂放晴。","th":"居住与环境"},{"w":"éclairer","p":"v.","cn":"照亮；阐明、启发","ex":"Cette pièce est éclairée par deux grandes fenêtres.","exCn":"这个房间靠两扇大窗户采光。","th":"描述与状态"},{"w":"éclater","p":"v.","cn":"爆发；爆炸、破裂；cf. éclater de rire 突然大笑起来","ex":"La Première Guerre mondiale a éclaté en 1914.","exCn":"第一次世界大战于1914年爆发。","th":"描述与状态"},{"w":"écologie","p":"n.f.","cn":"环保、生态保护；生态学","ex":"L'écologie est devenue une priorité pour les jeunes.","exCn":"环保已成为年轻人优先关注的事。","th":"常用词"},{"w":"écologique","p":"adj.","cn":"环保的；生态的","ex":"Les couches lavables sont plus écologiques que les jetables, mais elles demandent beaucoup plus de lessives.","exCn":"可洗尿布比一次性尿布更环保，但要多洗很多次。","th":"常用词"},{"w":"écologiste","p":"n.","cn":"环保人士；环保主义的","ex":"Les écologistes manifestent contre le nouvel aéroport.","exCn":"环保人士正在抗议新建机场。","th":"人物与身份"},{"w":"économie","p":"n.f.","cn":"经济；节约；（复数）积蓄","ex":"L'économie canadienne dépend en grande partie de l'exportation des ressources naturelles.","exCn":"加拿大经济在很大程度上依赖自然资源出口。","th":"社会与新闻"},{"w":"écossais","p":"adj.","cn":"苏格兰的；（布料）苏格兰格子的","ex":"Mon collègue a un accent écossais si fort que je comprends à peine ce qu'il dit.","exCn":"我同事的苏格兰口音太重了，他说的话我几乎听不懂。","th":"常用词"},{"w":"écoute","p":"n.f.","cn":"听、收听；（être à l'~ de）倾听、关心","ex":"À l'épreuve de compréhension orale du TCF, chaque document ne fait l'objet que d'une seule écoute.","exCn":"TCF听力考试中，每段录音只能听一遍。","th":"常用词"},{"w":"écraser","p":"v.","cn":"压碎、压扁；（车辆）轧、碾；（s'~）（飞机等）坠毁","ex":"Écrasez les pommes de terre avec une fourchette, puis ajoutez un peu de beurre.","exCn":"用叉子把土豆压碎，再加一点黄油。","th":"出行与旅行"},{"w":"écureuil","p":"n.m.","cn":"松鼠","ex":"Dans les parcs de Montréal, les écureuils n'ont presque pas peur des promeneurs.","exCn":"在蒙特利尔的公园里，松鼠几乎不怕散步的人。","th":"常用词"},{"w":"éditeur","p":"n.","cn":"出版商、出版人","ex":"Après plusieurs refus, elle a enfin trouvé un éditeur pour son premier roman.","exCn":"被拒了好几次之后，她终于为自己的第一部小说找到了出版商。","th":"人物与身份"},{"w":"édition","p":"n.f.","cn":"版、版本；出版；（节庆、赛事的）届","ex":"La nouvelle édition du dictionnaire sortira en mars.","exCn":"这部词典的新版将于三月出版。","th":"常用词"},{"w":"éducateur","p":"n.","cn":"教育工作者；（托儿所）幼教老师；（青少年）辅导员","ex":"Les parents sont les premiers éducateurs de leurs enfants.","exCn":"父母是孩子的第一任教育者。","th":"工作与学习"},{"w":"éducatif","p":"adj.","cn":"教育的、有教育意义的","ex":"Cette application propose des jeux éducatifs pour apprendre à lire.","exCn":"这个应用提供教孩子识字的教育类游戏。","th":"社会与新闻"},{"w":"éduquer","p":"v.","cn":"教育、培养","ex":"C'est aussi aux parents d'éduquer leurs enfants au respect des autres.","exCn":"教育孩子尊重他人，也是父母的责任。","th":"社会与新闻"},{"w":"égal","p":"adj.","cn":"相等的、平等的；（ça m'est ~）无所谓；cf. d'égal à égal 平等地；sans égal 无与伦比的","ex":"Tous les citoyens sont égaux devant la loi.","exCn":"法律面前人人平等。","th":"常用词"},{"w":"égalité","p":"n.f.","cn":"平等、相等","ex":"L'égalité entre les filles et les garçons commence à l'école.","exCn":"男女平等要从学校做起。","th":"常用词"},{"w":"égoïste","p":"n.","cn":"自私的；自私的人","ex":"Ne sois pas si égoïste, partage tes bonbons avec ta petite sœur !","exCn":"别这么自私，把你的糖果分给妹妹一些！","th":"人物与身份"},{"w":"électeur","p":"n.","cn":"选民","ex":"Un électeur sur trois ne s'est pas déplacé pour voter.","exCn":"三分之一的选民没有去投票。","th":"常用词"},{"w":"élection","p":"n.f.","cn":"选举","ex":"Elle a remporté une élection très serrée.","exCn":"她在一场竞争非常激烈的选举中胜出。","th":"社会与新闻"},{"w":"électroménager","p":"n.m.","cn":"家用电器；家电的","ex":"Le petit électroménager est en promotion cette semaine.","exCn":"小家电本周打折。","th":"常用词"},{"w":"élever","p":"v.","cn":"抚养；饲养（动物）；提高、抬高；（s'~ à）（金额、数量）达到","ex":"Mes grands-parents élèvent des moutons dans leur ferme.","exCn":"我祖父母在农场里养羊。","th":"居住与环境"},{"w":"élevé","p":"adj.","cn":"（价格、数量、程度）高的；（bien / mal ~）有教养的 / 没教养的","ex":"Le prix de cette voiture est très élevé.","exCn":"这辆车的价格很高。","th":"购物与金钱"},{"w":"éliminer","p":"v.","cn":"消除、排除；（比赛）淘汰","ex":"Ce produit élimine 99 % des bactéries.","exCn":"这款产品能消灭99%的细菌。","th":"常用词"},{"w":"élire","p":"v.","cn":"选举、选出","ex":"Les citoyens éliront leur nouveau maire en novembre.","exCn":"市民们将在十一月选出新市长。","th":"社会与新闻"},{"w":"éloigner","p":"v.","cn":"使远离、移开；（s'~）走远、远离","ex":"Éloignez ce radiateur des rideaux pour éviter un incendie.","exCn":"把这个取暖器挪得离窗帘远一点，以免引起火灾。","th":"常用词"},{"w":"éloigné","p":"adj.","cn":"遥远的、偏远的；（亲戚）远房的","ex":"C'est un cousin éloigné de ma mère : je ne l'ai vu qu'une fois.","exCn":"他是我妈妈的一个远房表亲，我只见过他一次。","th":"居住与环境"},{"w":"élégance","p":"n.f.","cn":"优雅、高雅","ex":"Elle s'habille toujours avec une élégance discrète.","exCn":"她的穿着总是低调而优雅。","th":"描述与状态"},{"w":"élément","p":"n.m.","cn":"要素、组成部分；（化学）元素","ex":"La confiance est un élément essentiel du travail en équipe.","exCn":"信任是团队合作中的一个关键要素。","th":"常用词"},{"w":"élémentaire","p":"adj.","cn":"基本的、起码的；初级的、小学的","ex":"Se laver les mains est une règle d'hygiène élémentaire.","exCn":"洗手是一条最起码的卫生规则。","th":"描述与状态"},{"w":"émouvant","p":"adj.","cn":"感人的、动人的","ex":"Le discours émouvant de la mariée a fait pleurer tous les invités.","exCn":"新娘感人的致辞让所有宾客都落泪了。","th":"人物与身份"},{"w":"ému","p":"adj.","cn":"感动的、激动的","ex":"Elle était très émue pendant la cérémonie.","exCn":"典礼上她非常感动。","th":"情绪与性格"},{"w":"énergique","p":"adj.","cn":"精力充沛的、有活力的；强有力的、果断的","ex":"Ma grand-mère est restée énergique jusqu'à quatre-vingt-dix ans.","exCn":"我奶奶直到九十岁都精力充沛。","th":"描述与状态"},{"w":"énervant","p":"adj.","cn":"烦人的、令人恼火的","ex":"C'est énervant, le wifi coupe toutes les cinq minutes depuis ce matin !","exCn":"真烦人，从早上开始Wi-Fi每五分钟就断一次！","th":"人物与身份"},{"w":"épais","p":"adj.","cn":"厚的；浓的、稠密的；（魁北克口语）蠢的、笨的","ex":"En hiver, il faut un manteau épais pour sortir à Montréal.","exCn":"在蒙特利尔，冬天出门要穿厚大衣。","th":"常用词"},{"w":"épicier","p":"n.","cn":"食品杂货商","ex":"Mon épicier fait aussi des livraisons à domicile.","exCn":"我常去的那家杂货店老板还提供送货上门。","th":"常用词"},{"w":"épidémie","p":"n.f.","cn":"流行病、疫情","ex":"Une épidémie de grippe touche actuellement plusieurs écoles de la région.","exCn":"目前，一场流感疫情正在该地区的多所学校蔓延。","th":"健康与身体"},{"w":"épingle","p":"n.f.","cn":"别针、大头针；（~ à cheveux）发夹；（tiré à quatre ~s）衣着讲究、一丝不苟","ex":"La couturière a fixé l'ourlet du pantalon avec des épingles avant de le coudre.","exCn":"裁缝先用大头针把裤脚边别好，再动手缝。","th":"描述与状态"},{"w":"éponge","p":"n.f.","cn":"海绵","ex":"Passe une éponge humide sur la table après le repas.","exCn":"饭后用湿海绵把桌子擦一下。","th":"居住与环境"},{"w":"épouser","p":"v.","cn":"娶、嫁给","ex":"Il a épousé une Québécoise qu'il avait rencontrée pendant ses études.","exCn":"他娶了一位读书时认识的魁北克姑娘。","th":"常用词"},{"w":"époux","p":"n.","cn":"名词；阳性 m. / 阴性 f.；l'époux / l'épouse；les époux / les épouses；配偶（阳性指丈夫，阴性指妻子）；（复数）夫妻","ex":"Les futurs époux ont choisi de se marier à la campagne.","exCn":"这对新人选择在乡下办婚礼。","th":"人物与身份"},{"w":"épreuve","p":"n.f.","cn":"考试、测验；考验、磨难；（体育）比赛项目","ex":"Les candidats doivent réussir une épreuve écrite avant l'entretien.","exCn":"应聘者要先通过一场笔试才能面试。","th":"工作与学习"},{"w":"épuisé","p":"adj.","cn":"精疲力竭的；（商品）售罄的、脱销的","ex":"Je suis épuisé après cette longue journée.","exCn":"忙了一整天，我累坏了。","th":"购物与金钱"},{"w":"équilibre","p":"n.m.","cn":"平衡、均衡","ex":"J'ai perdu l'équilibre sur le trottoir glacé et je suis tombé.","exCn":"我在结冰的人行道上失去平衡，摔倒了。","th":"常用词"},{"w":"équilibré","p":"adj.","cn":"均衡的、平衡的；（人）心态平和的","ex":"Ma grand-mère est une personne très équilibrée : rien ne la stresse.","exCn":"我奶奶心态特别平和，什么事都不会让她紧张。","th":"人物与身份"},{"w":"équipement","p":"n.m.","cn":"设备、装备；设施","ex":"Le club fournit tout l'équipement nécessaire pour l'escalade.","exCn":"俱乐部提供攀岩所需的全部装备。","th":"常用词"},{"w":"équiper","p":"v.","cn":"装备、配备；（s'~）备齐装备","ex":"Toutes les salles de classe sont désormais équipées de tableaux numériques.","exCn":"现在所有教室都配备了电子白板。","th":"常用词"},{"w":"équitation","p":"n.f.","cn":"骑马、马术","ex":"Ma fille fait de l'équitation le mercredi.","exCn":"我女儿每周三去骑马。","th":"常用词"},{"w":"établir","p":"v.","cn":"建立、确立；制定、开具（文件）；（s'~）定居、安家","ex":"Après ses études, elle s'est établie à Sherbrooke avec sa famille.","exCn":"毕业后，她和家人在舍布鲁克定居了下来。","th":"常用词"},{"w":"établissement","p":"n.m.","cn":"（学校、企业等）机构；建立、确立","ex":"Cet établissement scolaire accueille plus de mille élèves.","exCn":"这所学校有一千多名学生。","th":"工作与学习"},{"w":"éternel","p":"adj.","cn":"永恒的；（放在名词前）没完没了的、老一套的","ex":"J'en ai assez de ses éternelles excuses.","exCn":"我受够了他那些没完没了的借口。","th":"常用词"},{"w":"éternuer","p":"v.","cn":"打喷嚏","ex":"Éternuez dans votre coude, pas dans votre main.","exCn":"打喷嚏时请用手肘遮挡，不要用手。","th":"常用词"},{"w":"étiquette","p":"n.f.","cn":"标签","ex":"Le prix est indiqué sur une petite étiquette collée sous le pot.","exCn":"价格标在罐子底部贴的一张小标签上。","th":"常用词"},{"w":"étonnant","p":"adj.","cn":"令人惊讶的、惊人的；出色的、了不起的","ex":"Il n'est pas étonnant qu'il soit fatigué : il travaille depuis six heures du matin.","exCn":"他累了一点也不奇怪：他从早上六点就开始工作了。","th":"情绪与性格"},{"w":"étonner","p":"v.","cn":"使惊讶、使吃惊；（s'~ de / que）感到惊讶、奇怪","ex":"Ça m'étonnerait qu'il arrive à l'heure : il est toujours en retard.","exCn":"他要是能准时到我才奇怪呢：他总是迟到。","th":"饮食"},{"w":"étonné","p":"adj.","cn":"吃惊的、惊讶的","ex":"Elle avait l'air étonnée de me voir ici.","exCn":"她看到我在这儿似乎很惊讶。","th":"饮食"},{"w":"étrange","p":"adj.","cn":"奇怪的、奇特的；cf. étranger = 外国的；外国人","ex":"Il se passe des choses étranges dans cette maison.","exCn":"这栋房子里发生了些怪事。","th":"人物与身份"},{"w":"étroit","p":"adj.","cn":"窄的、狭窄的；紧密的、密切的","ex":"Les rues du Vieux-Québec sont étroites et pavées.","exCn":"魁北克老城的街道很窄，路面铺着石板。","th":"描述与状态"},{"w":"évaluation","p":"n.f.","cn":"评估、评价","ex":"Chaque employé passe une évaluation annuelle avec son responsable.","exCn":"每位员工每年都要和主管进行一次年度考评。","th":"购物与金钱"},{"w":"évaluer","p":"v.","cn":"评估、评价；估计、估算","ex":"Les enseignants évaluent les élèves tout au long de l'année.","exCn":"老师们全年都会对学生进行评估。","th":"购物与金钱"},{"w":"évidence","p":"n.f.","cn":"明显、显而易见的事","ex":"Il faut se rendre à l'évidence : nous ne finirons pas le projet à temps.","exCn":"必须承认这个明摆着的事实：我们没法按时完成项目了。","th":"常用词"},{"w":"évident","p":"adj.","cn":"明显的、显而易见的；（pas ~）不容易、不简单（口语）","ex":"La réponse était évidente, mais personne n'y avait pensé.","exCn":"答案明摆着，却谁都没想到。","th":"描述与状态"},{"w":"évier","p":"n.m.","cn":"（厨房）水槽、洗碗池","ex":"La cuisine est équipée d'un évier double et d'un lave-vaisselle.","exCn":"厨房配有双槽洗碗池和洗碗机。","th":"饮食"},{"w":"évoluer","p":"v.","cn":"发展、演变；（在某环境中）活动","ex":"La situation a beaucoup évolué depuis l'année dernière.","exCn":"自去年以来，情况已经发生了很大变化。","th":"居住与环境"},{"w":"évolution","p":"n.f.","cn":"发展、变化；（生物）进化","ex":"On observe une évolution rapide des habitudes de consommation des jeunes.","exCn":"年轻人的消费习惯正在迅速变化。","th":"抽象与概念"},{"w":"œuvre","p":"n.f.","cn":"作品、著作；cf. mettre en œuvre 实施、落实；la main-d'œuvre 劳动力；le chef-d'œuvre 杰作","ex":"Cette sculpture est une œuvre originale d'un artiste inuit.","exCn":"这座雕塑是一位因纽特艺术家的原创作品。","th":"常用词"}];
